// ─── Sidebar collapse/expand (Spotify-style "Your Library" rail) ──────────
function toggleSidebarCollapse(force) {
  const collapsed = typeof force === 'boolean' ? force : !document.body.classList.contains('side-collapsed');
  document.body.classList.toggle('side-collapsed', collapsed);
  const btn = document.getElementById('lib-collapse-btn');
  if (btn) {
    btn.title = collapsed ? 'Expand Your Library' : 'Collapse Your Library';
    const svg = btn.querySelector('svg');
    if (svg) svg.style.transform = collapsed ? 'rotate(180deg)' : 'rotate(0deg)';
  }
  try { localStorage.setItem('vibexa_side_collapsed', collapsed ? '1' : '0'); } catch(e) {}
}
(function restoreSidebarState(){
  try {
    if (localStorage.getItem('vibexa_side_collapsed') === '1') {
      document.addEventListener('DOMContentLoaded', () => toggleSidebarCollapse(true));
    }
  } catch(e) {}
})();

