// ─── Liked Songs (playlist khusus ala Spotify) ─────────────────────────
// Playlist dengan id tetap ini otomatis ada untuk setiap akun, dipin di
// paling atas panel kiri, dan tidak bisa dihapus/diubah nama lewat UI biasa.
// Tombol Like di player bar & tombol titik tiga di Song Preview sama-sama
// menyimpan lagu ke sini.
const LIKED_PLAYLIST_ID = 'liked-songs';

function ensureLikedPlaylist() {
  if (!playlists[LIKED_PLAYLIST_ID]) {
    playlists[LIKED_PLAYLIST_ID] = { id: LIKED_PLAYLIST_ID, name: 'Liked Songs', cover: '', coverThumb: '', tracks: [], isLiked: true };
  } else {
    playlists[LIKED_PLAYLIST_ID].isLiked = true;
    if (!playlists[LIKED_PLAYLIST_ID].name) playlists[LIKED_PLAYLIST_ID].name = 'Liked Songs';
    if (!Array.isArray(playlists[LIKED_PLAYLIST_ID].tracks)) playlists[LIKED_PLAYLIST_ID].tracks = [];
  }
}

function _findTrackIndexInPlaylist(plId, artist, title) {
  const pl = playlists[plId];
  if (!pl) return -1;
  return pl.tracks.findIndex(t => t.artist === artist && t.title === title);
}

function isTrackLiked(track) {
  if (!track) return false;
  ensureLikedPlaylist();
  return _findTrackIndexInPlaylist(LIKED_PLAYLIST_ID, track.artist, track.title) !== -1;
}

// Update tampilan tombol Like di player bar sesuai status songs yang sedang diputar
function updateBarLikeBtn(track) {
  const btn = document.getElementById('btn-like');
  if (!btn) return;
  if (!track) { btn.classList.remove('liked'); btn.disabled = true; return; }
  btn.disabled = false;
  btn.classList.toggle('liked', isTrackLiked(track));
}

// Tambahkan songs ke Liked Songs (dipakai oleh toggleLikeTrack di bawah).
// Mengembalikan true kalau berhasil ditambahkan.
function addTrackToLiked(track) {
  if (!track || !track.title || !track.artist) return false;
  ensureLikedPlaylist();
  const idx = _findTrackIndexInPlaylist(LIKED_PLAYLIST_ID, track.artist, track.title);
  if (idx !== -1) { toast(' Song is already in Liked Songs'); return false; }
  playlists[LIKED_PLAYLIST_ID].tracks.push({
    title: track.title, artist: track.artist, thumb: track.thumb || '',
    _query: track._query || (track.artist + '|||' + track.title + '|||0')
  });
  if (currentPlaylistId === LIKED_PLAYLIST_ID) renderPlaylistView(LIKED_PLAYLIST_ID);
  renderSidebarPlaylists();
  renderHomeGrid();
  scheduleSave();
  if (curTrack && curTrack.artist === track.artist && curTrack.title === track.title) updateBarLikeBtn(curTrack);
  toast(' "' + track.title + '" added to Liked Songs');
  return true;
}

// Toggle status like untuk SEMBARANG track object {title, artist, thumb, _query}.
// Dipakai bersama oleh tombol hati di player bar & tombol like di Song Preview.
// Mengembalikan true kalau sekarang berstatus liked, false kalau just now dihapus.
function toggleLikeTrack(track) {
  if (!track || !track.title || !track.artist) return false;
  ensureLikedPlaylist();
  const idx = _findTrackIndexInPlaylist(LIKED_PLAYLIST_ID, track.artist, track.title);
  if (idx !== -1) {
    playlists[LIKED_PLAYLIST_ID].tracks.splice(idx, 1);
    if (currentPlaylistId === LIKED_PLAYLIST_ID) renderPlaylistView(LIKED_PLAYLIST_ID);
    renderSidebarPlaylists();
    renderHomeGrid();
    scheduleSave();
    if (curTrack && curTrack.artist === track.artist && curTrack.title === track.title) updateBarLikeBtn(curTrack);
    toast(' Removed from Liked Songs');
    return false;
  }
  addTrackToLiked(track);
  return true;
}

// Toggle like untuk songs yang SEDANG diputar (dipanggil dari tombol hati di player bar)
function toggleLikeCurrentTrack() {
  if (!curTrack) { toast(' No song currently playing'); return; }
  toggleLikeTrack(curTrack);
}

