// ─── Bersih-bersih cache lokal yang sudah basi ─────────────────────────
// Banyak fitur (Daily Mix, Playlist Pop, Weekday Vibes, dll) menyimpan
// cache di localStorage dengan key bertanggal (misal "..._2026-07-13") yang
// TIDAK otomatis terhapus begitu tanggalnya lewat. Lama-lama localStorage
// penuh dan localStorage.setItem() mulai gagal dengan QuotaExceededError —
// ini yang bikin sebagian playlist (termasuk "For You") gagal ke-cache
// atau kadang gagal muncul saat banyak fitur menulis cache bersamaan.
// Dijalankan sekali tiap kali app dibuka: buang entri vibexa_* yang
// tanggalnya BUKAN hari ini, supaya selalu ada ruang kosong.
function _cleanupStaleLocalCache() {
  try {
    const todayStr = _dmTodayDateStr();
    const dateRe = /(\d{4}-\d{2}-\d{2})/;
    const keysToRemove = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k || !k.startsWith('vibexa_')) continue;
      const m = k.match(dateRe);
      if (m && m[1] !== todayStr) keysToRemove.push(k);
    }
    keysToRemove.forEach(k => { try { localStorage.removeItem(k); } catch (e) {} });
  } catch (e) {}
}


// ─── Mode Offline ───────────────────────────────────────────────────────
// Dipanggil kalau: (a) Firebase SDK gagal dimuat sama sekali (lihat try/catch
// di atas), atau (b) browser sedang offline dan proses login/redirect tidak
// bisa jalan. Tujuannya: jangan biarkan user terjebak di layar loading atau
// coba redirect ke login.html (yang butuh internet) — cukup sembunyikan
// overlay dan buka langsung halaman "Unduhan Offline" supaya lagu yang
// sudah didownload tetap bisa diputar tanpa koneksi & tanpa login.
let _vbxOfflineModeActive = false;
function _vbxEnterOfflineMode() {
  if (_vbxOfflineModeActive) return;
  _vbxOfflineModeActive = true;
  const overlay = document.getElementById('auth-overlay');
  if (overlay) {
    overlay.style.opacity = '0';
    overlay.style.transition = 'opacity .4s';
    setTimeout(() => {
      overlay.style.display = 'none';
      document.dispatchEvent(new Event('vbxAppReady'));
    }, 400);
  } else {
    document.dispatchEvent(new Event('vbxAppReady'));
  }
  document.body.classList.add('vbx-offline-mode');
  // Buka langsung halaman Unduhan Offline supaya user tidak perlu mencari-cari
  try { openDownloadsView(); } catch (e) { console.warn('Gagal membuka halaman Unduhan Offline otomatis:', e); }
  try { toast(' Kamu sedang offline — hanya lagu yang sudah diunduh yang bisa diputar'); } catch (e) {}
}

if (window._vbxFirebaseOK && auth) {
  auth.onAuthStateChanged(user => {
    if (user && !user.isAnonymous) {
      currentUser = user;
      try { localStorage.setItem('vibexa_last_uid', user.uid); } catch (e) {}
      // PENTING: setupPushNotifications() sengaja dipanggil PALING AWAL di
      // sini (dibungkus try-catch), bukan paling akhir seperti sebelumnya.
      // Sebelumnya baris ini ada di paling bawah, setelah ~15 fungsi load
      // lain yang dipanggil TANPA await dan TANPA try-catch (showApp,
      // _cleanupStaleLocalCache, startFriendSuggestionsListener, dst).
      // Kalau salah SATU SAJA dari fungsi non-async itu throw exception
      // secara synchronous, seluruh sisa baris di callback ini berhenti
      // di situ juga — termasuk setupPushNotifications() yang ada di
      // paling bawah — TANPA log error apa pun yang jelas menunjuk ke
      // sini, karena errornya justru muncul di fungsi lain. Ini kemungkinan
      // besar penyebab token FCM tidak pernah tersimpan walau app
      // kelihatan jalan normal. Dengan dipanggil paling awal + try-catch,
      // registrasi push dijamin selalu jalan apa pun yang terjadi di
      // fungsi-fungsi load lainnya di bawah.
      try { setupPushNotifications(user); } catch (e) { console.warn('setupPushNotifications gagal dipanggil:', e); }
      showApp(user);
      _cleanupStaleLocalCache();
      loadAllPlaylistsFromCloud();
      loadFavoriteArtistsFromCloud();
      loadTimePlaylists();
      startFriendSuggestionsListener();
      loadPublicFeed();
      loadTrendingSongs();
      loadRecentlyPlayedFromCloud();
      loadStreakFromCloud();
      loadDailyMixes();
      loadYearMixes();
      loadMadeForYouMixes();
      loadForYouPlaylists();
      loadMaybeLikeMixes();
      loadArtistRadioMixes();
      loadSadPlaylists();
      loadWeekdayPlaylists();
      _aiAttachFollowUpListener();
      _recentlyPlayedCache = null;
      _streakCache = null;
    } else {
      // Belum login (atau cuma sesi anonim dari halaman publik seperti
      // vibeprofile-view.html). Kalau sedang offline, jangan coba redirect
      // ke login.html (percuma, butuh internet) — masuk mode offline saja
      // supaya lagu yang sudah didownload tetap bisa diakses & diputar.
      if (!navigator.onLine) {
        _vbxEnterOfflineMode();
        return;
      }
      if (user && user.isAnonymous) {
        auth.signOut().finally(() => window.location.replace('login.html'));
      } else {
        window.location.replace('login.html');
      }
    }
  });
} else {
  // Firebase SDK gagal dimuat total (biasanya karena offline dan file
  // Firebase dari CDN belum ter-cache) → langsung masuk mode offline.
  _vbxEnterOfflineMode();
}

// Jaring pengaman tambahan: kalau untuk alasan apa pun (mis. request ke
// Firebase menggantung lama saat koneksi lemot/putus-nyambung) overlay
// loading masih terlihat setelah beberapa detik PADAHAL browser offline,
// paksa masuk mode offline supaya user tidak terjebak selamanya di layar
