// ── Stiker Lolu AI (Cloudinary, cari resource berdasarkan TAG) ─────────
// Lolu (AI) HANYA pernah mengirim sebuah TAG (lihat AI_SYSTEM_PROMPT,
// bagian "STIKER"), TIDAK PERNAH tau URL/Public ID/Asset ID/nama file.
// Aplikasi yang mencari sendiri semua stiker Cloudinary yang punya tag itu
// lewat endpoint publik "resource list by tag" milik Cloudinary, lalu
// milih satu secara acak buat ditampilkan.
//
// CATATAN SETUP CLOUDINARY: endpoint di bawah ini
// (https://res.cloudinary.com/<cloud>/image/list/<tag>.json) hanya bisa
// diakses tanpa API key/secret kalau opsi "Resource list" diaktifkan di
// dashboard Cloudinary akun stiker (Settings → Security → centang
// "Resource list"). Kalau belum aktif, endpoint ini akan menolak request
// dan stiker otomatis nggak akan tampil (gagal secara diam-diam, chat
// tetap jalan normal tanpa stiker).
const STICKER_CLOUD_NAME = 'sgwb5oml'; // akun/cloud Cloudinary khusus stiker Lolu (terpisah dari CLOUDINARY_CLOUD_NAME yg dipakai utk upload foto/video chat)
const STICKER_ALLOWED_TAGS = ['happy','sad','laugh','sleep','greeting','greeting_night','love','celebrate','thinking','forgive','angry'];
const _stickerTagCache = {}; // { tag: [{public_id,format,version}, ...] } — cache per tag biar nggak fetch ulang tiap kali tag yg sama muncul lagi

// Ambil (dgn cache) daftar semua resource Cloudinary yang punya tag tsb.
async function _fetchStickerResourcesByTag(tag){
  if (Object.prototype.hasOwnProperty.call(_stickerTagCache, tag)) return _stickerTagCache[tag];
  try{
    const res = await fetch(`https://res.cloudinary.com/${STICKER_CLOUD_NAME}/image/list/${encodeURIComponent(tag)}.json`);
    if (!res.ok) throw new Error('status ' + res.status);
    const data = await res.json();
    const resources = Array.isArray(data.resources) ? data.resources : [];
    _stickerTagCache[tag] = resources;
    return resources;
  }catch(e){
    console.warn('Gagal ambil daftar stiker Cloudinary utk tag "' + tag + '":', e);
    _stickerTagCache[tag] = [];
    return [];
  }
}

function _stickerResourceToUrl(r){
  if (!r || !r.public_id) return null;
  const fmt = r.format || 'png';
  const ver = r.version ? `v${r.version}/` : '';
  return `https://res.cloudinary.com/${STICKER_CLOUD_NAME}/image/upload/${ver}${r.public_id}.${fmt}`;
}

// Pilih & CACHE URL stiker untuk satu pesan AI (msg), sehingga hasilnya
// tetap SAMA setiap kali bubble ini dirender ulang (misal user keluar-masuk
// halaman chat, atau reload) — bukan diacak ulang tiap kali. Sekali dapat
// URL-nya (atau ketahuan kosong/gagal), hasilnya disimpan di msg._stickerUrl
// & msg._stickerResolved, lalu ikut tersimpan ke localStorage/cloud lewat
// _aiSaveChatState() persis seperti cover lagu yang sudah di-resolve.
async function _aiEnsureStickerResolved(msg){
  if (msg._stickerResolved) return msg._stickerUrl || null;
  if (msg._stickerResolving){
    let tries = 0;
    while (msg._stickerResolving && tries < 40){ await new Promise(r => setTimeout(r, 150)); tries++; }
    return msg._stickerUrl || null;
  }
  msg._stickerResolving = true;
  let url = null;
  try{ url = await _pickRandomSticker(msg.stickerTag); }
  catch(e){ console.warn('Gagal resolve stiker AI:', msg.stickerTag, e); }
  msg._stickerResolving = false;
  msg._stickerResolved = true;
  msg._stickerUrl = url;
  _aiSaveChatState();
  return url;
}

// Pilih satu URL stiker secara acak dari tag tsb, atau null kalau tag
// nggak dikenal / nggak ada stiker yg punya tag itu / gagal fetch.
async function _pickRandomSticker(tag){
  if (!tag || !STICKER_ALLOWED_TAGS.includes(tag)) return null;
  const resources = await _fetchStickerResourcesByTag(tag);
  if (!resources.length) return null;
  const r = resources[Math.floor(Math.random() * resources.length)];
  return _stickerResourceToUrl(r);
}

// Cari & lepas marker "[sticker:tag]" dari teks balasan AI (lihat format
// di AI_SYSTEM_PROMPT bagian "STIKER"). Mengembalikan teks yg udah bersih
// dari marker itu + tag stiker yg valid (atau null kalau nggak ada/nggak valid).
function _aiExtractStickerTag(text){
  if (!text) return { text: text || '', tag: null };
  const m = String(text).match(/\[sticker:\s*([a-z_]+)\s*\]/i);
  if (!m) return { text: String(text), tag: null };
  let tag = m[1].toLowerCase();
  // "greeting" otomatis diganti "greeting_night" kalau lagi jam 21.00–06.00
  // (dan sebaliknya, kalau AI kepeleset milih "greeting_night" padahal
  // udah bukan jam segitu, otomatis dibalikin ke "greeting" biasa) —
  // ditentukan dari jam PERANGKAT SAAT INI, bukan dari tebakan AI, biar akurat.
  if (tag === 'greeting' || tag === 'greeting_night'){
    tag = _isAiFabSleepHour() ? 'greeting_night' : 'greeting';
  }
  const cleaned = String(text).replace(m[0], '').replace(/\n{3,}/g, '\n\n').trim();
  return { text: cleaned, tag: STICKER_ALLOWED_TAGS.includes(tag) ? tag : null };
}

// ── Send GIF di Chat (Giphy) ───────────────────────────────────────────
// API Key ini BUKAN rahasia — memang didesain Giphy untuk dipakai langsung
// di sisi client (browser), beda dengan API Secret Cloudinary.
const GIPHY_API_KEY = 'a66wRYtqYPmQPBMXFSiE9Hvsfe1Wn0ez';
let _gifSearchDebounce = null;
let _gifSearchSeq = 0; // penanda request pencarian terakhir, cegah race condition hasil lama menimpa hasil baru

// Bikin id chat yang konsisten utk sepasang uid, urutan tidak masalah
function chatIdFor(a, b) {
  return [a, b].sort().join('_');
}

// Dipanggil sekali setelah login berhasil (dari showApp)
function initChatSystem(user) {
  if (!user) return;
  syncMyDirectoryEntry(user);
  subscribeChatInbox();
  subscribeChatDirectory();
  subscribeChatPerm();
  subscribeMyFollowing();
  subscribeMyFollowers();
  setupPresence(user);
  subscribeChatStatus();
  // Refresh berkala (tiap 5 menit) sbg jaga-jaga kalau ada perubahan status
  // follow yang tidak sempat ter-refresh live oleh listener di atas.
  setInterval(renderChatList, 5 * 60 * 1000);
}

// ── IZIN MULAI CHAT (anti chat sembarangan) ─────────────────────────────
// Mendengarkan node chat_perm/{myUid} secara real-time. Node ini menyimpan,
// untuk tiap lawan bicara, batasan chat SAYA ke mereka selama belum saling
// follow (follow diterima = bebas chat + kirim foto/GIF tanpa batas):
//   { type:'full' }                 → (legacy/opsional) follow diterima —
//                                      status "diterima" yang sebenarnya
//                                      selalu dicek langsung dari node
//                                      follows/, bukan dari sini.
//   { type:'blocked', blockedAt }   → permintaan follow saya ditolak,
//                                      TIDAK BOLEH kirim pesan sama sekali
//   { type:'free_used', usedAt }    → belum follow, dan jatah 1 pesan teks
//                                      gratis sudah dipakai — harus follow
//                                      dulu (dan diterima) utk lanjut chat
//   (tidak ada entri sama sekali)   → belum pernah kirim pesan ke orang ini,
//                                      masih ada jatah 1 pesan teks gratis
//                                      (tanpa foto/GIF — itu wajib follow)
//   { type:'onetime', ... }         → (legacy, tidak dibuat lagi)
//   { type:'onetime_peer', usedAt } → (legacy)
function subscribeChatPerm() {
  if (!currentUser) return;
  db.ref('chat_perm/' + currentUser.uid).on('value', snap => {
    _chatPermData = snap.exists() ? (snap.val() || {}) : {};
    renderChatList();
  }, err => console.error('Gagal memuat izin chat:', err));
}

// Cache live daftar orang yang SUDAH saya follow & diterima
// (follows/{myUid}/following/{peerUid} === true). Dipakai supaya
// isChatVisibleInList() bisa cek status follow secara instan/sinkron
// tanpa perlu query per-peer setiap render daftar chat.
let _myFollowingCache = {};
function subscribeMyFollowing() {
  if (!currentUser) return;
  db.ref('follows/' + currentUser.uid + '/following').on('value', snap => {
    _myFollowingCache = snap.exists() ? (snap.val() || {}) : {};
    renderChatList();
  }, err => console.error('Gagal memuat daftar following:', err));
}

// Cache live daftar orang yang MENGIKUTI saya & diterima
// (follows/{myUid}/followers/{peerUid} === true). Dibutuhkan supaya kalau
// ORANG LAIN yang mengirim permintaan follow ke saya lalu saya terima
// (bukan saya yang follow duluan), percakapan dengan orang itu tetap
// dianggap "sudah terhubung" — bukan cuma kalau saya yang follow dia.
let _myFollowersCache = {};
function subscribeMyFollowers() {
  if (!currentUser) return;
  db.ref('follows/' + currentUser.uid + '/followers').on('value', snap => {
    _myFollowersCache = snap.exists() ? (snap.val() || {}) : {};
    renderChatList();
  }, err => console.error('Gagal memuat daftar followers:', err));
}

// Apakah entri chat dengan peerUid termasuk "chat biasa" (sudah terhubung,
// bebas kirim pesan/foto/GIF tanpa batas)? True kalau ada hubungan follow
// yang diterima di SALAH SATU arah — saya follow dia, ATAU dia follow saya
// (mis. dia kirim permintaan follow ke saya dan saya terima). Kalau belum,
// lihat isChatRequest() di bawah — chat tsb masih bisa tampil di halaman
// Chat sebagai "Message Requests" asalkan sudah ada pesan asli.
function isChatVisibleInList(peerUid) {
  return !!_myFollowingCache[peerUid] || !!_myFollowersCache[peerUid];
}

// Apakah entri chat ini adalah "Message Requests" — chat dari/ke orang yang
// BELUM terhubung follow (lihat isChatVisibleInList), tapi sudah ada pesan
// asli yang terkirim (bukan sekadar thread kosong hasil tombol "Chat" di
// profil). Ditampilkan terpisah di halaman Chat supaya user tetap bisa
// melihat & membalas (maks 1x, lihat getChatSendPermission()) pesan dari
// orang yang belum mereka follow.
function isChatRequest(peerUid, chatEntry) {
  return !isChatVisibleInList(peerUid) && !!(chatEntry && chatEntry.lastMessage);
}

// Cek apakah saya boleh MEMBUKA percakapan baru dengan peerUid (bukan cek
// boleh kirim berapa banyak pesan — itu dicek per-pesan lewat
// getChatSendPermission()). Dipanggil sebelum membuat/membuka chat baru dari
// tombol Chat di profil user lain. Sejak sistem "1 pesan gratis", membuka
// chat SELALU boleh kecuali permintaan follow saya sudah pernah ditolak.
async function canInitiateChatWith(peerUid) {
  if (!currentUser) return { ok: false, message: 'ℹ️ Please log in first' };
  try {
    const permSnap = await db.ref('chat_perm/' + currentUser.uid + '/' + peerUid).get();
    const perm = permSnap.exists() ? permSnap.val() : null;
    if (perm && perm.type === 'blocked') {
      return { ok: false, message: "🔒 Your follow request was declined. You can't send messages to this user." };
    }
    return { ok: true };
  } catch(e) {
    console.error('Gagal memeriksa izin chat:', e);
    return { ok: false, message: '❌ Failed to check chat permissions, try again.' };
  }
}

// Cek apakah saya boleh MENGIRIM pesan ke peerUid sekarang, sesuai jenisnya:
//   kind: 'text'  → teks biasa (jatah 1x sebelum follow diterima)
//   kind: 'media' → foto/video/GIF (wajib sudah follow & diterima)
// Dipanggil tepat sebelum benar-benar mengirim (dan sebelum membuka
// file-picker/GIF-picker, supaya user langsung tahu tanpa perlu pilih file dulu).
async function getChatSendPermission(peerUid, kind) {
  if (!currentUser) return { ok: false, message: 'ℹ️ Please log in first' };
  try {
    const [followSnap, permSnap] = await Promise.all([
      db.ref('follows/' + peerUid + '/followers/' + currentUser.uid).get(),
      db.ref('chat_perm/' + currentUser.uid + '/' + peerUid).get()
    ]);
    const isFollowingAccepted = followSnap.exists() && followSnap.val() === true;
    if (isFollowingAccepted) return { ok: true };

    const perm = permSnap.exists() ? permSnap.val() : null;
    if (perm && perm.type === 'full') return { ok: true }; // legacy safety net
    if (perm && perm.type === 'blocked') {
      return { ok: false, message: "🔒 Your follow request was declined. You can't send messages to this user." };
    }

    if (kind === 'media') {
      return { ok: false, message: '📌 Follow this user first (and wait to be accepted) to send photos or GIFs.' };
    }

    // kind === 'text': jatah 1 pesan gratis sebelum follow diterima
    const freeUsed = perm && (perm.type === 'free_used' || (perm.type === 'onetime' && perm.used));
    if (freeUsed) {
      return { ok: false, message: "🔒 You've already sent 1 message to this user. Follow them first to continue chatting.", needsFollow: true };
    }
    return { ok: true, freeMessage: true };
  } catch(e) {
    console.error('Gagal memeriksa izin kirim pesan:', e);
    return { ok: false, message: '❌ Failed to check chat permissions, try again.' };
  }
}

// Tandai jatah 1 pesan gratis sudah dipakai (dipanggil setelah pesan teks
// PERTAMA berhasil terkirim ke peer yang belum saya follow).
function markFreeChatMessageUsed(peerUid, now) {
  if (!currentUser) return;
  const permUpdates = {};
  permUpdates['chat_perm/' + currentUser.uid + '/' + peerUid] = { type: 'free_used', usedAt: now };
  db.ref().update(permUpdates).catch(err => console.error('Gagal mencatat pemakaian jatah chat:', err));
}


// ── Status Online / Terakhir Dilihat (ala Instagram) ────────────────────
// Menyimpan status "online"/"offline" tiap user di node "status/{uid}",
// dengan memanfaatkan koneksi realtime bawaan Firebase:
//   - ".info/connected" bernilai true selama browser tersambung ke server.
//   - onDisconnect() didaftarkan SETIAP KALI baru tersambung, supaya kalau
//     koneksi putus tiba-tiba (tutup tab, internet mati, dsb), server
//     Firebase sendiri yang otomatis menandai status jadi "offline" beserta
//     jam terakhir terlihatnya — tanpa perlu browser masih menyala.
//
// CATATAN Firebase Security Rules — tambahkan (gabungkan dgn rules lain):
//   "status": {
//     ".read": "auth != null",
//     "$uid": { ".write": "auth != null && auth.uid === $uid" }
//   }
function setupPresence(user) {
  if (!user) return;
  const myStatusRef = db.ref('status/' + user.uid);
  db.ref('.info/connected').on('value', snap => {
    if (snap.val() !== true) return;
    myStatusRef.onDisconnect().set({
      state: 'offline',
      last_changed: firebase.database.ServerValue.TIMESTAMP
    }).then(() => {
      myStatusRef.set({
        state: 'online',
        last_changed: firebase.database.ServerValue.TIMESTAMP
      });
    }).catch(err => console.error('Gagal mengatur presence:', err));
  });
}

// Tandai status saya "offline" secara manual — dipanggil saat logout,
// supaya lawan bicara langsung melihat "offline" tanpa menunggu deteksi
// putus-koneksi (yang baru terjadi kalau tab benar-benar ditutup).
function markMyselfOffline() {
  if (!currentUser) return Promise.resolve();
  return db.ref('status/' + currentUser.uid).set({
    state: 'offline',
    last_changed: firebase.database.ServerValue.TIMESTAMP
  }).catch(() => {});
}

function subscribeChatStatus() {
  if (_chatStatusRef) _chatStatusRef.off();
  _chatStatusRef = db.ref('status');
  _chatStatusRef.on('value', snap => {
    _chatStatusCache = snap.exists() ? (snap.val() || {}) : {};
    renderChatList();               // refresh titik online di daftar chat
    renderDirectoryList();          // refresh titik online di halaman tambah teman
    refreshOpenConversationHeader(); // refresh status di header percakapan yg sedang dibuka
  }, err => console.error('Gagal memuat status online:', err));
}

// Menghasilkan HTML titik online (kalau user tsb sedang online) utk ditempel
// di sudut foto profil, dan teks status utk ditampilkan di tempat lain.
function getPeerOnlineDotHTML(uid) {
  const s = _chatStatusCache[uid];
  const online = !!(s && s.state === 'online');
  return online ? '<span class="chat-online-dot"></span>' : '';
}

// Instagram-style label: "Online" when currently online, or
// "Last seen X ago" based on last_changed.
function formatPeerStatusLabel(uid) {
  const s = _chatStatusCache[uid];
  if (!s) return '';
  if (s.state === 'online') return 'Online';
  if (!s.last_changed) return '';
  return 'Last seen ' + formatLastSeen(s.last_changed);
}

// "just now" / "5 minutes ago" / "3 hours ago" / "Yesterday" / date
function formatLastSeen(ts) {
  const diffMs = Date.now() - ts;
  const diffMin = Math.floor(diffMs / 60000);
  if (diffMin < 1) return 'just now';
  if (diffMin < 60) return diffMin + ' minutes ago';
  const diffHour = Math.floor(diffMin / 60);
  if (diffHour < 24) return diffHour + ' hours ago';
  const d = new Date(ts);
  const now = new Date();
  const yest = new Date(now); yest.setDate(now.getDate() - 1);
  if (d.toDateString() === yest.toDateString()) {
    return 'yesterday, ' + d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
  }
  return d.toLocaleDateString('en-US', { day: '2-digit', month: 'short', year: 'numeric' });
}

// Dengarkan node "directory" secara REAL-TIME (bukan sekali ambil saja),
// supaya kalau ada user lain yang mengganti nama / foto profil, daftar
// chat dan percakapan yang sedang terbuka langsung ikut ter-update tanpa
// perlu reload halaman.
function subscribeChatDirectory() {
  if (_chatDirRef) _chatDirRef.off();
  _chatDirRef = db.ref('directory');
  _chatDirRef.on('value', snap => {
    _chatDirectory = snap.exists() ? (snap.val() || {}) : {};
    _chatDirLoaded = true;
    renderChatList();              // refresh nama/foto di daftar chat
    renderDirectoryList();         // refresh nama/foto di halaman tambah teman
    refreshOpenConversationHeader(); // refresh header percakapan yg sedang dibuka
  }, err => console.error('Gagal memuat direktori pengguna (live):', err));
}

// Tulis/update entri profil publik saya sendiri di node "directory" supaya
// muncul di halaman "Add Friend" pengguna lain.
function syncMyDirectoryEntry(user) {
  db.ref('users/' + user.uid + '/profile').get().then(snap => {
    const profile = snap.exists() ? (snap.val() || {}) : {};
    const name = profile.displayName || user.displayName || (user.email ? user.email.split('@')[0] : 'User');
    const photo = profile.photoURL || profile.photoBase64 || user.photoURL || '';
    db.ref('directory/' + user.uid).set({
      displayName: name,
      photoURL: photo,
      updatedAt: Date.now()
    }).catch(err => console.error('Gagal sinkron direktori chat:', err));
  }).catch(() => {});
}

// ── Buka / tutup overlay chat ───────────────────────────────
function openChatOverlay() {
  // Kalau halaman lirik fullscreen sedang terbuka, tutup dulu supaya user
  // langsung diarahkan ke halaman Chat, bukan malah ketutupan lirik.
  if (typeof closeFSLyricsIfOpen === 'function') { closeFSLyricsIfOpen(); }
  // Tutup halaman Song Preview juga kalau sedang terbuka, supaya tidak
  // nyangkut di belakang halaman Chat.
  if (typeof closeSongPreviewIfOpen === 'function') { closeSongPreviewIfOpen(); }
  const mainEl = document.getElementById('main');
  if (mainEl) { mainEl.scrollTop = 0; mainEl.style.overflow = 'hidden'; }
  document.getElementById('chat-overlay').classList.add('show');
  showChatSubview('chat-list-view');
  // Sembunyikan tombol bulat "Lolu" (AI) beserta bubble sapaannya selama
  // halaman Chat terbuka, supaya tidak menutupi/mengganggu daftar chat
  // atau kotak tulis pesan (khususnya di mobile, karena posisinya fixed
  // di pojok kanan bawah).
  const aiFab = document.getElementById('ai-fab'); if (aiFab) aiFab.classList.add('hide');
  const aiFabBubble = document.getElementById('ai-fab-bubble'); if (aiFabBubble) aiFabBubble.classList.add('hide');
  // Khusus mobile: sembunyikan mini player (#bar) & buat halaman Chat
  // memenuhi layar penuh tanpa ruang kosong (lihat CSS body.chat-mobile-open).
  if (typeof isMobile === 'function' && isMobile()) document.body.classList.add('chat-mobile-open');
}
function closeChatOverlay() {
  document.getElementById('chat-overlay').classList.remove('show');
  const mainEl = document.getElementById('main');
  if (mainEl) mainEl.style.overflow = '';
  detachChatMessagesListener();
  if (_chatSelectMode) exitChatSelectMode();
  document.body.classList.remove('chat-mobile-open');
  document.body.classList.remove('chat-kb-open');
  // Tampilkan lagi tombol "Lolu" (AI) setelah keluar dari halaman Chat.
  const aiFab = document.getElementById('ai-fab'); if (aiFab) aiFab.classList.remove('hide');
  const aiFabBubble = document.getElementById('ai-fab-bubble'); if (aiFabBubble) aiFabBubble.classList.remove('hide');
}

// ── Auto-tutup halaman Chat saat tombol lain ditekan ─────────
// Selama overlay Chat terbuka, klik di mana pun DI LUAR overlay itu sendiri
// (mis. tombol sidebar lain, nav bawah di mobile, bell notifikasi, avatar
// profil, dst.) akan otomatis menutup halaman Chat — sama seperti membuka
// halaman lain. Klik pada tombol pembuka Chat sendiri dikecualikan karena
// sudah punya penanganan buka/tutupnya sendiri lewat openChatOverlay().
document.addEventListener('click', function(e) {
  const overlay = document.getElementById('chat-overlay');
  if (!overlay || !overlay.classList.contains('show')) return;
  if (overlay.contains(e.target)) return; // klik di dalam Chat sendiri, biarkan
  if (e.target.closest('#side-btn-chat, #mob-btn-chat')) return; // tombol Chat sendiri
  if (e.target.closest('#lib-collapse-btn')) return; // tombol expand/collapse Your Library — bukan navigasi halaman, jangan tutup Chat
  // FIX (bug: tap pesan di mobile malah menutup halaman Chat/kembali ke
  // tampilan awal): pengaman tambahan supaya interaksi apa pun dengan area
  // pesan (like, buka menu Reply/Delete, dst.) TIDAK PERNAH dianggap
  // "klik di luar Chat", bahkan di kondisi tepi (mis. render ulang bubble
  // yang sempat membuat e.target lepas dari DOM sesaat) yang bisa membuat
  // overlay.contains(e.target) di atas gagal mendeteksi dengan benar.
  if (e.target.closest && e.target.closest('#chat-messages, .chat-bubble-row, .chat-msg-like-btn, .chat-bubble-actions')) return;
  // Viewer foto/GIF fullscreen (#img-viewer) SENGAJA ditaruh di luar
  // #chat-overlay di DOM (supaya bisa dipakai ulang di halaman lain juga,
  // mis. foto komentar) — tapi ini menyebabkan bug: tap foto utk MENUTUP
  // viewer-nya (dari dalam Chat) ikut kebaca sebagai "klik di luar Chat",
  // sehingga bukan cuma viewer yang tertutup, halaman Chat-nya pun ikut
  // tertutup/ter-exit. Dikecualikan di sini supaya menutup viewer foto TIDAK
  // pernah ikut menutup Chat.
  if (e.target.closest('#img-viewer')) return;
  closeChatOverlay();
});
function showChatSubview(id) {
  document.querySelectorAll('.chat-subview').forEach(el => el.classList.remove('active'));
  const el = document.getElementById(id);
  if (el) el.classList.add('active');
}
function backToChatList() {
  detachChatMessagesListener();
  showChatSubview('chat-list-view');
}
function closeAddFriendView() {
  showChatSubview('chat-list-view');
}

// ── Inbox (daftar chat) ─────────────────────────────────────
function subscribeChatInbox() {
  if (!currentUser) return;
  if (_chatInboxRef) _chatInboxRef.off();
  _chatInboxRef = db.ref('userChats/' + currentUser.uid);
  _chatInboxRef.on('value', snap => {
    _chatInboxData = snap.exists() ? (snap.val() || {}) : {};
    syncChatListTypingListeners();
    renderChatList();
    updateChatUnreadBadge();
  }, err => console.error('Gagal memuat inbox chat:', err));
}

// Pasang/lepas listener "sedang mengetik" utk SETIAP chat yg tampil di
// daftar Chat — bukan cuma percakapan yg sedang dibuka — persis WhatsApp,
// yang menampilkan "mengetik..." langsung di daftar chat/inbox. Dipanggil
// setiap kali inbox berubah (chat baru masuk/dihapus), supaya listener
// selalu sinkron dengan chat yg benar2 sedang ditampilkan (tidak ada
// listener "menggantung" utk chat yg sudah dihapus dari daftar).
function syncChatListTypingListeners() {
  const chatIds = Object.keys(_chatInboxData || {});
  const wantedSet = new Set(chatIds);

  // Lepas listener utk chat yg sudah tidak ada lagi di inbox.
  Object.keys(_chatTypingListRefs).forEach(chatId => {
    if (!wantedSet.has(chatId)) {
      _chatTypingListRefs[chatId].off();
      delete _chatTypingListRefs[chatId];
      delete _chatTypingListCache[chatId];
    }
  });

  // Pasang listener baru utk chat yg belum punya listener.
  chatIds.forEach(chatId => {
    if (_chatTypingListRefs[chatId]) return; // sudah ada, tidak perlu dipasang ulang
    const peerUid = (_chatInboxData[chatId] || {}).with;
    if (!peerUid) return;
    const ref = db.ref('chats/' + chatId + '/typing/' + peerUid);
    _chatTypingListRefs[chatId] = ref;
    ref.on('value', snap => {
      const typing = snap.exists() && snap.val() === true;
      if (_chatTypingListCache[chatId] === typing) return; // tidak berubah, tidak perlu render ulang
      _chatTypingListCache[chatId] = typing;
      renderChatList();
    }, err => console.error('Gagal memuat status mengetik (daftar chat):', err));
  });
}

function renderChatList() {
  const wrap = document.getElementById('chat-list-items');
  const empty = document.getElementById('chat-list-empty');
  const reqSection = document.getElementById('chat-requests-section');
  const reqWrap = document.getElementById('chat-requests-items');
  const reqCountEl = document.getElementById('chat-requests-count');
  if (!wrap) return;

  const allEntries = Object.entries(_chatInboxData || {});
  // Chat biasa: sudah terhubung follow (di salah satu arah, lihat isChatVisibleInList).
  const regular = allEntries.filter(([, c]) => isChatVisibleInList(c.with));
  // Message Requests: BELUM terhubung follow, tapi sudah ada pesan asli
  // terkirim — supaya chat dari orang yang belum di-follow tetap kelihatan
  // (bukan hilang begitu saja), dan bisa dibalas maks 1x (lihat
  // getChatSendPermission()) sampai permintaan follow-nya diterima.
  const requests = allEntries.filter(([, c]) => isChatRequest(c.with, c));

  regular.sort((a, b) => (b[1].lastMessageAt || 0) - (a[1].lastMessageAt || 0));
  requests.sort((a, b) => (b[1].lastMessageAt || 0) - (a[1].lastMessageAt || 0));

  wrap.innerHTML = regular.map(([chatId, c]) => renderChatItemHTML(chatId, c, false)).join('');

  if (reqSection && reqWrap) {
    if (requests.length === 0) {
      reqWrap.innerHTML = '';
      reqSection.style.display = 'none';
    } else {
      reqSection.style.display = '';
      if (reqCountEl) reqCountEl.textContent = String(requests.length);
      reqWrap.innerHTML = requests.map(([chatId, c]) => renderChatItemHTML(chatId, c, true)).join('');
    }
  }

  if (empty) empty.style.display = (regular.length === 0 && requests.length === 0) ? 'flex' : 'none';
}

// Render satu baris di daftar chat (dipakai baik utk chat biasa maupun utk
// "Message Requests"). isRequest=true menambahkan label kecil "Permintaan"
// di sebelah nama. Saat mode pilih kontak aktif (_chatSelectMode), setiap
// baris menampilkan checkbox di depan supaya user bisa memilih kontak mana
// yang ingin dihapus lewat tombol "Delete Contact" di header (lihat
// toggleChatSelectMode()/deleteSelectedChatContacts()).
function renderChatItemHTML(chatId, c, isRequest) {
  // Pakai data terbaru dari node "directory" (live) kalau ada, supaya kalau
  // lawan bicara mengganti nama/foto profil, daftar chat langsung ikut
  // berubah — bukan memakai snapshot withName/withPhoto yang disimpan
  // sekali saja saat chat pertama kali dimulai.
  const live = _chatDirectory[c.with];
  const photo = (live && live.photoURL) || c.withPhoto || '';
  const name = (live && live.displayName) || c.withName || 'User';
  const avatarHTML = photo
    ? `<img src="${esc(photo)}" alt="" onerror="this.parentElement.innerHTML='&#128100;'">`
    : '&#128100;';
  const preview = c.lastMessage ? esc(c.lastMessage) : 'Start a conversation…';
  // Jumlah pesan belum dibaca dari pengirim ini (angka, bukan titik biru).
  const unreadCount = Number(c.unreadCount || 0);
  const dotHTML = getPeerOnlineDotHTML(c.with);
  const isChecked = _selectedChatIds.has(chatId);
  const checkboxHtml = _chatSelectMode
    ? `<div class="chat-checkbox-wrap"><div class="chat-checkbox"><svg viewBox="0 0 24 24" fill="none" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></div></div>`
    : '';
  // Sedang mengetik? Ganti sementara isi preview jadi "Typing..." + titik
  // berdenyut, ala WhatsApp — berlaku di daftar chat, bukan cuma saat
  // percakapannya sedang dibuka.
  const isTyping = !!_chatTypingListCache[chatId];
  const previewHTML = isTyping
    ? 'Typing<span class="chat-typing-dots"><span></span><span></span><span></span></span>'
    : preview;
  return `
    <div class="chat-item${_chatSelectMode ? ' selectable' : ''}${isChecked ? ' checked' : ''}" data-chatid="${esc(chatId)}" data-uid="${esc(c.with)}" data-name="${esc(name)}" data-photo="${esc(photo)}">
      ${checkboxHtml}
      <div class="chat-avatar-wrap">
        <div class="chat-avatar">${avatarHTML}</div>
        ${dotHTML}
      </div>
      <div class="chat-item-info">
        <div class="chat-item-name">${esc(name)}${isRequest ? '<span class="chat-request-tag">Request</span>' : ''}</div>
        <div class="chat-item-preview${unreadCount > 0 ? ' unread' : ''}${isTyping ? ' typing' : ''}">${previewHTML}</div>
      </div>
      <div class="chat-item-meta">
        <span class="chat-item-time">${formatChatTime(c.lastMessageAt)}</span>
        ${unreadCount > 0 ? `<span class="chat-unread-badge">${unreadCount > 99 ? '99+' : unreadCount}</span>` : ''}
      </div>
    </div>`;
}

// Delegasi klik utk daftar chat (aman terhadap nama yang mengandung tanda
// kutip/apostrof). Saat mode pilih kontak aktif, klik baris toggle centang
// (bukan membuka percakapan). Berlaku utk kedua daftar: chat biasa &
// Message Requests.
document.addEventListener('click', e => {
  const row = e.target.closest('#chat-list-items .chat-item, #chat-requests-items .chat-item');
  if (!row) return;
  if (_chatSelectMode) {
    toggleChatItemCheck(row.dataset.chatid);
    return;
  }
  openConversation(row.dataset.chatid, row.dataset.uid, row.dataset.name, row.dataset.photo);
});

// ── Mode pilih kontak untuk dihapus (tombol "Delete Contact" di header) ──
let _chatSelectMode = false;
let _selectedChatIds = new Set();

function toggleChatSelectMode() {
  if (_chatSelectMode) {
    exitChatSelectMode();
  } else {
    _chatSelectMode = true;
    _selectedChatIds.clear();
    const btn = document.getElementById('chat-deletecontact-toggle');
    if (btn) btn.classList.add('active');
    const bar = document.getElementById('chat-bulk-bar');
    if (bar) bar.classList.add('show');
    updateChatBulkBar();
    renderChatList();
  }
}

function exitChatSelectMode() {
  _chatSelectMode = false;
  _selectedChatIds.clear();
  const btn = document.getElementById('chat-deletecontact-toggle');
  if (btn) btn.classList.remove('active');
  const bar = document.getElementById('chat-bulk-bar');
  if (bar) bar.classList.remove('show');
  renderChatList();
}

function toggleChatItemCheck(chatId) {
  if (!chatId) return;
  if (_selectedChatIds.has(chatId)) {
    _selectedChatIds.delete(chatId);
  } else {
    _selectedChatIds.add(chatId);
  }
  updateChatBulkBar();
  const item = document.querySelector(`.chat-item[data-chatid="${CSS.escape(chatId)}"]`);
  if (item) item.classList.toggle('checked', _selectedChatIds.has(chatId));
}

function toggleChatSelectAll() {
  const allIds = Object.keys(_chatInboxData || {});
  const allSelected = allIds.length > 0 && allIds.every(id => _selectedChatIds.has(id));
  if (allSelected) {
    _selectedChatIds.clear();
  } else {
    allIds.forEach(id => _selectedChatIds.add(id));
  }
  renderChatList();
  updateChatBulkBar();
}

function updateChatBulkBar() {
  const count = _selectedChatIds.size;
  const countEl = document.getElementById('chat-bulk-count');
  const delBtn = document.getElementById('chat-bulk-delete-btn');
  const selAllBtn = document.getElementById('chat-bulk-selectall-btn');
  if (countEl) countEl.textContent = count + ' selected';
  if (delBtn) delBtn.disabled = count === 0;
  if (selAllBtn) {
    const allIds = Object.keys(_chatInboxData || {});
    const allSelected = allIds.length > 0 && allIds.every(id => _selectedChatIds.has(id));
    selAllBtn.textContent = allSelected ? 'Cancel selection' : 'Select all';
  }
}

// ── Hapus kontak terpilih SECARA PERMANEN ──────────────────────────────
// Beda dari fitur lama "hapus percakapan" (yang cuma menyembunyikan dari
// daftar chat saya sendiri): ini menghapus kontak dari daftar chat KEDUA
// pihak sekaligus MENGHAPUS TOTAL isi percakapannya (semua pesan) dari
// node "chats/", jadi begitu dihapus, isi percakapan langsung hilang
// permanen dan kontaknya juga langsung hilang dari daftar chat.
function deleteSelectedChatContacts() {
  if (!currentUser || _selectedChatIds.size === 0) return;
  const ids = [..._selectedChatIds];
  const label = ids.length === 1 ? 'kontak ini' : `${ids.length} contacts`;
  if (!confirm(`Delete ${label}? The entire conversation will be permanently deleted for both you and the other person, and cannot be undone.`)) return;

  const myUid = currentUser.uid;
  const updates = {};
  ids.forEach(chatId => {
    const c = _chatInboxData[chatId];
    const peerUid = c && c.with;
    updates['userChats/' + myUid + '/' + chatId] = null;
    if (peerUid) updates['userChats/' + peerUid + '/' + chatId] = null;
    updates['chats/' + chatId] = null; // hapus total isi percakapan (pesan) secara permanen
    // Kalau percakapan yang sedang dibuka termasuk yang dihapus, tutup dulu & kembali ke daftar chat.
    if (_chatCurrentPeer && _chatCurrentPeer.chatId === chatId) backToChatList();
  });

  db.ref().update(updates)
    .then(() => { toast('🗑️ Contact & conversation permanently deleted'); exitChatSelectMode(); })
    .catch(err => { console.error('Failed to delete contact:', err); toast('❌ Failed to delete contact'); });
}

// Total unread utk badge di tombol sidebar / mobile nav
function updateChatUnreadBadge() {
  const count = Object.values(_chatInboxData || {}).filter(c => Number(c.unreadCount || 0) > 0).length;
  const sideBadge = document.getElementById('side-chat-badge');
  const mobBadge = document.getElementById('mob-chat-badge');
  [sideBadge, mobBadge].forEach(b => {
    if (!b) return;
    b.textContent = count > 9 ? '9+' : String(count);
    b.classList.toggle('show', count > 0);
  });
}

// ── Add Friend (jelajahi semua pengguna) ──────────────────
function openAddFriendView() {
  showChatSubview('chat-addfriend-view');
  const search = document.getElementById('chat-user-search');
  if (search) search.value = '';
  // _chatDirectory sudah disinkronkan secara live oleh subscribeChatDirectory(),
  // jadi biasanya cukup render langsung dari cache (sudah pasti data terbaru).
  // Fallback ke fetch sekali kalau listener live-nya belum sempat memuat data.
  if (_chatDirLoaded) {
    renderDirectoryList();
  } else {
    loadDirectoryUsers();
  }
}

function loadDirectoryUsers() {
  const empty = document.getElementById('chat-directory-empty');
  db.ref('directory').get().then(snap => {
    _chatDirectory = snap.exists() ? (snap.val() || {}) : {};
    _chatDirLoaded = true;
    renderDirectoryList();
  }).catch(err => {
    console.error('Gagal memuat daftar pengguna:', err);
    if (empty) {
      empty.style.display = 'flex';
      empty.querySelector('h3').textContent = 'Failed to load users';
      empty.querySelector('p').textContent = 'Check your internet connection, then try again.';
    }
  });
}

function renderDirectoryList() {
  const wrap = document.getElementById('chat-directory-items');
  const empty = document.getElementById('chat-directory-empty');
  if (!wrap) return;
  const q = (document.getElementById('chat-user-search')?.value || '').toLowerCase().trim();
  const myUid = currentUser ? currentUser.uid : null;

  let entries = Object.entries(_chatDirectory || {}).filter(([uid]) => uid !== myUid);
  if (q) entries = entries.filter(([, u]) => (u.displayName || '').toLowerCase().includes(q));
  entries.sort((a, b) => (a[1].displayName || '').localeCompare(b[1].displayName || ''));

  if (entries.length === 0) {
    wrap.innerHTML = '';
    if (empty) {
      empty.style.display = 'flex';
      empty.querySelector('h3').textContent = q ? 'Not found' : 'No other users yet';
      empty.querySelector('p').textContent = q ? 'Try a different keyword' : 'Invite friends to sign up on Vibexa';
    }
    return;
  }
  if (empty) empty.style.display = 'none';

  wrap.innerHTML = entries.map(([uid, u]) => {
    const photo = u.photoURL || '';
    const avatarHTML = photo
      ? `<img src="${esc(photo)}" alt="" onerror="this.parentElement.innerHTML='&#128100;'">`
      : '&#128100;';
    const name = u.displayName || 'User';
    const dotHTML = getPeerOnlineDotHTML(uid);
    return `
      <div class="chat-item" data-uid="${esc(uid)}" data-name="${esc(name)}" data-photo="${esc(photo)}">
        <div class="chat-avatar-wrap">
          <div class="chat-avatar">${avatarHTML}</div>
          ${dotHTML}
        </div>
        <div class="chat-item-info">
          <div class="chat-item-name">${esc(name)}</div>
          <div class="chat-item-preview">Tap to view profile</div>
        </div>
      </div>`;
  }).join('');
}
// Delegasi klik utk daftar "Add Friend" — arahkan ke halaman PROFIL user
// tsb (bukan langsung buka chat). Dari profil, ada tombol Follow & Chat
// sendiri kalau user memang mau mulai percakapan.
document.addEventListener('click', e => {
  const row = e.target.closest('#chat-directory-items .chat-item');
  if (!row) return;
  window.location.href = 'profile.html?uid=' + encodeURIComponent(row.dataset.uid);
});

function filterDirectoryList() {
  if (!_chatDirLoaded) return;
  renderDirectoryList();
}

// Memulai / membuka chat dengan pengguna terpilih. Otomatis menambahkan
// kontak ini ke inbox KEDUA belah pihak, supaya user tujuan juga langsung
// bisa melihat & membalas chat ini.
// CATATAN: Dipanggil dari tombol "Chat" di halaman profil user lain (bukan
// lagi dari daftar "Add Friend" — di situ klik profil sekarang mengarah
// ke profile.html, lihat delegasi klik di atas). Membuka chat SELALU boleh
// kecuali permintaan follow saya sudah pernah ditolak (lihat
// canInitiateChatWith()); batasan "hanya 1 pesan teks & tanpa foto/GIF
// sebelum follow diterima" dicek per-pesan lewat getChatSendPermission().
async function startChatWithFriend(uid, name, photo) {
  if (!currentUser || !uid) return;
  const myUid = currentUser.uid;
  const chatId = chatIdFor(myUid, uid);

  const existing = _chatInboxData[chatId];
  const alreadyHasThread = !!(existing && existing.lastMessage);
  if (!alreadyHasThread) {
    const perm = await canInitiateChatWith(uid);
    if (!perm.ok) {
      toast(perm.message);
      return;
    }
  }

  db.ref('users/' + myUid + '/profile').get().then(snap => {
    const myProfile = snap.exists() ? (snap.val() || {}) : {};
    const myName = myProfile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const myPhoto = myProfile.photoURL || myProfile.photoBase64 || currentUser.photoURL || '';

    // Jangan timpa lastMessage yang sudah ada kalau chat sebelumnya sudah pernah dimulai
    const updates = {};
    updates['chats/' + chatId + '/participants/' + myUid] = true;
    updates['chats/' + chatId + '/participants/' + uid] = true;
    if (!existing) {
      const now = Date.now();
      updates['userChats/' + myUid + '/' + chatId] = { with: uid, withName: name, withPhoto: photo, lastMessage: '', lastMessageAt: now, unreadCount: 0 };
      updates['userChats/' + uid + '/' + chatId] = { with: myUid, withName: myName, withPhoto: myPhoto, lastMessage: '', lastMessageAt: now, unreadCount: 0 };
    }
    db.ref().update(updates).catch(err => console.error('Gagal memulai chat:', err))
      .finally(() => openConversation(chatId, uid, name, photo));
  });
}

// Dipanggil saat notifikasi "X menyukai pesanmu" di-klik — langsung buka
// overlay Chat dan arahkan ke percakapan dengan orang yang like pesan itu.
function openChatFromLikeNotif(n) {
  if (!n || !n.fromUid) return;
  document.getElementById('notif-panel')?.classList.remove('open');
  document.getElementById('notif-overlay')?.classList.remove('show');
  openChatOverlay();
  startChatWithFriend(n.fromUid, n.fromName || 'User', n.fromPhoto || '');
}

// ── Percakapan ───────────────────────────────────────────────
function openConversation(chatId, peerUid, peerName, peerPhoto) {
  detachChatMessagesListener();
  // Kalau ada data terbaru di node "directory" (live), pakai itu — supaya
  // percakapan langsung menampilkan nama/foto terbaru lawan bicara,
  // bukan data lama yang mungkin dibawa dari daftar chat.
  const live = _chatDirectory[peerUid];
  const name = (live && live.displayName) || peerName || 'User';
  const photo = (live && live.photoURL) || peerPhoto || '';
  _chatCurrentPeer = { uid: peerUid, name: name, photo: photo, chatId: chatId };

  const avatarEl = document.getElementById('chat-conv-avatar');
  avatarEl.innerHTML = photo
    ? `<img src="${esc(photo)}" alt="" onerror="this.parentElement.innerHTML='&#128100;'">`
    : '&#128100;';
  document.getElementById('chat-conv-name').textContent = name;
  renderConvStatusUI(peerUid);

  showChatSubview('chat-conv-view');
  document.getElementById('chat-messages').innerHTML = '';
  _chatPeerSeenAt = 0;
  _chatCurrentMessages = {};
  _chatReplyTarget = null;
  _chatOpenActionsKey = null;
  _chatOpenActionsMode = 'actions';
  renderReplyPreview();
  cancelChatMediaPreview(); // buang preview foto/video milik percakapan sebelumnya (kalau ada & tidak sedang upload)
  closeGifPicker();

  // Tandai sudah dibaca di sisi saya
  if (currentUser) {
    db.ref('userChats/' + currentUser.uid + '/' + chatId + '/unreadCount').set(0).catch(() => {});
    markChatSeen(chatId, currentUser.uid);
  }

  // Dengarkan status "dibaca" milik lawan bicara secara real-time — kalau
  // lawan bicara membuka percakapan ini, tampilkan "Dibaca · jam" di bawah
  // pesan terakhir yang saya kirim, seperti Instagram.
  _chatSeenRef = db.ref('chats/' + chatId + '/seen/' + peerUid);
  _chatSeenRef.on('value', snap => {
    _chatPeerSeenAt = snap.exists() ? (snap.val() || 0) : 0;
    renderChatMessages(_chatCurrentMessages);
  }, err => console.error('Gagal memuat status dibaca:', err));

  _chatMsgsRef = db.ref('chats/' + chatId + '/messages').orderByChild('ts').limitToLast(200);
  _chatMsgsRef.on('value', snap => {
    const val = snap.exists() ? (snap.val() || {}) : {};
    _chatCurrentMessages = val;
    renderChatMessages(val, true); // pesan baru masuk / percakapan baru dibuka → scroll ke pesan terbaru
    // Ada pesan baru masuk selagi percakapan ini terbuka → tandai langsung
    // dibaca supaya lawan bicara melihat status "Dibaca" secara real-time.
    if (currentUser) markChatSeen(chatId, currentUser.uid);
  }, err => console.error('Gagal memuat pesan:', err));

  // Dengarkan status "sedang mengetik" milik lawan bicara secara real-time,
  // persis seperti WhatsApp — label "Online"/"Terakhir dilihat..." di header
  // sementara diganti jadi "Mengetik..." selama node ini bernilai true.
  _peerIsTyping = false;
  _chatTypingRef = db.ref('chats/' + chatId + '/typing/' + peerUid);
  _chatTypingRef.on('value', snap => {
    _peerIsTyping = snap.exists() && snap.val() === true;
    renderConvStatusUI(peerUid);
  }, err => console.error('Gagal memuat status mengetik:', err));

  // Siapkan node typing milik SAYA di percakapan ini: kalau koneksi putus
  // tiba-tiba (tutup tab, internet mati), server otomatis menghapusnya —
  // sama seperti mekanisme onDisconnect() pada status online/offline.
  if (currentUser) {
    _chatMyTypingRef = db.ref('chats/' + chatId + '/typing/' + currentUser.uid);
    _chatMyTypingRef.onDisconnect().remove();
  }
  _chatMyTypingState = false;

  setTimeout(() => document.getElementById('chat-input')?.focus(), 150);
}

// Menyimpan timestamp "terakhir dibaca" milik user saat ini utk sebuah chat.
// Dibaca oleh lawan bicara utk menampilkan status "Dibaca · jam" ala Instagram.
function markChatSeen(chatId, uid) {
  db.ref('chats/' + chatId + '/seen/' + uid).set(Date.now()).catch(() => {});
}

// ── Kirim status "Sedang mengetik..." ke lawan bicara (ala WhatsApp) ───
// Dipanggil setiap kali saya mengetik di kolom pesan. Supaya tidak menulis
// ke database di SETIAP ketikan huruf (boros write), node "typing" hanya
// ditulis SEKALI saat mulai mengetik (true), lalu otomatis dihapus lagi
// setelah user berhenti mengetik selama beberapa detik (idle timeout) —
// atau segera setelah pesan benar-benar terkirim.
const CHAT_TYPING_IDLE_MS = 2500;

// ── Kolom ketik memanjang otomatis ke atas (ala WhatsApp) ──────────────
// Dipanggil setiap kali user mengetik. Tinggi textarea disesuaikan dengan
// isi teks (tumbuh ke atas), dibatasi CHAT_INPUT_MAX_HEIGHT supaya tidak
// memakan seluruh layar kalau teksnya sangat panjang — setelah itu baru
// discroll secara internal.
const CHAT_INPUT_MAX_HEIGHT = 132; // px, kira-kira 5-6 baris — cocok dgn CSS max-height #chat-input

function autoResizeChatInput(el) {
  if (!el) return;
  el.style.height = 'auto';
  const next = Math.min(el.scrollHeight, CHAT_INPUT_MAX_HEIGHT);
  el.style.height = next + 'px';
  el.style.overflowY = el.scrollHeight > CHAT_INPUT_MAX_HEIGHT ? 'auto' : 'hidden';
}

// Menampilkan/menyembunyikan tombol attach & GIF di sebelah kiri kolom
// ketik. Saat kolom ketik difokuskan (atau masih berisi teks), tombol2
// tsb menciut otomatis supaya kolom ketik melebar ke kiri dan user lebih
// leluasa mengetik — dipulihkan lagi begitu kolom kosong & tidak difokus.
function updateChatInputBarState() {
  const bar = document.querySelector('.chat-input-bar');
  const inputEl = document.getElementById('chat-input');
  if (!bar || !inputEl) return;
  const hasText = inputEl.value.trim().length > 0;
  const isFocused = document.activeElement === inputEl;
  bar.classList.toggle('chat-input-bar--focused', hasText || isFocused);
}

function onChatInputFocus() {
  updateChatInputBarState();
}

function onChatInputBlur() {
  updateChatInputBarState();
}

function onChatInputTyping() {
  autoResizeChatInput(document.getElementById('chat-input'));
  updateChatInputBarState();
  if (!_chatMyTypingRef || !_chatCurrentPeer) return;
  const inputEl = document.getElementById('chat-input');
  const hasText = !!(inputEl && inputEl.value.trim().length > 0);

  clearTimeout(_chatTypingStopTimer);

  if (hasText) {
    if (!_chatMyTypingState) {
      _chatMyTypingState = true;
      _chatMyTypingRef.set(true).catch(err => console.error('Gagal mengirim status mengetik:', err));
    }
    // Reset hitung mundur setiap kali user masih mengetik — status baru
    // dihapus kalau benar-benar berhenti (idle) selama CHAT_TYPING_IDLE_MS.
    _chatTypingStopTimer = setTimeout(stopChatTyping, CHAT_TYPING_IDLE_MS);
  } else {
    // Kolom pesan dikosongkan (mis. dihapus semua) → langsung tandai berhenti.
    stopChatTyping();
  }
}

// Menandai diri "berhenti mengetik" — dipanggil saat idle timeout, saat
// pesan terkirim, atau saat percakapan ditutup/dipindah.
function stopChatTyping() {
  clearTimeout(_chatTypingStopTimer);
  _chatTypingStopTimer = null;
  if (_chatMyTypingState && _chatMyTypingRef) {
    _chatMyTypingState = false;
    _chatMyTypingRef.remove().catch(() => {});
  }
}

// Menekan foto profil / nama lawan bicara di header percakapan → buka
// halaman profil milik user tersebut.
function goToPeerProfile() {
  if (!_chatCurrentPeer || !_chatCurrentPeer.uid) return;
  window.location.href = 'profile.html?uid=' + encodeURIComponent(_chatCurrentPeer.uid);
}

function detachChatMessagesListener() {
  if (_chatMsgsRef) { _chatMsgsRef.off(); _chatMsgsRef = null; }
  if (_chatSeenRef) { _chatSeenRef.off(); _chatSeenRef = null; }
  if (_chatTypingRef) { _chatTypingRef.off(); _chatTypingRef = null; }
  // Saya pindah/tutup percakapan → langsung bersihkan status "mengetik" milik
  // saya sendiri di percakapan ini, supaya tidak "nyangkut" jadi true selamanya.
  clearTimeout(_chatTypingStopTimer);
  _chatTypingStopTimer = null;
  if (_chatMyTypingRef) {
    _chatMyTypingRef.onDisconnect().cancel();
    if (_chatMyTypingState) _chatMyTypingRef.remove().catch(() => {});
    _chatMyTypingRef = null;
  }
  _chatMyTypingState = false;
  _peerIsTyping = false;
  _chatCurrentPeer = null;
  _chatPeerSeenAt = 0;
  _chatCurrentMessages = {};
  _chatReplyTarget = null;
  _chatOpenActionsKey = null;
  _chatOpenActionsMode = 'actions';
  closeGifPicker();
}

// Dipanggil setiap kali node "directory" berubah. Kalau percakapan sedang
// terbuka dengan lawan bicara yang profilnya just now diubah, langsung
// perbarui nama & foto di header percakapan secara real-time.
function refreshOpenConversationHeader() {
  if (!_chatCurrentPeer) return;
  const live = _chatDirectory[_chatCurrentPeer.uid];
  if (live) {
    const name = live.displayName || _chatCurrentPeer.name || 'User';
    const photo = live.photoURL || _chatCurrentPeer.photo || '';
    if (name !== _chatCurrentPeer.name || photo !== _chatCurrentPeer.photo) {
      _chatCurrentPeer.name = name;
      _chatCurrentPeer.photo = photo;
      const nameEl = document.getElementById('chat-conv-name');
      const avatarEl = document.getElementById('chat-conv-avatar');
      if (nameEl) nameEl.textContent = name;
      if (avatarEl) {
        avatarEl.innerHTML = photo
          ? `<img src="${esc(photo)}" alt="" onerror="this.parentElement.innerHTML='&#128100;'">`
          : '&#128100;';
      }
    }
  }
  // Status online/terakhir dilihat dicek terpisah dari nama/foto, supaya
  // tetap ter-update real-time walau nama/foto lawan bicara tidak berubah.
  renderConvStatusUI(_chatCurrentPeer.uid);
}

// Set titik online + label "Online" / "Terakhir dilihat ..." di header percakapan.
// Kalau lawan bicara sedang mengetik, label ini diganti sementara jadi
// "Mengetik..." dengan titik-titik berdenyut, persis ala WhatsApp — dan
// akan kembali sendiri ke label online/last-seen begitu berhenti mengetik.
function renderConvStatusUI(uid) {
  const dotEl = document.getElementById('chat-conv-dot');
  const statusEl = document.getElementById('chat-conv-status');
  if (!dotEl || !statusEl) return;
  const s = _chatStatusCache[uid];
  const online = !!(s && s.state === 'online');
  dotEl.style.display = online ? '' : 'none';

  if (_chatCurrentPeer && _chatCurrentPeer.uid === uid && _peerIsTyping) {
    statusEl.innerHTML = 'Typing<span class="chat-typing-dots"><span></span><span></span><span></span></span>';
    statusEl.classList.add('online', 'typing');
    return;
  }
  statusEl.classList.remove('typing');
  statusEl.textContent = formatPeerStatusLabel(uid);
  statusEl.classList.toggle('online', online);
}

function renderChatMessages(msgsObj, scrollToBottom) {
  const wrap = document.getElementById('chat-messages');
  if (!wrap) return;
  const myUid = currentUser ? currentUser.uid : null;

  // Sembunyikan pesan yang saya hapus "untuk saya" — pesan tsb tetap ada
  // di database (lawan bicara masih bisa melihatnya), hanya disaring dari
  // tampilan saya sendiri.
  const list = Object.entries(msgsObj)
    .filter(([, m]) => !(myUid && m.deletedFor && m.deletedFor[myUid]))
    .sort((a, b) => (a[1].ts || 0) - (b[1].ts || 0));

  // Cari key pesan terakhir yang saya kirim → hanya pesan itu yang
  // menampilkan status "Terkirim" / "Dibaca", persis seperti Instagram
  // (bukan per-pesan seperti centang WhatsApp).
  let lastMineKey = null;
  list.forEach(([key, m]) => { if (m.from === myUid) lastMineKey = key; });

  let lastDateKey = '';
  const html = list.map(([key, m]) => {
    const mine = m.from === myUid;
    const deleted = !!m.deletedForEveryone;

    let sepHTML = '';
    if (m.ts) {
      const dateKey = new Date(m.ts).toDateString();
      if (dateKey !== lastDateKey) {
        lastDateKey = dateKey;
        sepHTML = `<div class="chat-date-sep"><span>${formatChatDateSeparator(m.ts)}</span></div>`;
      }
    }

    let quoteHTML = '';
    if (m.replyTo && !deleted) {
      const rt = m.replyTo;
      const rtName = rt.from === myUid ? 'You' : (rt.name || (_chatCurrentPeer && _chatCurrentPeer.name) || 'User');
      quoteHTML = `
        <div class="chat-bubble-quote" data-gotokey="${esc(rt.key || '')}">
          <div class="chat-bubble-quote-body">
            <div class="chat-bubble-quote-name">${esc(rtName)}</div>
            <div class="chat-bubble-quote-text">${esc(rt.text || 'Message')}</div>
          </div>
        </div>`;
    }

    let bubbleHTML;
    if (deleted) {
      bubbleHTML = `<div class="chat-bubble chat-bubble-deleted">
           <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M9.5 9.5 14.5 14.5M14.5 9.5 9.5 14.5"/></svg>
           This message has been deleted
         </div>`;
    } else if (m.type === 'image' && m.mediaUrl) {
      bubbleHTML = `<div class="chat-bubble-media" onclick="event.stopPropagation();openImgViewer('${esc(m.mediaUrl)}')">
           <img src="${esc(m.mediaUrl)}" alt="Photo" loading="lazy">
         </div>${m.text ? `<div class="chat-bubble-caption">${esc(m.text)}</div>` : ''}`;
    } else if (m.type === 'video' && m.mediaUrl) {
      bubbleHTML = `<div class="chat-bubble-media" onclick="event.stopPropagation();">
           <video src="${esc(m.mediaUrl)}" controls preload="metadata" playsinline></video>
         </div>${m.text ? `<div class="chat-bubble-caption">${esc(m.text)}</div>` : ''}`;
    } else if (m.type === 'gif' && m.mediaUrl) {
      bubbleHTML = `<div class="chat-bubble-media" onclick="event.stopPropagation();openImgViewer('${esc(m.mediaUrl)}')">
           <span class="chat-bubble-gif-badge">GIF</span>
           <img src="${esc(m.mediaUrl)}" alt="GIF" loading="lazy">
         </div>${m.text ? `<div class="chat-bubble-caption">${esc(m.text)}</div>` : ''}`;
    } else {
      // Kalau pesannya cuma emoji (dan bukan balasan pesan lain, karena
      // kutipan balasan butuh latar bubble supaya tetap terbaca), tampilkan
      // besar & tanpa background — mirip WhatsApp/Telegram. Emoji apa pun
      // yang dipilih user lewat keyboard tetap didukung, tidak dibatasi.
      const msgText = m.text || '';
      const emojiOnly = !quoteHTML && isChatEmojiOnlyMessage(msgText);
      bubbleHTML = `<div class="chat-bubble${emojiOnly ? ' chat-bubble-emoji-only' : ''}">${esc(msgText)}</div>`;
    }

    let readHTML = '';
    if (mine && key === lastMineKey) {
      const seen = _chatPeerSeenAt && _chatPeerSeenAt >= (m.ts || 0);
      readHTML = seen
        ? `<div class="chat-read-status seen">Read · ${formatChatTime(_chatPeerSeenAt)}</div>`
        : `<div class="chat-read-status">Sent</div>`;
    }

    let actionsHTML = '';
    if (!deleted && _chatOpenActionsKey === key) {
      if (_chatOpenActionsMode === 'confirm-delete') {
        actionsHTML = `
          <div class="chat-bubble-actions open">
            <button class="cba-btn" data-act="delete-me" data-key="${key}">Delete for me</button>
            ${mine ? `<button class="cba-btn danger" data-act="delete-everyone" data-key="${key}">Delete for everyone</button>` : ''}
            <button class="cba-btn" data-act="cancel-delete" data-key="${key}">Cancel</button>
          </div>`;
      } else {
        actionsHTML = `
          <div class="chat-bubble-actions open">
            <button class="cba-btn" data-act="reply" data-key="${key}">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 14 4 9l5-5"/><path d="M4 9h11a5 5 0 0 1 0 10h-1"/></svg>
              Reply
            </button>
            <button class="cba-btn danger" data-act="ask-delete" data-key="${key}">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m3 0-1 14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2L4 6"/></svg>
              Delete
            </button>
          </div>`;
      }
    }

    // Like pesan (ala Instagram): tombol hati muncul saat hover di desktop,
    // dan tekan-tahan 1 detik di mobile (lihat listener 'touchstart' di bawah). Status
    // like disimpan per-uid di m.likes supaya kedua pihak bisa like pesan
    // yang sama secara independen.
    let likeBtnHTML = '';
    if (!deleted) {
      const iLiked = !!(myUid && m.likes && m.likes[myUid]);
      likeBtnHTML = `
        <button type="button" class="chat-msg-like-btn${iLiked ? ' liked' : ''}" data-act="like-msg" data-key="${key}" title="${iLiked ? 'Unlike' : 'Like'}" aria-label="Like message">
          <svg viewBox="0 0 24 24" fill="${iLiked ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 21s-6.7-4.34-9.3-8.24C1 10.02 1.6 6.6 4.3 5.06c2.3-1.31 4.9-.5 6.3 1.4L12 8l1.4-1.54c1.4-1.9 4-2.71 6.3-1.4 2.7 1.54 3.3 4.96 1.6 7.7C18.7 16.66 12 21 12 21z"/></svg>
        </button>`;
    }

    return `${sepHTML}
      <div class="chat-bubble-row ${mine ? 'me' : 'them'}" data-msgkey="${key}">
        ${quoteHTML}
        <div class="chat-bubble-wrap">
          ${likeBtnHTML}
          ${bubbleHTML}
        </div>
        <div class="chat-bubble-time">${formatChatTime(m.ts)}</div>
        ${readHTML}
        ${actionsHTML}
      </div>`;
  }).join('');

  // FIX (bug: menekan pesan di paling atas malah "menurunkan" halaman ke
  // paling bawah): sebelumnya wrap.scrollTop = wrap.scrollHeight dipanggil
  // di SETIAP render, termasuk render ulang gara-gara buka/tutup menu
  // Reply/Delete atau like/unlike pesan yang sudah ada — jadi setiap
  // interaksi kecil sekalipun langsung melempar posisi scroll ke paling
  // bawah. Sekarang posisi scroll saat ini disimpan dulu SEBELUM DOM
  // diganti, lalu dikembalikan lagi persis di posisi yang sama — kecuali
  // caller memang secara eksplisit minta scroll ke bawah (parameter
  // scrollToBottom, dipakai saat pesan baru masuk / percakapan baru dibuka).
  const prevScrollTop = wrap.scrollTop;
  const prevScrollHeight = wrap.scrollHeight;
  wrap.innerHTML = html;
  if (scrollToBottom) {
    wrap.scrollTop = wrap.scrollHeight;
  } else {
    // Selisih tinggi konten (kalau ada, mis. menu aksi baru saja
    // dibuka/ditutup) diperhitungkan supaya posisi pesan yang sedang
    // dilihat user tetap persis di tempat yang sama, tidak ikut geser.
    wrap.scrollTop = prevScrollTop + (wrap.scrollHeight - prevScrollHeight);
  }
}

// Delegasi klik utk seluruh interaksi di area pesan: buka/tutup menu aksi
// (Balas/Hapus) saat bubble ditekan, dan tombol-tombol di dalam menu itu.
document.addEventListener('click', e => {
  const wrap = document.getElementById('chat-messages');
  if (!wrap || !wrap.contains(e.target)) return;

  const actBtn = e.target.closest('.cba-btn');
  if (actBtn) {
    handleBubbleAction(actBtn.dataset.act, actBtn.dataset.key);
    return;
  }

  const likeBtn = e.target.closest('.chat-msg-like-btn');
  if (likeBtn) {
    e.stopPropagation();
    toggleChatMessageLike(likeBtn.dataset.key);
    return;
  }

  const quote = e.target.closest('.chat-bubble-quote');
  if (quote) {
    const target = quote.dataset.gotokey;
    if (target) {
      const row = wrap.querySelector(`.chat-bubble-row[data-msgkey="${CSS.escape(target)}"]`);
      if (row) { row.scrollIntoView({ behavior: 'smooth', block: 'center' }); }
    }
    return;
  }

  const bubble = e.target.closest('.chat-bubble:not(.chat-bubble-deleted), .chat-bubble-caption');
  if (bubble) {
    const row = bubble.closest('.chat-bubble-row');
    const key = row && row.dataset.msgkey;
    if (!key) return;
    _chatOpenActionsKey = (_chatOpenActionsKey === key) ? null : key;
    _chatOpenActionsMode = 'actions';
    renderChatMessages(_chatCurrentMessages);
  }
});

// Tekan-tahan (long-press) 1 detik di mobile utk like pesan, ala
// Instagram — BUKAN double-tap. Dipasang lewat touchstart/touchmove/
// touchend (bukan 'click') supaya tetap terdeteksi walau elemen di dalam
// bubble (foto/video) punya onclick sendiri dengan stopPropagation.
const CHAT_LONG_PRESS_MS = 1000;   // lama tekan supaya dianggap "like"
const CHAT_LONG_PRESS_MOVE_TOLERANCE = 10; // px toleransi geser jari sebelum dianggap scroll (batal like)

function _clearChatLongPress() {
  if (_chatLongPressTimer) { clearTimeout(_chatLongPressTimer); _chatLongPressTimer = null; }
  _chatLongPressKey = null;
  _chatLongPressStartXY = null;
  _chatLongPressMoved = false;
}

document.addEventListener('touchstart', e => {
  const wrap = document.getElementById('chat-messages');
  if (!wrap || !wrap.contains(e.target)) return;
  const bubbleTarget = e.target.closest('.chat-bubble:not(.chat-bubble-deleted), .chat-bubble-media, .chat-bubble-caption');
  if (!bubbleTarget) return;
  const row = e.target.closest('.chat-bubble-row');
  const key = row && row.dataset.msgkey;
  if (!key) return;

  _clearChatLongPress();
  _chatLongPressFired = false;
  _chatLongPressKey = key;
  const t = e.touches[0];
  _chatLongPressStartXY = { x: t.clientX, y: t.clientY };
  _chatLongPressTimer = setTimeout(() => {
    _chatLongPressTimer = null;
    if (_chatLongPressMoved || _chatLongPressKey !== key) return; // jari sudah geser/beda pesan → batal
    _chatLongPressFired = true; // tandai supaya 'click' yg menyusul (saat jari diangkat) tidak buka menu aksi
    if (navigator.vibrate) { try { navigator.vibrate(15); } catch (e2) {} } // getaran halus sbg feedback, kalau didukung
    toggleChatMessageLike(key, row);
  }, CHAT_LONG_PRESS_MS);
}, { passive: true });

document.addEventListener('touchmove', e => {
  if (!_chatLongPressKey || !_chatLongPressStartXY) return;
  const t = e.touches[0];
  const dx = t.clientX - _chatLongPressStartXY.x;
  const dy = t.clientY - _chatLongPressStartXY.y;
  if (Math.abs(dx) > CHAT_LONG_PRESS_MOVE_TOLERANCE || Math.abs(dy) > CHAT_LONG_PRESS_MOVE_TOLERANCE) {
    _chatLongPressMoved = true;
    _clearChatLongPress(); // jari lagi scroll, bukan menekan-tahan pesan → batalkan
  }
}, { passive: true });

document.addEventListener('touchend', e => {
  // Kalau timer belum sempat menyala (tekan-tahan belum genap 1 detik),
  // batalkan saja — ini jadi tap biasa (buka/tutup menu Balas/Hapus lewat
  // listener 'click' seperti biasa).
  _clearChatLongPress();
  if (_chatLongPressFired) {
    // Like sudah terpicu lewat tekan-tahan → cegah "ghost click" yang
    // menyusul supaya TIDAK ikut membuka menu aksi Balas/Hapus.
    e.preventDefault();
    _chatLongPressFired = false;
  }
}, { passive: false });

document.addEventListener('touchcancel', () => { _clearChatLongPress(); _chatLongPressFired = false; });

function handleBubbleAction(act, key) {
  const chatId = _chatCurrentPeer && _chatCurrentPeer.chatId;
  if (!chatId || !key) return;
  if (act === 'reply') {
    startReply(key);
    _chatOpenActionsKey = null;
    renderChatMessages(_chatCurrentMessages);
  } else if (act === 'ask-delete') {
    _chatOpenActionsKey = key;
    _chatOpenActionsMode = 'confirm-delete';
    renderChatMessages(_chatCurrentMessages);
  } else if (act === 'cancel-delete') {
    _chatOpenActionsMode = 'actions';
    renderChatMessages(_chatCurrentMessages);
  } else if (act === 'delete-me') {
    deleteMessageForMe(chatId, key);
    _chatOpenActionsKey = null;
    renderChatMessages(_chatCurrentMessages);
  } else if (act === 'delete-everyone') {
    deleteMessageForEveryone(chatId, key);
    _chatOpenActionsKey = null;
    renderChatMessages(_chatCurrentMessages);
  }
}

// ── Like pesan chat (ala Instagram) ─────────────────────────────────────
// Toggle like SAYA sendiri utk satu pesan. Disimpan di
// chats/{chatId}/messages/{key}/likes/{myUid} = true, supaya kedua pihak
// bisa like pesan yang sama secara independen (dan dihapus lagi kalau
// di-tap/klik ulang, sama seperti Instagram).
async function toggleChatMessageLike(key, rowEl) {
  if (!currentUser || !_chatCurrentPeer || !_chatCurrentPeer.chatId || !key) return;
  const m = _chatCurrentMessages[key];
  if (!m || m.deletedForEveryone) return;

  const chatId = _chatCurrentPeer.chatId;
  const myUid = currentUser.uid;
  const alreadyLiked = !!(m.likes && m.likes[myUid]);
  const likeRef = db.ref('chats/' + chatId + '/messages/' + key + '/likes/' + myUid);

  // Update optimistik lokal supaya UI langsung terasa responsif, listener
  // realtime akan menimpanya lagi dengan data server begitu sinkron.
  m.likes = m.likes || {};
  if (alreadyLiked) {
    delete m.likes[myUid];
  } else {
    m.likes[myUid] = true;
  }
  renderChatMessages(_chatCurrentMessages);
  // Panggil burst SETELAH render, karena render menimpa ulang innerHTML
  // (elemen burst yg ditambah sebelum render akan langsung terhapus lagi).
  if (!alreadyLiked) spawnChatHeartBurst(key);

  try {
    if (alreadyLiked) {
      await likeRef.remove();
    } else {
      await likeRef.set(true);
      // Jangan kirim notifikasi like ke diri sendiri (pesan sendiri yang di-like sendiri)
      if (m.from && m.from !== myUid) {
        sendChatMessageLikeNotif(m, key, chatId);
      }
    }
  } catch (err) {
    console.warn('Gagal update like pesan:', err);
  }
}

// Kirim notifikasi in-app + push notification ke pemilik pesan yang di-like,
// mirip alur notifikasi like playlist (lihat toggleLike()).
async function sendChatMessageLikeNotif(msg, key, chatId) {
  try {
    const ownerUid = msg.from;
    const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(() => null);
    const profile = profileSnap?.val() || {};
    const fromName = profile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const fromPhoto = profile.photoURL || profile.photoBase64 || currentUser.photoURL || '';

    let preview = (msg.text || '').toString().trim();
    if (!preview) {
      if (msg.type === 'image') preview = 'Photo';
      else if (msg.type === 'video') preview = 'Video';
      else if (msg.type === 'gif') preview = 'GIF';
      else preview = 'Message';
    }

    const notif = {
      type: 'chat_like',
      fromUid: currentUser.uid,
      fromName,
      fromPhoto,
      chatId,
      msgKey: key,
      msgPreview: preview.slice(0, 100),
      ts: Date.now(),
      read: false
    };
    db.ref('users/' + ownerUid + '/notifications').push(notif).catch(() => {});

    // Push notification ala WhatsApp walau app/tab lagi tertutup, pakai
    // Worker yang sama dengan notifikasi pesan chat biasa.
    triggerChatPushNotification(
      { uid: ownerUid, chatId },
      `${fromName} menyukai pesanmu: "${preview.slice(0, 60)}"`
    );
  } catch (e) {
    console.warn('sendChatMessageLikeNotif error:', e);
  }
}

// Animasi hati besar muncul-lalu-menghilang di tengah bubble saat di-like,
// persis efek double-tap di Instagram.
function spawnChatHeartBurst(key, rowEl) {
  const row = rowEl || document.querySelector(`.chat-bubble-row[data-msgkey="${CSS.escape(key)}"]`);
  const wrap = row && row.querySelector('.chat-bubble-wrap');
  if (!wrap) return;
  const burst = document.createElement('div');
  burst.className = 'chat-heart-burst';
  burst.innerHTML = '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>';
  wrap.appendChild(burst);
  setTimeout(() => burst.remove(), 800);
}

// Menyimpan pesan yg akan dibalas & menampilkan preview-nya di atas kotak input.
function startReply(key) {
  const m = _chatCurrentMessages[key];
  if (!m || m.deletedForEveryone) return;
  const myUid = currentUser ? currentUser.uid : null;
  const mine = m.from === myUid;
  const name = mine ? 'You' : ((_chatCurrentPeer && _chatCurrentPeer.name) || 'User');
  _chatReplyTarget = { key: key, text: m.text || '', from: m.from, name: name };
  renderReplyPreview();
  document.getElementById('chat-input')?.focus();
}

function cancelReply() {
  _chatReplyTarget = null;
  renderReplyPreview();
}

function renderReplyPreview() {
  const wrap = document.getElementById('chat-reply-preview');
  if (!wrap) return;
  if (!_chatReplyTarget) {
    wrap.classList.remove('show');
    return;
  }
  const nameEl = document.getElementById('chat-reply-preview-name');
  const textEl = document.getElementById('chat-reply-preview-text');
  if (nameEl) nameEl.textContent = 'Membalas ' + _chatReplyTarget.name;
  if (textEl) textEl.textContent = _chatReplyTarget.text || '';
  wrap.classList.add('show');
}

// Hapus pesan hanya utk saya sendiri — pesan tetap ada bagi lawan bicara.
function deleteMessageForMe(chatId, key) {
  if (!currentUser) return;
  db.ref('chats/' + chatId + '/messages/' + key + '/deletedFor/' + currentUser.uid).set(true).catch(err => console.error('Gagal menghapus pesan:', err));
}

// Hapus pesan utk semua orang — hanya berlaku utk pesan milik sendiri.
// Isi teksnya dikosongkan & ditandai deletedForEveryone, lalu semua
// perangkat (termasuk milik lawan bicara) akan menampilkan placeholder
// "Pesan ini telah dihapus".
function deleteMessageForEveryone(chatId, key) {
  if (!currentUser) return;
  const m = _chatCurrentMessages[key];
  if (!m || m.from !== currentUser.uid) return; // jaga-jaga: hanya pesan sendiri

  const updates = {};
  updates['chats/' + chatId + '/messages/' + key + '/text'] = '';
  updates['chats/' + chatId + '/messages/' + key + '/deletedForEveryone'] = true;
  updates['chats/' + chatId + '/messages/' + key + '/deletedBy'] = currentUser.uid;

  // Kalau pesan yg dihapus ini adalah pesan TERAKHIR di chat (dilihat dari ts-nya),
  // preview "lastMessage" di halaman Chat juga perlu ikut diperbarui. Sebelumnya
  // preview tsb tidak pernah disentuh saat delete-for-everyone, jadi teks lama
  // tetap nongol di halaman Chat walau bubble-nya sendiri sudah jadi placeholder.
  const allMsgs = _chatCurrentMessages || {};
  const myTs = m.ts || 0;
  let isLatest = true;
  for (const k in allMsgs) {
    if (k === key) continue;
    const other = allMsgs[k];
    if (other && (other.ts || 0) > myTs) { isLatest = false; break; }
  }

  if (isLatest && _chatCurrentPeer) {
    const myUid = currentUser.uid;
    const peerUid = _chatCurrentPeer.uid;
    const placeholder = 'This message has been deleted';
    updates['userChats/' + myUid + '/' + chatId + '/lastMessage'] = placeholder;
    updates['userChats/' + peerUid + '/' + chatId + '/lastMessage'] = placeholder;
  }

  db.ref().update(updates)
    .then(() => {
      // Notifikasi ala WhatsApp: kalau pesan yg baru dihapus ini yg lagi
      // tampil sbg notifikasi push di HP lawan bicara, minta ikut hilang.
      if (_chatCurrentPeer) triggerCloseChatNotification(_chatCurrentPeer);
    })
    .catch(err => console.error('Gagal menghapus pesan:', err));

  // Juga tutup di device sendiri (mis. ada tab/jendela lain yg kebetulan
  // masih menampilkan notifikasi utk chat ini).
  if (currentUser) closeNotificationsByTag(`chat_${currentUser.uid}`);
}

// ── Deteksi pesan "cuma emoji" (utk tampilan bubble besar tanpa background,
//    ala WhatsApp/Telegram) ───────────────────────────────────────────────
// Sengaja TIDAK memakai daftar emoji tertentu / whitelist — semua emoji Unicode
// (termasuk emoji gabungan/ZWJ, bendera, dan varian warna kulit) dianggap valid,
// jadi user bebas pilih emoji apa saja lewat keyboard emoji bawaan HP-nya.
// Batas hanya pada JUMLAH karakter emoji dalam satu pesan (maks 10), semata-mata
// supaya tampilan besar tetap rapi, bukan membatasi jenis emojinya.
const CHAT_EMOJI_ONLY_MAX_COUNT = 10;
function isChatEmojiOnlyMessage(text) {
  if (!text) return false;
  const trimmed = String(text).trim();
  if (!trimmed) return false;
  try {
    if (typeof Intl !== 'undefined' && Intl.Segmenter) {
      const seg = new Intl.Segmenter('en', { granularity: 'grapheme' });
      const graphemes = Array.from(seg.segment(trimmed), s => s.segment).filter(g => g.trim() !== '');
      if (!graphemes.length || graphemes.length > CHAT_EMOJI_ONLY_MAX_COUNT) return false;
      const EMOJI_CHAR_RE = /\p{Extended_Pictographic}|[\u{1F1E6}-\u{1F1FF}]|[\u{1F3FB}-\u{1F3FF}]|\u200D|\uFE0F|\u20E3/u;
      return graphemes.every(g => EMOJI_CHAR_RE.test(g));
    }
  } catch (e) { /* lanjut ke fallback di bawah kalau Intl.Segmenter bermasalah */ }
  // Fallback (browser tanpa Intl.Segmenter) — tetap tidak membatasi jenis emoji.
  const EMOJI_ONLY_FALLBACK_RE = /^(?:\p{Extended_Pictographic}\uFE0F?(?:\u200D\p{Extended_Pictographic}\uFE0F?)*|[\u{1F1E6}-\u{1F1FF}]{2}|[0-9#\*]\uFE0F?\u20E3|[\u{1F3FB}-\u{1F3FF}]\s*)+$/u;
  return trimmed.length <= 40 && EMOJI_ONLY_FALLBACK_RE.test(trimmed);
}

// WhatsApp-style date separator label: "Today", "Yesterday", or the
// full date (e.g. "July 14, 2026") for earlier days.
function formatChatDateSeparator(ts) {
  const d = new Date(ts);
  const now = new Date();
  if (d.toDateString() === now.toDateString()) return 'Today';
  const yest = new Date(now); yest.setDate(now.getDate() - 1);
  if (d.toDateString() === yest.toDateString()) return 'Yesterday';
  return d.toLocaleDateString('en-US', { day: '2-digit', month: 'long', year: 'numeric' });
}

// (Fungsi lama maybeConsumeOnetimeChatPerm() sudah digantikan oleh
// markFreeChatMessageUsed() + getChatSendPermission() di atas.)

async function sendChatMessage() {
  if (!currentUser || !_chatCurrentPeer) return;
  // Kalau ada foto/video yang sedang dipilih (menunggu di preview bar),
  // kirim sebagai pesan media — teks di kolom input dipakai sebagai caption.
  if (_chatPendingMediaFile) { sendChatMediaMessage(); return; }

  const input = document.getElementById('chat-input');
  const text = (input.value || '').trim();
  if (!text) return;

  const peer = _chatCurrentPeer;
  const perm = await getChatSendPermission(peer.uid, 'text');
  if (!perm.ok) {
    toast(perm.message);
    return;
  }

  input.value = '';
  autoResizeChatInput(input); // kolom ketik kembali ke tinggi normal (1 baris)
  updateChatInputBarState(); // tombol attach & GIF muncul lagi kalau kolom kosong & tidak difokus
  stopChatTyping(); // pesan sudah terkirim → indikator "mengetik" langsung berhenti

  const myUid = currentUser.uid;
  const chatId = peer.chatId;
  const now = Date.now();
  const msgKey = db.ref('chats/' + chatId + '/messages').push().key;

  const msgData = { from: myUid, text: text, ts: now };
  if (_chatReplyTarget) {
    msgData.replyTo = {
      key: _chatReplyTarget.key,
      text: _chatReplyTarget.text,
      from: _chatReplyTarget.from,
      name: _chatReplyTarget.name
    };
  }

  const updates = {};
  updates['chats/' + chatId + '/participants/' + myUid] = true;
  updates['chats/' + chatId + '/participants/' + peer.uid] = true;
  updates['chats/' + chatId + '/messages/' + msgKey] = msgData;
  updates['userChats/' + myUid + '/' + chatId + '/lastMessage'] = text;
  updates['userChats/' + myUid + '/' + chatId + '/lastMessageAt'] = now;
  updates['userChats/' + myUid + '/' + chatId + '/unreadCount'] = 0;
  updates['userChats/' + peer.uid + '/' + chatId + '/lastMessage'] = text;
  updates['userChats/' + peer.uid + '/' + chatId + '/lastMessageAt'] = now;
  updates['userChats/' + peer.uid + '/' + chatId + '/unreadCount'] = firebase.database.ServerValue.increment(1);

  cancelReply();

  db.ref().update(updates).then(() => {
    // Pesan teks berhasil terkirim & ini memakai jatah gratis (belum follow) → catat.
    if (perm.freeMessage) markFreeChatMessageUsed(peer.uid, now);
    // Kabari penerima lewat push notification (ala WhatsApp) kalau dia
    // sedang tidak membuka app — lihat CHAT_NOTIF_WORKER di atas.
    triggerChatPushNotification(peer, text);
  }).catch(err => {
    console.error('Gagal mengirim pesan:', err);
    input.value = text; // kembalikan teks kalau gagal terkirim
    autoResizeChatInput(input);
    updateChatInputBarState();
  });
}

// ── Kirim Foto/Video: pilih file → preview → upload Cloudinary → kirim ──

// Dipanggil saat tombol attach ditekan. Cek dulu izin kirim media (wajib
// sudah follow & diterima) SEBELUM membuka file-picker, supaya user tidak
// capek pilih file dulu baru ditolak belakangan.
async function openChatMediaPicker() {
  if (!currentUser || !_chatCurrentPeer) return;
  const perm = await getChatSendPermission(_chatCurrentPeer.uid, 'media');
  if (!perm.ok) {
    toast(perm.message);
    return;
  }
  document.getElementById('chat-media-input')?.click();
}

// Dipanggil saat user memilih file dari input[type=file] (tombol lampiran).
function handleChatMediaSelected(event) {
  const file = event.target.files && event.target.files[0];
  event.target.value = ''; // reset supaya bisa pilih file yg sama lagi nanti
  if (!file) return;
  closeGifPicker();

  const isImage = file.type.startsWith('image/');
  const isVideo = file.type.startsWith('video/');
  if (!isImage && !isVideo) {
    alert('Only photo or video files are supported.');
    return;
  }
  const maxMb = isImage ? CLOUDINARY_MAX_IMAGE_MB : CLOUDINARY_MAX_VIDEO_MB;
  if (file.size > maxMb * 1024 * 1024) {
    alert(`File is too large. Maximum ${maxMb}MB for ${isImage ? 'photo' : 'video'}.`);
    return;
  }

  cancelChatMediaPreview(); // bersihkan pilihan sebelumnya (kalau ada)
  _chatPendingMediaFile = file;
  _chatPendingMediaType = isImage ? 'image' : 'video';
  _chatPendingMediaPreviewUrl = URL.createObjectURL(file);

  const thumb = document.getElementById('chat-media-preview-thumb');
  thumb.className = 'chat-media-preview-thumb' + (isVideo ? ' video' : '');
  if (isImage) {
    thumb.style.display = '';
    thumb.src = _chatPendingMediaPreviewUrl;
    thumb.innerHTML = '';
  } else {
    // Untuk video, tampilkan ikon sederhana sbg thumbnail (hemat proses).
    thumb.removeAttribute('src');
    thumb.style.display = 'flex';
    thumb.innerHTML = '&#127916;';
  }

  document.getElementById('chat-media-preview-name').textContent = file.name;
  document.getElementById('chat-media-preview-status').textContent = 'Ready to send · write a caption (optional) then press send';
  const bar = document.getElementById('chat-media-preview-bar');
  bar.classList.remove('show');
  document.getElementById('chat-media-preview-bar-fill').style.width = '0%';
  document.getElementById('chat-media-preview').classList.add('show');
  document.getElementById('chat-input')?.focus();
}

// Batalkan pemilihan foto/video sebelum dikirim.
function cancelChatMediaPreview() {
  if (_chatMediaUploading) return; // jangan batalkan selagi sedang upload
  if (_chatPendingMediaPreviewUrl) URL.revokeObjectURL(_chatPendingMediaPreviewUrl);
  _chatPendingMediaFile = null;
  _chatPendingMediaType = null;
  _chatPendingMediaPreviewUrl = null;
  document.getElementById('chat-media-preview')?.classList.remove('show');
  const closeBtn = document.getElementById('chat-media-preview-close');
  const attachBtn = document.getElementById('chat-attach-btn');
  const barWrap = document.getElementById('chat-media-preview-bar');
  const barFill = document.getElementById('chat-media-preview-bar-fill');
  if (closeBtn) closeBtn.style.visibility = '';
  if (attachBtn) attachBtn.disabled = false;
  if (barWrap) barWrap.classList.remove('show');
  if (barFill) barFill.style.width = '0%';
}

// Upload satu file ke Cloudinary lewat unsigned upload preset.
// resourceType: 'image' atau 'video'. onProgress(percent 0-100) opsional.
function uploadToCloudinary(file, resourceType, onProgress) {
  return new Promise((resolve, reject) => {
    const url = `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/${resourceType}/upload`;
    const formData = new FormData();
    formData.append('file', file);
    formData.append('upload_preset', CLOUDINARY_UPLOAD_PRESET);

    const xhr = new XMLHttpRequest();
    xhr.open('POST', url, true);
    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable && onProgress) onProgress(Math.round((e.loaded / e.total) * 100));
    };
    xhr.onload = () => {
      let res;
      try { res = JSON.parse(xhr.responseText); } catch (e) { res = null; }
      if (xhr.status >= 200 && xhr.status < 300 && res && res.secure_url) {
        resolve(res);
      } else {
        const msg = (res && res.error && res.error.message) || `Upload failed (status ${xhr.status})`;
        reject(new Error(msg));
      }
    };
    xhr.onerror = () => reject(new Error('Connection failed while uploading to Cloudinary.'));
    xhr.send(formData);
  });
}

// Upload file yang sedang dipilih ke Cloudinary lalu kirim sbg pesan chat
// (caption diambil dari kolom teks, boleh kosong).
async function sendChatMediaMessage() {
  if (!currentUser || !_chatCurrentPeer || !_chatPendingMediaFile) return;
  if (_chatMediaUploading) return;

  const peer = _chatCurrentPeer;
  const permCheck = await getChatSendPermission(peer.uid, 'media');
  if (!permCheck.ok) {
    toast(permCheck.message);
    return;
  }

  stopChatTyping(); // pesan (media) sedang dikirim → indikator "mengetik" langsung berhenti

  const file = _chatPendingMediaFile;
  const mediaType = _chatPendingMediaType;
  const chatId = peer.chatId;         // tangkap sekarang, sebelum upload async berjalan,
  const myUid = currentUser.uid;      // supaya kalau user pindah percakapan selagi upload
  const replyTargetSnapshot = _chatReplyTarget; // masih berjalan, pesan tetap terkirim ke chat yg benar
  const input = document.getElementById('chat-input');
  const caption = (input.value || '').trim();
  const statusEl = document.getElementById('chat-media-preview-status');
  const barWrap = document.getElementById('chat-media-preview-bar');
  const barFill = document.getElementById('chat-media-preview-bar-fill');
  const closeBtn = document.getElementById('chat-media-preview-close');
  const attachBtn = document.getElementById('chat-attach-btn');

  _chatMediaUploading = true;
  if (closeBtn) closeBtn.style.visibility = 'hidden';
  if (attachBtn) attachBtn.disabled = true;
  barWrap.classList.add('show');
  statusEl.textContent = 'Mengunggah 0%...';

  try {
    const result = await uploadToCloudinary(file, mediaType, (pct) => {
      barFill.style.width = pct + '%';
      statusEl.textContent = `Mengunggah ${pct}%...`;
    });

    statusEl.textContent = 'Mengirim...';
    input.value = '';

    const now = Date.now();
    const msgKey = db.ref('chats/' + chatId + '/messages').push().key;

    const msgData = {
      from: myUid,
      text: caption,
      ts: now,
      type: mediaType,               // 'image' | 'video'
      mediaUrl: result.secure_url,
      mediaWidth: result.width || null,
      mediaHeight: result.height || null
    };
    if (replyTargetSnapshot) {
      msgData.replyTo = {
        key: replyTargetSnapshot.key,
        text: replyTargetSnapshot.text,
        from: replyTargetSnapshot.from,
        name: replyTargetSnapshot.name
      };
    }

    const previewLabel = (mediaType === 'image' ? '📷 Photo' : '🎥 Video') + (caption ? ': ' + caption : '');

    const updates = {};
    updates['chats/' + chatId + '/participants/' + myUid] = true;
    updates['chats/' + chatId + '/participants/' + peer.uid] = true;
    updates['chats/' + chatId + '/messages/' + msgKey] = msgData;
    updates['userChats/' + myUid + '/' + chatId + '/lastMessage'] = previewLabel;
    updates['userChats/' + myUid + '/' + chatId + '/lastMessageAt'] = now;
    updates['userChats/' + myUid + '/' + chatId + '/unreadCount'] = 0;
    updates['userChats/' + peer.uid + '/' + chatId + '/lastMessage'] = previewLabel;
    updates['userChats/' + peer.uid + '/' + chatId + '/lastMessageAt'] = now;
    updates['userChats/' + peer.uid + '/' + chatId + '/unreadCount'] = firebase.database.ServerValue.increment(1);

    cancelReply();
    await db.ref().update(updates);
    triggerChatPushNotification(peer, previewLabel);
    _chatMediaUploading = false;
    cancelChatMediaPreview();
  } catch (err) {
    console.error('Gagal mengirim foto/video:', err);
    _chatMediaUploading = false;
    statusEl.textContent = 'Failed to upload — try again.';
    barWrap.classList.remove('show');
    if (closeBtn) closeBtn.style.visibility = '';
    if (attachBtn) attachBtn.disabled = false;
  }
}

// ── GIF Picker (Giphy) ──────────────────────────────────────────────────

async function toggleGifPicker() {
  const panel = document.getElementById('chat-gif-picker');
  if (!panel) return;
  if (panel.classList.contains('show')) { closeGifPicker(); return; }
  if (!currentUser || !_chatCurrentPeer) return;
  const perm = await getChatSendPermission(_chatCurrentPeer.uid, 'media');
  if (!perm.ok) {
    toast(perm.message);
    return;
  }
  openGifPicker();
}

function openGifPicker() {
  cancelChatMediaPreview(); // jangan tumpang-tindih dgn preview foto/video
  const panel = document.getElementById('chat-gif-picker');
  const btn = document.getElementById('chat-gif-btn');
  if (!panel) return;
  panel.classList.add('show');
  if (btn) btn.classList.add('active');
  const searchInput = document.getElementById('chat-gif-search');
  const grid = document.getElementById('chat-gif-grid');
  // Kalau grid masih kosong (belum pernah dibuka / belum ada hasil), muat trending
  if (grid && !grid.children.length) fetchGiphyTrending();
  setTimeout(() => searchInput?.focus(), 150);
}

function closeGifPicker() {
  const panel = document.getElementById('chat-gif-picker');
  const btn = document.getElementById('chat-gif-btn');
  if (panel) panel.classList.remove('show');
  if (btn) btn.classList.remove('active');
}

// Debounce 400ms supaya tidak fetch API di setiap ketikan huruf
function onGifSearchInput() {
  clearTimeout(_gifSearchDebounce);
  const q = (document.getElementById('chat-gif-search')?.value || '').trim();
  _gifSearchDebounce = setTimeout(() => {
    if (q) fetchGiphySearch(q); else fetchGiphyTrending();
  }, 400);
}

function fetchGiphyTrending() {
  const seq = ++_gifSearchSeq;
  renderGifGridLoading();
  const url = `https://api.giphy.com/v1/gifs/trending?api_key=${GIPHY_API_KEY}&limit=24&rating=pg-13`;
  fetch(url)
    .then(r => r.json())
    .then(data => { if (seq === _gifSearchSeq) renderGifGrid(data.data || []); })
    .catch(err => { console.error('Gagal memuat GIF trending:', err); if (seq === _gifSearchSeq) renderGifGridError(); });
}

function fetchGiphySearch(query) {
  const seq = ++_gifSearchSeq;
  renderGifGridLoading();
  const url = `https://api.giphy.com/v1/gifs/search?api_key=${GIPHY_API_KEY}&q=${encodeURIComponent(query)}&limit=24&rating=pg-13`;
  fetch(url)
    .then(r => r.json())
    .then(data => { if (seq === _gifSearchSeq) renderGifGrid(data.data || []); })
    .catch(err => { console.error('Gagal mencari GIF:', err); if (seq === _gifSearchSeq) renderGifGridError(); });
}

function renderGifGridLoading() {
  const grid = document.getElementById('chat-gif-grid');
  if (grid) grid.innerHTML = '<div class="chat-gif-loading">Loading GIF...</div>';
}

function renderGifGridError() {
  const grid = document.getElementById('chat-gif-grid');
  if (grid) grid.innerHTML = '<div class="chat-gif-empty">Failed to load GIF. Try again.</div>';
}

function renderGifGrid(items) {
  const grid = document.getElementById('chat-gif-grid');
  if (!grid) return;
  if (!items.length) {
    grid.innerHTML = '<div class="chat-gif-empty">No GIFs found</div>';
    return;
  }
  // _gifCache menyimpan url final per index, supaya klik item tidak perlu
  // menaruh URL panjang di atribut HTML (aman dari karakter aneh & rapi).
  _gifCache = {};
  grid.innerHTML = items.map((g, i) => {
    const thumbUrl = (g.images.fixed_width_small || g.images.fixed_width || g.images.original).url;
    const sendImg = g.images.fixed_height || g.images.original;
    _gifCache[i] = { url: sendImg.url, width: sendImg.width, height: sendImg.height };
    return `<div class="chat-gif-grid-item" data-gifidx="${i}" title="${esc(g.title || 'GIF')}">
      <img src="${esc(thumbUrl)}" alt="${esc(g.title || 'GIF')}" loading="lazy">
    </div>`;
  }).join('');
}
let _gifCache = {};

document.addEventListener('click', e => {
  const item = e.target.closest('#chat-gif-grid .chat-gif-grid-item');
  if (!item) return;
  const idx = item.dataset.gifidx;
  const g = _gifCache[idx];
  if (g) sendGifMessage(g.url, g.width, g.height);
});

// Send GIF langsung begitu dipilih — sama seperti WhatsApp/Instagram,
// tanpa perlu tombol kirim terpisah. Teks di kolom input (kalau ada)
// dikirim sebagai caption.
async function sendGifMessage(gifUrl, width, height) {
  if (!currentUser || !_chatCurrentPeer) return;
  const peer = _chatCurrentPeer;
  const perm = await getChatSendPermission(peer.uid, 'media');
  if (!perm.ok) {
    toast(perm.message);
    closeGifPicker();
    return;
  }

  const input = document.getElementById('chat-input');
  const caption = (input.value || '').trim();
  input.value = '';
  closeGifPicker();
  stopChatTyping(); // pesan (GIF) sedang dikirim → indikator "mengetik" langsung berhenti

  const myUid = currentUser.uid;
  const chatId = peer.chatId;
  const now = Date.now();
  const msgKey = db.ref('chats/' + chatId + '/messages').push().key;

  const msgData = {
    from: myUid,
    text: caption,
    ts: now,
    type: 'gif',
    mediaUrl: gifUrl,
    mediaWidth: width || null,
    mediaHeight: height || null
  };
  if (_chatReplyTarget) {
    msgData.replyTo = {
      key: _chatReplyTarget.key,
      text: _chatReplyTarget.text,
      from: _chatReplyTarget.from,
      name: _chatReplyTarget.name
    };
  }

  const previewLabel = '🎞️ GIF' + (caption ? ': ' + caption : '');

  const updates = {};
  updates['chats/' + chatId + '/participants/' + myUid] = true;
  updates['chats/' + chatId + '/participants/' + peer.uid] = true;
  updates['chats/' + chatId + '/messages/' + msgKey] = msgData;
  updates['userChats/' + myUid + '/' + chatId + '/lastMessage'] = previewLabel;
  updates['userChats/' + myUid + '/' + chatId + '/lastMessageAt'] = now;
  updates['userChats/' + myUid + '/' + chatId + '/unreadCount'] = 0;
  updates['userChats/' + peer.uid + '/' + chatId + '/lastMessage'] = previewLabel;
  updates['userChats/' + peer.uid + '/' + chatId + '/lastMessageAt'] = now;
  updates['userChats/' + peer.uid + '/' + chatId + '/unreadCount'] = firebase.database.ServerValue.increment(1);

  cancelReply();
  db.ref().update(updates)
    .then(() => triggerChatPushNotification(peer, previewLabel))
    .catch(err => console.error('Gagal mengirim GIF:', err));
}

// Format waktu singkat ala Instagram: "14:05" utk hari ini, "Kmr" utk kemarin,
// atau tanggal singkat utk yang lebih lama.
function formatChatTime(ts) {
  if (!ts) return '';
  const d = new Date(ts);
  const now = new Date();
  const isToday = d.toDateString() === now.toDateString();
  const yest = new Date(now); yest.setDate(now.getDate() - 1);
  const isYesterday = d.toDateString() === yest.toDateString();
  if (isToday) return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
  if (isYesterday) return 'Kmr';
  return d.toLocaleDateString('en-US', { day: '2-digit', month: 'short' });
}

function showAuthWall() {
  const overlay = document.getElementById('auth-overlay');
  overlay.innerHTML = `
    <div class="auth-box">
      <div style="font-size:2.5rem;margin-bottom:12px"></div>
      <h2>Login Diperlukan</h2>
      <p>You must log in with your ALVIN account to access Music Player and save your playlists.</p>
      <div class="auth-btns">
        <a class="btn-login" href="index.html">Login / Sign Up</a>
      </div>
    </div>`;
  overlay.style.display = 'flex';
  overlay.style.opacity = '1';
}

function setCloudStatus(state, text) {
  const dot  = document.getElementById('cloud-dot');
  const span = document.getElementById('cloud-status');
  if (!dot || !span) return;
  dot.className = 'cloud-dot' + (state === 'synced' ? ' synced' : state === 'saving' ? ' saving' : '');
  span.textContent = text;
}

// ─── Cloud Playlist Sync ──────────────────────────────────
function getPlRef() {
  if (!currentUser) return null;
  return db.ref('music_playlists_v2/' + currentUser.uid);
}

// Flag supaya tidak ada dua flush berjalan bersamaan / rebutan
let _saveInFlight = null;

// Menulis state `playlists` saat ini ke Firebase SEKARANG JUGA (tanpa delay).
// Dipakai baik oleh debounce normal maupun oleh logout/tutup halaman.
async function flushSave() {
  if (!currentUser) return;
  clearTimeout(saveTimeout);
  try {
    const toSave = {};
    for (const id in playlists) {
      const pl = playlists[id];
      toSave[id] = {
        id: pl.id,
        name: pl.name,
        coverThumb: pl.coverThumb || '',
        public: pl.public || false,
        sourceMixId: pl.sourceMixId || null,
        tracks: (pl.tracks || []).map(t => ({
          title: t.title || '',
          artist: t.artist || '',
          thumb: t.thumb || '',
          photo: t.photo || '',
          _query: t._query || ''
        }))
      };
    }
    _saveInFlight = getPlRef().set(toSave);
    await _saveInFlight;
    const count = Object.keys(playlists).length;
    setCloudStatus('synced', 'Tersimpan · ' + count + ' playlist');
    // Sync any public playlists with updated data
    syncPublicPlaylists();
  } catch(e) {
    setCloudStatus('', 'Failed to save: ' + e.message);
    throw e;
  } finally {
    _saveInFlight = null;
  }
}

function scheduleSave() {
  clearTimeout(saveTimeout);
  setCloudStatus('saving', 'Menyimpan...');
  saveTimeout = setTimeout(() => { flushSave(); }, 1200);
}

// Pastikan semua perubahan yang masih tertunda benar-benar tersimpan
// sebelum logout / halaman ditutup / berpindah.
async function flushPendingSaveBeforeExit() {
  // Ada perubahan yang masih menunggu debounce (belum sempat terkirim)
  if (saveTimeout) {
    clearTimeout(saveTimeout);
    saveTimeout = null;
    try { await flushSave(); } catch(e) {}
    return;
  }
  // Ada penyimpanan yang sedang berjalan (in-flight) — tunggu selesai
  if (_saveInFlight) {
    try { await _saveInFlight; } catch(e) {}
  }
}

function doLogout() {
  if (confirm('Are you sure you want to log out?')) {
    setCloudStatus('saving', 'Menyimpan sebelum logout...');
    flushPendingSaveBeforeExit().finally(() => {
      markMyselfOffline().finally(() => {
        auth.signOut().then(() => {
          try { localStorage.removeItem('vibexa_last_uid'); } catch (e) {}
          window.location.href = 'index.html';
        });
      });
    });
  }
}

// ─── Menu popup tombol profil (avatar bulat kanan atas) — My Profile / Logout ───
function toggleTopProfileMenu(e) {
  if (e) e.stopPropagation();
  const menu = document.getElementById('topbar-profile-menu');
  if (!menu) return;
  menu.classList.toggle('show');
}
function closeTopProfileMenu() {
  const menu = document.getElementById('topbar-profile-menu');
  if (menu) menu.classList.remove('show');
}
// Klik di luar menu -> tutup menu
document.addEventListener('click', (e) => {
  const wrap = document.getElementById('topbar-profile-wrap');
  const menu = document.getElementById('topbar-profile-menu');
  if (menu && menu.classList.contains('show') && wrap && !wrap.contains(e.target)) {
    closeTopProfileMenu();
  }
});

// Jaring pengaman tambahan: kalau tab/app ditutup atau dipindah ke
// background saat masih ada perubahan yang belum tersimpan, coba
// paksa simpan segera (best-effort, browser bisa saja tetap memotongnya).
window.addEventListener('pagehide', () => { if (saveTimeout) flushSave(); });
document.addEventListener('visibilitychange', () => {
  if (document.hidden && saveTimeout) flushSave();
});

// Sync updated playlist data to public_playlists node
async function syncPublicPlaylists() {
  if (!currentUser) return;
  // Ambil foto profil terkini sekali saja
  const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(()=>null);
  const profileData = profileSnap?.val() || {};
  const ownerName = profileData.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
  const ownerPhoto = profileData.photoURL || profileData.photoBase64 || currentUser.photoURL || '';

  for (const id in playlists) {
    const pl = playlists[id];
    if (!pl.public) continue;
    const key = currentUser.uid + '_' + id;
    try {
      const snap = await db.ref('public_playlists/' + key).get();
      if (!snap.exists()) continue;
      await db.ref('public_playlists/' + key).update({
        name: pl.name || 'Playlist',
        coverThumb: pl.coverThumb || '',
        ownerName,
        ownerPhoto,
        tracks: (pl.tracks || []).slice(0, 50).map(t => ({
          title: t.title || '',
          artist: t.artist || '',
          thumb: t.thumb || '',
          _query: t._query || ''
        }))
      });
    } catch(e) { /* silently ignore */ }
  }
}

// Supaya playlist yang baru ditambahkan (mis. dari Home/Daily Mix) TIDAK
// pernah hilang/tertimpa gara-gara Firebase auth token refresh (yang bisa
// memicu auth.onAuthStateChanged lagi di tengah sesi dan memanggil fungsi
// ini ULANG), kita hanya benar-benar reload+timpa `playlists` dari cloud
// SEKALI per sesi login. Panggilan berikutnya cukup dilewati saja karena
// state lokal sudah jadi sumber kebenaran dan rutin ter-sync ke cloud
// lewat scheduleSave().
let _playlistsLoadedOnce = false;

async function loadAllPlaylistsFromCloud() {
  if (!currentUser) return;
  if (_playlistsLoadedOnce) return;
  setCloudStatus('saving', 'Loading playlist...');
  try {
    // Pastikan tidak ada penambahan lokal yang masih menunggu debounce
    // sebelum kita membaca dari cloud, supaya tidak ada race condition
    // yang membuat data lokal ke-timpa oleh data cloud yang lebih lama.
    await flushPendingSaveBeforeExit();
    const snap = await getPlRef().get();
    if (snap.exists()) {
      const data = snap.val();
      if (data && typeof data === 'object') {
        playlists = {};
        for (const id in data) {
          const raw = data[id];
          playlists[id] = {
            id,
            name: raw.name || 'Playlist',
            coverThumb: raw.coverThumb || '',
            cover: raw.coverThumb || '',
            public: raw.public || false,
            sourceMixId: raw.sourceMixId || null,
            tracks: Array.isArray(raw.tracks) ? raw.tracks.map(t => ({
              title: t.title || '',
              artist: t.artist || '',
              thumb: t.thumb || '',
              photo: t.photo || '',
              _query: t._query || (t.artist + '|||' + t.title + '|||0')
            })) : []
          };
        }
        const count = Object.keys(playlists).length;
        toast(' ' + count + ' playlist dimuat');
      }
    }
    _playlistsLoadedOnce = true;
    ensureLikedPlaylist();
    renderSidebarPlaylists();
    renderHomeGrid();
    if (typeof syncRankAddButtons === 'function') syncRankAddButtons();
    updateBarLikeBtn(curTrack);
    setCloudStatus('synced', 'Tersimpan · ' + Object.keys(playlists).length + ' playlist');
  } catch(e) {
    setCloudStatus('', 'Failed to load: ' + e.message);
    toast(' Failed to load playlist');
  }
}

// ─── Artis Favorit (follow artis) ──────────────────────────
// Disimpan per akun di Firebase, jadi tombol "Ikuti" di mana pun (halaman
// profil artis, panel lirik kanan, feed Song Preview) semuanya menulis ke
// tempat yang sama dan otomatis muncul di bagian "Artis Favorit" Home.
function getFavArtistRef() {
  if (!currentUser) return null;
  // Disimpan di bawah "users/{uid}/..." (sama seperti profile, notifications,
  // lyricsBackground) karena path top-level terpisah "favorite_artists/{uid}"
  // tidak tercakup oleh security rules akun, sehingga penulisan gagal secara
  // diam-diam (hanya console.error) dan data hilang lagi setelah refresh.
  return db.ref('users/' + currentUser.uid + '/favoriteArtists');
}

async function loadFavoriteArtistsFromCloud() {
  if (!currentUser) return;
  try {
    const snap = await getFavArtistRef().get();
    favoriteArtists = {};
    if (snap.exists()) {
      const data = snap.val() || {};
      for (const key in data) {
        const v = data[key];
        if (v && v.name) favoriteArtists[key] = { name: v.name, photo: v.photo || '' };
      }
    }
  } catch (e) {
    console.error('loadFavoriteArtistsFromCloud error:', e);
  }
  renderFavoriteArtists();
  syncAllFollowButtons();
  loadRecommendedSongs(false);
  loadMadeForYouMixes(false);
  loadForYouPlaylists(false);
  loadMaybeLikeMixes(false);
  loadArtistRadioMixes(false);
}

function isArtistFavorited(name) {
  if (!name) return false;
  return !!favoriteArtists[name.toLowerCase()];
}

async function setArtistFavorited(name, photo, following) {
  if (!name) return;
  const key = name.toLowerCase();
  if (following) {
    favoriteArtists[key] = { name, photo: photo || (favoriteArtists[key] && favoriteArtists[key].photo) || '' };
  } else {
    delete favoriteArtists[key];
  }
  renderFavoriteArtists();
  syncAllFollowButtons();
  loadRecommendedSongs(true);
  // "For You" (satu artis satu playlist) harus langsung menyesuaikan:
  // playlist baru muncul begitu artis di-follow, dan langsung hilang begitu
  // artis di-unfollow — tidak menunggu refresh atau cache harian habis.
  loadForYouPlaylists(false);
  // "Berdasarkan Artis Favorit Kamu" (Tri Mix) disusun dari artis favorit user, jadi
  // begitu user follow artis baru atau unfollow artis lama, mix ini harus
  // dibikin ulang supaya isinya langsung menyesuaikan daftar artis favorit
  // yang terbaru (bukan menunggu cache harian habis).
  loadArtistRadioMixes(true);
  if (!currentUser) return;
  try {
    const ref = getFavArtistRef();
    if (following) await ref.child(key).set({ name, photo: photo || '' });
    else await ref.child(key).remove();
  } catch (e) {
    console.error('setArtistFavorited save error:', e);
  }
}

// Fungsi bersama dipanggil oleh SEMUA tombol "Ikuti" di app supaya
// perilakunya konsisten. Mengembalikan status baru (true = sekarang mengikuti).
function toggleFollowArtist(name, photo) {
  if (!name) return false;
  const nowFollowing = !isArtistFavorited(name);
  setArtistFavorited(name, photo, nowFollowing);
  toast(nowFollowing ? ` Following ${name}` : ` Unfollowed ${name}`);
  return nowFollowing;
}

// ─── Modal "Add Favorite Artist" — cari artis lewat Deezer (nama + foto)
// lalu tambahkan/hapus langsung dari "Favorite Artists" tanpa harus buka
// halaman profil artisnya dulu. Dipicu tombol "+ Add Artist" di section
// Favorite Artists (Home/PC & halaman "Yours" khusus mobile). ──────────
let _favArtistSearchDebounce = null;
let _favArtistSearchGen = 0;

function openAddFavArtistModal() {
  const modal = document.getElementById('add-fav-artist-modal');
  if (!modal) return;
  const input = document.getElementById('fav-artist-search-input');
  const results = document.getElementById('fav-artist-search-results');
  if (input) input.value = '';
  if (results) results.innerHTML = '';
  modal.style.display = 'flex';
  setTimeout(() => { if (input) input.focus(); }, 100);
}

function closeAddFavArtistModal() {
  const modal = document.getElementById('add-fav-artist-modal');
  if (modal) modal.style.display = 'none';
}

function onFavArtistSearchInput(q) {
  q = (q || '').trim();
  clearTimeout(_favArtistSearchDebounce);
  const results = document.getElementById('fav-artist-search-results');
  if (!q) { if (results) results.innerHTML = ''; return; }
  if (results) results.innerHTML = '<div class="empty" style="padding:20px 0;"><p>Searching...</p></div>';
  _favArtistSearchDebounce = setTimeout(() => _runFavArtistSearch(q), 320);
}

async function _runFavArtistSearch(q) {
  const myGen = ++_favArtistSearchGen;
  let artists = [];
  try {
    const data = await _deezerJsonp('https://api.deezer.com/search/artist?q=' + encodeURIComponent(q) + '&limit=15');
    const ql = q.toLowerCase();
    artists = ((data && data.data) || []).filter(a => (a.name || '').toLowerCase().includes(ql)).slice(0, 15);
  } catch (e) { artists = []; }
  if (myGen !== _favArtistSearchGen) return; // hasil sudah usang (user mengetik query baru)
  _renderFavArtistSearchResults(artists);
}

function _renderFavArtistSearchResults(artists) {
  const results = document.getElementById('fav-artist-search-results');
  if (!results) return;
  if (!artists.length) {
    results.innerHTML = '<div class="empty" style="padding:20px 0;"><p>No artists found</p></div>';
    return;
  }
  results.innerHTML = '';
  artists.forEach(a => {
    const name = a.name || 'Unknown';
    const photo = a.picture_medium || a.picture_big || a.picture || '';
    const following = isArtistFavorited(name);
    const item = document.createElement('div');
    item.className = 'modal-pl-item';
    item.innerHTML = `
      ${photo ? `<img src="${esc(photo)}" alt="${esc(name)}" style="width:36px;height:36px;border-radius:50%;object-fit:cover;flex-shrink:0;" onerror="this.style.display='none'">` : `<div class="fav-artist-ph" style="width:36px;height:36px;border-radius:50%;background:var(--card);flex-shrink:0;">🎤</div>`}
      <span style="flex:1;font-size:.85rem;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(name)}</span>
      <button class="home-new-pl-btn" style="${following ? 'background:var(--green);color:#fff;' : ''}">${following ? 'Added' : 'Add'}</button>
    `;
    const btn = item.querySelector('button');
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const nowFollowing = toggleFollowArtist(name, photo);
      btn.textContent = nowFollowing ? 'Added' : 'Add';
      btn.style.background = nowFollowing ? 'var(--green)' : '';
      btn.style.color = nowFollowing ? '#fff' : '';
    });
    results.appendChild(item);
  });
}

// Render bagian "Artis Favorit": hanya foto + nama artis, diklik akan
// membuka halaman profil artis tersebut. Merender ke DUA tempat sekaligus
// — section "Favorite Artists" bawaan di Home (dipakai di PC) dan grid
// milik halaman "Yours" khusus mobile — supaya keduanya selalu sinkron.
// Section-nya SELALU ditampilkan (termasuk saat user belum follow artis
// sama sekali) supaya tombol "+ Add Artist" tetap bisa ditekan untuk
// mencari & menambahkan artis favorit pertama mereka.
function renderFavoriteArtists() {
  const list = Object.values(favoriteArtists);

  const section = document.getElementById('fav-artist-section');
  const grid = document.getElementById('fav-artist-grid');
  if (section && grid) {
    section.style.display = 'block';
    _buildFavArtistGridInto(grid, list);
  }

  const yTitle = document.getElementById('yours-fav-artist-title');
  const yGrid = document.getElementById('yours-fav-artist-grid');
  if (yGrid) {
    if (yTitle) yTitle.style.display = 'flex';
    _buildFavArtistGridInto(yGrid, list);
  }
}

function _buildFavArtistGridInto(grid, list) {
  grid.innerHTML = '';
  if (!list.length) {
    grid.innerHTML = `
      <div class="empty" style="grid-column:1/-1;padding:24px 0;">
        <i></i>
        <h3>No Favorite Artists Yet</h3>
        <p>Click &quot;+ Add Artist&quot; to search and follow your favorite artists</p>
      </div>`;
    return;
  }
  list.forEach(a => {
    const card = document.createElement('div');
    card.className = 'fav-artist-card';
    card.title = a.name;
    card.innerHTML = a.photo
      ? `<img class="fav-artist-photo" src="${esc(a.photo)}" alt="${esc(a.name)}" loading="lazy" onerror="this.outerHTML='<div class=&quot;fav-artist-photo fav-artist-ph&quot;>&#127908;</div>'">`
      : `<div class="fav-artist-photo fav-artist-ph">🎤</div>`;
    card.innerHTML += `<div class="fav-artist-name">${esc(a.name)}</div>`;
    card.addEventListener('click', () => openArtistView(a.name));
    grid.appendChild(card);
  });
}

// ─── SARAN PUBLIC (Home) ─────────────────────────────────────────────────
// Sekarang PUBLIC: bukan lagi menarik data dari lagu favorit user yang kita
// follow, tapi dari node global "friendSuggestions/{key}" yang bisa diisi
// SIAPA SAJA lewat tombol "+ Suggest Song" (openAddSuggestionModal()). Karena
// public, section ini tampil sama untuk semua user, meskipun kita belum
// follow pemilik lagunya. Satu baris flat yang discroll ke samping, dan
// selalu diurutkan dari jumlah LIKE TERBANYAK di PALING KIRI (kalau sama,
// yang paling baru ditambahkan di paling kiri).
//
// friendSuggestions: [ {key, uid, name, photo, title, artist, thumb, note,
//                        noteColor, emoji, preview, _query, addedAt, likes}, ... ]
//                     likes: { [uid]: true, ... } — dipakai untuk urutan & tombol like
let friendSuggestions = [];
let _friendSuggestionsOff = null; // fungsi untuk stop listener

// Dipanggil sekali setelah login (lihat auth.onAuthStateChanged di atas).
// Memasang listener REALTIME (bukan sekali ambil) ke node public
// "friendSuggestions" (dibatasi 60 lagu terbaru) supaya section ini
// otomatis ter-update begitu ADA SAJA user yang menambah/menghapus saran
// lagu, tanpa perlu refresh halaman dan tanpa syarat follow-mengikuti.
function startFriendSuggestionsListener() {
  if (!currentUser) return;
  if (_friendSuggestionsOff) { _friendSuggestionsOff(); _friendSuggestionsOff = null; }

  const ref = db.ref('friendSuggestions').orderByChild('addedAt').limitToLast(60);
  const onChange = (snap) => {
    const val = snap.exists() ? snap.val() : {};
    friendSuggestions = Object.entries(val)
      .map(([key, s]) => ({ key, ...s }))
      // Like terbanyak → paling kiri. Kalau jumlah like sama, yang paling
      // baru ditambahkan → paling kiri.
      .sort((a, b) => {
        const likeA = a.likes ? Object.keys(a.likes).length : 0;
        const likeB = b.likes ? Object.keys(b.likes).length : 0;
        if (likeB !== likeA) return likeB - likeA;
        return (b.addedAt ?? 0) - (a.addedAt ?? 0);
      });
    renderFriendFavorites();
  };
  ref.on('value', onChange);
  _friendSuggestionsOff = () => ref.off('value', onChange);
}

// Render bagian "Saran Public" di Home: satu baris flat (bukan dikelompokkan
// per teman lagi) yang bisa discroll ke samping. Tiap lagu tampil dengan
// bubble catatan (kalau diisi si penyaran) persis seperti Lagu Favorit di
// halaman profil, ditambah tombol Like + jumlah like di bawah kartu (lihat
// toggleFriendSongLike()), dan bisa diklik untuk diputar penuh (bukan cuma
// preview 30 detik). Urutan lagu mengikuti jumlah like (lihat sort di
// startFriendSuggestionsListener()), bukan lagi berdasar siapa yang menyarankan.
function renderFriendFavorites() {
  const section = document.getElementById('friend-fav-section');
  const grid = document.getElementById('friend-fav-grid');
  if (!section || !grid) return;

  if (!friendSuggestions.length) {
    grid.innerHTML = `<div style="padding:14px 4px;color:var(--muted);font-size:.8rem;">No song suggestions yet. Be the first to press "+ Suggest Song" above!</div>`;
    return;
  }

  grid.innerHTML = friendSuggestions.map((s, idx) => {
    const isMine = currentUser && s.uid === currentUser.uid;
    const likeCount = s.likes ? Object.keys(s.likes).length : 0;
    const iLiked = !!(currentUser && s.likes && s.likes[currentUser.uid]);
    const commentCount = s.comments ? Object.keys(s.comments).length : 0;
    // Pakai data terbaru dari node "directory" (live) kalau ada, supaya kalau
    // pemilik saran mengganti nama/foto profil, bubble ini langsung ikut
    // berubah — bukan memakai snapshot name/photo yang disimpan sekali saja
    // saat lagu itu pertama kali disarankan (lihat addSongSuggestion()).
    const liveSuggester = _chatDirectory[s.uid];
    const suggesterName = (liveSuggester && liveSuggester.displayName) || s.name || 'User';
    const suggesterPhoto = (liveSuggester && liveSuggester.photoURL) || s.photo || '';
    // Bubble catatan dibuat SAMA PERSIS dengan struktur di halaman profil
    // (fav-note-bubble > fav-note-text + fav-note-author), baris "author" di
    // sini memakai nama & foto user yang MENYARANKAN lagu itu. Bubble bisa
    // ditekan untuk membuka teks yang terlalu panjang, dan nama/foto di
    // dalam bubble bisa ditekan untuk membuka profilnya (stopPropagation
    // supaya tidak ikut memicu toggle expand / putar lagu).
    const bubble = s.note
      ? `<div class="fav-note-bubble" style="--bubble-color:${esc(s.noteColor || '#2E7DFF')}" onclick="showFavNotePopover(this,event)">
           ${s.emoji ? `<span class="fav-note-emoji-badge">${esc(s.emoji)}</span>` : ''}
           <div class="fav-note-text">${esc(s.note)}</div>
         </div>`
      : '';
    // Badge "Trending Pick" / "Community Favorite" — dekoratif, otomatis
    // diberikan ke 2 saran teratas (paling banyak like, lihat urutan sort di
    // startFriendSuggestionsListener()) supaya tampilan mirip kartu ulasan.
    let badge = '';
    if (idx === 0 && likeCount > 0) {
      badge = `<div class="ff-badge trending"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2c1 3-2 4.5-2 7a4 4 0 0 0 8 0c0-1-.3-2-1-3 1.5.5 3 2.5 3 5a6 6 0 0 1-12 0c0-3.5 2.3-6 4-9z"/></svg>Trending</div>`;
    } else if (idx === 1 && likeCount > 0) {
      badge = `<div class="ff-badge community"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l2.9 6.3 6.9.7-5.2 4.6 1.6 6.8L12 17l-6.2 3.4 1.6-6.8-5.2-4.6 6.9-.7z"/></svg>Favorite</div>`;
    }
    return `
      <div class="friend-fav-item" onclick="playFriendSuggestedSong('${s.key}')" title="Play full: ${esc(s.title)}">
        <div class="ff-header">
          <div class="ff-avatar" onclick="event.stopPropagation();window.location.href='profile.html?uid=${encodeURIComponent(s.uid)}'">${suggesterPhoto ? `<img src="${esc(suggesterPhoto)}" alt="">` : '👤'}</div>
          <div class="ff-suggester-name" onclick="event.stopPropagation();window.location.href='profile.html?uid=${encodeURIComponent(s.uid)}'">${esc(suggesterName)}</div>
        </div>
        ${bubble}
        <div class="friend-fav-thumb-wrap">
          ${badge}
          ${isMine ? `<button type="button" class="friend-fav-del-btn" onclick="event.stopPropagation();deleteSongSuggestion('${s.key}')" title="Delete this song suggestion">✕</button>` : ''}
          ${s.thumb ? `<img src="${esc(s.thumb)}" alt="" loading="lazy">` : `<div class="friend-fav-thumb-ph">♪</div>`}
          <div class="friend-fav-play-ov"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg></div>
        </div>
        <div class="friend-fav-title">${esc(s.title || '—')}</div>
        <div class="friend-fav-artist">${esc(s.artist || '—')}</div>
        <div class="friend-fav-actions-row">
          <button type="button" class="friend-fav-like-btn${iLiked ? ' liked' : ''}" onclick="event.stopPropagation();toggleFriendSongLike(event,'${s.key}',${iLiked})" title="${iLiked ? 'Unlike this song' : 'Like this song'}">
            <svg viewBox="0 0 24 24" fill="${iLiked ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2.5"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
            <span>${likeCount}</span>
          </button>
          <button type="button" class="friend-fav-comment-btn" onclick="openCommentModal(event,'${SUGG_COMMENT_PREFIX}${esc(s.key)}','${esc(((s.title||'Song') + (s.artist ? ' · ' + s.artist : '')).replace(/'/g,"\\'"))}')" title="Comment on this song">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
            <span class="comment-count-${SUGG_COMMENT_PREFIX}${esc(s.key)}">${commentCount ? ' '+commentCount : ''}</span>
          </button>
          <button type="button" class="friend-fav-addpl-btn" onclick="event.stopPropagation();addFriendSuggestedSongToPlaylist('${s.key}')" title="Add to playlist">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>
          </button>
        </div>
      </div>`;
  }).join('');
}

// ─── Popup teks penuh bubble catatan (lagu favorit teman) ───────────────
// Dipanggil saat bubble catatan (.fav-note-bubble) ditekan. Menampilkan teks
// LENGKAP (diambil langsung dari isi .fav-note-text yang sudah ada di DOM,
// jadi tidak perlu simpan ulang di atribut HTML) lewat elemen position:fixed
// yang ditempel ke <body> — supaya tidak pernah kepotong oleh area scroll
// manapun (lihat catatan di CSS .fav-note-popover).
let _favNotePopoverEl = null;

function showFavNotePopover(bubbleEl, event) {
  if (event) event.stopPropagation();
  const isSameBubble = _favNotePopoverEl && _favNotePopoverEl._sourceBubble === bubbleEl;
  closeFavNotePopover();
  if (isSameBubble) return; // tekan bubble yang sama lagi → cukup ditutup

  const textEl = bubbleEl.querySelector('.fav-note-text');
  const text = textEl ? textEl.textContent : '';
  const color = bubbleEl.style.getPropertyValue('--bubble-color') || '#2E7DFF';

  const pop = document.createElement('div');
  pop.className = 'fav-note-popover';
  pop.style.setProperty('--bubble-color', color);
  pop.textContent = text;
  document.body.appendChild(pop);

  const rect = bubbleEl.getBoundingClientRect();
  const popRect = pop.getBoundingClientRect();

  // Coba taruh di atas bubble dulu; kalau mepet tepi atas layar, taruh di bawah bubble
  let top = rect.top - popRect.height - 10;
  if (top < 8) top = rect.bottom + 10;
  let left = rect.left;
  if (left + popRect.width > window.innerWidth - 8) left = window.innerWidth - popRect.width - 8;
  if (left < 8) left = 8;

  pop.style.top = top + 'px';
  pop.style.left = left + 'px';
  pop._sourceBubble = bubbleEl;
  _favNotePopoverEl = pop;

  requestAnimationFrame(() => pop.classList.add('show'));
}

function closeFavNotePopover() {
  if (_favNotePopoverEl) {
    _favNotePopoverEl.remove();
    _favNotePopoverEl = null;
  }
}

// Tutup popup kalau klik di luar area popup, atau saat scroll/resize
document.addEventListener('click', (e) => {
  if (_favNotePopoverEl && !_favNotePopoverEl.contains(e.target)) closeFavNotePopover();
});
window.addEventListener('scroll', () => closeFavNotePopover(), true);
window.addEventListener('resize', () => closeFavNotePopover());

// Klik lagu di "Saran Public" → putar PENUH lewat player utama (sama
// seperti klik lagu di Rekomendasi/Top Songs/dll), bukan cuma preview 30 detik.
function playFriendSuggestedSong(key) {
  const s = friendSuggestions.find(x => x.key === key);
  if (!s) return;
  const track = {
    title: s.title || 'Unknown',
    artist: s.artist || 'Unknown',
    thumb: s.thumb || '',
    preview: s.preview || null,
    videoId: null,
    photo: null,
    duration: 0,
    _query: s._query || `${s.artist || ''}|||${s.title || ''}|||${key}`
  };
  loadPlay(track, null);
}

// Tombol "+" di kartu "Saran Public" → buka modal pilih playlist yang sudah
// ada di seluruh aplikasi (openAddSongModal()), tanpa langsung memutar lagu.
function addFriendSuggestedSongToPlaylist(key) {
  const s = friendSuggestions.find(x => x.key === key);
  if (!s) return;
  openAddSongModal({
    title: s.title || 'Unknown',
    artist: s.artist || 'Unknown',
    thumb: s.thumb || '',
    _query: s._query || `${s.artist || ''}|||${s.title || ''}|||${key}`
  });
}

// Hapus saran lagu — hanya bisa dilakukan oleh yang menambahkannya sendiri
// (tombol ✕ hanya dirender untuk item milik currentUser, lihat renderFriendFavorites()).
async function deleteSongSuggestion(key) {
  if (!currentUser) return;
  const s = friendSuggestions.find(x => x.key === key);
  if (!s || s.uid !== currentUser.uid) return;
  try {
    await db.ref('friendSuggestions/' + key).remove();
    toast('🗑️ Song suggestion deleted');
  } catch (e) {
    toast('❌ Failed: ' + e.message);
  }
}

// Like/unlike lagu di "Saran Public" — disimpan realtime di
// friendSuggestions/{key}/likes/{uid}. Section ini sudah dipasangi listener
// 'value' (lihat startFriendSuggestionsListener()) yang otomatis me-render
// ulang & mengurutkan ulang grid begitu jumlah like berubah, jadi di sini
// cukup tulis/hapus like-nya saja tanpa perlu utak-atik DOM manual. Saat lagu
// di-like (bukan unlike), kirim notifikasi ke pengguna yang menyarankan lagu
// itu, sama seperti notifikasi like di playlist publik (lihat toggleLike()).
async function toggleFriendSongLike(e, key, currentlyLiked) {
  if (e) e.stopPropagation();
  if (!currentUser) { toast('Log in first to like this song'); return; }
  const likeRef = db.ref('friendSuggestions/' + key + '/likes/' + currentUser.uid);
  try {
    if (currentlyLiked) {
      await likeRef.remove();
    } else {
      await likeRef.set(true);

      // ── Kirim notifikasi ke pengguna yang menyarankan lagu ini ──
      try {
        const suggSnap = await db.ref('friendSuggestions/' + key).get();
        if (suggSnap.exists()) {
          const suggData = suggSnap.val();
          const ownerUid = suggData.uid;
          // Jangan kirim notif ke diri sendiri
          if (ownerUid && ownerUid !== currentUser.uid) {
            const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(() => null);
            const profile = profileSnap?.val() || {};
            const fromName = profile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
            const fromPhoto = profile.photoURL || profile.photoBase64 || currentUser.photoURL || '';
            const notif = {
              type: 'song_like',
              fromUid: currentUser.uid,
              fromName,
              fromPhoto,
              songKey: key,
              songTitle: suggData.title || 'song',
              songArtist: suggData.artist || '',
              ts: Date.now(),
              read: false
            };
            db.ref('users/' + ownerUid + '/notifications').push(notif).catch(() => {});
          }
        }
      } catch (notifErr) {
        console.warn('Notif song_like gagal:', notifErr);
      }
    }
  } catch (err) {
    toast('❌ Failed to like: ' + err.message);
  }
}

// ─── Modal: Add Song Suggestion ("Saran Public") ─────────────────────────
let selectedSuggTrack = null;
let suggSearchResults = [];
let suggSearchTimer = null;
let suggSearchAudio = null;
let suggSearchSeq = 0;

function openAddSuggestionModal() {
  if (!currentUser) { toast('❗ Log in first to add a song suggestion'); return; }
  selectedSuggTrack = null;
  document.getElementById('inp-sugg-picker').value = '';
  document.getElementById('inp-sugg-note').value = '';
  document.getElementById('inp-sugg-note-color').value = '#2E7DFF';
  document.getElementById('inp-sugg-emoji').value = '';
  document.getElementById('sugg-picker-preview').style.display = 'none';
  document.getElementById('sugg-picker-results').style.display = 'none';
  document.getElementById('sugg-picker-results').innerHTML = '';
  document.getElementById('sugg-emoji-full-picker').style.display = 'none';
  document.getElementById('btn-sugg-emoji-more').textContent = '😀 All Emojis';
  _suggEmojiFullPickerOpen = false;
  renderSuggEmojiQuickpick();
  document.getElementById('add-suggestion-modal').style.display = 'flex';
}
function closeAddSuggestionModal() {
  document.getElementById('add-suggestion-modal').style.display = 'none';
  if (suggSearchAudio) { suggSearchAudio.pause(); suggSearchAudio = null; }
}
document.getElementById('add-suggestion-modal').addEventListener('click', e => {
  if (e.target === document.getElementById('add-suggestion-modal')) closeAddSuggestionModal();
});

const SUGG_EMOJI_QUICKPICK = ['❤️','🔥','😍','😂','🥹','⭐','👍','🎧'];
function renderSuggEmojiQuickpick() {
  const el = document.getElementById('sugg-emoji-quickpick');
  const input = document.getElementById('inp-sugg-emoji');
  if (!el || !input) return;
  const current = input.value;
  el.innerHTML = SUGG_EMOJI_QUICKPICK.map(e =>
    `<button type="button" class="${e === current ? 'active' : ''}" onclick="pickSuggEmoji('${e}')">${e}</button>`
  ).join('');
}
function pickSuggEmoji(emoji) {
  document.getElementById('inp-sugg-emoji').value = emoji;
  renderSuggEmojiQuickpick();
  if (_suggEmojiFullPickerOpen) renderSuggEmojiFullPicker();
}
function clearSuggEmoji() {
  document.getElementById('inp-sugg-emoji').value = '';
  renderSuggEmojiQuickpick();
  if (_suggEmojiFullPickerOpen) renderSuggEmojiFullPicker();
}

