let _suggEmojiFullPickerOpen = false;

function toggleSuggEmojiFullPicker() {
  _suggEmojiFullPickerOpen = !_suggEmojiFullPickerOpen;
  const wrap = document.getElementById('sugg-emoji-full-picker');
  const btn = document.getElementById('btn-sugg-emoji-more');
  if (!wrap) return;
  if (_suggEmojiFullPickerOpen) {
    renderSuggEmojiFullPicker();
    wrap.style.display = 'block';
    if (btn) btn.textContent = '✕ Close';
  } else {
    wrap.style.display = 'none';
    if (btn) btn.textContent = '😀 All Emojis';
  }
}

function renderSuggEmojiFullPicker() {
  const wrap = document.getElementById('sugg-emoji-full-picker');
  const input = document.getElementById('inp-sugg-emoji');
  if (!wrap || !input) return;
  const current = input.value;
  wrap.innerHTML = Object.entries(SUGG_EMOJI_CATEGORIES).map(([label, list]) => `
    <div class="sugg-emoji-cat-label">${esc(label)}</div>
    <div class="sugg-emoji-cat-grid">
      ${list.map(e => `<button type="button" class="${e === current ? 'active' : ''}" onclick="pickSuggEmoji('${e}')" title="${esc(e)}">${e}</button>`).join('')}
    </div>
  `).join('');
}

function onSuggPickerInput(val) {
  selectedSuggTrack = null;
  document.getElementById('sugg-picker-preview').style.display = 'none';
  clearTimeout(suggSearchTimer);
  const dropdown = document.getElementById('sugg-picker-results');
  const q = (val || '').trim();
  if (q.length < 2) {
    dropdown.style.display = 'none';
    dropdown.innerHTML = '';
    return;
  }
  dropdown.style.display = 'block';
  dropdown.innerHTML = `<div class="sugg-picker-loading">Searching...</div>`;
  suggSearchTimer = setTimeout(() => doSuggSearch(q), 400);
}

// Menilai relevansi tiap hasil pencarian supaya rilisan ASLI naik ke atas,
// dan cover/tribute/karaoke/remix yg judulnya kebetulan menyebut nama artis
// aslinya (mis. "The Less I Know the Better (Tame Impala Cover)") tidak lagi
// ngalahin posisi lagu aslinya di daftar — walau menurut algoritma relevansi
// iTunes sendiri cover itu kadang skor-nya lebih tinggi krn nama artis asli
// ikut nyantol di teks judul.
function _suggBaseTitle(title) {
  // buang embel2 dlm kurung di akhir judul, mis "(Cover)", "(Tame Impala Cover)", "(Live)"
  return (title || '').replace(/\s*[\(\[][^\)\]]*[\)\]]\s*$/g, '').trim().toLowerCase();
}
function _suggScoreResult(t, q) {
  const base = _suggBaseTitle(t.title);
  const query = (q || '').trim().toLowerCase();
  let score = 0;
  if (base === query) score -= 100;               // judul (tanpa embel2 kurung) sama persis
  else if (base.startsWith(query) || query.startsWith(base)) score -= 40;
  else if (base.includes(query)) score -= 10;
  // dorong ke bawah kalau kelihatan bukan rilisan asli
  if (/\b(cover|tribute|karaoke|instrumental|made famous by|in the style of|originally performed by|remix)\b/i.test(t.title)) score += 60;
  return score;
}

// Search song lewat iTunes Search API. Sebelumnya dibatasi limit=8 dan HANYA
// storefront Indonesia (country=ID) — ini yang bikin banyak lagu (terutama
// rilisan artis luar yang belum masuk katalog Apple Music Indonesia, mis.
// "Sweet Boy" - Malcolm Todd) tidak pernah muncul sama sekali, karena
// storefront ID memang tidak selalu punya track itu di database-nya,
// terlepas seberapa tepat kata kuncinya. Sekarang: query DUA storefront
// sekaligus (ID + US, storefront dengan katalog musik terluas) secara
// paralel, gabungkan hasilnya (dedupe berdasar trackId), dan TIDAK ada lagi
// limit buatan pada jumlah hasil yang ditampilkan — semua hasil yang
// dikembalikan iTunes (maksimum teknis API itu sendiri, 200/request) akan
// tampil, tinggal discroll di dropdown-nya.
//
// TAMBAHAN: utk judul yg sangat umum (mis. "the less i know the better")
// ada RATUSAN cover/tribute/karaoke/lofi version yg beredar, jadi rilisan
// asli bisa saja tidak masuk 200 hasil teratas versi default iTunes (yg
// mencocokkan term ke SEMUA field: judul, artis, album sekaligus) — kalau
// track itu sendiri tidak pernah ke-fetch sama sekali, sortir ulang di
// atas tidak akan membantu. Makanya sekarang query dijalankan 2x per
// storefront: sekali default, sekali lagi dgn attribute=songTerm (cari
// KHUSUS di kolom judul lagu saja, tanpa terganggu match di field artis/
// album) — kombinasi ini jauh lebih mungkin menjaring rilisan aslinya.
async function doSuggSearch(q) {
  const mySeq = ++suggSearchSeq;
  const dropdown = document.getElementById('sugg-picker-results');
  try {
    const countries = ['ID', 'US'];
    const reqs = [];
    // cache-buster: iTunes Search API endpoint ada bug dikenal di CDN Apple —
    // utk term yg sangat sering dicari dari BANYAK situs berbeda (spt lagu
    // hits ini), respons yg ke-cache di edge kadang membawa header
    // Access-Control-Allow-Origin milik origin situs LAIN, bikin browser
    // diam2 nge-block fetch() krn dianggap pelanggaran CORS (tanpa error yg
    // kelihatan di UI kita krn di-catch jadi array kosong). Nambahin
    // parameter acak + cache:'no-store' motong request lewat cache yg
    // "diracuni" itu, jadi kita selalu dapet respons fresh dari Apple.
    const bust = () => `_=${Date.now()}_${Math.random().toString(36).slice(2)}`;
    countries.forEach(c => {
      reqs.push(fetch(`https://itunes.apple.com/search?term=${encodeURIComponent(q)}&media=music&entity=song&limit=200&country=${c}&${bust()}`, { signal: AbortSignal.timeout(8000), cache: 'no-store' })
        .then(res => res.ok ? res.json() : { results: [] })
        .catch(() => ({ results: [] })));
      reqs.push(fetch(`https://itunes.apple.com/search?term=${encodeURIComponent(q)}&media=music&entity=song&attribute=songTerm&limit=200&country=${c}&${bust()}`, { signal: AbortSignal.timeout(8000), cache: 'no-store' })
        .then(res => res.ok ? res.json() : { results: [] })
        .catch(() => ({ results: [] })));
    });
    // Sumber KEDUA yg independen dari iTunes: Deezer. Deezer ngasih skor
    // popularitas resmi per lagu ("rank" — makin tinggi makin sering
    // diputar/disukai), jadi kalau iTunes gagal balikin rilisan aslinya utk
    // term tertentu (spt yg kejadian di kasus ini), Deezer bisa jadi
    // jaring pengaman: lagu aslinya yg populer hampir pasti menang rank-nya
    // lawan cover2 yg jarang didengar. Pakai JSONP (bukan fetch) krn Deezer
    // memang tidak kasih header CORS utk request browser biasa.
    const deezerPromise = _deezerJsonp('https://api.deezer.com/search?q=' + encodeURIComponent(q) + '&order=RANKING&limit=25')
      .catch(() => null);

    const responses = await Promise.all(reqs);
    const deezerData = await deezerPromise;
    if (mySeq !== suggSearchSeq) return; // hasil pencarian lama, abaikan

    const seen = new Set();
    suggSearchResults = [];
    responses.forEach(data => {
      (data.results || []).forEach(it => {
        const id = it.trackId || `${it.artistName}|||${it.trackName}`;
        if (seen.has(id)) return; // sudah ada dari storefront/mode lain, skip duplikat
        seen.add(id);
        suggSearchResults.push({
          title: it.trackName || 'Unknown',
          artist: it.artistName || 'Unknown',
          thumb: (it.artworkUrl100 || '').replace('100x100bb', '600x600bb'),
          preview: it.previewUrl || null,
          releaseTs: it.releaseDate ? Date.parse(it.releaseDate) : Infinity,
          rank: 0,
          _query: `${it.artistName || ''}|||${it.trackName || ''}|||${it.trackId || Math.random()}`
        });
      });
    });

    // Gabungkan hasil Deezer, hindari duplikat berdasar judul(base)+artis yg
    // sudah ada dari iTunes.
    const seenNames = new Set(suggSearchResults.map(t => _suggBaseTitle(t.title) + '|||' + (t.artist || '').trim().toLowerCase()));
    ((deezerData && deezerData.data) || []).forEach(t => {
      const dt = _normalizeDeezerTrack(t);
      const nameKey = _suggBaseTitle(dt.title) + '|||' + (dt.artist || '').trim().toLowerCase();
      if (seenNames.has(nameKey)) return;
      seenNames.add(nameKey);
      suggSearchResults.push({
        title: dt.title,
        artist: dt.artist,
        thumb: dt.thumb,
        preview: dt.preview,
        releaseTs: Infinity,
        rank: dt.rank || 0,
        _query: `${dt.artist}|||${dt.title}|||dz${dt.id}`
      });
    });

    // Susun ulang: lagu yg judulnya paling cocok (rilisan asli) naik ke atas,
    // cover/tribute/karaoke/remix didorong ke bawah. Kalau skornya sama,
    // menangkan yg skor popularitas Deezer-nya lebih tinggi, baru kalau itu
    // masih seri juga menangkan rilisan yg tanggal rilis iTunes-nya PALING
    // LAWAS — cover/tribute hampir selalu dirilis belakangan drpd aslinya.
    suggSearchResults.sort((a, b) => {
      const diff = _suggScoreResult(a, q) - _suggScoreResult(b, q);
      if (diff !== 0) return diff;
      const rankDiff = (b.rank || 0) - (a.rank || 0);
      if (rankDiff !== 0) return rankDiff;
      return (a.releaseTs || Infinity) - (b.releaseTs || Infinity);
    });

    if (!suggSearchResults.length) {
      dropdown.innerHTML = `<div class="sugg-picker-loading">No results for "${esc(q)}"</div>`;
      return;
    }
    dropdown.innerHTML = suggSearchResults.map((t, i) => `
      <div class="sugg-picker-row" onclick="selectSuggSearchResult(${i})">
        <div class="sugg-picker-thumb">${t.thumb ? `<img src="${esc(t.thumb)}" alt="">` : '♪'}</div>
        <div class="sugg-picker-info">
          <div class="sugg-picker-title">${esc(t.title)}</div>
          <div class="sugg-picker-artist">${esc(t.artist)}</div>
        </div>
        ${t.preview ? `<button type="button" class="sugg-picker-play-btn" onclick="event.stopPropagation();previewSuggTrack(${i})" title="Play 30-second preview"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg></button>` : ''}
      </div>`).join('');
  } catch (e) {
    if (mySeq !== suggSearchSeq) return;
    dropdown.innerHTML = `<div class="sugg-picker-loading">❌ ${esc(e.message)}</div>`;
  }
}

function previewSuggTrack(i) {
  const t = suggSearchResults[i];
  if (!t || !t.preview) { toast('ℹ️ Preview not available for this song'); return; }
  if (suggSearchAudio) { suggSearchAudio.pause(); suggSearchAudio = null; }
  suggSearchAudio = new Audio(t.preview);
  suggSearchAudio.play().catch(() => toast('❌ Failed to play preview'));
  toast('▶️ Memutar preview 30 detik: ' + t.title);
}

function selectSuggSearchResult(i) {
  const t = suggSearchResults[i];
  if (!t) return;
  selectedSuggTrack = t;
  document.getElementById('inp-sugg-picker').value = `${t.title} — ${t.artist}`;
  const dropdown = document.getElementById('sugg-picker-results');
  dropdown.style.display = 'none';
  dropdown.innerHTML = '';
  const preview = document.getElementById('sugg-picker-preview');
  preview.style.display = 'flex';
  preview.innerHTML = `
    <div style="width:36px;height:36px;border-radius:7px;overflow:hidden;flex-shrink:0;background:var(--panel);display:flex;align-items:center;justify-content:center;font-size:1rem;">${t.thumb ? `<img src="${esc(t.thumb)}" alt="" style="width:100%;height:100%;object-fit:cover;">` : '♪'}</div>
    <div style="min-width:0;flex:1;">
      <div style="font-size:.78rem;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${esc(t.title)}</div>
      <div style="font-size:.68rem;color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${esc(t.artist)}</div>
    </div>
    ${t.preview ? `<button type="button" onclick="previewSuggTrack(suggSearchResults.indexOf(selectedSuggTrack))" style="flex-shrink:0;width:30px;height:30px;border-radius:50%;background:var(--green-dim);border:1px solid rgba(46,125,255,.3);color:var(--green);display:flex;align-items:center;justify-content:center;cursor:pointer;" title="Play preview"><svg viewBox="0 0 24 24" fill="currentColor" width="13" height="13"><path d="M8 5v14l11-7z"/></svg></button>` : ''}
  `;
}

// Tutup dropdown pencarian saat klik di luar area
document.addEventListener('click', (e) => {
  const wrap = document.querySelector('#add-suggestion-modal .sugg-picker-wrap');
  if (wrap && !wrap.contains(e.target)) {
    const dropdown = document.getElementById('sugg-picker-results');
    if (dropdown) dropdown.style.display = 'none';
  }
});

// Simpan saran lagu ke node PUBLIC "friendSuggestions" (bukan lagi ke
// users/{uid}/favoriteSongs milik sendiri) — supaya langsung tampil di
// "Saran Public" untuk SEMUA user via listener realtime di
// startFriendSuggestionsListener(), tidak peduli status follow.
async function addSongSuggestion() {
  if (!currentUser) return;
  const note = document.getElementById('inp-sugg-note').value.trim();
  const noteColor = document.getElementById('inp-sugg-note-color').value || '#2E7DFF';
  const emoji = document.getElementById('inp-sugg-emoji').value.trim();
  if (!selectedSuggTrack) { toast('❗ Select a song from the list first'); return; }

  const btn = document.getElementById('btn-add-suggestion');
  btn.disabled = true; btn.textContent = 'Adding...';
  try {
    const pSnap = await db.ref('users/' + currentUser.uid + '/profile').get();
    const myProfile = pSnap.exists() ? (pSnap.val() || {}) : {};
    const myName = myProfile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const myPhoto = myProfile.photoURL || myProfile.photoBase64 || currentUser.photoURL || '';

    await db.ref('friendSuggestions').push({
      uid: currentUser.uid,
      name: myName,
      photo: myPhoto,
      title: selectedSuggTrack.title || '',
      artist: selectedSuggTrack.artist || '',
      thumb: selectedSuggTrack.thumb || '',
      _query: selectedSuggTrack._query || '',
      preview: selectedSuggTrack.preview || '',
      note, noteColor, emoji, addedAt: Date.now()
    });
    toast('✅ Song suggestion added to "Public Suggestions"!');
    closeAddSuggestionModal();
  } catch (e) {
    toast('❌ Failed: ' + e.message);
  } finally {
    btn.disabled = false; btn.textContent = '+ Add';
  }
}

// Sinkronkan label semua tombol "Ikuti" yang mungkin sedang tampil
// (halaman profil artis & panel lirik kanan) dengan status terbaru.
function syncAllFollowButtons() {
  const artistBtn = document.getElementById('artist-follow-btn');
  if (artistBtn && _currentArtistData && _currentArtistData.name) {
    const f = isArtistFavorited(_currentArtistData.name);
    artistBtn.textContent = f ? 'Following' : 'Follow';
    artistBtn.classList.toggle('following', f);
  }
  const lyrBtn = document.getElementById('lyr-artist-follow-btn');
  if (lyrBtn && curTrack && curTrack.artist) {
    const f = isArtistFavorited(curTrack.artist);
    lyrBtn.textContent = f ? 'Following' : 'Follow';
    lyrBtn.classList.toggle('following', f);
  }
  const npBtn = document.getElementById('np-about-follow');
  if (npBtn && curTrack && curTrack.artist) {
    const f = isArtistFavorited(curTrack.artist);
    npBtn.textContent = f ? 'Following' : 'Follow';
    npBtn.classList.toggle('following', f);
  }
  // Tombol "Ikuti" di feed Song Preview: semua slide dibangun sekaligus di
  // awal (renderSpSlides), jadi kalau follow/unfollow dilakukan lewat slide
  // lain, tombol slide-slide lain untuk artis yang sama (yang baru terlihat
  // saat scroll) perlu ikut disinkronkan di sini juga.
  document.querySelectorAll('.sp-follow-btn[data-artist]').forEach(btn => {
    const artist = btn.dataset.artist;
    if (!artist) return;
    const f = isArtistFavorited(artist);
    btn.textContent = f ? 'Following' : 'Follow';
    btn.classList.toggle('following', f);
  });
}

// Tombol "Ikuti" di halaman profil artis (Home > buka artis)
function toggleArtistViewFollow() {
  if (!_currentArtistData || !_currentArtistData.name) { toast(' Artist data not loaded yet'); return; }
  toggleFollowArtist(_currentArtistData.name, _currentArtistData.photo || '');
}

