// ─── GAYA TEKS / KINETIC TYPOGRAPHY ──────────────────────
let _lyrStyle = localStorage.getItem('lyrStyle') || 'classic'; // 'classic' | 'kinetic' | 'alight'
let _kineticIdx = -1;
let _kWordTimer = null;
let _kBeatTimer = null;
let _kDotTimer = null;
let _kRafId = null;
let _kWordTimestamps = [];
let _kWordLitIdx = -1;
// Mode Alight: baris pendek (<3 kata) digabung dengan baris berikutnya supaya
// setiap "kelompok" yang tampil di layar selalu berisi minimal 3 kata, dan
// kata yang sudah tampil tidak dirender ulang / diblur lagi selama masih
// dalam kelompok yang sama.
let _kAlightGroupStart = -1;
let _kAlightGroupEnd = -1;

function openStylePicker() {
  document.getElementById('style-picker-modal').style.display = 'flex';
  document.getElementById('style-classic').classList.toggle('selected', _lyrStyle === 'classic');
  document.getElementById('style-kinetic').classList.toggle('selected', _lyrStyle === 'kinetic');
  document.getElementById('style-alight').classList.toggle('selected', _lyrStyle === 'alight');
}
function closeStylePicker() {
  document.getElementById('style-picker-modal').style.display = 'none';
}
function selectLyrStyle(style) {
  _lyrStyle = style;
  localStorage.setItem('lyrStyle', style);
  document.getElementById('style-classic').classList.toggle('selected', style === 'classic');
  document.getElementById('style-kinetic').classList.toggle('selected', style === 'kinetic');
  document.getElementById('style-alight').classList.toggle('selected', style === 'alight');
  // Update UI
  const fsEl = document.getElementById('fs-lyr');
  const styleBtn = document.getElementById('fs-style-btn');
  const sideBtn = document.getElementById('lyr-style-btn');
  fsEl.classList.remove('kinetic-mode', 'alight-mode');
  if (style === 'kinetic' || style === 'alight') {
    fsEl.classList.add(style === 'kinetic' ? 'kinetic-mode' : 'alight-mode');
    if (styleBtn) styleBtn.classList.add('active');
    if (sideBtn) sideBtn.classList.add('active');
    _kineticIdx = -1;
    _kWordLitIdx = -1;
    _kWordTimestamps = [];
    _kAlightGroupStart = -1;
    _kAlightGroupEnd = -1;
    if (lyrs.length) updateKinetic();
  } else {
    if (styleBtn) styleBtn.classList.remove('active');
    if (sideBtn) sideBtn.classList.remove('active');
    clearKineticTimers();
    updateFSLyr();
  }
  closeStylePicker();
}

function clearKineticTimers() {
  if (_kWordTimer) clearTimeout(_kWordTimer);
  if (_kBeatTimer) clearTimeout(_kBeatTimer);
  if (_kDotTimer) clearTimeout(_kDotTimer);
  if (_kRafId) { cancelAnimationFrame(_kRafId); _kRafId = null; }
}

// ─── New system: word-by-word sync via requestAnimationFrame ───

function updateKinetic() {
  if ((_lyrStyle !== 'kinetic' && _lyrStyle !== 'alight') || !lyrs.length) return;
  let idx = 0;
  for (let i = 0; i < lyrs.length; i++) { if (cur >= lyrs[i].time) idx = i; else break; }
  if (idx === _kineticIdx) return;
  _kineticIdx = idx;
  renderKineticLines(idx);
}

function renderKineticLines(idx) {
  const prevEl  = document.getElementById('k-prev');
  const nextEl  = document.getElementById('k-next');
  const stage   = document.getElementById('k-word-stage');
  if (!prevEl || !nextEl || !stage) return;

  const prevLine = idx > 0 ? (lyrs[idx - 1].instrumental ? '' : lyrs[idx - 1].text) : '';
  const curLine  = lyrs[idx].instrumental ? '' : lyrs[idx].text;
  const nextLine = idx < lyrs.length - 1 ? (lyrs[idx + 1].instrumental ? '' : lyrs[idx + 1].text) : '';

  // Baris konteks
  prevEl.textContent = prevLine;
  nextEl.textContent = nextLine;

  // Hitung durasi baris aktif
  const lineStart = lyrs[idx].time;
  const lineEnd   = idx < lyrs.length - 1 ? lyrs[idx + 1].time : lineStart + 4;
  const lineDur   = Math.max(lineEnd - lineStart, 0.5);

  // Motion blur flash
  const overlay = document.getElementById('k-blur-overlay');
  if (overlay) { overlay.classList.remove('flash'); void overlay.offsetWidth; overlay.classList.add('flash'); }

  // Create elemen kata di stage — semuanya mulai tersembunyi
  stage.innerHTML = '';
  stage.classList.remove('k-stage-enter');

  // Instrumental line: show animated bars in stage
  if (lyrs[idx].instrumental) {
    stage.innerHTML = '<div class="fs-ll instrumental active" style="justify-content:center;"><span class="inst-notes"><span style="height:8px"></span><span style="height:18px"></span><span style="height:10px"></span><span style="height:20px"></span><span style="height:12px"></span></span></div>';
    _kWordTimestamps = [];
    _kAlightGroupStart = -1;
    _kAlightGroupEnd = -1;
    buildProgressDots(0);
    void stage.offsetWidth;
    stage.classList.add('k-stage-enter');
    if (_kRafId) cancelAnimationFrame(_kRafId);
    return;
  }

  // ── Mode Alight: gabungkan baris pendek (<3 kata) dengan baris
  //    berikutnya supaya kelompok kata yang tampil selalu minimal 3 kata.
  //    Kalau baris aktif (idx) masih bagian dari kelompok yang sedang
  //    tampil, jangan render ulang stage sama sekali — supaya kata yang
  //    sudah muncul sebelumnya tidak ikut ter-reset/blur lagi.
  if (_lyrStyle === 'alight') {
    if (idx >= _kAlightGroupStart && idx <= _kAlightGroupEnd && stage.children.length) {
      return; // masih dalam kelompok yang sama, biarkan rAF loop lanjut jalan
    }

    const MIN_WORDS = 3;
    let groupEnd = idx;
    let wordCount = (lyrs[idx].instrumental ? 0 : lyrs[idx].text.trim().split(/\s+/).filter(Boolean).length);
    while (wordCount < MIN_WORDS && groupEnd + 1 < lyrs.length && !lyrs[groupEnd + 1].instrumental) {
      groupEnd++;
      wordCount += lyrs[groupEnd].text.trim().split(/\s+/).filter(Boolean).length;
    }
    _kAlightGroupStart = idx;
    _kAlightGroupEnd = groupEnd;

    stage.innerHTML = '';
    _kWordTimestamps = [];
    _kWordLitIdx = -1;

    const LEAD  = 0.08;
    const TRAIL = 0.12;

    // Bungkus semua kata dalam grup ini (idx..groupEnd, minimal 3 kata)
    // ke dalam SATU baris (row) supaya tampil sebaris, bukan 1 kata/baris.
    const rowEl = document.createElement('div');
    rowEl.className = 'k-word-line';
    stage.appendChild(rowEl);

    for (let li = idx; li <= groupEnd; li++) {
      const subStart = lyrs[li].time;
      const subEnd   = li < lyrs.length - 1 ? lyrs[li + 1].time : subStart + 4;
      const subDur   = Math.max(subEnd - subStart, 0.5);
      const subWords = lyrs[li].text.trim().split(/\s+/).filter(Boolean);
      if (!subWords.length) continue;

      const usable   = subDur * (1 - LEAD - TRAIL);
      const charLens = subWords.map(w => Math.max(w.replace(/\W/g, '').length, 1));
      const totalChars = charLens.reduce((a, b) => a + b, 0);

      let cumChars = 0;
      subWords.forEach((w, i) => {
        const sp = document.createElement('span');
        sp.className = 'k-word';
        sp.textContent = w;
        rowEl.appendChild(sp);

        const tWord = subStart + subDur * LEAD + (cumChars / totalChars) * usable;
        _kWordTimestamps.push({ t: tWord, el: sp });
        cumChars += charLens[i];
      });
    }

    void stage.offsetWidth;
    stage.classList.add('k-stage-enter');
    buildProgressDots(_kWordTimestamps.length);

    if (_kRafId) cancelAnimationFrame(_kRafId);
    _kRafWordLoop();
    return;
  }

  const words = curLine.trim().split(/\s+/).filter(Boolean);
  _kWordTimestamps = [];
  _kWordLitIdx = -1;

  // Distribusi timestamp berdasarkan bobot panjang karakter kata.
  // Kata lebih panjang = waktu lebih banyak.
  // Sisakan 8% di awal (jeda natural masuk baris) dan 12% di akhir
  // (napas / jeda ke baris berikutnya).
  const LEAD   = 0.08;
  const TRAIL  = 0.12;
  const usable = lineDur * (1 - LEAD - TRAIL);

  const charLens   = words.map(w => Math.max(w.replace(/\W/g, '').length, 1));
  const totalChars = charLens.reduce((a, b) => a + b, 0);

  let cumChars = 0;
  words.forEach((w, i) => {
    const sp = document.createElement('span');
    sp.className = 'k-word';
    sp.textContent = w;
    stage.appendChild(sp);

    // Offset proporsional karakter kumulatif
    const tWord = lineStart + lineDur * LEAD + (cumChars / totalChars) * usable;
    _kWordTimestamps.push({ t: tWord, el: sp });
    cumChars += charLens[i];
  });

  // Animasi masuk stage
  void stage.offsetWidth;
  stage.classList.add('k-stage-enter');

  // Progress dots
  buildProgressDots(words.length);

  // Mulai rAF loop (restart jika sudah jalan)
  if (_kRafId) cancelAnimationFrame(_kRafId);
  _kRafWordLoop();
}

function _kRafWordLoop() {
  if (_lyrStyle !== 'kinetic' && _lyrStyle !== 'alight') return;

  const nowSec = cur;

  for (let i = 0; i < _kWordTimestamps.length; i++) {
    const wt = _kWordTimestamps[i];
    if (nowSec >= wt.t && i > _kWordLitIdx) {
      // Mark previous word as past
      if (_kWordLitIdx >= 0) {
        const prev = _kWordTimestamps[_kWordLitIdx].el;
        prev.classList.remove('k-word-lit', 'k-word-enter');
        prev.classList.add('k-word-past');
      }

      // Cek apakah kata ini sudah "jauh" terlewat (>0.4 detik terlambat)
      // Kalau iya, langsung past tanpa animasi supaya tidak menumpuk
      const isSkipped = (nowSec - wt.t) > 0.4;
      if (isSkipped) {
        wt.el.classList.remove('k-word-enter');
        wt.el.classList.add('k-word-past');
      } else {
        wt.el.classList.remove('k-word-past');
        wt.el.classList.add('k-word-enter');
        const el = wt.el;
        setTimeout(() => {
          el.classList.remove('k-word-enter');
          el.classList.add('k-word-lit');
        }, 180);
      }

      // Mode Alight: kata turun ke bawah, jaga kata aktif tetap di tengah layar
      if (_lyrStyle === 'alight') {
        const stage = document.getElementById('k-word-stage');
        // Titik pusat digeser sedikit ke bawah (bukan persis 50%) supaya
        // baris aktif tidak terlalu mepet ke atas layar.
        if (stage) stage.scrollTo({ top: wt.el.offsetTop - stage.clientHeight * 0.52 + wt.el.clientHeight / 2, behavior: 'smooth' });
      }

      _kWordLitIdx = i;
      updateDot(i, _kWordTimestamps.length);
    }
  }

  _kRafId = requestAnimationFrame(_kRafWordLoop);
}

function buildProgressDots(count) {
  const wrap = document.getElementById('k-progress-dots');
  if (!wrap) return;
  const n = Math.min(count, 8);
  wrap.innerHTML = '';
  for (let i = 0; i < n; i++) {
    const d = document.createElement('div');
    d.className = 'k-dot';
    d.id = 'k-dot-' + i;
    wrap.appendChild(d);
  }
}

function updateDot(wordIdx, total) {
  const n = Math.min(total, 8);
  const dotIdx = Math.round((wordIdx / Math.max(total - 1, 1)) * (n - 1));
  for (let i = 0; i < n; i++) {
    const d = document.getElementById('k-dot-' + i);
    if (d) d.classList.toggle('lit', i === dotIdx);
  }
}

// Hook into existing lyric update loop
const _origUpdateFSLyr = updateFSLyr;
updateFSLyr = function() {
  if (_lyrStyle === 'kinetic' || _lyrStyle === 'alight') {
    updateKinetic();
    updateFSProg(); // keep progress bar updated
    return;
  }
  _origUpdateFSLyr();
};

// Apply saved style on FS open
const _origOpenFS = openFS;
openFS = function() {
  _origOpenFS();
  const fsEl = document.getElementById('fs-lyr');
  const styleBtn = document.getElementById('fs-style-btn');
  const sideBtn = document.getElementById('lyr-style-btn');
  fsEl.classList.remove('kinetic-mode', 'alight-mode');
  if (_lyrStyle === 'kinetic' || _lyrStyle === 'alight') {
    fsEl.classList.add(_lyrStyle === 'kinetic' ? 'kinetic-mode' : 'alight-mode');
    if (styleBtn) styleBtn.classList.add('active');
    if (sideBtn) sideBtn.classList.add('active');
    _kineticIdx = -1;
    _kWordLitIdx = -1;
    _kWordTimestamps = [];
    _kAlightGroupStart = -1;
    _kAlightGroupEnd = -1;
    if (lyrs.length) updateKinetic();
  } else {
    if (styleBtn) styleBtn.classList.remove('active');
    if (sideBtn) sideBtn.classList.remove('active');
  }
};

// Clean up timers on close
const _origCloseFSKinetic = closeFS;
closeFS = function() {
  clearKineticTimers();
  _origCloseFSKinetic();
};

// ─── PUBLIC PLAYLISTS FEED ────────────────────────────────
let pubLikesCache = {}; // { key: likeCount }
let myLikes = {}; // { key: true }

async function loadPublicFeed() {
  if (!currentUser) return;
  const grid = document.getElementById('pub-grid');
  const rankGrid = document.getElementById('rank-grid');
  if (grid) grid.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:24px 0;font-size:.82rem;"><i style="font-size:1.8rem"></i><h3>Loading...</h3></div>';

  try {
    // Load my likes
    const likeSnap = await db.ref('public_playlists').get();
    if (!likeSnap.exists()) {
      document.getElementById('public-feed-section').style.display = 'none';
      if (grid) grid.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:24px 0;font-size:.82rem;"><i></i><h3>No playlists yet publik</h3></div>';
      return;
    }

    // Load my own likes record
    const myLikeSnap = await db.ref('public_playlists').get();
    const allData = likeSnap.val();

    // Build array of playlists with like counts
    const pls = [];
    for (const key in allData) {
      const pl = allData[key];
      if (!pl || !pl.ownerUid) continue;
      const likes = pl.likes ? Object.keys(pl.likes).length : 0;
      const iLiked = pl.likes && pl.likes[currentUser.uid] === true;
      const commentCount = pl.comments ? Object.keys(pl.comments).length : 0;
      pls.push({ key, ...pl, likeCount: likes, iLiked, commentCount });
    }

    if (!pls.length) {
      document.getElementById('public-feed-section').style.display = 'none';
      return;
    }

    document.getElementById('public-feed-section').style.display = 'block';

    // Render public grid (all, sorted by recency if possible)
    renderPublicGrid(pls);

  } catch(e) {
    console.error('loadPublicFeed error:', e);
    if (grid) grid.innerHTML = `<div class="empty" style="grid-column:1/-1;font-size:.82rem;color:var(--sub)"> Failed to load: ${esc(e.message)}</div>`;
  }
}

// ─── TOP SONGS TRENDING (Deezer live chart) ────────────────
// Deezer's public API doesn't send CORS headers for browser fetch(), so we
// load it via JSONP (a <script> tag call) — this is Deezer's own documented
// workaround for client-side apps. Data always comes straight from Deezer's
// chart endpoint, so it reflects whatever they have "trending" at the moment
// you open/refresh the page (their chart itself is updated daily on their end).
// Antrian & pembatas jumlah request Deezer JSONP yang jalan BERSAMAAN.
// Sebelumnya, setiap fitur (Daily Mix, Made For You, For You, Radio
// Artis Favorit, Rekomendasi) yang butuh top-track artis langsung menembak
// Deezer di saat yang sama saat halaman dimuat. Kalau user follow banyak
// artis, ini bisa jadi puluhan <script> JSONP nyala bareng dan banyak yang
// timeout/gagal (playlist jadi kosong / tidak muncul). Sekarang dibatasi
// maksimal beberapa request aktif sekaligus, sisanya antre dan dijalankan
// begitu slot kosong — bukan dibatalkan.
let _dzActiveCount = 0;
const _dzQueue = [];
const DZ_MAX_CONCURRENT = 5;
function _dzRunNext() {
  if (_dzActiveCount >= DZ_MAX_CONCURRENT || !_dzQueue.length) return;
  const job = _dzQueue.shift();
  _dzActiveCount++;
  job();
}
function _dzJobDone() {
  _dzActiveCount = Math.max(0, _dzActiveCount - 1);
  _dzRunNext();
}

function _deezerJsonp(url) {
  return new Promise((resolve, reject) => {
    _dzQueue.push(() => {
      const cbName = '_dzcb_' + Date.now() + '_' + Math.floor(Math.random() * 1e6);
      const script = document.createElement('script');
      let settled = false;
      // Kalau request sudah dianggap gagal/timeout tapi respons JSONP-nya baru
      // benar-benar sampai belakangan (request lama tetap jalan di jaringan
      // walau <script> tag-nya sudah dibuang), JANGAN langsung menghapus nama
      // callback-nya — ganti jadi fungsi kosong (no-op) dulu selama beberapa
      // detik. Ini yang mencegah "Uncaught ReferenceError: _dzcb_... is not
      // defined" di console saat banyak request foto artis berjalan bersamaan
      // (misalnya waktu scroll cepat di Song Preview).
      const cleanupSettled = () => {
        script.remove();
        try { delete window[cbName]; } catch (e) {}
      };
      const cleanupUnsettled = () => {
        script.remove();
        window[cbName] = () => { try { delete window[cbName]; } catch (e) {} };
        setTimeout(() => { try { delete window[cbName]; } catch (e) {} }, 15000);
      };
      window[cbName] = (data) => { if (settled) return; settled = true; cleanupSettled(); _dzJobDone(); resolve(data); };
      script.onerror = () => { if (settled) return; settled = true; cleanupUnsettled(); _dzJobDone(); reject(new Error('Failed to load Deezer data')); };
      script.src = url + (url.includes('?') ? '&' : '?') + 'output=jsonp&callback=' + cbName;
      document.body.appendChild(script);
      setTimeout(() => { if (settled) return; settled = true; cleanupUnsettled(); _dzJobDone(); reject(new Error('Deezer timeout')); }, 10000);
    });
    _dzRunNext();
  });
}

// ─── WIDGET "TENTANG ARTIS" (sidebar kiri) + PANEL ALBUM (kanan) ──
let _artistPhotoCache = {}; // nama artis (lowercase) -> url foto
let _artistReqGen = 0;
let _currentArtistData = null; // {id,name,photo,fans,tracks,albums} milik halaman profil artis yg sedang dibuka

function _updateArtistWidgets(track) {
  if (!track) return;
  // Panel kanan: gambar album + judul
  const artEl = document.getElementById('lyr-album-art');
  const titleEl = document.getElementById('lyr-album-title');
  const artistEl = document.getElementById('lyr-album-artist');
  const albumEl = document.getElementById('lyr-album-name');
  const headerTitleEl = document.getElementById('lyr-header-title');
  if (headerTitleEl) headerTitleEl.textContent = track.title || 'Album';
  if (artEl) { if (track.thumb) { artEl.style.display = 'block'; artEl.src = track.thumb; } else { artEl.style.display = 'none'; } }
  if (titleEl) titleEl.textContent = track.title || '—';
  if (artistEl) artistEl.textContent = track.artist || '—';
  if (albumEl) albumEl.textContent = track.album ? ` ${track.album}` : '';

  // Sidebar kiri: kartu "Tentang Artis"
  const card = document.getElementById('side-artist-card');
  const nameEl = document.getElementById('side-artist-name');
  const photoEl = document.getElementById('side-artist-photo');
  if (card && track.artist) {
    card.classList.add('show');
    if (nameEl) nameEl.textContent = track.artist;
    _loadArtistPhotoInto(photoEl, track.artist);
  }

  // Panel kanan: kotak artis + daftar album artis (bisa discroll)
  _updateLyrArtistBox(track);
  // Panel kanan: kotak "Next Up" (lagu selanjutnya, khusus PC)
  _renderLyrNextUp();
  // Panel kanan: kotak "Next Song" — antrian real, khusus mode Lolu DJ aktif
  _renderLyrNextSongBox();
}

// ─── Kotak "Tentang Artis" + Daftar Album di panel lirik kanan ──
let _lyrArtistAlbumsCache = {}; // nama artis (lowercase) -> daftar album
let _lyrArtistFansCache = {}; // nama artis (lowercase) -> jumlah pendengar
let _lyrArtistReqGen = 0;
let _lyrLastArtist = '';
let _lyrFollowedArtists = {}; // nama artis (lowercase) -> true jika diikuti (sesi ini saja)

async function _updateLyrArtistBox(track) {
  const card = document.getElementById('lyr-artist-card');
  const nameEl = document.getElementById('lyr-artist-card-name');
  const bannerImg = document.getElementById('lyr-artist-banner-img');
  const fansEl = document.getElementById('lyr-artist-card-fans-num');
  const followBtn = document.getElementById('lyr-artist-follow-btn');
  const albumsBox = document.getElementById('lyr-albums-box');
  const albumsScroll = document.getElementById('lyr-albums-scroll');

  if (!track || !track.artist) {
    if (card) card.classList.remove('show');
    if (albumsBox) albumsBox.classList.remove('show');
    return;
  }

  if (card) card.classList.add('show');
  if (nameEl) nameEl.textContent = track.artist;
  _loadArtistPhotoInto(bannerImg, track.artist);
  if (followBtn) {
    const following = isArtistFavorited(track.artist);
    followBtn.textContent = following ? 'Following' : 'Follow';
    followBtn.classList.toggle('following', following);
  }

  const key = track.artist.toLowerCase();
  if (fansEl) fansEl.textContent = _lyrArtistFansCache[key] != null ? formatFanCount(_lyrArtistFansCache[key]) : '—';

  if (key === _lyrLastArtist && _lyrArtistAlbumsCache[key]) {
    renderLyrAlbumsList(_lyrArtistAlbumsCache[key]);
    return;
  }
  _lyrLastArtist = key;

  if (_lyrArtistAlbumsCache[key]) {
    renderLyrAlbumsList(_lyrArtistAlbumsCache[key]);
    return;
  }

  const myGen = ++_lyrArtistReqGen;
  if (albumsBox) albumsBox.classList.add('show');
  if (albumsScroll) albumsScroll.innerHTML = '<div class="lyr-albums-loading">Loading albums...</div>';

  try {
    // PENTING: jangan cari artis cuma berdasarkan nama saja (bisa salah
    // tangkap artis lain yang kebetulan punya nama sama persis, mis. ada
    // beberapa artis di Deezer bernama "Oasis"). Pakai resolusi yang sama
    // dengan kotak "About the artist"/"Albums" Now Playing: cocokkan
    // artis+judul lagu yang sedang diputar dulu (atau pakai artistId yang
    // sudah tersimpan di track kalau ada), baru fallback ke nama saja.
    const artistId = track.artistId || await _resolveArtistIdForTrack(track.artist, track.title);
    if (myGen !== _lyrArtistReqGen) return;
    if (!artistId) {
      if (albumsScroll) albumsScroll.innerHTML = '<div class="lyr-albums-empty">Album not found</div>';
      return;
    }
    const artistData = await _deezerJsonp('https://api.deezer.com/artist/' + artistId);
    if (myGen !== _lyrArtistReqGen) return;
    _lyrArtistFansCache[key] = (artistData && artistData.nb_fan) || 0;
    if (fansEl && _lyrLastArtist === key) fansEl.textContent = formatFanCount(artistData && artistData.nb_fan);

    const albumData = await _deezerJsonp('https://api.deezer.com/artist/' + artistId + '/albums?limit=20');
    if (myGen !== _lyrArtistReqGen) return;
    const albums = ((albumData && albumData.data) || []).map(a => ({
      id: a.id,
      title: a.title || 'Unknown',
      cover: a.cover_medium || a.cover_big || a.cover_xl || '',
      year: (a.release_date || '').slice(0, 4)
    }));
    _lyrArtistAlbumsCache[key] = albums;
    renderLyrAlbumsList(albums);
  } catch (e) {
    if (myGen !== _lyrArtistReqGen) return;
    console.error('_updateLyrArtistBox error:', e);
    if (albumsScroll) albumsScroll.innerHTML = '<div class="lyr-albums-empty">Failed to load album</div>';
  }
}

// Tombol "Ikuti" di panel lirik kanan — memakai store follow global yang
// sama dengan halaman profil artis, sehingga otomatis muncul di "Artis Favorit".
function toggleLyrArtistFollow() {
  if (!curTrack || !curTrack.artist) return;
  const bannerImg = document.getElementById('lyr-artist-banner-img');
  const key = curTrack.artist.toLowerCase();
  const photo = (bannerImg && bannerImg.src && bannerImg.style.display !== 'none') ? bannerImg.src : (_artistPhotoCache[key] || '');
  toggleFollowArtist(curTrack.artist, photo);
}

function renderLyrAlbumsList(albums) {
  const albumsBox = document.getElementById('lyr-albums-box');
  const c = document.getElementById('lyr-albums-scroll');
  if (!c) return;
  c.innerHTML = '';
  if (albumsBox) albumsBox.classList.add('show');
  if (!albums.length) {
    c.innerHTML = '<div class="lyr-albums-empty">No albums found</div>';
    return;
  }
  albums.forEach(a => {
    const div = document.createElement('div');
    div.className = 'lyr-album-item';
    div.innerHTML = `
      <img class="lyr-album-item-cover" src="${esc(a.cover)}" alt="" loading="lazy" onerror="this.style.display='none'">
      <div class="lyr-album-item-info">
        <div class="lyr-album-item-title">${esc(a.title)}</div>
        <div class="lyr-album-item-year">${esc(a.year || '')}</div>
      </div>
    `;
    div.addEventListener('click', (e) => { e.stopPropagation(); openAlbumView(a.id, a.title); });
    c.appendChild(div);
  });
}

// Kotak "Jelajahi <Artis>" di panel kanan (khusus PC) — kartu menyamping
// (sama persis datanya dengan kotak mobile, lihat _renderNPNextUp()), isinya
// lagu-lagu LAIN dari artis yang SEDANG diputar. Klik salah satu langsung
// memutarnya & menjadikan seluruh daftar artis tsb sebagai antrian baru.
function _renderLyrNextUp() {
  const c = document.getElementById('lyr-nextup-scroll');
  const labelEl = document.getElementById('lyr-nextup-label');
  if (!c) return;
  const artistName = curTrack && curTrack.artist;
  if (labelEl) labelEl.textContent = artistName ? `Jelajahi ${artistName}` : 'Jelajahi Artis';
  if (!artistName) { c.innerHTML = '<div class="lyr-albums-empty">Play a song to see previews</div>'; return; }
  const full = _getExploreArtistTracks(artistName, curTrack && curTrack.title);
  const list = full.filter(t=>!curTrack || t.title.toLowerCase()!==curTrack.title.toLowerCase() || t.artist.toLowerCase()!==curTrack.artist.toLowerCase());
  if (!list.length) {
    c.innerHTML = '<div class="lyr-albums-empty">Loading previews…</div>';
    return;
  }
  c.innerHTML = '';
  list.forEach(t => {
    const div = document.createElement('div');
    div.className = 'expl-card';
    div.innerHTML = `
      <div class="expl-cover-wrap">
        ${t.thumb ? `<img class="expl-cover-img" src="${esc(t.thumb)}" alt="" loading="lazy" onerror="this.style.display='none'">` : ''}
        <div class="expl-overlay"><div class="expl-title">${esc(t.title)}</div></div>
      </div>
    `;
    div.addEventListener('click', (e) => { e.stopPropagation(); playExploreArtistTrack(t, full); });
    c.appendChild(div);
  });
}

// Ambil foto artis dari Deezer (di-cache per nama) lalu pasang ke elemen <img> tertentu.
async function _loadArtistPhotoInto(imgEl, artistName) {
  if (!imgEl || !artistName) return null;
  imgEl.dataset.wanted = artistName;
  const key = artistName.toLowerCase();
  if (_artistPhotoCache[key]) {
    if (imgEl.dataset.wanted === artistName) { imgEl.style.display = 'block'; imgEl.src = _artistPhotoCache[key]; }
    return _artistPhotoCache[key];
  }
  // Kalau foto artis yang sama sedang diminta oleh slide lain di saat
  // bersamaan (umum terjadi saat scroll cepat, karena banyak lagu bisa
  // punya artis yang sama), gabung ke satu request yang sama alih-alih
  // menembak request JSONP baru berkali-kali — ini yang bikin loading
  // lebih cepat dan mengurangi request yang gagal/timeout.
  let pending = _artistPhotoInFlight[key];
  if (!pending) {
    pending = _queueArtistPhotoFetch(artistName, key);
    _artistPhotoInFlight[key] = pending;
  }
  const pic = await pending;
  if (pic && imgEl.dataset.wanted === artistName) { imgEl.style.display = 'block'; imgEl.src = pic; }
  return pic;
}

// Request in-flight per artis (key -> Promise), supaya slide berbeda dengan
// artis yang sama tidak saling menembak request duplikat.
let _artistPhotoInFlight = {};
// Batasi maksimal berapa request foto artis yang boleh berjalan bersamaan ke
// Deezer. Tanpa batas ini, scroll cepat di Song Preview bisa memicu puluhan
// request JSONP sekaligus yang saling berebut koneksi — bikin lambat DAN
// gampang timeout (yang berujung foto tidak muncul). Dengan antrean kecil
// ini, request tetap jalan cepat satu-satu tanpa membanjiri jaringan.
const ARTIST_PHOTO_MAX_CONCURRENT = 4;
let _artistPhotoActive = 0;
const _artistPhotoQueue = [];
function _runArtistPhotoQueue() {
  if (_artistPhotoActive >= ARTIST_PHOTO_MAX_CONCURRENT) return;
  const job = _artistPhotoQueue.shift();
  if (!job) return;
  _artistPhotoActive++;
  job().finally(() => { _artistPhotoActive--; _runArtistPhotoQueue(); });
}
function _queueArtistPhotoFetch(artistName, key) {
  return new Promise((resolveOuter) => {
    const job = async () => {
      try {
        const data = await _deezerJsonp('https://api.deezer.com/search/artist?q=' + encodeURIComponent(artistName) + '&limit=10');
        const qResults = (data && data.data) || [];
        const qNorm = artistName.trim().toLowerCase();
        const a = qResults.find(x => (x.name || '').trim().toLowerCase() === qNorm) || qResults[0];
        const pic = a ? (a.picture_xl || a.picture_big || a.picture_medium) : '';
        if (pic) _artistPhotoCache[key] = pic;
        resolveOuter(pic || null);
      } catch (e) {
        resolveOuter(null);
      } finally {
        delete _artistPhotoInFlight[key];
      }
    };
    _artistPhotoQueue.push(job);
    _runArtistPhotoQueue();
  });
}

function formatFanCount(n) {
  n = n || 0;
  try { return n.toLocaleString('en-US'); } catch (e) { return String(n); }
}

// ─── HALAMAN PROFIL ARTIS (cara kerja seperti Spotify) ─────
// Dipanggil saat nama artis manapun di-klik: bar pemutar, hero pencarian,
// panel album kanan, atau kartu "Tentang Artis" di sidebar kiri.
function openArtistView(artistName) {
  if (!artistName) { toast(' No song currently playing'); return; }
  _closeYoursViewIfOpen();
  document.getElementById('home-view').classList.remove('active');
  document.getElementById('search-view').classList.remove('active');
  document.getElementById('finder-view').style.display = 'none';
  document.getElementById('playlist-view').style.display = 'none';
  document.getElementById('top-songs-full-view').style.display = 'none';
  document.getElementById('recently-played-full-view').style.display = 'none';
  document.getElementById('recommend-full-view').style.display = 'none';
  document.getElementById('artist-view').style.display = 'block';
  document.getElementById('album-view').style.display = 'none';
  document.getElementById('song-preview-view').style.display = 'none';
  document.body.classList.remove('sp-mobile-open');
  if (typeof spAudio !== 'undefined' && spAudio) { spAudio.pause(); }
  if (typeof closeFSLyricsIfOpen === 'function') { closeFSLyricsIfOpen(); }
  document.getElementById('nav-home').classList.remove('on');
  document.getElementById('nav-search').classList.remove('on');
  document.getElementById('nav-finder').classList.remove('on');
  document.getElementById('nav-songpreview')?.classList.remove('on');
  const mainEl = document.getElementById('main'); if (mainEl) mainEl.scrollTop = 0;

  document.getElementById('artist-banner-name').textContent = artistName;
  document.getElementById('artist-banner-sub').textContent = 'Loading...';
  const bg = document.getElementById('artist-banner-bg'); bg.style.display = 'none'; bg.src = '';
  document.getElementById('artist-banner-desc').textContent = '';
  ['artist-social-ig', 'artist-social-yt', 'artist-social-x'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.href = '#';
  });
  document.getElementById('artist-songs-grid').innerHTML = '<div class="empty" style="grid-column:1/-1;padding:16px 0;font-size:.8rem;"><i></i><h3>Loading songs...</h3></div>';
  document.getElementById('artist-albums-grid').innerHTML = '<div class="empty" style="grid-column:1/-1;padding:16px 0;font-size:.8rem;"><i></i><h3>Loading albums...</h3></div>';
  const followBtn = document.getElementById('artist-follow-btn');
  if (followBtn) {
    const f = isArtistFavorited(artistName);
    followBtn.textContent = f ? 'Following' : 'Follow';
    followBtn.classList.toggle('following', f);
  }

  // reset sticky header (animasi scroll spt Spotify) & tombol "Show all"
  const stickyHeader = document.getElementById('artist-sticky-header');
  if (stickyHeader) stickyHeader.classList.remove('show');
  const stickyPhoto = document.getElementById('artist-sticky-photo');
  if (stickyPhoto) { stickyPhoto.src = ''; }
  document.getElementById('artist-sticky-name').textContent = artistName;
  const showAllBtn = document.getElementById('artist-showall-btn');
  if (showAllBtn) showAllBtn.classList.remove('show');
  closeArtistAllAlbumsView();
  if (mainEl) mainEl.scrollTop = 0;
  // reset animasi foto/nama besar sebelum data baru dimuat
  const bannerContent = document.querySelector('#artist-view .artist-banner-content');
  if (bannerContent) { bannerContent.style.opacity = ''; bannerContent.style.transform = ''; bannerContent.style.pointerEvents = ''; }
  if (bg) { bg.style.transform = ''; bg.style.opacity = ''; }
  _updateArtistScrollFx();

  loadArtistProfile(artistName);
}

function backFromArtistView() {
  document.getElementById('artist-view').style.display = 'none';
  document.getElementById('album-view').style.display = 'none';
  document.getElementById('song-preview-view').style.display = 'none';
  document.body.classList.remove('sp-mobile-open');
  if (typeof spAudio !== 'undefined' && spAudio) { spAudio.pause(); }
  if (typeof closeFSLyricsIfOpen === 'function') { closeFSLyricsIfOpen(); }
  closeArtistAllAlbumsView();
  document.getElementById('artist-sticky-header')?.classList.remove('show');
  showHomeView();
}

// Ambil SEMUA album milik seorang artis, tidak dibatasi jumlah — Deezer
// membatasi setiap request maksimal 100 item, jadi di sini kita loop
// menaikkan "index" (halaman berikutnya) sampai datanya habis.
async function _fetchAllArtistAlbums(artistId) {
  const pageSize = 100;
  let index = 0;
  let all = [];
  while (true) {
    let data;
    try {
      data = await _deezerJsonp('https://api.deezer.com/artist/' + artistId + '/albums?limit=' + pageSize + '&index=' + index);
    } catch (e) { break; }
    const list = (data && data.data) || [];
    if (!list.length) break;
    all = all.concat(list);
    if (list.length < pageSize) break; // ini sudah halaman terakhir
    index += pageSize;
    if (all.length > 1000) break; // jaga-jaga biar tidak loop tanpa henti
  }
  return all;
}

async function loadArtistProfile(artistName) {
  const myGen = ++_artistReqGen;
  try {
    const searchData = await _deezerJsonp('https://api.deezer.com/search/artist?q=' + encodeURIComponent(artistName) + '&limit=10');
    const results = (searchData && searchData.data) || [];
    const qNorm = artistName.trim().toLowerCase();
    // Deezer's search endpoint doesn't always put the artist you searched for
    // first — it sometimes ranks a similarly-named artist (e.g. a tribute /
    // cover act) above the real one. Prefer an exact (case-insensitive) name
    // match over just taking result[0], and only fall back to the top result
    // if nothing matches exactly.
    const exactMatches = results.filter(a => (a.name || '').trim().toLowerCase() === qNorm);
    const artist = (exactMatches.length
      ? exactMatches.reduce((best, a) => (a.nb_fan || 0) > (best.nb_fan || 0) ? a : best)
      : results[0]);
    if (myGen !== _artistReqGen) return; // pengguna sudah membuka artis lain sebelum request ini selesai
    if (!artist) {
      document.getElementById('artist-banner-sub').textContent = 'Artist not found';
      document.getElementById('artist-songs-grid').innerHTML = '<div class="err-box">Artist data not found on Deezer.</div>';
      document.getElementById('artist-albums-grid').innerHTML = '';
      return;
    }
    const photo = artist.picture_xl || artist.picture_big || artist.picture_medium || '';
    _currentArtistData = { id: artist.id, name: artist.name, photo, fans: artist.nb_fan || 0, tracks: [], albums: [] };
    if (photo) _artistPhotoCache[artistName.toLowerCase()] = photo;
    syncAllFollowButtons();

    document.getElementById('artist-banner-name').textContent = artist.name;
    document.getElementById('artist-banner-sub').textContent = formatFanCount(artist.nb_fan) + ' listeners';
    const bgEl = document.getElementById('artist-banner-bg');
    if (photo) { bgEl.src = photo; bgEl.style.display = 'block'; }
    document.getElementById('artist-sticky-name').textContent = artist.name;
    const stickyPhoto = document.getElementById('artist-sticky-photo');
    if (stickyPhoto && photo) stickyPhoto.src = photo;

    // Tombol Instagram & X — arahkan langsung ke profil dengan format
    // instagram.com/namaartis/ dan x.com/namaartis (slug dari nama artis,
    // tanpa spasi/simbol). Tombol YouTube tetap ke halaman pencarian karena
    // Deezer tidak menyediakan link akun resmi YouTube.
    const igSlug = artist.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
    const socialQ = encodeURIComponent(artist.name);
    const igEl = document.getElementById('artist-social-ig');
    const ytEl = document.getElementById('artist-social-yt');
    const xEl = document.getElementById('artist-social-x');
    if (igEl) igEl.href = 'https://www.instagram.com/' + igSlug + '/';
    if (ytEl) ytEl.href = 'https://www.youtube.com/results?search_query=' + socialQ;
    if (xEl) xEl.href = 'https://x.com/' + igSlug;
    _updateArtistScrollFx();

    const [topData, allAlbums] = await Promise.all([
      _deezerJsonp('https://api.deezer.com/artist/' + artist.id + '/top?limit=10').catch(() => null),
      _fetchAllArtistAlbums(artist.id).catch(() => [])
    ]);
    if (myGen !== _artistReqGen) return;

    const tracks = ((topData && topData.data) || []).map(t => ({
      id: t.id,
      title: t.title || t.title_short || 'Unknown',
      artist: (t.artist && t.artist.name) || artist.name,
      thumb: (t.album && (t.album.cover_xl || t.album.cover_big || t.album.cover_medium)) || photo || '',
      preview: t.preview || null,
      duration: t.duration || 0
    }));
    _currentArtistData.tracks = tracks;
    renderArtistSongs(tracks);

    const albums = (allAlbums || []).map(a => ({
      id: a.id,
      title: a.title || 'Unknown',
      cover: a.cover_xl || a.cover_big || a.cover_medium || '',
      year: (a.release_date || '').slice(0, 4)
    }));
    _currentArtistData.albums = albums;
    renderArtistAlbums(albums);

    // Keterangan singkat tentang artis, tampil di bawah nama
    const descEl = document.getElementById('artist-banner-desc');
    if (descEl) {
      const parts = [];
      if (albums.length) parts.push(albums.length + ' Album');
      if (tracks.length) parts.push(tracks.length + ' Popular Songs');
      descEl.textContent = parts.length ? parts.join(' · ') : '';
    }
  } catch (e) {
    if (myGen !== _artistReqGen) return;
    console.error('loadArtistProfile error:', e);
    document.getElementById('artist-banner-sub').textContent = 'Failed to load artist data';
    document.getElementById('artist-songs-grid').innerHTML = '<div class="err-box"> Failed to load artist songs. Try again.</div>';
    document.getElementById('artist-albums-grid').innerHTML = '';
  }
}

function renderArtistSongs(tracks) {
  const c = document.getElementById('artist-songs-grid');
  if (!c) return;
  c.innerHTML = '';
  if (!tracks.length) { c.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:16px 0;font-size:.8rem;color:var(--sub)">No songs found.</div>'; return; }
  tracks.forEach((t, i) => c.appendChild(buildRankItemEl(t, i, true)));
}

const ARTIST_ALBUMS_PREVIEW_COUNT = 9;

function _buildAlbumCardEl(a) {
  const div = document.createElement('div');
  div.className = 'artist-album-card';
  div.innerHTML = `
    <img class="artist-album-cover" src="${esc(a.cover)}" alt="" loading="lazy" onerror="this.style.display='none'">
    <div class="artist-album-title">${esc(a.title)}</div>
    <div class="artist-album-year">${esc(a.year || '')}</div>
  `;
  div.addEventListener('click', () => { closeArtistAllAlbumsView(); openAlbumView(a.id, a.title); });
  return div;
}

function renderArtistAlbums(albums) {
  const c = document.getElementById('artist-albums-grid');
  const showAllBtn = document.getElementById('artist-showall-btn');
  if (!c) return;
  c.innerHTML = '';
  if (!albums.length) {
    c.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:16px 0;font-size:.8rem;color:var(--sub)">No albums found.</div>';
    if (showAllBtn) showAllBtn.classList.remove('show');
    return;
  }
  // Hanya tampilkan 6 album di halaman artis; sisanya bisa dilihat lewat tombol "Show all"
  const preview = albums.slice(0, ARTIST_ALBUMS_PREVIEW_COUNT);
  preview.forEach(a => c.appendChild(_buildAlbumCardEl(a)));
  if (showAllBtn) showAllBtn.classList.toggle('show', albums.length > ARTIST_ALBUMS_PREVIEW_COUNT);
}

// Tombol "Show all" — arahkan user ke halaman berisi semua album artis ini
function openArtistAllAlbumsView() {
  if (!_currentArtistData || !_currentArtistData.albums.length) return;
  const view = document.getElementById('artist-all-albums-view');
  const grid = document.getElementById('artist-all-albums-grid');
  document.getElementById('aall-title').textContent = _currentArtistData.name;
  document.getElementById('aall-subtitle').textContent = _currentArtistData.albums.length + ' Album';
  grid.innerHTML = '';
  _currentArtistData.albums.forEach(a => grid.appendChild(_buildAlbumCardEl(a)));
  view.classList.add('show');
}

function closeArtistAllAlbumsView() {
  const view = document.getElementById('artist-all-albums-view');
  if (view) view.classList.remove('show');
}

// ── Animasi scroll di halaman Artis (gaya sama dengan halaman Now Playing) ──
// Foto besar artis & nama memudar + mengecil/bergerak ke atas secara bertahap
// mengikuti posisi scroll, lalu header mini (foto kecil + nama) muncul solid
// begitu foto besar sudah hampir hilang sepenuhnya.
function _updateArtistScrollFx() {
  const artistView = document.getElementById('artist-view');
  const sticky = document.getElementById('artist-sticky-header');
  const mainEl = document.getElementById('main');
  if (!artistView || !sticky || !mainEl) return;
  if (artistView.style.display !== 'block') { sticky.classList.remove('show'); return; }

  const banner = artistView.querySelector('.artist-banner');
  const bg = document.getElementById('artist-banner-bg');
  const content = artistView.querySelector('.artist-banner-content');
  const y = mainEl.scrollTop;
  const fadeRange = banner ? banner.offsetHeight * 0.65 : 260; // jarak scroll sampai foto+nama hilang total
  const p = Math.min(1, y / fadeRange); // progres 0 -> 1

  if (content) {
    content.style.opacity = String(1 - p);
    content.style.transform = `translateY(${-p * 26}px) scale(${1 - p * 0.1})`;
    content.style.pointerEvents = p >= 1 ? 'none' : '';
  }
  if (bg) {
    bg.style.transform = `scale(${1 + p * 0.1}) translateY(${-p * 34}px)`;
    bg.style.opacity = String(1 - p * 0.65);
  }
  // Header mini muncul setelah foto besar hampir sepenuhnya memudar
  sticky.classList.toggle('show', p >= 0.85);
}
document.getElementById('main')?.addEventListener('scroll', _updateArtistScrollFx, { passive: true });

// Tombol Play besar di banner: putar semua lagu populer artis sbg antrian
function playArtistTopTracks() {
  if (!_currentArtistData || !_currentArtistData.tracks.length) { toast(' No songs loaded yet'); return; }
  const tracks = _currentArtistData.tracks.map(t => ({
    title: t.title, artist: t.artist, thumb: t.thumb, album: '',
    preview: t.preview || null, videoId: null, photo: null,
    duration: t.duration, _query: `${t.artist}|||${t.title}|||${t.id}`
  }));
  curQueue = [...tracks];
  loadPlay(tracks[0], null);
}

// ─── HALAMAN ALBUM: tampilkan semua lagu, baru diputar saat diklik ──
let _currentAlbumTracks = []; // daftar lagu album yg sedang ditampilkan (utk antrian)

// Dipanggil saat kartu album di halaman artis diklik
function openAlbumView(albumId, albumTitle) {
  document.getElementById('album-view').style.display = 'block';
  document.getElementById('artist-view').style.display = 'none';
  document.getElementById('home-view').classList.remove('active');
  document.getElementById('search-view').classList.remove('active');
  document.getElementById('finder-view').style.display = 'none';
  document.getElementById('playlist-view').style.display = 'none';
  document.getElementById('top-songs-full-view').style.display = 'none';
  document.getElementById('recently-played-full-view').style.display = 'none';
  document.getElementById('recommend-full-view').style.display = 'none';
  document.getElementById('nav-home').classList.remove('on');
  document.getElementById('nav-search').classList.remove('on');
  document.getElementById('nav-finder').classList.remove('on');
  document.getElementById('nav-songpreview')?.classList.remove('on');
  // Tutup halaman Song Preview kalau sedang terbuka, supaya tidak nyangkut
  // di belakang halaman Album.
  if (typeof closeSongPreviewIfOpen === 'function') { closeSongPreviewIfOpen(); }
  const mainEl = document.getElementById('main'); if (mainEl) mainEl.scrollTop = 0;

  document.getElementById('album-title').textContent = albumTitle || 'Album';
  document.getElementById('album-sub').textContent = 'Loading...';
  document.getElementById('album-cover').src = '';
  document.getElementById('album-tracks').innerHTML = '<div class="empty" style="grid-column:1/-1;padding:16px 0;font-size:.8rem;"><i></i><h3>Loading album songs...</h3></div>';

  loadAlbumView(albumId, albumTitle);
}

// Kembali ke halaman artis jika ada, kalau tidak ke Home
function backFromAlbumView() {
  document.getElementById('album-view').style.display = 'none';
  document.getElementById('song-preview-view').style.display = 'none';
  document.body.classList.remove('sp-mobile-open');
  if (typeof spAudio !== 'undefined' && spAudio) { spAudio.pause(); }
  if (typeof closeFSLyricsIfOpen === 'function') { closeFSLyricsIfOpen(); }
  if (_currentArtistData) {
    document.getElementById('artist-view').style.display = 'block';
  } else {
    showHomeView();
  }
}

// Ambil daftar lagu album dari Deezer lalu tampilkan (belum diputar otomatis)
async function loadAlbumView(albumId, albumTitleHint) {
  try {
    const data = await _deezerJsonp('https://api.deezer.com/album/' + albumId);
    if (!data || !data.tracks || !data.tracks.data || !data.tracks.data.length) {
      document.getElementById('album-sub').textContent = 'Album is empty';
      document.getElementById('album-tracks').innerHTML = '<div class="err-box">No songs in this album.</div>';
      return;
    }
    const cover = data.cover_xl || data.cover_big || data.cover_medium || '';
    const albumTitle = data.title || albumTitleHint || 'Album';
    const artistName = (data.artist && data.artist.name) || '';
    const year = (data.release_date || '').slice(0, 4);

    document.getElementById('album-cover').src = cover;
    document.getElementById('album-title').textContent = albumTitle;
    document.getElementById('album-sub').innerHTML = `${esc(artistName)}${year ? ' · ' + esc(year) : ''} · ${data.tracks.data.length} songs`;
    // Nama artis di sub-judul album bisa diklik utk membuka profil artis
    const subEl = document.getElementById('album-sub');
    if (artistName) {
      subEl.innerHTML = `<span style="color:var(--green);cursor:pointer;font-weight:600;" onclick="openArtistView('${esc(artistName).replace(/'/g, "\\'")}')">${esc(artistName)}</span>${year ? ' · ' + esc(year) : ''} · ${data.tracks.data.length} songs`;
    }

    const tracks = data.tracks.data.map(t => ({
      title: t.title || 'Unknown',
      artist: (t.artist && t.artist.name) || artistName,
      thumb: cover,
      album: albumTitle,
      preview: t.preview || null, videoId: null, photo: null,
      duration: t.duration || 0,
      _query: `${(t.artist && t.artist.name) || artistName}|||${t.title}|||${t.id}`
    }));
    _currentAlbumTracks = tracks;
    renderAlbumTracks(tracks);
  } catch (e) {
    console.error('loadAlbumView error:', e);
    document.getElementById('album-sub').textContent = 'Failed to load album';
    document.getElementById('album-tracks').innerHTML = '<div class="err-box"> Failed to load album songs. Try again.</div>';
  }
}

function renderAlbumTracks(tracks) {
  const c = document.getElementById('album-tracks');
  if (!c) return;
  c.innerHTML = '';
  tracks.forEach((t, i) => c.appendChild(buildAlbumTrackRow(t, i)));
}

// Baris lagu di halaman album — klik utk memutar songs itu & set antrian = seluruh album
function buildAlbumTrackRow(t, i) {
  const numClass = i === 0 ? 'gold' : i === 1 ? 'silver' : i === 2 ? 'bronze' : '';
  const mins = Math.floor((t.duration || 0) / 60);
  const secs = String((t.duration || 0) % 60).padStart(2, '0');
  const div = document.createElement('div');
  div.className = 'rank-item';
  div.innerHTML = `
    <div class="rank-num ${numClass}">${i + 1}</div>
    <div class="rank-cover">${t.thumb ? `<img src="${esc(t.thumb)}" alt="" loading="lazy" onerror="this.style.display='none'">` : ''}</div>
    <div class="rank-info">
      <div class="rank-name">${esc(t.title)}</div>
      <div class="rank-owner">${esc(t.artist)}${t.duration ? ` · ${mins}:${secs}` : ''}</div>
    </div>
    ${buildAddBtnHTML(t)}
  `;
  div.addEventListener('click', (e) => {
    if (e.target.closest('.add-btn')) return;
    curQueue = [..._currentAlbumTracks];
    loadPlay(t, null);
  });
  wireAddBtn(div.querySelector('.add-btn'), t);
  return div;
}

// Tombol Play besar di header album: putar dari songs pertama
function playAlbumFromStart() {
  if (!_currentAlbumTracks.length) { toast(" Album hasn't finished loading"); return; }
  curQueue = [..._currentAlbumTracks];
  loadPlay(_currentAlbumTracks[0], null);
}

// ─── TOP SONGS: indikator naik/turun peringkat (dibanding data hari sebelumnya) ──
// Baseline pembanding disimpan GLOBAL di Firebase Realtime Database (bukan
// localStorage), supaya semua user/device melihat panah naik/turun yang SAMA
// untuk hari yang sama — bukan hasil riwayat kunjungan masing-masing browser.
// Path: trending_rank_hist/{listId} = { date, list, prevList }
// - "list"     = snapshot chart hari ini (jadi pembanding untuk besok)
// - "prevList" = snapshot chart kemarin yang dipakai sebagai pembanding hari ini
async function _computeRankChanges(listId, items) {
  const todayStr = new Date().toISOString().slice(0, 10);
  const keyOf = (t) => `${(t.artist||'').trim().toLowerCase()}|||${(t.title||'').trim().toLowerCase()}`;
  const histRef = db.ref('trending_rank_hist/' + listId);

  let baseline = null; // list kemarin yang jadi acuan perbandingan hari ini
  try {
    const result = await histRef.transaction(current => {
      // Snapshot hari ini SUDAH pernah dibuat (oleh user/device manapun) —
      // jangan ditimpa, biar semua user hari ini bandingnya ke baseline yang sama.
      if (current && current.date === todayStr) return current;
      // Pertama kali chart di-refresh hari ini: simpan snapshot baru, dan
      // simpan snapshot lama (current, kalau ada) sebagai baseline pembanding.
      return {
        date: todayStr,
        prevList: current ? current.list : null,
        list: items.map(t => ({ artist: t.artist, title: t.title }))
      };
    });
    const val = result.snapshot.val();
    baseline = val ? val.prevList : null;
  } catch (e) {
    console.error('Gagal sinkronisasi rank trending global, fallback ke stabil:', e);
    items.forEach(t => { t.rankChange = 'up'; });
    return items;
  }

  items.forEach((t, i) => {
    if (!baseline) { t.rankChange = 'up'; return; } // belum ada data pembanding — anggap stabil (hijau)
    const prevIdx = baseline.findIndex(p => keyOf(p) === keyOf(t));
    if (prevIdx === -1) t.rankChange = 'up';        // lagu baru masuk chart
    else if (prevIdx < i) t.rankChange = 'down';     // dulu di posisi lebih atas (angka kecil), sekarang lebih bawah = turun
    else t.rankChange = 'up';                        // naik ATAU tetap di posisi sama = hijau ▲
  });

  return items;
}

async function loadTrendingSongs(force) {
  const section = document.getElementById('top-ranking-section');
  const grid = document.getElementById('rank-grid');
  if (section) section.style.display = 'block';

  // Simple per-day cache so we don't re-hit the API on every page load,
  // but it naturally refreshes as soon as the date changes.
  const todayKey = 'vibexa_trending5_' + new Date().toISOString().slice(0, 10);
  if (!force) {
    try {
      const cached = localStorage.getItem(todayKey);
      if (cached) {
        const items = JSON.parse(cached);
        if (items && items.length) { renderTrendingSongs(items); return; }
      }
    } catch(e) {}
  }

  if (grid) grid.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:16px 0;font-size:.8rem;"><i></i><h3>Loading trending songs...</h3></div>';

  try {
    const items = await fetchDeezerChartTracks(5);
    await _computeRankChanges('trending5', items);

    try {
      localStorage.setItem(todayKey, JSON.stringify(items));
      // Bersihkan cache hari-hari sebelumnya
      Object.keys(localStorage).forEach(k => {
        if (k.startsWith('vibexa_trending_') && !k.startsWith('vibexa_trending_full_') && k !== todayKey) localStorage.removeItem(k);
      });
    } catch(e) {}

    renderTrendingSongs(items);
  } catch(e) {
    console.error('loadTrendingSongs error:', e);
    if (grid) grid.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:16px 0;font-size:.8rem;color:var(--sub)"> Failed to load trending songs, try refreshing.</div>';
  }
}

// Fetch N tracks from Deezer's live chart and normalize the shape.
// genreId is optional (defaults to 0 = overall chart); pass a genre id to get
// that genre's own live chart (used by the Daily Mix feature below).
async function fetchDeezerChartTracks(limit, genreId) {
  const gid = genreId || 0;
  const data = await _deezerJsonp('https://api.deezer.com/chart/' + gid + '/tracks?limit=' + limit);
  if (!data || data.error || !data.data || !data.data.length) throw new Error('Trending data not available');
  return data.data.map(t => ({
    id: t.id,
    title: t.title || t.title_short || 'Unknown',
    artist: (t.artist && t.artist.name) || 'Unknown',
    thumb: (t.album && (t.album.cover_xl || t.album.cover_big || t.album.cover_medium)) || '',
    preview: t.preview || null,
    duration: t.duration || 0
  }));
}

// ─── GENRE MUSIK: menu genre + daftar lagu trending/populer per genre ──
// Setiap genre dipetakan ke nama genre asli Deezer (untuk mengambil chart
// live-nya bila tersedia) + kata kunci pencarian cadangan (order=RANKING,
// yaitu diurutkan berdasarkan popularitas) untuk genre yang tidak punya
// chart resmi di Deezer (K-Pop, Phonk, Lo-fi, Afrobeats) atau untuk
// melengkapi daftar sampai target 100 lagu.
// CATATAN PERBAIKAN AKURASI GENRE:
// Sebelumnya hanya genre yang "rawan" (K-Pop/Indie/Phonk/Lo-fi/Afrobeats) yang
// punya daftar artis inti (seedArtists) terkurasi manual, sedangkan genre lain
// (Pop/Hip-Hop/Rap/R&B/Rock/EDM/Latin) full mengandalkan chart Deezer + fallback
// pencarian teks bebas (mis. cari "Rock hits"). Masalahnya pencarian teks bebas
// itu tidak benar-benar tahu genre lagunya apa — ia cuma mencocokkan kata di
// judul/nama artis/album, jadi gampang kebobolan lagu yang genre-nya beda tapi
// judulnya kebetulan mengandung kata kunci itu. Sekarang SEMUA genre diberi
// seedArtists berisi artis yang memang benar-benar identik dengan genre
// tersebut, supaya lagu #1 & mayoritas isi daftar dijamin akurat, dan
// pencarian teks bebas hanya dipakai sebagai pelengkap paling akhir dengan
