// Dinaikkan jauh dari 100 supaya pool lagu per genre jauh lebih besar —
// dikombinasikan dengan mekanisme "scroll tanpa batas" (lihat _spExtendFeed)
// di bagian Song Preview, sehingga user bisa scroll sepuasnya tanpa mentok.
const GENRE_TARGET_COUNT = 400;
let _deezerGenreListCache = null;

function _normalizeDeezerTrack(t) {
  return {
    id: t.id,
    // Simpan juga ID artis Deezer dari HASIL PENCARIAN LAGU INI SECARA
    // SPESIFIK (bukan dari pencarian nama artis terpisah belakangan). Ini
    // penting karena banyak artis di Deezer berbagi nama yang persis sama
    // (mis. ada beberapa artis bernama "Oasis"). Dengan ID ini tersimpan
    // dari awal, kartu "About the artist"/"Albums" bisa langsung memakai
    // artis yang BENAR-BENAR menyanyikan lagu ini, bukan menebak lewat
    // pencarian nama yang bisa salah tangkap artis lain yang kebetulan
    // sama nama.
    artistId: (t.artist && t.artist.id) || 0,
    title: t.title || t.title_short || 'Unknown',
    artist: (t.artist && t.artist.name) || 'Unknown',
    thumb: (t.album && (t.album.cover_xl || t.album.cover_big || t.album.cover_medium)) || '',
    preview: t.preview || null,
    duration: t.duration || 0,
    // "rank" dari Deezer = skor popularitas lagu (makin tinggi makin sering
    // diputar/disukai pendengar). Dipakai sebagai proxy "like terbanyak"
    // untuk mengurutkan lagu terpopuler tiap artis di fitur Tri Mix.
    rank: typeof t.rank === 'number' ? t.rank : 0
  };
}

// Cari id genre asli Deezer berdasarkan daftar kandidat nama (case-insensitive, partial match)
async function _getDeezerGenreId(nameList) {
  if (!nameList || !nameList.length) return null;
  try {
    if (!_deezerGenreListCache) {
      const data = await _deezerJsonp('https://api.deezer.com/genre');
      _deezerGenreListCache = (data && data.data) || [];
    }
    // 1) Cari exact match dulu (case-insensitive) — paling akurat, supaya
    // tidak salah nyantol ke genre lain yang namanya cuma mirip/mengandung kata yang sama.
    for (const n of nameList) {
      const found = _deezerGenreListCache.find(g => (g.name || '').toLowerCase() === n.toLowerCase());
      if (found) return found.id;
    }
    // 2) Kalau tidak ada yang exact, baru coba partial match sebagai cadangan.
    for (const n of nameList) {
      const found = _deezerGenreListCache.find(g => (g.name || '').toLowerCase().includes(n));
      if (found) return found.id;
    }
  } catch (e) {}
  return null;
}

// ─── MUSICBRAINZ (khusus untuk menu Genre saja — tidak dipakai di fitur lain) ──
// MusicBrainz adalah database metadata musik terbuka. Di sini dipakai untuk
// mengetahui artis-artis mana yang benar-benar terasosiasi dengan sebuah
// genre/tag (misalnya "k-pop", "phonk", "lo-fi", "afrobeats") berdasarkan
// folksonomy tag milik MusicBrainz, lalu nama artis tsb dipakai untuk
// melengkapi daftar lagu dari Deezer supaya lebih akurat sesuai genre.
async function _getMusicBrainzGenreArtists(genreKey) {
  const def = GENRE_DEFS[genreKey];
  if (!def || !def.mbTag) return [];
  const cacheKey = 'vibexa_mb_genre_artists_' + genreKey;
  try {
    const cached = localStorage.getItem(cacheKey);
    if (cached) {
      const parsed = JSON.parse(cached);
      if (parsed && parsed.artists && parsed.ts && (Date.now() - parsed.ts) < 7 * 24 * 3600 * 1000) {
        return parsed.artists;
      }
    }
  } catch (e) {}

  let artists = [];
  try {
    const url = 'https://musicbrainz.org/ws/2/artist/?query=' + encodeURIComponent('tag:"' + def.mbTag + '"') +
      '&fmt=json&limit=100';
    const res = await fetch(url, { headers: { 'Accept': 'application/json' } });
    if (res.ok) {
      const data = await res.json();
      artists = ((data && data.artists) || [])
        // skor dinaikkan dari 30 -> 45 -> 60 supaya artis yang dipetakan ke genre
        // ini benar-benar kuat asosiasinya (bukan sekadar nyerempet tag), karena
        // daftar ini juga dipakai untuk memvalidasi hasil pencarian umum di
        // langkah 3 fetchGenreSongs (lihat _isTrackFromKnownGenreArtist).
        .filter(a => (a.score || 0) >= 60 && a.name)
        .sort((a, b) => (b.score || 0) - (a.score || 0))
        .map(a => a.name);
    }
  } catch (e) {}

  try { localStorage.setItem(cacheKey, JSON.stringify({ ts: Date.now(), artists })); } catch (e) {}
  return artists;
}

// Ambil top track (Deezer) milik seorang artis berdasarkan namanya
async function _deezerArtistTopTracksByName(artistName, limit) {
  try {
    const searchData = await _deezerJsonp('https://api.deezer.com/search/artist?q=' + encodeURIComponent(artistName) + '&limit=10');
    const ttResults = (searchData && searchData.data) || [];
    const ttQNorm = artistName.trim().toLowerCase();
    const artist = ttResults.find(a => (a.name || '').trim().toLowerCase() === ttQNorm) || ttResults[0];
    if (!artist) return [];
    const topData = await _deezerJsonp('https://api.deezer.com/artist/' + artist.id + '/top?limit=' + (limit || 10));
    return ((topData && topData.data) || []).map(_normalizeDeezerTrack);
  } catch (e) { return []; }
}

// Saring lagu-lagu "sampah" yang sering muncul di hasil pencarian umum:
// versi cover/instrumental/karaoke/tribute yang judulnya memuat kata kunci genre
// tapi sebenarnya bukan lagu asli dari artis genre tsb.
const _GENRE_JUNK_RX = /\b(cover|karaoke|tribute( to)?|instrumental|piano version|guitar version|harp version|violin version|flute version|music box version|made famous by|in the style of|originally performed by|backing track|8d audio|sped up|nightcore|remix by [a-z]|lo-?fi version|type beat|tribute band|mashup|acapella|acoustic version|slowed( \+|and)? reverb|reverb version|8-bit|midi version|orchestral version|children'?s version|kids version|lullaby version|study version|meme version|fan made|parody|for kids)\b/i;
// Tangkap juga format "(Nama Remix)" — remix kolaborasi yang credit-nya ditulis
// di dalam kurung tanpa kata "by" (mis. "Dracula (JENNIE Remix)"). Remix
// semacam ini sering "meminjam" nama artis dari genre lain, sehingga kalau
// jadi lagu #1/foto kotak genre, kesannya jadi tidak sesuai dengan genre aslinya.
const _GENRE_JUNK_PAREN_REMIX_RX = /\([^)]*\bremix\)/i;
function _isJunkGenreTrack(t) {
  return _GENRE_JUNK_RX.test(t.title || '') || _GENRE_JUNK_RX.test(t.artist || '')
    || _GENRE_JUNK_PAREN_REMIX_RX.test(t.title || '');
}

// Bandingkan nama artis secara longgar (lowercase, tanpa tanda baca/spasi
// berlebih) supaya "Tyler, The Creator" vs "tyler the creator" tetap cocok.
function _normArtistName(name) {
  return (name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

// Cek apakah nama artis sebuah lagu ada di dalam himpunan artis yang sudah
// tervalidasi benar-benar termasuk genre ini (gabungan seedArtists kurasi
// manual + artis hasil validasi tag MusicBrainz). Dipakai untuk MENYARING
// hasil pencarian teks bebas (langkah 3) supaya tidak asal comot lagu yang
// cuma kebetulan judul/artisnya mengandung kata kunci genre.
function _isTrackFromKnownGenreArtist(t, knownArtistsSet) {
  if (!knownArtistsSet || !knownArtistsSet.size) return false;
  const a = _normArtistName(t.artist);
  if (!a) return false;
  if (knownArtistsSet.has(a)) return true;
  // toleransi kolaborasi/featuring: "Drake feat. Rihanna" — cek tiap nama
  // yang dipisah oleh feat/ft/x/&/,
  const parts = a.split(/\b(?:feat|ft|featuring|and|x)\b|,|&/).map(s => s.trim()).filter(Boolean);
  return parts.some(p => knownArtistsSet.has(p));
}

// Ambil sampai GENRE_TARGET_COUNT lagu yang sedang tren/populer untuk satu genre.
// Urutan sumber (dari paling akurat ke paling umum):
// 0) Daftar artis inti yang dikurasi manual (hanya untuk genre yang rawan
//    salah kaprah: K-Pop, Phonk, Lo-fi, Afrobeats) — paling akurat karena
//    artisnya sudah pasti benar, tidak bergantung pada pencarian teks.
// 1) Chart resmi per-genre Deezer (kalau genre-nya tersedia di taksonomi Deezer)
// 2) Lagu-lagu teratas dari artis yang menurut data genre/tag MusicBrainz benar-benar
//    terasosiasi dengan genre ini — pelengkap untuk genre yang tidak
//    punya chart resmi di Deezer
// 3) Pencarian umum yang diurutkan berdasarkan popularitas (order=RANKING),
//    sebagai pelengkap terakhir saja, dengan penyaringan versi cover/
//    instrumental/karaoke supaya tidak mengotori hasil.
async function fetchGenreSongs(genreKey) {
  const def = GENRE_DEFS[genreKey];
  if (!def) return [];
  const seen = new Set();
  const out = [];
  const addTracks = (list, filterJunk) => {
    for (const t of list) {
      if (out.length >= GENRE_TARGET_COUNT) break;
      if (!t || !t.id || seen.has(t.id)) continue;
      if (filterJunk && _isJunkGenreTrack(t)) continue;
      seen.add(t.id);
      out.push(t);
    }
  };

  // Ambil dulu daftar artis yang sudah/akan tervalidasi untuk genre ini
  // (kurasi manual + tag MusicBrainz), supaya bisa dipakai sebagai "daftar
  // putih" saat menyaring hasil pencarian teks bebas nanti di langkah 3.
  const mbArtists = await _getMusicBrainzGenreArtists(genreKey).catch(() => []);
  const knownArtists = new Set(
    [...(def.seedArtists || []), ...mbArtists].map(_normArtistName).filter(Boolean)
  );

  // 0) PALING PRIORITAS: daftar artis inti yang sudah dikurasi manual untuk
  // genre ini. Karena ini didahulukan, lagu #1 (dan foto kotak genre yang
  // mengikuti lagu #1) dijamin berasal dari artis yang benar-benar dikenal
  // luas sebagai genre tersebut — bukan hasil tebakan dari pencarian teks.
  if (def.seedArtists && def.seedArtists.length) {
    for (const artistName of def.seedArtists) {
      if (out.length >= GENRE_TARGET_COUNT) break;
      try {
        const tracks = await _deezerArtistTopTracksByName(artistName, 10);
        addTracks(tracks, true);
      } catch (e) {}
    }
  }

  // 1) Chart resmi per-genre Deezer (lagu yang sedang trending di genre tsb) —
  // ini sumber terpercaya juga karena taksonomi genre-nya ditentukan Deezer
  // sendiri, jadi tidak perlu divalidasi ulang lewat daftar artis.
  try {
    const gid = await _getDeezerGenreId(def.genreNames);
    if (gid) {
      // Loop dinamis (bukan array indeks tetap) — terus ambil halaman
      // berikutnya selama Deezer masih mengembalikan data, sampai target
      // terpenuhi atau sumbernya benar-benar habis. Batas pengaman
      // (idx < 5000) hanya untuk mencegah loop tak berujung kalau API
      // berperilaku aneh, bukan batas fitur.
      for (let idx = 0; idx < 5000 && out.length < GENRE_TARGET_COUNT; idx += 100) {
        try {
          const data = await _deezerJsonp('https://api.deezer.com/chart/' + gid + '/tracks?limit=100&index=' + idx);
          const list = ((data && data.data) || []).map(_normalizeDeezerTrack);
          if (!list.length) break;
          addTracks(list, true);
        } catch (e) { break; }
      }
    }
  } catch (e) {}

  // 2) Lagu-lagu teratas dari artis yang benar-benar terasosiasi dengan genre ini
  // menurut data genre/tag MusicBrainz — prioritas lebih tinggi dari pencarian
  // umum karena artisnya sudah tervalidasi sesuai genre.
  if (out.length < GENRE_TARGET_COUNT) {
    for (const artistName of mbArtists) {
      if (out.length >= GENRE_TARGET_COUNT) break;
      try {
        const tracks = await _deezerArtistTopTracksByName(artistName, 20);
        addTracks(tracks, true);
      } catch (e) {}
    }
  }

  // 3) PALING TERAKHIR & PALING KETAT: kalau masih kurang dari target, baru
  // lengkapi dari pencarian teks umum yang diurutkan berdasarkan ranking/
  // popularitas. Berbeda dari versi sebelumnya, hasil pencarian ini TIDAK
  // langsung dipercaya — setiap lagu WAJIB lolos dua saringan: (a) bukan
  // versi cover/karaoke/instrumental/remix ganjil, DAN (b) nama artisnya
  // benar-benar ada di daftar artis yang sudah tervalidasi (knownArtists).
  // Kalau daftar artis tervalidasi untuk genre ini kosong (mis. MusicBrainz
  // sedang tidak bisa diakses), langkah ini dilewati saja daripada
  // mengambil lagu yang tidak bisa dipastikan genre-nya — lebih baik daftar
  // lagunya sedikit tapi akurat, daripada 100 lagu tapi banyak yang meleset.
  if (out.length < GENRE_TARGET_COUNT && knownArtists.size) {
    for (let idx = 0; idx < 5000 && out.length < GENRE_TARGET_COUNT; idx += 100) {
      try {
        const url = 'https://api.deezer.com/search?q=' + encodeURIComponent(def.query) + '&order=RANKING&limit=100&index=' + idx;
        const data = await _deezerJsonp(url);
        const list = ((data && data.data) || []).map(_normalizeDeezerTrack)
          .filter(t => _isTrackFromKnownGenreArtist(t, knownArtists));
        if (!list.length) break;
        addTracks(list, true);
      } catch (e) { break; }
    }
  }

  return out;
}

function playTrendingTrack(t) {
  const track = {
    title: t.title,
    artist: t.artist,
    thumb: t.thumb,
    preview: t.preview,
    videoId: null,
    photo: null,
    duration: t.duration,
    _query: `${t.artist}|||${t.title}|||${t.id}`
  };
  loadPlay(track, null);
}

// ── Tombol tambah ke playlist (dipakai di semua bagian: top songs, hasil pencarian, saran, hero) ──
// Selalu tampil ikon "+" (tidak pernah berubah jadi centang), supaya lagu
// yang sama tetap bisa ditambahkan ke playlist lain berkali-kali.
function _addBtnIconHTML(saved) {
  return '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>';
}
function buildAddBtnHTML(track, extraClass) {
  return `<button class="add-btn${extraClass ? ' ' + extraClass : ''}" data-artist="${esc(track.artist)}" data-title="${esc(track.title)}" title="Add song to playlist">${_addBtnIconHTML(false)}</button>`;
}
// Pasang event klik pada tombol add-btn: selalu buka modal pilih playlist
function wireAddBtn(btn, track) {
  if (!btn) return;
  btn.addEventListener('click', e => {
    e.stopPropagation();
    openAddSongModal(track);
  });
}

// ─── DAILY MIX (Spotify-style, powered by Deezer's overall live top chart) ──
// Genre no longer matters here — every day we take Deezer's current overall
// top/trending chart (all genres combined), keep only songs by well-known
// artists, shuffle that pool with a date-based seed (so it's stable all day
// but different tomorrow), and slice it into DM_MIX_COUNT mixes of
// DM_TRACKS_PER_MIX songs each. The cover shown for a mix is simply the
// album art of the first song in that mix. Everything is cached under a
// date-stamped localStorage key, so once the date rolls over the old mixes
// are gone and fresh ones are generated automatically from that day's chart.
//
// "Well-known" is measured using Deezer's own nb_fan (fan count) figure on
// the Artist object — an artist below the threshold is skipped even if one
// of their songs happens to be sitting in the top chart right now.
const DM_MIX_COUNT = 8;
const DM_TRACKS_PER_MIX = 15;
// Setiap Daily Mix HARUS berisi tepat 15 lagu, jadi batas bawah = batas atas.
// Kalau pool lagu yang terkumpul tidak cukup untuk 8 x 15, mekanisme fallback
// di bawah akan tetap membentuk 8 playlist (boleh sedikit tumpang tindih lagu
// antar mix pada kasus ekstrem) supaya jumlah playlist-nya tetap 8.
const DM_MIN_TRACKS_PER_MIX = 15;
const DM_COLORS = ['#26e0ff', '#eaff2e', '#ff5a4d', '#5ce87c', '#c17bff', '#4d8bff', '#ff6fc9', '#ffb238'];
// Minimum Deezer fan count for an artist to count as "terkenal" (well-known).
const DM_FAMOUS_FAN_THRESHOLD = 300000;

// Tanggal "hari ini" untuk Daily Mix dihitung berdasarkan WIB (GMT+7), bukan UTC,
// supaya Daily Mix berganti tepat tengah malam waktu Indonesia (bukan jam 7 pagi
// WIB seperti kalau pakai UTC apa adanya). Dipakai sebagai bagian dari cache key
// lokal maupun key node Firebase (daily_mix_shared/{dateStr}) supaya SEMUA user,
// di zona waktu manapun mereka berada, tetap melihat Daily Mix yang sama pada
// "hari WIB" yang sama.
function _dmTodayDateStr() {
  const wib = new Date(Date.now() + 7 * 60 * 60 * 1000); // geser ke WIB (UTC+7)
  return wib.toISOString().slice(0, 10);
}

function _dmSeedFromString(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (Math.imul(31, h) + str.charCodeAt(i)) | 0; }
  return h >>> 0;
}
function _dmMulberry32(seed) {
  return function() {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function _dmSeededShuffle(arr, seedStr) {
  const rng = _dmMulberry32(_dmSeedFromString(seedStr));
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Cache of artist.id -> nb_fan so we never look the same artist up twice
// while building today's mixes.
let _dmArtistFanCache = {};
async function _dmGetArtistFanCount(artistId) {
  if (_dmArtistFanCache[artistId] !== undefined) return _dmArtistFanCache[artistId];
  try {
    const data = await _deezerJsonp('https://api.deezer.com/artist/' + artistId);
    const fans = (data && !data.error && typeof data.nb_fan === 'number') ? data.nb_fan : 0;
    _dmArtistFanCache[artistId] = fans;
    return fans;
  } catch (e) {
    _dmArtistFanCache[artistId] = 0;
    return 0;
  }
}

// Filter a candidate track list down to only tracks by well-known artists
// (nb_fan >= DM_FAMOUS_FAN_THRESHOLD), stopping once `cap` good ones are
// found. Runs artist lookups in small concurrent batches and caches by
// artist id so repeat artists in the pool cost nothing extra.
async function _dmFilterFamousTracks(tracks, cap) {
  cap = cap || tracks.length;
  const result = [];
  const CONCURRENCY = 10;
  let i = 0;
  while (i < tracks.length && result.length < cap) {
    const batch = tracks.slice(i, i + CONCURRENCY);
    i += CONCURRENCY;
    const fanCounts = await Promise.all(batch.map(t => _dmGetArtistFanCount(t.artistId || t.id)));
    batch.forEach((t, idx) => {
      if (result.length >= cap) return;
      if (fanCounts[idx] >= DM_FAMOUS_FAN_THRESHOLD) result.push(t);
    });
  }
  return result;
}

// Raw fetch helper that keeps the artist's numeric id around (needed for
// the nb_fan lookup above) — fetchDeezerChartTracks() normalizes that away.
// `rank` = skor popularitas dari Deezer sendiri (dipakai buat urutkan lagu
// yang lagi paling populer duluan, misalnya di Playlist Pop).
async function _dmFetchRawTracks(url) {
  const data = await _deezerJsonp(url);
  return ((data && data.data) || []).map(t => ({
    id: t.id,
    artistId: (t.artist && t.artist.id) || 0,
    title: t.title || t.title_short || 'Unknown',
    artist: (t.artist && t.artist.name) || 'Unknown',
    thumb: (t.album && (t.album.cover_xl || t.album.cover_big || t.album.cover_medium)) || '',
    preview: t.preview || null,
    duration: t.duration || 0,
    rank: t.rank || 0
  }));
}

async function loadDailyMixes(force) {
  const section = document.getElementById('daily-mix-section');
  const grid = document.getElementById('daily-mix-grid');
  if (section) section.style.display = 'block';

  _dmArtistFanCache = {}; // reset cache per load supaya data fan count tetap segar

  // Date-stamped cache key (berbasis WIB): once the date changes, the old
  // mixes are simply no longer looked up and get cleaned up below — fresh
  // ones are built. v5 supaya cache lama (berbasis UTC) tidak ikut kepakai.
  const dateStr = _dmTodayDateStr();
  const todayKey = 'vibexa_dailymix_topsongs_v5_' + dateStr;
  const neededTotal = DM_MIX_COUNT * DM_TRACKS_PER_MIX; // minimal 120 lagu (8 x 15)

  if (!force) {
    try {
      const cached = localStorage.getItem(todayKey);
      if (cached) {
        const mixes = JSON.parse(cached);
        if (mixes && mixes.length >= DM_MIX_COUNT) { renderDailyMixes(mixes); return; }
      }
    } catch (e) { console.error('[DailyMix] gagal baca cache lokal:', e); }
  }

  // Daily Mix BERSAMA untuk semua user: sebelum generate sendiri (yang berarti
  // puluhan panggilan ke API Deezer), coba dulu ambil hasil yang sudah dibuat
  // user lain hari ini dari Firebase. Kalau sudah ada, semua user tinggal
  // pakai data yang sama persis — jauh lebih ringan daripada tiap orang
  // generate ulang dari nol.
  if (!force) {
    try {
      const sharedSnap = await db.ref('daily_mix_shared/' + dateStr).get();
      if (sharedSnap.exists()) {
        const sharedMixes = sharedSnap.val();
        if (Array.isArray(sharedMixes) && sharedMixes.length >= DM_MIX_COUNT) {
          try { localStorage.setItem(todayKey, JSON.stringify(sharedMixes)); } catch (e) { console.error('[DailyMix] gagal simpan cache lokal:', e); }
          renderDailyMixes(sharedMixes);
          return;
        }
      }
    } catch (e) {
      // PENTING: kalau ini muncul di console sebagai "PERMISSION_DENIED", artinya
      // Firebase Realtime Database Rules belum mengizinkan baca path daily_mix_shared
      // -> Daily Mix TIDAK akan pernah bisa sama antar user sampai rule-nya dibenarkan.
      console.error('[DailyMix] gagal baca daily_mix_shared dari Firebase (cek Firebase Rules):', e);
    }
  }

  if (grid) grid.innerHTML = '<div class="empty" style="padding:16px 0;font-size:.8rem;"><i></i><h3>Preparing Daily Mix...</h3></div>';

  try {
    // 1) Ambil chart top/trending Deezer saat ini (gabungan semua genre),
    // lalu tambah dengan chart per-genre supaya pool lagu jauh lebih besar
    // dan cukup untuk membentuk 8 mix x 30 lagu secara konsisten.
    const seen = new Set();
    let allRawTracks = []; // SEMUA lagu yang berhasil diambil (belum disaring "terkenal")
    try {
      const chartTracks = await _dmFetchRawTracks('https://api.deezer.com/chart/0/tracks?limit=100');
      chartTracks.forEach(t => { if (!seen.has(t.id)) { seen.add(t.id); allRawTracks.push(t); } });
    } catch (e) {}

    // 1b) Lengkapi dari chart per-genre (diambil dinamis dari daftar genre Deezer)
    // supaya pool lagu lebih beragam & lebih besar dari sekadar top chart global.
    try {
      const genreData = await _deezerJsonp('https://api.deezer.com/genre');
      const genreIds = ((genreData && genreData.data) || [])
        .map(g => g.id)
        .filter(id => id && id !== 0)
        .slice(0, 12);
      for (const gid of genreIds) {
        try {
          const gTracks = await _dmFetchRawTracks('https://api.deezer.com/chart/' + gid + '/tracks?limit=50');
          gTracks.forEach(t => { if (!seen.has(t.id)) { seen.add(t.id); allRawTracks.push(t); } });
        } catch (e) {}
      }
    } catch (e) {}

    // 2) Saring: hanya lagu dari artis yang benar-benar terkenal (nb_fan tinggi).
    let pool = await _dmFilterFamousTracks(allRawTracks, neededTotal);

    // 3) Kalau masih belum cukup untuk 8 x 30 lagu, lengkapi dari lagu-lagu
    // top milik artis-artis paling populer saat ini (top artists chart
    // Deezer), tanpa peduli genre — tetap "lagu yang lagi naik daun".
    if (pool.length < neededTotal) {
      try {
        const artistData = await _deezerJsonp('https://api.deezer.com/chart/0/artists?limit=100');
        const topArtists = ((artistData && artistData.data) || []).filter(a => (a.nb_fan || 0) >= DM_FAMOUS_FAN_THRESHOLD);
        for (const artist of topArtists) {
          if (pool.length >= neededTotal) break;
          try {
            const topTracks = await _dmFetchRawTracks('https://api.deezer.com/artist/' + artist.id + '/top?limit=50');
            for (const t of topTracks) {
              if (seen.has(t.id)) continue;
              seen.add(t.id);
              const track = { ...t, artistId: artist.id, artist: t.artist || artist.name };
              allRawTracks.push(track);
              if (pool.length < neededTotal) pool.push(track);
            }
          } catch (e) {}
        }
      } catch (e) {}
    }

    // 4) Jaring pengaman terakhir: kalau lagu dari artis "terkenal" saja tetap
    // belum cukup untuk 8 mix x 30 lagu (misal koneksi API terbatas), isi sisa
    // slot dengan lagu trending lain yang sudah terkumpul (tanpa syarat fan
    // count) supaya jumlah 8 Daily Mix x 30 lagu selalu terpenuhi selama data
    // dari Deezer tersedia.
    if (pool.length < neededTotal) {
      const poolIds = new Set(pool.map(t => t.id));
      for (const t of allRawTracks) {
        if (pool.length >= neededTotal) break;
        if (poolIds.has(t.id)) continue;
        poolIds.add(t.id);
        pool.push(t);
      }
    }

    if (pool.length < DM_MIN_TRACKS_PER_MIX) throw new Error('Trending song data insufficient');

    // 4) Acak urutan dengan seed tanggal hari ini (stabil sepanjang hari,
    // berubah otomatis besok) lalu potong jadi DM_MIX_COUNT (8) mix.
    //
    // Supaya Daily Mix TIDAK PERNAH kurang dari 8 playlist, ukuran tiap mix
    // dibuat menyesuaikan besarnya pool: idealnya tetap 15 lagu/mix, tapi
    // kalau pool tidak cukup untuk 8 x 15, jaring pengaman di bawah akan tetap
    // membentuk 8 mix (boleh sedikit tumpang tindih pada kasus ekstrem).
    const shuffledPool = _dmSeededShuffle(pool, todayKey);
    let mixes = [];
    let offset = 0;
    const buildMixFromSlice = (slice, idKey) => {
      const uniqueArtists = [];
      for (const t of slice) { if (!uniqueArtists.includes(t.artist)) uniqueArtists.push(t.artist); if (uniqueArtists.length >= 2) break; }
      return {
        id: 'dm_top_' + idKey,
        title: uniqueArtists.length >= 2 ? `${uniqueArtists[0]} and ${uniqueArtists[1]}` : (uniqueArtists[0] || 'Mix Populer'),
        cover: slice[0].thumb,
        tracks: slice
      };
    };
    while (mixes.length < DM_MIX_COUNT && offset < shuffledPool.length) {
      const mixesLeft = DM_MIX_COUNT - mixes.length;
      const tracksLeft = shuffledPool.length - offset;
      // Bagi rata sisa lagu ke sisa mix yang perlu dibuat, dibatasi antara
      // DM_MIN_TRACKS_PER_MIX dan DM_TRACKS_PER_MIX.
      const tracksForThisMix = Math.max(DM_MIN_TRACKS_PER_MIX, Math.min(DM_TRACKS_PER_MIX, Math.floor(tracksLeft / mixesLeft)));
      const slice = shuffledPool.slice(offset, offset + tracksForThisMix).map(t => ({ ...t, _query: `${t.artist}|||${t.title}|||${t.id}` }));
      if (slice.length < DM_MIN_TRACKS_PER_MIX) break; // sisa lagu benar-benar tidak cukup, hentikan
      mixes.push(buildMixFromSlice(slice, offset));
      offset += tracksForThisMix;
    }

    // Jaring pengaman terakhir: kalau pool tetap tidak cukup untuk membentuk
    // 8 mix unik (pool sangat kecil), lengkapi sisa mix dengan mengambil ulang
    // (boleh tumpang tindih) dari pool yang sudah ada secara acak, supaya Home
    // tetap menampilkan 8 Daily Mix, bukan kurang dari itu.
    let extraRound = 0;
    while (mixes.length < DM_MIX_COUNT && shuffledPool.length >= DM_MIN_TRACKS_PER_MIX) {
      const start = (extraRound * DM_MIN_TRACKS_PER_MIX) % shuffledPool.length;
      const slice = [];
      for (let i = 0; i < DM_MIN_TRACKS_PER_MIX; i++) {
        const t = shuffledPool[(start + i) % shuffledPool.length];
        slice.push({ ...t, _query: `${t.artist}|||${t.title}|||${t.id}` });
      }
      mixes.push(buildMixFromSlice(slice, 'extra_' + extraRound));
      extraRound++;
      if (extraRound > DM_MIX_COUNT) break; // jaga-jaga supaya tidak infinite loop
    }

    if (!mixes.length) throw new Error('Failed to create Daily Mix');

    // Simpan hasil generate ini sebagai mix BERSAMA di Firebase supaya user
    // lain hari ini tinggal membaca, bukan generate ulang (hemat beban ke
    // Deezer). Pakai transaction: kalau ternyata sudah ada yang lebih dulu
    // menyimpan (dua user generate hampir bersamaan), jangan ditimpa — pakai
    // versi yang sudah tersimpan supaya semua user tetap dapat mix yang
    // sama persis, bukan versi masing-masing.
    try {
      const txResult = await db.ref('daily_mix_shared/' + dateStr).transaction(current => {
        // Kalau data yang sudah tersimpan TIDAK lengkap 8 mix (misal sisa data
        // lama dari sebelum jaminan "selalu 8 playlist" ini ada), TIMPA dengan
        // hasil generate baru supaya semua user tetap dapat 8 Daily Mix, bukan
        // ikut-ikutan data lama yang kurang.
        if (Array.isArray(current) && current.length >= DM_MIX_COUNT) return; // sudah lengkap -> jangan timpa
        return mixes;
      });
      if (txResult && txResult.snapshot && txResult.snapshot.exists()) {
        const finalMixes = txResult.snapshot.val();
        // Hanya pakai versi Firebase kalau memang lengkap 8 mix. Kalau ternyata
        // masih kurang dari 8 (race condition atau data lama), tetap pakai versi
        // yang just now digenerate secara lokal (sudah pasti 8) supaya user ini
        // tidak ikut melihat Daily Mix yang kurang dari 8.
        if (Array.isArray(finalMixes) && finalMixes.length >= DM_MIX_COUNT) mixes = finalMixes;
      }
      // Bersihkan entri tanggal-tanggal lama supaya node ini tidak menumpuk.
      db.ref('daily_mix_shared').get().then(snap => {
        if (!snap.exists()) return;
        snap.forEach(child => {
          if (child.key !== dateStr) db.ref('daily_mix_shared/' + child.key).remove().catch(() => {});
        });
      }).catch(() => {});
    } catch (e) {
      // PENTING: kalau ini muncul sebagai "PERMISSION_DENIED" di console, artinya
      // Firebase Rules belum mengizinkan tulis ke path daily_mix_shared -> tiap
      // user akan terus generate versi masing-masing (tidak akan pernah sama).
      console.error('[DailyMix] gagal tulis daily_mix_shared ke Firebase (cek Firebase Rules):', e);
    }

    try {
      localStorage.setItem(todayKey, JSON.stringify(mixes));
      Object.keys(localStorage).forEach(k => {
        if (k.startsWith('vibexa_dailymix_') && k !== todayKey) localStorage.removeItem(k);
      });
    } catch (e) {
      // Kemungkinan besar localStorage penuh (QuotaExceededError). Bersihkan
      // cache-cache lain milik app ini lalu coba sekali lagi, supaya refresh
      // berikutnya tetap bisa pakai cache (bukan generate ulang tiap kali).
      console.error('[DailyMix] gagal simpan cache lokal, coba bersihkan & ulang:', e);
      try {
        Object.keys(localStorage).forEach(k => { if (k.startsWith('vibexa_')) localStorage.removeItem(k); });
        localStorage.setItem(todayKey, JSON.stringify(mixes));
      } catch (e2) { console.error('[DailyMix] tetap gagal simpan cache lokal setelah dibersihkan:', e2); }
    }

    renderDailyMixes(mixes);
  } catch (e) {
    console.error('loadDailyMixes error:', e);
    if (grid) grid.innerHTML = '<div class="empty" style="padding:16px 0;font-size:.8rem;color:var(--sub)"> Failed to load Daily Mix, try refreshing.</div>';
  }
}

function renderDailyMixes(mixes) {
  const c = document.getElementById('daily-mix-grid');
  if (!c) return;
  c.innerHTML = '';
  mixes.forEach((mix, i) => c.appendChild(buildDailyMixCardEl(mix, i)));
}

// ─── "Add to Library" untuk playlist otomatis (Daily Mix, Mix Tahunan,
// For You, Radio Artis, Weekday Vibes, Playlist Pop, Mungkin Kamu Suka,
// Made For You, dll). Menyimpan salinan playlist tsb ke `playlists`
// (object yang sama dipakai untuk playlist buatan user sendiri), sehingga:
// - otomatis muncul berjejer di sidebar kiri (renderSidebarPlaylists)
// - otomatis muncul di "All Playlists" (renderHomeGrid, tampil di mobile)
// - otomatis ikut ter-sync ke Firebase (scheduleSave -> cloud), jadi TETAP
//   ADA meskipun user logout lalu login kembali.
function _mixLibSvg(added) {
  return added
    ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12l5 5L20 6"/></svg>'
    : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M12 4v16M4 12h16"/></svg>';
}
function isMixInLibrary(mix) {
  if (!mix || !mix.id) return false;
  return Object.keys(playlists).some(id => playlists[id].sourceMixId === mix.id);
}
function mixLibBtnHtml(mix) {
  const added = isMixInLibrary(mix);
  return `<button type="button" class="mix-lib-btn${added ? ' added' : ''}" title="${added ? 'Already in library' : 'Add to Library'}" aria-label="Add to Library">${_mixLibSvg(added)}</button>`;
}
function attachMixLibBtn(div, mix) {
  const btn = div.querySelector('.mix-lib-btn');
  if (!btn) return;
  btn.addEventListener('click', (e) => {
    e.stopPropagation();
    addMixToLibrary(mix, btn);
  });
}
// Tombol "Add to Library" sekarang ditampilkan di halaman detail playlist
// (dekat tombol "Play All"), bukan lagi di kartu playlist. Fungsi berikut
// menampilkan/menyembunyikan & memperbarui tombol tsb sesuai mix yang
// sedang dibuka (lihat openDailyMix, showPlaylistView, openPublicPlaylist).
function updatePvMixLibBtn(mix) {
  const btn = document.getElementById('pv-mixlib-btn');
  if (!btn) return;
  if (!mix) { btn.style.display = 'none'; return; }
  btn.style.display = '';
  const added = isMixInLibrary(mix);
  btn.classList.toggle('added', added);
  btn.title = added ? 'Already in library' : 'Add to Library';
  const iconEl = document.getElementById('pv-mixlib-icon');
  if (iconEl) iconEl.innerHTML = _mixLibSvg(added);
  const labelEl = document.getElementById('pv-mixlib-label');
  if (labelEl) labelEl.textContent = added ? 'Added to Library' : 'Add to Library';
}
function handlePvMixLibClick() {
  if (!_currentDailyMix) return;
  addMixToLibrary(_currentDailyMix, document.getElementById('pv-mixlib-btn'));
}
function addMixToLibrary(mix, btnEl) {
  if (!mix) return;
  if (mix.id && isMixInLibrary(mix)) {
    toast(' This playlist is already in your library');
    return;
  }
  const tracks = Array.isArray(mix.tracks) ? mix.tracks.map(t => ({
    title: t.title,
    artist: t.artist,
    thumb: t.thumb || '',
    _query: t._query || (t.artist + '|||' + t.title + '|||0')
  })) : [];
  if (!tracks.length) { toast(' This playlist is still empty'); return; }
  const cover = mix.cover || mix.artistPhoto || (Array.isArray(mix.photos) && mix.photos[0]) || tracks[0].thumb || '';
  const id = genId();
  playlists[id] = {
    id,
    name: mix.title || mix.name || 'Playlist',
    cover,
    coverThumb: cover,
    tracks,
    sourceMixId: mix.id || null
  };
  renderSidebarPlaylists();
  renderHomeGrid();
  scheduleSave();
  updatePvMixLibBtn(mix);
  toast(' "' + (mix.title || 'Playlist') + '" added to Library');
}

function buildDailyMixCardEl(mix, i) {
  const color = DM_COLORS[i % DM_COLORS.length];
  const num = String(i + 1).padStart(2, '0');
  const div = document.createElement('div');
  div.className = 'dm-card';
  div.innerHTML = `
    <div class="dm-cover-wrap">
      ${mix.cover ? `<img class="dm-cover-img" src="${esc(mix.cover)}" alt="" loading="lazy" onerror="this.style.display='none'">` : ''}
      <div class="dm-cover-ov">
        <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
      </div>
      <div class="dm-badge-mix">Daily Mix</div>
      <div class="dm-badge-num" style="color:${color}">${num}</div>
    </div>
    <div class="dm-title">${esc(mix.title)}</div>
  `;
  div.querySelector('.dm-cover-ov').addEventListener('click', (e) => { e.stopPropagation(); playDailyMix(mix); });
  div.addEventListener('click', () => openDailyMix(mix));
  return div;
}

function toggleDailyMixShowAll() {
  const grid = document.getElementById('daily-mix-grid');
  const label = document.getElementById('dm-showall-label');
  if (!grid) return;
  const expanded = grid.classList.toggle('expanded');
  if (label) label.textContent = expanded ? 'Tampilkan Sedikit' : 'Show All';
}

