const YEAR_MIX_CACHE_VERSION = 'v1';

// Cari satu lagu spesifik (artist+judul) di Deezer. Pakai sintaks pencarian
// lanjutan artist:"" track:"" dulu (paling akurat), kalau tidak ketemu baru
// jatuh ke pencarian bebas "artis judul" sebagai cadangan.
async function _ymResolveTrack(artistName, trackTitle) {
  const cleanArtist = String(artistName).replace(/"/g, '');
  const cleanTitle = String(trackTitle).replace(/"/g, '');
  try {
    const q1 = 'artist:"' + cleanArtist + '" track:"' + cleanTitle + '"';
    let data = await _deezerJsonp('https://api.deezer.com/search?q=' + encodeURIComponent(q1) + '&limit=1');
    let hit = data && data.data && data.data[0];
    if (!hit) {
      data = await _deezerJsonp('https://api.deezer.com/search?q=' + encodeURIComponent(cleanArtist + ' ' + cleanTitle) + '&order=RANKING&limit=1');
      hit = data && data.data && data.data[0];
    }
    if (!hit) return null;
    const t = _normalizeDeezerTrack(hit);
    t._query = `${t.artist}|||${t.title}|||${t.id}`;
    return t;
  } catch (e) { return null; }
}

// Ambil foto ARTIS (bukan cover album) untuk dijadikan sampul kartu Mix
// Tahunan — sesuai permintaan: foto dari artis lagu pertama di playlist.
async function _ymGetArtistPhoto(artistName) {
  try {
    const searchData = await _deezerJsonp('https://api.deezer.com/search/artist?q=' + encodeURIComponent(artistName) + '&limit=10');
    const ymResults = (searchData && searchData.data) || [];
    const ymQNorm = artistName.trim().toLowerCase();
    const a = ymResults.find(x => (x.name || '').trim().toLowerCase() === ymQNorm) || ymResults[0];
    return a ? (a.picture_xl || a.picture_big || a.picture_medium || '') : '';
  } catch (e) { return ''; }
}

// Resolve satu definisi Mix Tahunan (30 lagu terkurasi) jadi objek mix siap
// tampil & diputar. Dijalankan dalam batch kecil supaya tidak membanjiri API.
async function _ymBuildMix(def) {
  const tracks = [];
  const CONCURRENCY = 6;
  let i = 0;
  while (i < def.songs.length) {
    const batch = def.songs.slice(i, i + CONCURRENCY);
    i += CONCURRENCY;
    const results = await Promise.all(batch.map(s => _ymResolveTrack(s.artist, s.title)));
    results.forEach(t => { if (t) tracks.push(t); });
  }
  if (!tracks.length) return null;
  const cover = await _ymGetArtistPhoto(tracks[0].artist);
  const uniqueArtists = [];
  for (const t of tracks) {
    if (!uniqueArtists.includes(t.artist)) uniqueArtists.push(t.artist);
    if (uniqueArtists.length >= 3) break;
  }
  return {
    id: 'ym_' + def.key,
    key: def.key,
    title: def.label,
    label: def.label,
    color: def.color,
    caption: uniqueArtists.join(', '),
    subtitle: `${def.label} · ${tracks.length} songs`,
    cover: cover || tracks[0].thumb,
    tracks
  };
}

// Muat 9 Mix Tahunan. Urutan sumber: cache lokal (permanen, tanpa tanggal) ->
// data BERSAMA di Firebase (supaya semua user dapat hasil yang identik &
// tidak perlu tiap orang resolve ulang ke Deezer) -> baru kalau benar-benar
// belum ada, resolve dari nol lalu simpan sebagai data bersama.
async function loadYearMixes(force) {
  const section = document.getElementById('year-mix-section');
  if (section) section.style.display = 'block';
  const grid = document.getElementById('year-mix-grid');
  if (grid && !grid.childElementCount) {
    grid.innerHTML = '<div class="empty" style="padding:16px 0;font-size:.8rem;"><i></i><h3>Preparing Time Machine...</h3></div>';
  }

  const mixes = [];
  for (const def of YEAR_MIX_DEFS) {
    const localKey = 'vibexa_yearmix_' + YEAR_MIX_CACHE_VERSION + '_' + def.key;
    let mix = null;

    if (!force) {
      try {
        const cached = localStorage.getItem(localKey);
        if (cached) {
          const parsed = JSON.parse(cached);
          if (parsed && parsed.tracks && parsed.tracks.length) mix = parsed;
        }
      } catch (e) {}
    }

    if (!mix) {
      try {
        const snap = await db.ref('year_mix_shared_' + YEAR_MIX_CACHE_VERSION + '/' + def.key).get();
        if (snap.exists()) {
          const shared = snap.val();
          if (shared && shared.tracks && shared.tracks.length) {
            mix = shared;
            try { localStorage.setItem(localKey, JSON.stringify(mix)); } catch (e) {}
          }
        }
      } catch (e) {
        // PENTING: kalau ini muncul sebagai "PERMISSION_DENIED", Firebase Rules
        // belum mengizinkan baca path year_mix_shared_v1 -> Mix Tahunan tidak
        // akan pernah sama antar user sampai rule-nya dibenarkan.
        console.error('[YearMix] gagal baca year_mix_shared dari Firebase (cek Firebase Rules):', e);
      }
    }

    if (!mix) {
      mix = await _ymBuildMix(def);
      if (mix) {
        try {
          const txResult = await db.ref('year_mix_shared_' + YEAR_MIX_CACHE_VERSION + '/' + def.key).transaction(current => {
            if (current && current.tracks && current.tracks.length) return; // sudah ada -> jangan timpa
            return mix;
          });
          if (txResult && txResult.snapshot && txResult.snapshot.exists()) {
            const finalMix = txResult.snapshot.val();
            if (finalMix && finalMix.tracks && finalMix.tracks.length) mix = finalMix;
          }
        } catch (e) {
          console.error('[YearMix] gagal tulis year_mix_shared ke Firebase (cek Firebase Rules):', e);
        }
        try { localStorage.setItem(localKey, JSON.stringify(mix)); } catch (e) {}
      }
    }

    if (mix) mixes.push(mix);
    // Render progresif per-mix supaya kartu yang sudah siap langsung tampil,
    // tidak perlu menunggu ke-6 mix selesai semua baru muncul.
    renderYearMixes(mixes);
  }

  if (!mixes.length && grid) {
    grid.innerHTML = '<div class="empty" style="padding:16px 0;font-size:.8rem;color:var(--sub)"> Failed to load Yearly Mix, try refreshing.</div>';
  }
}

function renderYearMixes(mixes) {
  const c = document.getElementById('year-mix-grid');
  if (!c) return;
  c.innerHTML = '';
  mixes.forEach(mix => c.appendChild(buildYearMixCardEl(mix)));
}

