// ─── DIBUAT UNTUK KAMU (Made For You) ────────────────────────
// 8 playlist otomatis, isi 15 lagu tiap playlist, disusun dari lagu-lagu
// milik artis yang diikuti user (favoriteArtists) — bukan chart umum seperti
// Daily Mix. Misal user follow Justin Bieber, lagu-lagu Justin Bieber akan
// ikut masuk ke salah satu (atau beberapa) dari 8 playlist ini.
// Diacak dengan seed harian + uid supaya personal per-user, stabil selama
// satu hari, dan otomatis berubah besok / saat user follow-unfollow artis.
const MFY_MIX_COUNT = 8;
const MFY_TRACKS_PER_MIX = 15;

async function loadMadeForYouMixes(force) {
  const section = document.getElementById('made-for-you-section');
  const grid = document.getElementById('made-for-you-grid');
  const followed = Object.values(favoriteArtists);
  if (!followed.length) { if (section) section.style.display = 'none'; return; }
  if (section) section.style.display = 'block';

  const setKey = followed.map(a => a.name.toLowerCase()).sort().join('|');
  const dateStr = new Date().toISOString().slice(0, 10);
  const uidPart = currentUser ? currentUser.uid : 'anon';
  const cacheKey = 'vibexa_madeforyou_v1_' + uidPart + '_' + dateStr + '_' + setKey;

  if (!force) {
    try {
      const cached = localStorage.getItem(cacheKey);
      if (cached) {
        const mixes = JSON.parse(cached);
        if (mixes && mixes.length) { renderMadeForYouMixes(mixes); return; }
      }
    } catch (e) {}
  }

  if (grid) grid.innerHTML = '<div class="empty" style="padding:16px 0;font-size:.8rem;"><i></i><h3>Preparing a playlist for you...</h3></div>';

  try {
    const neededTotal = MFY_MIX_COUNT * MFY_TRACKS_PER_MIX; // 8 x 15 = 120

    // Ambil lagu-lagu teratas dari tiap artis yang diikuti (Deezer top tracks)
    const perArtistLimit = Math.min(50, Math.max(15, Math.ceil(neededTotal / followed.length) + 5));
    const perArtistResults = await Promise.all(followed.map(a => fetchArtistTopTracks(a.name, perArtistLimit)));

    // Gabungkan secara round-robin (bergiliran per artis) supaya playlist
    // tidak didominasi satu artis, lalu hindari lagu duplikat di tahap ini.
    const merged = [];
    const seen = new Set();
    let idx = 0, addedAny = true;
    while (addedAny) {
      addedAny = false;
      for (let i = 0; i < perArtistResults.length; i++) {
        const arr = perArtistResults[i];
        if (arr && arr[idx]) {
          const t = arr[idx];
          if (!seen.has(t.id)) { seen.add(t.id); merged.push(t); addedAny = true; }
        }
      }
      idx++;
    }

    if (!merged.length) throw new Error('No songs from followed artists');

    // Kalau lagu unik yang berhasil dikumpulkan masih kurang dari 120 (mis.
    // user baru follow 1-2 artis), lengkapi dengan mengulang pool yang ada
    // supaya 8 playlist x 15 lagu tetap selalu terisi penuh.
    const pool = [...merged];
    let cycle = 0;
    while (pool.length < neededTotal) {
      pool.push(merged[cycle % merged.length]);
      cycle++;
    }

    // Acak dengan seed harian + uid: personal per user, stabil sepanjang
    // hari yang sama, otomatis berubah besok atau saat daftar artis berubah.
    const shuffled = _dmSeededShuffle(pool, cacheKey);

    let mixes = [];
    for (let m = 0; m < MFY_MIX_COUNT; m++) {
      const slice = shuffled.slice(m * MFY_TRACKS_PER_MIX, m * MFY_TRACKS_PER_MIX + MFY_TRACKS_PER_MIX)
        .map(t => ({ ...t, _query: `${t.artist}|||${t.title}|||${t.id}` }));
      if (!slice.length) continue;
      const uniqueArtists = [];
      for (const t of slice) { if (!uniqueArtists.includes(t.artist)) uniqueArtists.push(t.artist); if (uniqueArtists.length >= 2) break; }
      mixes.push({
        id: 'mfy_' + m,
        label: 'Made For You',
        title: uniqueArtists.length >= 2 ? `${uniqueArtists[0]} and ${uniqueArtists[1]}` : (uniqueArtists[0] || 'Made For You'),
        cover: slice[0].thumb,
        tracks: slice
      });
    }

    if (!mixes.length) throw new Error('Failed to create playlist for you');

    try {
      localStorage.setItem(cacheKey, JSON.stringify(mixes));
      Object.keys(localStorage).forEach(k => {
        if (k.startsWith('vibexa_madeforyou_v1_' + uidPart + '_') && k !== cacheKey) localStorage.removeItem(k);
      });
    } catch (e) {}

    renderMadeForYouMixes(mixes);
  } catch (e) {
    console.error('loadMadeForYouMixes error:', e);
    if (grid) grid.innerHTML = '<div class="empty" style="padding:16px 0;font-size:.8rem;color:var(--sub)"> Failed to load your playlist, try refreshing.</div>';
  }
}

function renderMadeForYouMixes(mixes) {
  const c = document.getElementById('made-for-you-grid');
  if (!c) return;
  c.innerHTML = '';
  mixes.forEach((mix, i) => c.appendChild(buildMadeForYouCardEl(mix, i)));
}

function buildMadeForYouCardEl(mix, i) {
  const color = DM_COLORS[i % DM_COLORS.length];
  const num = String(i + 1).padStart(2, '0');
  const div = document.createElement('div');
  div.className = 'dm-card';
  div.innerHTML = `
    <div class="dm-cover-wrap">
      ${mix.cover ? `<img class="dm-cover-img" src="${esc(mix.cover)}" alt="" loading="lazy" onerror="this.style.display='none'">` : ''}
      <div class="dm-cover-ov">
        <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
      </div>
      <div class="dm-badge-mix">For You</div>
      <div class="dm-badge-num" style="color:${color}">${num}</div>
    </div>
    <div class="dm-title">${esc(mix.title)}</div>
  `;
  div.querySelector('.dm-cover-ov').addEventListener('click', (e) => { e.stopPropagation(); playDailyMix(mix); });
  div.addEventListener('click', () => openDailyMix(mix));
  return div;
}

