function renderRanking(items) {
  const c = document.getElementById('rank-grid');
  if (!c) return;
  c.innerHTML = '';
  items.forEach((pl, i) => {
    const numClass = i === 0 ? 'gold' : i === 1 ? 'silver' : i === 2 ? 'bronze' : '';
    const numLabel = i === 0 ? '1' : i === 1 ? '2' : i === 2 ? '3' : (i+1);
    const div = document.createElement('div');
    div.className = 'rank-item';
    div.innerHTML = `
      <div class="rank-num ${numClass}">${numLabel}</div>
      <div class="rank-cover">${plCoverInnerHTML(pl)}</div>
      <div class="rank-info">
        <div class="rank-name">${esc(pl.name || 'Playlist')}</div>
        <div class="rank-owner">by ${esc(pl.ownerName || 'Anonymous')} · ${(pl.tracks||[]).length} songs</div>
      </div>
      <div class="rank-likes">
        <svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>
        ${pl.likeCount}
      </div>
    `;
    div.addEventListener('click', () => openPublicPlaylist(pl));
    c.appendChild(div);
  });
}

function renderPublicGrid(pls) {
  // Show other users' playlists first, then own published
  const others = pls.filter(p => p.ownerUid !== currentUser.uid);
  const mine = pls.filter(p => p.ownerUid === currentUser.uid);
  const sorted = [...others, ...mine];

  _pubFullList = sorted;
  renderPubGridItems();
}

let _pubFullList = [];

function renderPubGridItems() {
  const c = document.getElementById('pub-grid');
  if (!c) return;
  c.innerHTML = '';

  const sorted = _pubFullList;
  if (!sorted.length) {
    c.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:24px 0;font-size:.82rem;"><i></i><h3>No playlists yet publik</h3></div>';
    return;
  }

  const visible = sorted;

  visible.forEach(pl => {
    const card = document.createElement('div');
    card.className = 'pub-card';
    const isOwn = pl.ownerUid === currentUser.uid;
    card.innerHTML = `
      <div class="pub-cover-wrap">
        ${plCoverHTML(pl, 'pub-card-img', 'pub-card-cover')}
        <div class="pub-cover-ov">
          <svg viewBox="0 0 24 24" fill="white"><path d="M8 5v14l11-7z"/></svg>
        </div>
      </div>
      <div class="pub-card-body">
        <div class="pub-card-name">${esc(pl.name || 'Playlist')}</div>
        <div class="pub-card-bottom">
          <span class="pub-card-owner">
            ${isOwn
              ? `<svg viewBox="0 0 24 24" width="11" height="11" fill="currentColor"><path d="M12 12c2.7 0 5-2.3 5-5s-2.3-5-5-5-5 2.3-5 5 2.3 5 5 5zm0 2c-3.3 0-10 1.7-10 5v2h20v-2c0-3.3-6.7-5-10-5z"/></svg> Milikmu`
              : `<svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/></svg> ${esc(pl.ownerName || 'Anonymous')}`}
          </span>
          <button class="pub-like-btn ${pl.iLiked ? 'liked' : ''}" data-key="${esc(pl.key)}" onclick="toggleLike(event,'${esc(pl.key)}',${pl.iLiked})">
            <svg viewBox="0 0 24 24" fill="${pl.iLiked ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2.5"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
            <span class="like-count-${esc(pl.key)}">${pl.likeCount}</span>
          </button>
          <button class="pub-comment-btn" onclick="openCommentModal(event,'${esc(pl.key)}','${esc((pl.name||'Playlist').replace(/'/g,"\\'"))}')">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
            <span class="comment-count-${esc(pl.key)}">${pl.commentCount ? ' '+pl.commentCount : ''}</span>
          </button>
        </div>
      </div>
    `;
    card.querySelector('.pub-cover-ov').addEventListener('click', e => { e.stopPropagation(); openPublicPlaylist(pl); playPublicPlaylist(pl); });
    card.addEventListener('click', () => openPublicPlaylist(pl));
    c.appendChild(card);
  });

}

async function toggleLike(e, key, currentlyLiked) {
  e.stopPropagation();
  if (!currentUser) return;
  const likeRef = db.ref('public_playlists/' + key + '/likes/' + currentUser.uid);
  const btn = e.currentTarget;
  const countEl = document.querySelector('.like-count-' + key);

  try {
    if (currentlyLiked) {
      await likeRef.remove();
      btn.classList.remove('liked');
      btn.querySelector('svg').setAttribute('fill','none');
      if (countEl) countEl.textContent = Math.max(0, parseInt(countEl.textContent) - 1);
      btn.setAttribute('onclick', `toggleLike(event,'${key}',false)`);
    } else {
      await likeRef.set(true);
      btn.classList.add('liked');
      btn.querySelector('svg').setAttribute('fill','currentColor');
      if (countEl) countEl.textContent = parseInt(countEl.textContent) + 1;
      btn.setAttribute('onclick', `toggleLike(event,'${key}',true)`);
      toast(' Playlist liked!');

      // ── Kirim notifikasi ke owner playlist ──
      try {
        const plSnap = await db.ref('public_playlists/' + key).get();
        if (plSnap.exists()) {
          const plData = plSnap.val();
          const ownerUid = plData.ownerUid;
          // Jangan kirim notif ke diri sendiri
          if (ownerUid && ownerUid !== currentUser.uid) {
            const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(() => null);
            const profile = profileSnap?.val() || {};
            const fromName = profile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
            const fromPhoto = profile.photoURL || profile.photoBase64 || currentUser.photoURL || '';
            const notif = {
              type: 'like',
              fromUid: currentUser.uid,
              fromName,
              fromPhoto,
              playlistKey: key,
              playlistName: plData.name || 'Playlist',
              ts: Date.now(),
              read: false
            };
            db.ref('users/' + ownerUid + '/notifications').push(notif).catch(() => {});
          }
        }
      } catch(notifErr) {
        console.warn('Notif like gagal:', notifErr);
      }
    }
    // Refresh ranking after like change
    setTimeout(() => loadPublicFeed(), 500);
  } catch(err) {
    toast(' Failed: ' + err.message);
  }
}

// Open a public playlist (read-only view)
let currentPubPlaylist = null;
async function openPublicPlaylist(pl) {
  _reorderMode = false; // reset mode saat buka playlist publik
  currentPubPlaylist = pl;
  currentPlaylistId = null; // not an owned playlist
  const tracks = (pl.tracks || []).map(t => ({
    title: t.title || '',
    artist: t.artist || '',
    thumb: t.thumb || '',
    photo: t.photo || t.thumb || '',
    _query: t._query || (t.artist + '|||' + t.title + '|||0')
  }));

  document.getElementById('home-view').classList.remove('active');
  document.getElementById('search-view').classList.remove('active');
  document.getElementById('playlist-view').style.display = 'block';
  document.getElementById('top-songs-full-view').style.display = 'none';
  document.getElementById('recently-played-full-view').style.display = 'none';
  document.getElementById('recommend-full-view').style.display = 'none';
  document.getElementById('artist-view').style.display = 'none';
  document.getElementById('album-view').style.display = 'none';
  document.getElementById('song-preview-view').style.display = 'none';
  document.body.classList.remove('sp-mobile-open');
  if (typeof spAudio !== 'undefined' && spAudio) { spAudio.pause(); }
  if (typeof closeFSLyricsIfOpen === 'function') { closeFSLyricsIfOpen(); }
  document.getElementById('nav-home').classList.remove('on');
  document.getElementById('nav-search').classList.remove('on');

  // Fill playlist view with public data (read-only) — cover otomatis dari art songs-nya juga
  const coverEl = document.getElementById('pv-cover');
  coverEl.outerHTML = plCoverHTML({ tracks }, 'pv-cover', 'pv-cover-ph', 'pv-cover');
  document.getElementById('pv-title').textContent = pl.name || 'Playlist';
  document.getElementById('pv-sub').textContent = `${tracks.length} songs`;

  // Hide edit actions for other people's playlists
  const isOwn = pl.ownerUid === currentUser?.uid;
  document.querySelectorAll('.pv-action-btn').forEach(b => b.style.display = isOwn ? '' : 'none');
  updatePvMixLibBtn(null);
  const pubBtn = document.getElementById('pv-publish-btn');
  if (pubBtn) pubBtn.style.display = 'none';
  const reorderBtn = document.getElementById('pv-reorder-btn');
  if (reorderBtn) reorderBtn.style.display = 'none';
  const covEdit = document.querySelector('.pv-cover-edit');
  if (covEdit) covEdit.style.display = 'none';

  // ── Owner Profile Card ──
  // Remove old card if exists
  const oldCard = document.getElementById('pv-owner-card');
  if (oldCard) oldCard.remove();

  // Ambil foto profil owner dari Firebase
  const ownerCard = document.createElement('div');
  ownerCard.id = 'pv-owner-card';
  ownerCard.className = 'pv-owner-card';
  const ownerName = pl.ownerName || 'Anonymous';
  ownerCard.innerHTML = `
    <div class="pv-owner-avatar" id="pv-owner-avatar">
      <svg viewBox="0 0 24 24" fill="currentColor" style="color:var(--sub);width:22px;height:22px"><path d="M12 12c2.7 0 5-2.3 5-5s-2.3-5-5-5-5 2.3-5 5 2.3 5 5 5zm0 2c-3.3 0-10 1.7-10 5v2h20v-2c0-3.3-6.7-5-10-5z"/></svg>
    </div>
    <div class="pv-owner-info">
      <div class="pv-owner-label">Created by</div>
      <div class="pv-owner-name">${esc(ownerName)}</div>
    </div>
    <div class="pv-owner-arrow">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M9 18l6-6-6-6"/></svg>
    </div>
  `;
  // Klik owner card → ke halaman profil owner (jika punya UID)
  if (pl.ownerUid) {
    ownerCard.title = 'View profile ' + ownerName;
    ownerCard.addEventListener('click', () => {
      window.location.href = 'profile.html?uid=' + encodeURIComponent(pl.ownerUid);
    });
    // Load foto profil owner dari DB
    db.ref('users/' + pl.ownerUid + '/profile').get().then(snap => {
      if (!snap.exists()) return;
      const profile = snap.val();
      const avatarEl = document.getElementById('pv-owner-avatar');
      if (!avatarEl) return;
      // Update name if newer
      if (profile.displayName) {
        const nameEl = ownerCard.querySelector('.pv-owner-name');
        if (nameEl) nameEl.textContent = profile.displayName;
      }
      // Tampilkan foto profil
      const photoUrl = profile.photoURL || profile.photoBase64 || '';
      if (photoUrl) {
        avatarEl.innerHTML = `<img src="${esc(photoUrl)}" alt="${esc(ownerName)}" onerror="this.parentElement.innerHTML=''">`;
      }
    }).catch(() => {});
  } else {
    ownerCard.style.cursor = 'default';
    const arrowEl = ownerCard.querySelector('.pv-owner-arrow');
    if (arrowEl) arrowEl.style.display = 'none';
  }

  // Sisipkan card setelah pv-actions
  const pvActions = document.querySelector('.pv-actions');
  if (pvActions) pvActions.after(ownerCard);

  const c = document.getElementById('pv-tracks');
  if (!tracks.length) {
    c.innerHTML = `<div class="pv-empty"><div class="pv-empty-icon"></div>This playlist is empty.</div>`;
    return;
  }
  c.innerHTML = `<div class="track-list-header"><div class="tl-h">#</div><div class="tl-h">Title</div><div class="tl-h">Artist</div><div class="tl-h r"></div></div>`;
  tracks.forEach((t, i) => {
    const row = document.createElement('div');
    row.className = 'track-row' + (curTrack && curTrack._query === t._query ? ' playing' : '');
    const src = t.photo || t.thumb;
    row.innerHTML = `
      <div class="tr-num">${i+1}</div>
      <div class="tr-info">
        ${src ? `<img class="tr-thumb" src="${esc(src)}" onerror="this.style.display='none'">` : `<div class="tr-thumb-ph"></div>`}
        <div class="tr-text">
          <div class="tr-title">${esc(t.title)}</div>
          <div class="tr-artist" style="font-size:.7rem;color:var(--sub)">${esc(t.artist)}</div>
        </div>
      </div>
      <div class="tr-album">${esc(t.artist)}</div>
      <div class="tr-dur">${buildAddBtnHTML(t, 'tr-add')}</div>
    `;
    row.addEventListener('click', (e) => {
      if (e.target.closest('.tr-add')) return;
      curQueue = [...tracks];
      loadPlay(t, null);
      // Re-render to update playing highlight
      setTimeout(() => openPublicPlaylist(pl), 100);
    });
    wireAddBtn(row.querySelector('.add-btn'), t);
    c.appendChild(row);
  });
}

function playPublicPlaylist(pl) {
  const tracks = (pl.tracks || []).map(t => ({
    title: t.title || '',
    artist: t.artist || '',
    thumb: t.thumb || '',
    photo: t.photo || t.thumb || '',
    _query: t._query || (t.artist + '|||' + t.title + '|||0')
  }));
  if (!tracks.length) { toast(' Playlist is empty'); return; }
  curQueue = [...tracks];
  loadPlay(tracks[0], null);
}

// ─── PUBLISH / UNPUBLISH ──────────────────────────────────
async function togglePublishPlaylist() {
  if (!currentPlaylistId || !currentUser) return;
  const pl = playlists[currentPlaylistId];
  if (!pl) return;

  const key = currentUser.uid + '_' + currentPlaylistId;
  const isPublic = !!pl.public;

  if (isPublic) {
    // Unpublish
    if (!confirm('Remove playlist "' + pl.name + '" from public feed?')) return;
    try {
      await db.ref('public_playlists/' + key).remove();
      pl.public = false;
      scheduleSave();
      updatePublishBtn(false);
      toast(' Playlist hidden from public');
      loadPublicFeed();
    } catch(e) { toast(' Failed: ' + e.message); }
  } else {
    // Publish
    const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(()=>null);
    const profileData = profileSnap?.val() || {};
    const ownerName = profileData.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const ownerPhoto = profileData.photoURL || profileData.photoBase64 || currentUser.photoURL || '';
    try {
      await db.ref('public_playlists/' + key).set({
        name: pl.name || 'Playlist',
        ownerUid: currentUser.uid,
        ownerName,
        ownerPhoto,
        coverThumb: pl.coverThumb || '',
        tracks: (pl.tracks || []).slice(0, 50).map(t => ({
          title: t.title || '',
          artist: t.artist || '',
          thumb: t.thumb || '',
          _query: t._query || ''
        })),
        likes: {},
        publishedAt: Date.now()
      });
      pl.public = true;
      scheduleSave();
      updatePublishBtn(true);
      toast(' Playlist published!');
      loadPublicFeed();
    } catch(e) { toast(' Failed: ' + e.message); }
  }
}

// ─── HOME GIF BANNER — "GIF TIME" ──────────────────────────
// Banner GIF bawaan di paling atas halaman Home yang otomatis berganti
// sesuai jam lokal perangkat. Bersifat read-only: tidak ada lagi opsi
// bagi user untuk mengunggah atau mengganti GIF ini.
// Jadwal (berulang setiap hari, berdasarkan jam lokal perangkat):
//   01:00–03:00  kiss
//   03:00–08:00  sunrise
//   08:00–12:00  cat
//   12:00–15:00  waterboom
//   15:00–18:00  dawn
//   18:00–20:00  night
//   20:00–23:00  cyber
//   23:00–01:00  zombie
const HOME_GIF_TIME_SCHEDULE = [
  { start: 1,  end: 3,  url: 'https://res.cloudinary.com/vqlllesq/image/upload/v1784382654/kiss_hbfu93.gif' },
  { start: 3,  end: 8,  url: 'https://res.cloudinary.com/vqlllesq/image/upload/v1784382655/sunrise_d3hvle.gif' },
  { start: 8,  end: 12, url: 'https://res.cloudinary.com/vqlllesq/image/upload/v1784382655/cat_khs6b2.gif' },
  { start: 12, end: 15, url: 'https://res.cloudinary.com/vqlllesq/image/upload/v1784382653/waterboom_obkyn2.gif' },
  { start: 15, end: 18, url: 'https://res.cloudinary.com/vqlllesq/image/upload/v1784382654/dawn_whuqpy.gif' },
  { start: 18, end: 20, url: 'https://res.cloudinary.com/vqlllesq/image/upload/v1784382653/night_fyngrn.gif' },
  { start: 20, end: 23, url: 'https://res.cloudinary.com/vqlllesq/image/upload/v1784382652/cyber_tqwdtn.gif' },
  // 23:00–01:00 (lewat tengah malam)
  { start: 23, end: 25, url: 'https://res.cloudinary.com/vqlllesq/image/upload/v1784382653/zombie_tc31kb.gif' },
];

// Ambil URL GIF yang seharusnya tampil untuk jam tertentu (default: jam sekarang)
function getHomeGifTimeUrl(date) {
  date = date || new Date();
  let hour = date.getHours();
  // Normalisasi jam 0 (tengah malam) supaya jatuh ke slot 23-25 (zombie)
  const h = hour === 0 ? 24 : hour;
  for (const slot of HOME_GIF_TIME_SCHEDULE) {
    if (h >= slot.start && h < slot.end) return slot.url;
  }
  // fallback (seharusnya tidak pernah kena karena jadwal menutup 24 jam penuh)
  return HOME_GIF_TIME_SCHEDULE[HOME_GIF_TIME_SCHEDULE.length - 1].url;
}

let _hgbTimeInterval = null;
let _hgbLastAppliedTimeUrl = null;

// Jalankan pengecekan berkala supaya banner otomatis ganti begitu masuk slot
// jam berikutnya, tanpa perlu reload halaman.
function _hgbStartTimeWatcher() {
  if (_hgbTimeInterval) return;
  _hgbTimeInterval = setInterval(() => {
    const nextUrl = getHomeGifTimeUrl();
    if (nextUrl !== _hgbLastAppliedTimeUrl) {
      applyHomeBanner();
    }
  }, 30000); // cek tiap 30 detik
}

// Terapkan GIF "GIF Time" (sesuai jam saat ini) ke elemen <img> di Home.
function applyHomeBanner() {
  const img = document.getElementById('home-gif-banner-img');
  if (!img) return;
  const timeUrl = getHomeGifTimeUrl();
  _hgbLastAppliedTimeUrl = timeUrl;
  img.src = timeUrl;
  _hgbStartTimeWatcher();
}

applyHomeBanner();


// ─── LYRICS BACKGROUND ────────────────────────────────────
let _lyrBgData = null;       // base64 dari foto yang dipilih (belum disimpan)
let _lyrBgSaved = null;      // base64 yang sudah aktif/tersimpan
let _lyrBgPending = false;

// Load background dari Firebase saat login
async function loadLyrBgFromCloud() {
  if (!currentUser) return;
  try {
    const snap = await db.ref('users/' + currentUser.uid + '/lyricsBackground').get();
    if (snap.exists() && snap.val()) {
      _lyrBgSaved = snap.val();
      applyLyrBg(_lyrBgSaved);
    }
  } catch(e) { console.warn('loadLyrBg error:', e); }
}

function applyLyrBg(dataUrl) {
  const fsEl = document.getElementById('fs-lyr');
  const fsBg = document.getElementById('fs-bg');
  if (dataUrl) {
    fsBg.style.backgroundImage = `url('${dataUrl}')`;
    fsBg.style.backgroundSize = 'cover';
    fsBg.style.backgroundPosition = 'center';
    fsBg.style.backgroundRepeat = 'no-repeat';
    fsEl.classList.add('has-custom-bg');
  } else {
    fsBg.style.backgroundImage = '';
    fsEl.classList.remove('has-custom-bg');
    // Restore color background
    pickFSColor();
  }
}

function openLyrBgModal() {
  const modal = document.getElementById('lyr-bg-modal');
  modal.style.display = 'flex';
  _lyrBgData = null;
  _lyrBgPending = false;

  // Tampilkan preview kalau sudah ada foto tersimpan
  const previewImg = document.getElementById('lyr-bg-preview-img');
  const previewEmpty = document.getElementById('lyr-bg-preview-empty');
  const saveBtn = document.getElementById('lyr-bg-save-btn');
  const resetBtn = document.getElementById('lyr-bg-reset-btn');

  if (_lyrBgSaved) {
    previewImg.src = _lyrBgSaved;
    previewImg.style.display = 'block';
    previewEmpty.style.display = 'none';
    resetBtn.style.display = 'flex';
  } else {
    previewImg.style.display = 'none';
    previewEmpty.style.display = 'flex';
    resetBtn.style.display = 'none';
  }
  saveBtn.style.display = 'none';
}

function closeLyrBgModal() {
  document.getElementById('lyr-bg-modal').style.display = 'none';
  _lyrBgData = null;
  _lyrBgPending = false;
}

document.getElementById('lyr-bg-modal').addEventListener('click', e => {
  if (e.target === document.getElementById('lyr-bg-modal')) closeLyrBgModal();
});

document.getElementById('lyr-bg-file').addEventListener('change', function() {
  const file = this.files[0];
  if (!file) return;
  if (file.size > 5 * 1024 * 1024) {
    toast(' Photo is too large (max 5 MB)');
    return;
  }
  const reader = new FileReader();
  reader.onload = e => {
    _lyrBgData = e.target.result;
    _lyrBgPending = true;
    // Tampilkan preview
    const previewImg = document.getElementById('lyr-bg-preview-img');
    const previewEmpty = document.getElementById('lyr-bg-preview-empty');
    previewImg.src = _lyrBgData;
    previewImg.style.display = 'block';
    previewEmpty.style.display = 'none';
    document.getElementById('lyr-bg-save-btn').style.display = 'inline-flex';
    document.getElementById('lyr-bg-reset-btn').style.display = 'flex';
  };
  reader.readAsDataURL(file);
  // Reset file input agar bisa pilih file yang sama lagi
  this.value = '';
});

async function saveLyrBg() {
  if (!_lyrBgData || !currentUser) return;
  const btn = document.getElementById('lyr-bg-save-btn');
  btn.textContent = 'Menyimpan...';
  btn.disabled = true;
  try {
    await db.ref('users/' + currentUser.uid + '/lyricsBackground').set(_lyrBgData);
    _lyrBgSaved = _lyrBgData;
    applyLyrBg(_lyrBgSaved);
    toast(' Lyrics background saved!');
    closeLyrBgModal();
  } catch(e) {
    toast(' Save failed: ' + e.message);
  } finally {
    btn.textContent = 'Terapkan';
    btn.disabled = false;
  }
}

async function resetLyrBg() {
  if (!confirm('Delete lyrics background photo?')) return;
  try {
    if (currentUser) await db.ref('users/' + currentUser.uid + '/lyricsBackground').remove();
    _lyrBgSaved = null;
    _lyrBgData = null;
    applyLyrBg(null);
    const previewImg = document.getElementById('lyr-bg-preview-img');
    const previewEmpty = document.getElementById('lyr-bg-preview-empty');
    previewImg.style.display = 'none';
    previewEmpty.style.display = 'flex';
    document.getElementById('lyr-bg-save-btn').style.display = 'none';
    document.getElementById('lyr-bg-reset-btn').style.display = 'none';
    toast(' Lyrics background removed');
  } catch(e) { toast(' Delete failed: ' + e.message); }
}

// Hook ke showApp agar background dimuat setelah login
const _origShowApp = showApp;
showApp = function(user) {
  _origShowApp(user);
  loadLyrBgFromCloud();
};

// Pastikan background tetap aktif saat pickFSColor dipanggil (jika ada foto custom)
const _origPickFSColor = pickFSColor;
pickFSColor = function() {
  if (_lyrBgSaved) {
    // Jangan ganti warna kalau ada custom bg
    return;
  }
  _origPickFSColor();
};

function updatePublishBtn(isPublic) {
  const btn = document.getElementById('pv-publish-btn');
  if (!btn) return;
  if (isPublic) {
    btn.classList.add('published');
    btn.innerHTML = `<svg viewBox="0 0 24 24" fill="currentColor" width="14" height="14"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 14.5v-9l6 4.5-6 4.5z"/></svg> Published`;
  } else {
    btn.classList.remove('published');
    btn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" width="14" height="14"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg> Publikasikan`;
  }
}

// ─── SISTEM NOTIFIKASI ──────────────────────────────────
// Menyimpan notifikasi di Firebase: users/{uid}/notifications/{notifId}
// Listener real-time untuk like & komentar di semua playlist publik milik user

let _notifListeners = []; // simpan ref agar bisa di-detach
let _notifCache = [];           // cache notifikasi terakhir yang dirender
let _notifSelectMode = false;   // apakah mode pilih sedang aktif
let _selectedNotifIds = new Set(); // id notifikasi yang sedang dicentang

// Config update APK terbaru yang berhasil dideteksi oleh checkForAppUpdate()
// (lihat bagian "CEK UPDATE APK" di bawah). Dipakai untuk menampilkan kartu
// pinned "Update Tersedia" di panel notifikasi (bell), supaya user yang
// menutup/melewatkan modal tetap bisa update lewat notifikasi.
let _pendingApkUpdate = null;

// ── Notifikasi "Download / Update App" (pinned di paling atas panel bell) ──
// Naikkan APP_VERSION setiap kali merilis versi baru supaya notifikasi ini
// muncul lagi ke user yang sebelumnya sudah menekan "Nanti".
const APP_VERSION = '1.0.0';

function isPwaInstalled() {
  return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)
    || window.navigator.standalone === true
    || localStorage.getItem('vibexa_pwa_installed') === '1';
}

function shouldShowAppUpdateNotif() {
  if (isPwaInstalled()) return false; // sudah pakai app, tidak perlu ditawari lagi
  if (localStorage.getItem('vibexa_pwa_dismissed_version') === APP_VERSION) return false;
  return true;
}

function buildAppUpdateNotifHtml() {
  return `
    <div class="notif-item notif-app-item" id="notif-app-update-item">
      <div class="notif-icon-wrap notif-icon-app"><img src="logo-icon.png" alt="Vibexa" onerror="this.parentElement.textContent='⬇️'"></div>
      <div class="notif-body">
        <div class="notif-msg">
          <strong>Vibexa</strong> Pasang aplikasi Vibexa di perangkatmu — lebih cepat, tampil di layar utama, dan bisa dibuka walau offline.
        </div>
        <div class="notif-app-actions">
          <button class="notif-download-btn" type="button" onclick="event.stopPropagation(); downloadAppNow();">Download</button>
          <button class="notif-dismiss-btn" type="button" onclick="event.stopPropagation(); dismissAppUpdateNotif();">Nanti</button>
        </div>
        <div class="notif-time">Versi ${esc(APP_VERSION)}</div>
      </div>
    </div>
  `;
}

function dismissAppUpdateNotif() {
  localStorage.setItem('vibexa_pwa_dismissed_version', APP_VERSION);
  renderNotifications(_notifCache);
}

// ── Notifikasi "Update APK Tersedia" (pinned di panel bell, sumber data
// dari _pendingApkUpdate yang diisi oleh checkForAppUpdate()) ──
// Pakai key dismiss yang SAMA dengan modal ('vbx_update_dismissed') supaya
// menekan "Nanti" di modal ATAU di kartu notifikasi ini efeknya konsisten:
// keduanya sama-sama disembunyikan untuk versionCode yang sama, di sesi ini.
function isApkUpdateDismissed(versionCode) {
  try {
    return sessionStorage.getItem('vbx_update_dismissed') === String(versionCode);
  } catch (e) {
    return false;
  }
}

function shouldShowApkUpdateNotif() {
  return !!(_pendingApkUpdate && _pendingApkUpdate.versionCode && _pendingApkUpdate.apkUrl
    && (_pendingApkUpdate.forceUpdate || !isApkUpdateDismissed(_pendingApkUpdate.versionCode)));
}

function buildApkUpdateNotifHtml() {
  const cfg = _pendingApkUpdate;
  if (!cfg) return '';
  const changelogHtml = cfg.changelog
    ? `<div class="notif-comment-preview">${esc(String(cfg.changelog))}</div>`
    : '';
  return `
    <div class="notif-item notif-app-item" id="notif-apk-update-item">
      <div class="notif-icon-wrap notif-icon-app">🚀</div>
      <div class="notif-body">
        <div class="notif-msg">
          <strong>Vibexa</strong> Update ${esc(cfg.versionName || '')} tersedia untuk diunduh.
        </div>
        ${changelogHtml}
        <div class="notif-app-actions">
          <button class="notif-download-btn" type="button" onclick="event.stopPropagation(); downloadApkUpdateNow();">Update Sekarang</button>
          ${cfg.forceUpdate ? '' : '<button class="notif-dismiss-btn" type="button" onclick="event.stopPropagation(); dismissApkUpdateNotif();">Nanti</button>'}
        </div>
        <div class="notif-time">Versi ${esc(cfg.versionName || '')}</div>
      </div>
    </div>
  `;
}

function downloadApkUpdateNow() {
  if (!_pendingApkUpdate || !_pendingApkUpdate.apkUrl) return;
  window.open(_pendingApkUpdate.apkUrl, '_system');
}

function dismissApkUpdateNotif() {
  if (!_pendingApkUpdate) return;
  try { sessionStorage.setItem('vbx_update_dismissed', String(_pendingApkUpdate.versionCode)); } catch (e) {}
  renderNotifications(_notifCache);
  refreshAppInstallBadge();
}

// Dipanggil dari checkForAppUpdate() setiap kali status update berubah,
// supaya kartu pinned di panel notifikasi & badge lonceng langsung sinkron
// tanpa perlu user membuka/menutup panel dulu.
function refreshApkUpdateNotifUI() {
  renderNotifications(_notifCache);
  refreshAppInstallBadge();
}

function timeAgo(ts) {
  const diff = Date.now() - ts;
  const m = Math.floor(diff / 60000);
  if (m < 1) return 'Just now';
  if (m < 60) return m + ' minutes ago';
  const h = Math.floor(m / 60);
  if (h < 24) return h + ' hours ago';
  const d = Math.floor(h / 24);
  if (d < 7) return d + ' days ago';
  return new Date(ts).toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: '2-digit' });
}

function toggleNotifPanel() {
  const panel = document.getElementById('notif-panel');
  const overlay = document.getElementById('notif-overlay');
  if (panel.classList.contains('open')) {
    closeNotifPanel();
  } else {
    // Kalau halaman lirik fullscreen sedang terbuka, tutup dulu supaya user
    // langsung diarahkan ke panel notifikasi, bukan malah ketutupan lirik.
    if (typeof closeFSLyricsIfOpen === 'function') { closeFSLyricsIfOpen(); }
    panel.classList.add('open');
    overlay.classList.add('show');
  }
}

function closeNotifPanel() {
  document.getElementById('notif-panel').classList.remove('open');
  document.getElementById('notif-overlay').classList.remove('show');
  // Keluar dari mode pilih saat panel ditutup
  if (_notifSelectMode) exitNotifSelectMode();
}

async function markAllRead() {
  if (!currentUser) return;
  const snap = await db.ref('users/' + currentUser.uid + '/notifications').orderByChild('read').equalTo(false).get().catch(() => null);
  if (!snap || !snap.exists()) return;
  const updates = {};
  snap.forEach(child => { updates[child.key + '/read'] = true; });
  db.ref('users/' + currentUser.uid + '/notifications').update(updates).catch(() => {});
  // Update badge
  updateNotifBadge(0);
}

// Tandai satu notifikasi sebagai sudah dibaca (dipanggil saat notifikasi dibuka/di-zoom)
function markNotifRead(id) {
  if (!currentUser || !id) return;
  db.ref('users/' + currentUser.uid + '/notifications/' + id + '/read').set(true).catch(() => {});
}

async function clearAllNotifications() {
  if (!currentUser) return;
  if (!confirm('Clear all notifications?')) return;
  await db.ref('users/' + currentUser.uid + '/notifications').remove().catch(() => {});
  renderNotifications([]);
  updateNotifBadge(0);
}

// ── Mode pilih notifikasi ──
function toggleNotifSelectMode() {
  if (_notifSelectMode) {
    exitNotifSelectMode();
  } else {
    _notifSelectMode = true;
    _selectedNotifIds.clear();
    document.getElementById('notif-select-toggle').classList.add('active');
    document.getElementById('notif-select-toggle').textContent = 'Cancel';
    document.getElementById('notif-bulk-bar').classList.add('show');
    renderNotifications(_notifCache);
  }
}

function exitNotifSelectMode() {
  _notifSelectMode = false;
  _selectedNotifIds.clear();
  const toggleBtn = document.getElementById('notif-select-toggle');
  if (toggleBtn) { toggleBtn.classList.remove('active'); toggleBtn.textContent = 'Select'; }
  const bar = document.getElementById('notif-bulk-bar');
  if (bar) bar.classList.remove('show');
  renderNotifications(_notifCache);
}

function toggleNotifCheck(id) {
  if (_selectedNotifIds.has(id)) {
    _selectedNotifIds.delete(id);
  } else {
    _selectedNotifIds.add(id);
  }
  updateNotifBulkBar();
  const item = document.querySelector(`.notif-item[data-id="${CSS.escape(id)}"]`);
  if (item) item.classList.toggle('checked', _selectedNotifIds.has(id));
}

function toggleNotifSelectAll() {
  const allIds = _notifCache.map(n => n._id);
  const allSelected = allIds.length > 0 && allIds.every(id => _selectedNotifIds.has(id));
  if (allSelected) {
    _selectedNotifIds.clear();
  } else {
    allIds.forEach(id => _selectedNotifIds.add(id));
  }
  renderNotifications(_notifCache);
}

function updateNotifBulkBar() {
  const count = _selectedNotifIds.size;
  const countEl = document.getElementById('notif-bulk-count');
  const delBtn = document.getElementById('notif-bulk-delete-btn');
  const selAllBtn = document.getElementById('notif-bulk-selectall-btn');
  if (countEl) countEl.textContent = count + ' selected';
  if (delBtn) delBtn.disabled = count === 0;
  if (selAllBtn) {
    const allIds = _notifCache.map(n => n._id);
    const allSelected = allIds.length > 0 && allIds.every(id => _selectedNotifIds.has(id));
    selAllBtn.textContent = allSelected ? 'Cancel selection' : 'Select all';
  }
}

async function deleteSelectedNotifications() {
  if (!currentUser || _selectedNotifIds.size === 0) return;
  const ids = [..._selectedNotifIds];
  if (!confirm(`Delete ${ids.length} selected notifications?`)) return;
  const updates = {};
  ids.forEach(id => { updates[id] = null; });
  await db.ref('users/' + currentUser.uid + '/notifications').update(updates).catch(() => {});
  exitNotifSelectMode();
}

async function deleteSingleNotification(id) {
  if (!currentUser || !id) return;
  await db.ref('users/' + currentUser.uid + '/notifications/' + id).remove().catch(() => {});
}

function updateNotifBadge(count) {
  const badge = document.getElementById('notif-badge');
  const mobBadge = document.getElementById('mob-notif-badge');
  if (!badge) return;
  if (count > 0) {
    badge.textContent = count > 99 ? '99+' : count;
    badge.classList.add('show');
    if (mobBadge) { mobBadge.textContent = count > 99 ? '99+' : count; mobBadge.classList.add('show'); }
  } else {
    badge.classList.remove('show');
    if (mobBadge) mobBadge.classList.remove('show');
  }
}

// ── Modal zoom: melihat isi notifikasi secara utuh (tidak terpotong) ──
let _notifZoomCurrentId = null;

function openNotifZoom(id) {
  const n = _notifCache.find(x => x._id === id);
  if (!n) return;
  _notifZoomCurrentId = id;
  if (!n.read) markNotifRead(id);

  const isAsk = n.type === 'ask_message';
  const isLike = n.type === 'like';
  const isSongLike = n.type === 'song_like';
  const isCommentLike = n.type === 'comment_like';
  const isReply = n.type === 'comment_reply';
  const isChatLike = n.type === 'chat_like';

  const isSongTarget = n.targetType === 'song';
  let actionText;
  if (isAsk) actionText = 'sent an anonymous message to your vibeprofile';
  else if (isChatLike) actionText = `liked your message`;
  else if (isLike) actionText = `liked your "${n.playlistName || 'playlist'}" playlist`;
  else if (isSongLike) actionText = `liked the song you suggested: "${n.songTitle || 'song'}"`;
  else if (isCommentLike) actionText = `liked your comment on "${n.playlistName || 'playlist'}"`;
  else if (isReply) actionText = `membalas komentarmu di "${n.playlistName || 'playlist'}"`;
  else if (isSongTarget) actionText = `mengomentari lagu yang kamu sarankan: "${n.playlistName || 'song'}"`;
  else actionText = `mengomentari playlist "${n.playlistName || 'playlist'}"mu`;

  document.getElementById('notif-zoom-name').textContent = n.fromName || 'Seseorang';

  const avatarWrap = document.getElementById('notif-zoom-avatar');
  if (n.fromPhoto) {
    avatarWrap.innerHTML = `<div class="notif-avatar"><img src="${esc(n.fromPhoto)}" alt=""></div>`;
  } else if (isAsk) {
    avatarWrap.innerHTML = `<div class="notif-icon-wrap notif-icon-ask">💬</div>`;
  } else if (isLike || isSongLike || isChatLike) {
    avatarWrap.innerHTML = `<div class="notif-icon-wrap notif-icon-like">${isChatLike ? '❤' : ''}</div>`;
  } else {
    avatarWrap.innerHTML = `<div class="notif-icon-wrap notif-icon-comment"></div>`;
  }

  const bodyEl = document.getElementById('notif-zoom-body');
  const fullText = isAsk ? (n.text || '') : (isChatLike ? (n.msgPreview || '') : (n.comment || ''));
  if (fullText) {
    bodyEl.innerHTML = `<div style="margin-bottom:10px;color:var(--sub);font-size:.8rem;">${esc(n.fromName || 'Seseorang')} ${esc(actionText)}</div><div>${esc(fullText)}</div>`;
  } else {
    bodyEl.innerHTML = `<div>${esc(n.fromName || 'Seseorang')} ${esc(actionText)}</div>`;
  }

  document.getElementById('notif-zoom-overlay').classList.add('show');

  // Tutup panel notifikasi di belakangnya supaya pesan anonim lain tidak
  // ikut terlihat/ter-screenshot bersamaan dengan pesan yang sedang di-zoom.
  document.getElementById('notif-panel').classList.remove('open');
  document.getElementById('notif-overlay').classList.remove('show');
}

function closeNotifZoom() {
  document.getElementById('notif-zoom-overlay').classList.remove('show');
  _notifZoomCurrentId = null;
}

async function deleteNotifFromZoom() {
  if (!_notifZoomCurrentId) return;
  if (!confirm('Delete this notification?')) return;
  await deleteSingleNotification(_notifZoomCurrentId);
  closeNotifZoom();
}

function renderNotifications(notifs) {
  _notifCache = notifs || [];
  const list = document.getElementById('notif-list');
  if (!list) return;

  // Kartu update APK dipasang paling atas (prioritas tertinggi), baru
  // kartu ajakan install PWA, baru notifikasi normal (like/komentar/dst).
  const apkUpdateHtml = shouldShowApkUpdateNotif() ? buildApkUpdateNotifHtml() : '';
  const appUpdateHtml = shouldShowAppUpdateNotif() ? buildAppUpdateNotifHtml() : '';
  const pinnedHtml = apkUpdateHtml + appUpdateHtml;

  if (!notifs || !notifs.length) {
    list.innerHTML = pinnedHtml + `<div class="notif-empty"><span></span>No notifications yet.<br>When someone likes, comments,<br>likes your chat message, or sends<br>an anonymous message, it will appear here.</div>`;
    updateNotifBulkBar();
    return;
  }
  const sorted = [...notifs].sort((a, b) => (b.ts || 0) - (a.ts || 0));
  list.innerHTML = pinnedHtml;
  sorted.forEach(n => {
    const item = document.createElement('div');
    const isChecked = _selectedNotifIds.has(n._id);
    item.className = 'notif-item' + (n.read ? '' : ' unread') + (_notifSelectMode ? ' selectable' : '') + (isChecked ? ' checked' : '');
    item.dataset.id = n._id;

    const isLike = n.type === 'like';
    const isSongLike = n.type === 'song_like';
    const isCommentLike = n.type === 'comment_like';
    const isReply = n.type === 'comment_reply';
    const isAsk = n.type === 'ask_message';
    const isFollowReq = n.type === 'follow_request';
    const isChatLike = n.type === 'chat_like';

    let icon, actionText;
    if (isFollowReq) {
      icon = `<div class="notif-icon-wrap notif-icon-follow">👤</div>`;
      actionText = `wants to follow you`;
    } else if (isAsk) {
      icon = `<div class="notif-icon-wrap notif-icon-ask">💬</div>`;
      actionText = `sent an anonymous message to your vibeprofile`;
    } else if (isChatLike) {
      icon = `<div class="notif-icon-wrap notif-icon-like">❤</div>`;
      actionText = `liked your message`;
    } else if (isLike) {
      icon = `<div class="notif-icon-wrap notif-icon-like"></div>`;
      actionText = `liked your <span class="notif-pl">${esc(n.playlistName || 'playlist')}</span> playlist`;
    } else if (isSongLike) {
      icon = `<div class="notif-icon-wrap notif-icon-like"></div>`;
      actionText = `liked the song you suggested: <span class="notif-pl">${esc(n.songTitle || 'song')}</span>`;
    } else if (isCommentLike) {
      icon = `<div class="notif-icon-wrap notif-icon-comment-like"></div>`;
      actionText = `liked your comment on <span class="notif-pl">${esc(n.playlistName || 'playlist')}</span>`;
    } else if (isReply) {
      icon = `<div class="notif-icon-wrap notif-icon-comment">↩</div>`;
      actionText = `membalas komentarmu di <span class="notif-pl">${esc(n.playlistName || 'playlist')}</span>`;
    } else if (n.targetType === 'song') {
      icon = `<div class="notif-icon-wrap notif-icon-comment"></div>`;
      actionText = `mengomentari lagu yang kamu sarankan: <span class="notif-pl">${esc(n.playlistName || 'song')}</span>`;
    } else {
      icon = `<div class="notif-icon-wrap notif-icon-comment"></div>`;
      actionText = `mengomentari playlist <span class="notif-pl">${esc(n.playlistName || 'playlist')}</span>mu`;
    }

    const photo = n.fromPhoto
      ? `<div class="notif-avatar"><img src="${esc(n.fromPhoto)}" alt="" onerror="this.parentElement.textContent=''"></div>`
      : `<div class="notif-avatar"></div>`;

    const commentPrev = (!isLike && !isSongLike && !isAsk && n.comment)
      ? `<div class="notif-comment-preview">"${esc(n.comment.slice(0, 80))}${n.comment.length > 80 ? '…' : ''}"</div>`
      : '';

    const askPrev = isAsk && n.text
      ? `<div class="notif-comment-preview notif-ask-preview">❝ ${esc(n.text.slice(0, 100))}${n.text.length > 100 ? '…' : ''} ❞</div>`
      : '';

    const chatLikePrev = isChatLike && n.msgPreview
      ? `<div class="notif-comment-preview">"${esc(n.msgPreview.slice(0, 80))}${n.msgPreview.length > 80 ? '…' : ''}"</div>`
      : '';

    // Tombol Terima/Tolak untuk notifikasi permintaan follow (hanya kalau masih pending),
    // atau label status kalau sudah diproses sebelumnya.
    const followActionsHtml = isFollowReq
      ? (n.status === 'accepted'
          ? `<div class="notif-follow-status accepted"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" width="11" height="11"><path d="M20 6 9 17l-5-5"/></svg> You accepted this request</div>`
          : n.status === 'rejected'
            ? `<div class="notif-follow-status rejected"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" width="11" height="11"><path d="M18 6 6 18M6 6l12 12"/></svg> You declined this request</div>`
            : `<div class="notif-follow-actions">
                 <button class="notif-follow-btn accept" type="button" data-act="accept-follow" data-uid="${esc(n.fromUid || '')}" data-notif="${esc(n._id)}">Accept</button>
                 <button class="notif-follow-btn reject" type="button" data-act="reject-follow" data-uid="${esc(n.fromUid || '')}" data-notif="${esc(n._id)}">Decline</button>
               </div>`)
      : '';

    const checkboxHtml = _notifSelectMode
      ? `<div class="notif-checkbox-wrap"><div class="notif-checkbox"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></div></div>`
      : '';

    // Untuk pesan anonim: jam pengiriman disembunyikan, diganti status baca
    const bottomLine = isAsk
      ? (n.read
          ? `<div class="notif-read-status notif-read-status--read"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" width="11" height="11"><path d="M20 6 9 17l-5-5"/></svg> Read</div>`
          : `<div class="notif-read-status notif-read-status--unread"><span class="notif-unread-dot"></span> Unread</div>`)
      : `<div class="notif-time">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="11" height="11"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
          ${timeAgo(n.ts || 0)}
        </div>`;

    item.innerHTML = `
      ${checkboxHtml}
      ${n.fromPhoto ? photo : icon}
      <div class="notif-body">
        <div class="notif-msg">
          <strong>${esc(n.fromName || 'Seseorang')}</strong>
          ${actionText}
        </div>
        ${commentPrev}
        ${askPrev}
        ${chatLikePrev}
        ${followActionsHtml}
        ${bottomLine}
      </div>
    `;

    // Klik item: mode pilih -> toggle centang, follow_request -> tombol sendiri yang menangani aksi
    // (klik area lain cuma menandai dibaca), mode normal lainnya -> buka zoom (lihat pesan utuh)
    item.addEventListener('click', (ev) => {
      if (_notifSelectMode) {
        toggleNotifCheck(n._id);
      } else if (isFollowReq) {
        if (ev.target.closest('.notif-follow-btn')) return; // ditangani listener delegasi tombol sendiri
        if (!n.read) markNotifRead(n._id);
      } else if (isChatLike) {
        // Klik notif "like pesan" langsung membuka percakapannya, bukan
        // modal zoom, supaya user langsung diarahkan ke pesan yg di-like.
        if (!n.read) markNotifRead(n._id);
        openChatFromLikeNotif(n);
      } else {
        openNotifZoom(n._id);
      }
    });

    list.appendChild(item);
  });
  updateNotifBulkBar();
}

// Delegasi klik tombol Terima/Tolak permintaan follow di dalam panel notifikasi
document.addEventListener('click', e => {
  const acceptBtn = e.target.closest('.notif-follow-btn.accept');
  const rejectBtn = e.target.closest('.notif-follow-btn.reject');
  if (acceptBtn) {
    e.stopPropagation();
    acceptFollowRequest(acceptBtn.dataset.uid, acceptBtn.dataset.notif, acceptBtn);
  } else if (rejectBtn) {
    e.stopPropagation();
    rejectFollowRequest(rejectBtn.dataset.uid, rejectBtn.dataset.notif, rejectBtn);
  }
});

// ── FOLLOW REQUEST: Terima / Tolak (dipicu dari tombol di notifikasi) ──
// Struktur data terkait (lihat juga catatan di profile.html):
//   follow_requests/{myUid}/{fromUid}   → status permintaan follow
//   follows/{uid}/followers|following   → hubungan follow yang sudah aktif
//   chat_perm/{ownerUid}/{peerUid}      → izin ownerUid MEMULAI chat baru dgn peerUid
//     { type:'full' }              → boleh chat kapan saja (follow diterima)
//     { type:'blocked' }           → TIDAK BOLEH chat sama sekali (follow ditolak)
// Ini yang membuat "tidak ada orang yang bisa sembarangan chat orang lain":
// startChatWithFriend() di bagian Chat System akan cek node ini dulu
// sebelum mengizinkan percakapan baru dimulai.
async function acceptFollowRequest(fromUid, notifId, btnEl) {
  if (!currentUser || !fromUid) return;
  const myUid = currentUser.uid;
  const wrap = btnEl ? btnEl.closest('.notif-follow-actions') : null;
  if (wrap) wrap.querySelectorAll('button').forEach(b => b.disabled = true);
  try {
    // LANGKAH 1: tandai status permintaan follow jadi 'accepted' dulu (+
    // notifikasi) lewat update TERPISAH, dan tunggu sampai benar-benar
    // tersimpan di server. Ini penting: rule keamanan di node "follows/"
    // mensyaratkan follow_requests/.../status === 'accepted' sebelum
    // mengizinkan penulisan relasi follow. Kalau langkah ini digabung jadi
    // satu multi-path update() bersama langkah 2, sebagian server Firebase
    // bisa mengevaluasi rule tersebut memakai data SEBELUM update ini
    // (masih 'pending') sehingga langkah 2 gagal dengan PERMISSION_DENIED
    // meski rule-nya sendiri sudah benar. Memisahkan jadi 2 langkah
    // berurutan menghilangkan ambiguitas ini sama sekali.
    const step1 = {};
    step1['follow_requests/' + myUid + '/' + fromUid + '/status'] = 'accepted';
    step1['users/' + myUid + '/notifications/' + notifId + '/status'] = 'accepted';
    step1['users/' + myUid + '/notifications/' + notifId + '/read'] = true;
    await db.ref().update(step1);

    // LANGKAH 2: baru sekarang tulis relasi follow (kedua arah) & buka izin
    // chat penuh — pada titik ini status 'accepted' di langkah 1 SUDAH
    // pasti tersimpan di server, jadi rule "follows/" akan membacanya
    // dengan benar.
    const step2 = {};
    step2['follows/' + myUid + '/followers/' + fromUid] = true;
    step2['follows/' + fromUid + '/following/' + myUid] = true;
    step2['chat_perm/' + fromUid + '/' + myUid] = { type: 'full' };
    step2['chat_perm/' + myUid + '/' + fromUid] = { type: 'full' };
    await db.ref().update(step2);

    toast('✅ Follow request accepted');
  } catch(e) {
    console.error('Gagal menerima permintaan follow:', e);
    toast('❌ Failed to accept follow request');
    if (wrap) wrap.querySelectorAll('button').forEach(b => b.disabled = false);
  }
}

async function rejectFollowRequest(fromUid, notifId, btnEl) {
  if (!currentUser || !fromUid) return;
  const myUid = currentUser.uid;
  const wrap = btnEl ? btnEl.closest('.notif-follow-actions') : null;
  if (wrap) wrap.querySelectorAll('button').forEach(b => b.disabled = true);
  try {
    const now = Date.now();
    const updates = {};
    updates['follow_requests/' + myUid + '/' + fromUid + '/status'] = 'rejected';
    updates['users/' + myUid + '/notifications/' + notifId + '/status'] = 'rejected';
    updates['users/' + myUid + '/notifications/' + notifId + '/read'] = true;
    // Ditolak = requester TIDAK BOLEH kirim pesan sama sekali ke saya.
    // (Dulu ada "jatah 1x pesan" lewat type:'onetime', sekarang dihapus —
    // ditolak berarti diblokir total dari chat baru. Ini juga menimpa
    // kemungkinan chat_perm lama, mis. dari follow sebelumnya yang lalu
    // di-unfollow lalu request lagi, supaya status blokir ini selalu final.)
    updates['chat_perm/' + fromUid + '/' + myUid] = { type: 'blocked', blockedAt: now };
    await db.ref().update(updates);
    toast('Follow request declined');
  } catch(e) {
    console.error('Gagal menolak permintaan follow:', e);
    toast('❌ Failed to decline follow request');
    if (wrap) wrap.querySelectorAll('button').forEach(b => b.disabled = false);
  }
}

// Mulai listen notifikasi dari Firebase
function startNotifListeners() {
  if (!currentUser) return;

  // Remove old listeners
  _notifListeners.forEach(off => off());
  _notifListeners = [];

  const notifRef = db.ref('users/' + currentUser.uid + '/notifications');

  // Listen ke SEMUA notifikasi (read + unread) — render panel
  const allOff = notifRef.orderByChild('ts').limitToLast(50).on('value', snap => {
    const notifs = [];
    if (snap.exists()) {
      snap.forEach(child => { notifs.push({ _id: child.key, ...child.val() }); });
    }
    renderNotifications(notifs);

    // Hitung unread
    const unread = notifs.filter(n => !n.read).length
      + (shouldShowAppUpdateNotif() ? 1 : 0)
      + (shouldShowApkUpdateNotif() ? 1 : 0);
    updateNotifBadge(unread);
  });
  _notifListeners.push(() => notifRef.off('value', allOff));

  // ── Listen ask messages dari vibeprofile milik user ──
  const spShareId = localStorage.getItem('sp_share_id');
  if (spShareId) {
    const msgRef = db.ref('vibeprofiles/' + spShareId + '/messages');
    const msgOff = msgRef.orderByChild('ts').limitToLast(20).on('child_added', snap => {
      if (!snap.exists()) return;
      const msg = snap.val();
      // Cek apakah sudah dikonversi jadi notifikasi (berdasarkan ts)
      // If no 'notified' flag yet, push to notifications and mark
      if (!msg.notified) {
        // Mark to avoid duplicates
        db.ref('vibeprofiles/' + spShareId + '/messages/' + snap.key + '/notified').set(true).catch(() => {});
        // Push ke notifikasi user
        const notifId = 'ask_' + snap.key;
        db.ref('users/' + currentUser.uid + '/notifications/' + notifId).set({
          type: 'ask_message',
          text: msg.text || '',
          sid: spShareId,
          ts: msg.ts || Date.now(),
          read: false,
          fromName: 'Anonymous',
        }).catch(() => {});
      }
    });
    _notifListeners.push(() => msgRef.off('child_added', msgOff));
  }
}

// Helper: kirim notifikasi komentar ke owner playlist
// ════════════════════════════════════════════════════════════
//  SISTEM KOMENTAR LENGKAP: LIKE · REPLY · FOTO · NOTIFIKASI
// ════════════════════════════════════════════════════════════

// ── Image viewer fullscreen ──
// CATATAN PENTING (fix bug "tombol kembali malah keluar ke home"):
// Sebelumnya buka/tutup viewer ini murni visual (cuma toggle class "open"),
// TANPA pernah menambah riwayat (history) browser. Akibatnya saat user
// menekan tombol "kembali" (hardware back Android / gesture back), browser
// tidak punya riwayat APAPUN utk di-pop di dalam halaman ini — jadi yang
// ke-trigger adalah keluar dari seluruh aplikasi (balik ke home screen HP),
// bukan menutup viewer fotonya saja.
//
// Perbaikannya: setiap kali viewer dibuka, kita pushState() satu entri
// riwayat baru. Sekarang tombol "kembali" akan mengonsumsi entri itu lebih
// dulu (lewat event "popstate" di bawah) dan HANYA menutup viewer — user
// tetap berada di halaman Chat, tidak terlempar keluar aplikasi. Menutup
// viewer lewat tap foto/tombol X pun dibuat konsisten: memanggil
// history.back() supaya entri riwayat yang tadi ditambahkan ikut "dibuang
// rapi", bukan menumpuk sehingga user harus menekan kembali 2x nantinya.
let _imgViewerHistoryPushed = false;

function openImgViewer(src) {
  const v = document.getElementById('img-viewer');
  const img = document.getElementById('img-viewer-img');
  if (!v || !img) return;
  img.src = src;
  v.classList.add('open');
  document.body.style.overflow = 'hidden';
  history.pushState({ imgViewer: true }, '', location.href);
  _imgViewerHistoryPushed = true;
}

// Dipanggil saat user menutup viewer secara manual (tap foto/backdrop,
// tombol X, atau tombol Escape).
function closeImgViewer() {
  const v = document.getElementById('img-viewer');
  if (!v || !v.classList.contains('open')) return;
  if (_imgViewerHistoryPushed) {
    _imgViewerHistoryPushed = false;
    history.back(); // konsumsi entri riwayat → memicu "popstate" di bawah, yang benar2 menyembunyikan viewer
  } else {
    hideImgViewerVisual();
  }
}

// Bagian visual murni (sembunyikan overlay) — dipisah dari closeImgViewer()
// supaya bisa dipanggil dari event "popstate" tanpa memicu history.back() lagi.
function hideImgViewerVisual() {
  const v = document.getElementById('img-viewer');
  if (v) v.classList.remove('open');
  document.body.style.overflow = '';
}

// Menangkap tombol "kembali" (hardware/gesture back Android, maupun tombol
// back di browser). Kalau viewer sedang terbuka, cukup sembunyikan viewer­nya
// saja — JANGAN biarkan browser lanjut mundur ke luar aplikasi.
window.addEventListener('popstate', () => {
  const v = document.getElementById('img-viewer');
  if (v && v.classList.contains('open')) {
    _imgViewerHistoryPushed = false;
    hideImgViewerVisual();
  }
});
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeImgViewer(); });

// ── Compress image to base64 (max 800px, quality 0.72) ──
function compressImage(file, maxPx = 800, quality = 0.72) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = ev => {
      const img = new Image();
      img.onload = () => {
        let w = img.width, h = img.height;
        if (w > maxPx || h > maxPx) {
          if (w > h) { h = Math.round(h * maxPx / w); w = maxPx; }
          else { w = Math.round(w * maxPx / h); h = maxPx; }
        }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.onerror = reject;
      img.src = ev.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

// ── State foto komentar ──
let _pvCommentPhotoData = null;
let _cmModalPhotoData = null;

async function onPvCommentPhotoSelected(event) {
  const file = event.target.files[0];
  if (!file) return;
  try {
    const b64 = await compressImage(file);
    _pvCommentPhotoData = b64;
    const prev = document.getElementById('pv-comment-photo-preview');
    const row = document.getElementById('pv-comment-photo-preview-row');
    prev.src = b64; row.style.display = 'flex';
    const sendBtn = document.getElementById('pv-comment-send-btn');
    if (sendBtn) sendBtn.disabled = false;
  } catch(e) { toast(' Failed to load photo'); }
  event.target.value = '';
}
function removePvCommentPhoto() {
  _pvCommentPhotoData = null;
  document.getElementById('pv-comment-photo-preview-row').style.display = 'none';
  document.getElementById('pv-comment-photo-preview').src = '';
  const ta = document.getElementById('pv-comment-textarea');
  const sendBtn = document.getElementById('pv-comment-send-btn');
  if (sendBtn) sendBtn.disabled = !ta?.value.trim();
}

async function onCmModalPhotoSelected(event) {
  const file = event.target.files[0];
  if (!file) return;
  try {
    const b64 = await compressImage(file);
    _cmModalPhotoData = b64;
    const prev = document.getElementById('cm-modal-photo-preview');
    const row = document.getElementById('cm-modal-photo-preview-row');
    prev.src = b64; row.style.display = 'flex';
    const sendBtn = document.getElementById('cm-modal-send-btn');
    if (sendBtn) sendBtn.disabled = false;
  } catch(e) { toast(' Failed to load photo'); }
  event.target.value = '';
}
function removeCmModalPhoto() {
  _cmModalPhotoData = null;
  document.getElementById('cm-modal-photo-preview-row').style.display = 'none';
  document.getElementById('cm-modal-photo-preview').src = '';
  const ta = document.getElementById('cm-modal-textarea');
  const sendBtn = document.getElementById('cm-modal-send-btn');
  if (sendBtn) sendBtn.disabled = !ta?.value.trim();
}

// ── Komentar bisa menempel di DUA jenis target: playlist publik ATAU lagu
// saran di "Picked by Listeners". Supaya seluruh mesin komentar (like, reply,
// foto, notifikasi) bisa dipakai untuk keduanya tanpa duplikasi kode, key
// untuk lagu saran selalu diberi prefix "sugg__" (mis. "sugg__-Nx8k...").
// _commentRootPath() menerjemahkan key itu ke path Firebase yang benar, dan
// _commentTargetInfo() mengambil info pemilik + nama/judul untuk notifikasi.
const SUGG_COMMENT_PREFIX = 'sugg__';
function _isSuggComment(key){ return typeof key === 'string' && key.startsWith(SUGG_COMMENT_PREFIX); }
function _commentRootPath(key){
  return _isSuggComment(key)
    ? 'friendSuggestions/' + key.slice(SUGG_COMMENT_PREFIX.length)
    : 'public_playlists/' + key;
}
async function _commentTargetInfo(key){
  if (_isSuggComment(key)) {
    const suggKey = key.slice(SUGG_COMMENT_PREFIX.length);
    const snap = await db.ref('friendSuggestions/' + suggKey).get().catch(() => null);
    const v = snap?.val() || {};
    const name = v.title ? (v.title + (v.artist ? ' · ' + v.artist : '')) : 'a song';
    return { ownerUid: v.uid || null, name, targetType: 'song' };
  }
  const snap = await db.ref('public_playlists/' + key).get().catch(() => null);
  const v = snap?.val() || {};
  return { ownerUid: v.ownerUid || null, name: v.name || 'Playlist', targetType: 'playlist' };
}

// ── Kirim notifikasi ke owner playlist/lagu setelah komentar ──
async function sendCommentNotif(playlistKey, commentText) {
  if (!currentUser) return;
  try {
    const { ownerUid, name, targetType } = await _commentTargetInfo(playlistKey);
    if (!ownerUid || ownerUid === currentUser.uid) return;

    const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(() => null);
    const profile = profileSnap?.val() || {};
    const fromName = profile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const fromPhoto = profile.photoURL || profile.photoBase64 || currentUser.photoURL || '';

    const notif = {
      type: 'comment',
      fromUid: currentUser.uid,
      fromName,
      fromPhoto,
      playlistKey,
      playlistName: name,
      targetType,
      comment: (commentText || '').slice(0, 200),
      ts: Date.now(),
      read: false
    };
    db.ref('users/' + ownerUid + '/notifications').push(notif).catch(() => {});
  } catch(e) {
    console.warn('sendCommentNotif error:', e);
  }
}

// ── Kirim notifikasi like komentar ke pemilik komentar ──
async function sendCommentLikeNotif(playlistKey, commentOwnerUid, commenterName, commentText) {
  if (!currentUser || !commentOwnerUid) return;
  if (commentOwnerUid === currentUser.uid) return; // jangan notif diri sendiri

  try {
    const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(() => null);
    const profile = profileSnap?.val() || {};
    const fromName = profile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const fromPhoto = profile.photoURL || profile.photoBase64 || currentUser.photoURL || '';

    const { name: plName, targetType } = await _commentTargetInfo(playlistKey);

    const notif = {
      type: 'comment_like',
      fromUid: currentUser.uid,
      fromName,
      fromPhoto,
      playlistKey,
      playlistName: plName,
      targetType,
      comment: (commentText || '').slice(0, 100),
      ts: Date.now(),
      read: false
    };
    db.ref('users/' + commentOwnerUid + '/notifications').push(notif).catch(() => {});
  } catch(e) {
    console.warn('sendCommentLikeNotif error:', e);
  }
}

// ── Kirim notifikasi reply komentar ke pemilik komentar ──
async function sendReplyNotif(playlistKey, commentOwnerUid, replyText) {
  if (!currentUser || !commentOwnerUid) return;
  if (commentOwnerUid === currentUser.uid) return;

  try {
    const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(() => null);
    const profile = profileSnap?.val() || {};
    const fromName = profile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const fromPhoto = profile.photoURL || profile.photoBase64 || currentUser.photoURL || '';

    const { name: plName, targetType } = await _commentTargetInfo(playlistKey);

    const notif = {
      type: 'comment_reply',
      fromUid: currentUser.uid,
      fromName,
      fromPhoto,
      playlistKey,
      playlistName: plName,
      targetType,
      comment: (replyText || '').slice(0, 100),
      ts: Date.now(),
      read: false
    };
    db.ref('users/' + commentOwnerUid + '/notifications').push(notif).catch(() => {});
  } catch(e) {
    console.warn('sendReplyNotif error:', e);
  }
}

// ─── SISTEM KOMENTAR ─────────────────────────────────────
let _commentListener = null;
let _cmModalListener = null;
let _currentCommentKey = null;
let _replyPhotoDataMap = {}; // commentId → base64

// ── Toggle like komentar ──
async function toggleCommentLike(playlistKey, commentId, commentOwnerUid, commentText, btn) {
  if (!currentUser) { toast(' Please log in first'); return; }
  const likeRef = db.ref(_commentRootPath(playlistKey) + '/comments/' + commentId + '/likes/' + currentUser.uid);
  const isLiked = btn.classList.contains('liked');
  const countEl = btn.querySelector('.clk-count');

  if (isLiked) {
    await likeRef.remove().catch(() => {});
    btn.classList.remove('liked');
    btn.querySelector('svg').setAttribute('fill', 'none');
    if (countEl) countEl.textContent = Math.max(0, parseInt(countEl.textContent || '0') - 1) || '';
  } else {
    await likeRef.set(true).catch(() => {});
    btn.classList.add('liked');
    btn.querySelector('svg').setAttribute('fill', 'currentColor');
    if (countEl) countEl.textContent = (parseInt(countEl.textContent || '0') + 1);
    // Kirim notif ke pemilik komentar
    sendCommentLikeNotif(playlistKey, commentOwnerUid, '', commentText);
  }
}

// ── Toggle reply form ──
function toggleReplyForm(commentId, playlistKey, commentOwnerUid) {
  const existing = document.getElementById('reply-form-' + commentId);
  if (existing) { existing.remove(); _replyPhotoDataMap[commentId] = null; return; }

  const commentItem = document.getElementById('ci-' + commentId);
  if (!commentItem) return;

  // Get self avatar
  let selfAvatarHtml = '';
  if (currentUser) {
    db.ref('users/' + currentUser.uid + '/profile').get().then(snap => {
      const p = snap?.val() || {};
      const photo = p.photoURL || p.photoBase64 || currentUser.photoURL || '';
      const avatarEl = document.getElementById('reply-self-av-' + commentId);
      if (avatarEl) avatarEl.innerHTML = photo ? `<img src="${esc(photo)}" alt="">` : '';
    }).catch(() => {});
  }

  const form = document.createElement('div');
  form.className = 'reply-input-wrap';
  form.id = 'reply-form-' + commentId;
  form.innerHTML = `
    <div class="reply-avatar-self" id="reply-self-av-${esc(commentId)}">${selfAvatarHtml}</div>
    <div class="reply-box">
      <textarea class="reply-textarea" id="reply-ta-${esc(commentId)}" placeholder="Reply to comment..." rows="1"></textarea>
      <div id="reply-photo-prev-row-${esc(commentId)}" style="display:none;" class="reply-preview-row">
        <img id="reply-photo-prev-${esc(commentId)}" class="reply-preview-photo" src="" alt="">
        <button class="reply-preview-remove" onclick="removeReplyPhoto('${esc(commentId)}')" title="Remove photo"></button>
      </div>
      <div class="reply-bottom-row">
        <div style="display:flex;align-items:center;gap:6px;">
          <button class="reply-photo-btn" onclick="document.getElementById('reply-photo-input-${esc(commentId)}').click()" title="Share photo">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>
            Photo
          </button>
          <input type="file" id="reply-photo-input-${esc(commentId)}" accept="image/*" style="display:none;" onchange="onReplyPhotoSelected(event,'${esc(commentId)}')">
          <button class="reply-cancel-btn" onclick="toggleReplyForm('${esc(commentId)}','${esc(playlistKey)}','${esc(commentOwnerUid)}')">Cancel</button>
        </div>
        <button class="reply-send-btn" id="reply-send-${esc(commentId)}" disabled>
          <svg viewBox="0 0 24 24" fill="currentColor" width="11" height="11"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>
          Reply
        </button>
      </div>
    </div>
  `;
  commentItem.after(form);

  const ta = document.getElementById('reply-ta-' + commentId);
  const sendBtn = document.getElementById('reply-send-' + commentId);
  ta.addEventListener('input', () => {
    ta.style.height = 'auto';
    ta.style.height = Math.min(ta.scrollHeight, 80) + 'px';
    sendBtn.disabled = !ta.value.trim() && !_replyPhotoDataMap[commentId];
  });
  sendBtn.addEventListener('click', () => submitReply(playlistKey, commentId, commentOwnerUid, ta, sendBtn));
  ta.addEventListener('keydown', e => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submitReply(playlistKey, commentId, commentOwnerUid, ta, sendBtn); }
  });
  setTimeout(() => ta.focus(), 100);
}

async function onReplyPhotoSelected(event, commentId) {
  const file = event.target.files[0];
  if (!file) return;
  try {
    const b64 = await compressImage(file);
    _replyPhotoDataMap[commentId] = b64;
    const prev = document.getElementById('reply-photo-prev-' + commentId);
    const row = document.getElementById('reply-photo-prev-row-' + commentId);
    if (prev) prev.src = b64;
    if (row) row.style.display = 'flex';
    const sendBtn = document.getElementById('reply-send-' + commentId);
    if (sendBtn) sendBtn.disabled = false;
  } catch(e) { toast(' Failed to load photo'); }
  event.target.value = '';
}
function removeReplyPhoto(commentId) {
  _replyPhotoDataMap[commentId] = null;
  const row = document.getElementById('reply-photo-prev-row-' + commentId);
  const prev = document.getElementById('reply-photo-prev-' + commentId);
  if (row) row.style.display = 'none';
  if (prev) prev.src = '';
  const ta = document.getElementById('reply-ta-' + commentId);
  const sendBtn = document.getElementById('reply-send-' + commentId);
  if (sendBtn) sendBtn.disabled = !ta?.value.trim();
}

// ── Submit balasan ──
async function submitReply(playlistKey, commentId, commentOwnerUid, textareaEl, sendBtn) {
  const text = textareaEl.value.trim();
  const photoData = _replyPhotoDataMap[commentId] || null;
  if (!text && !photoData) return;
  if (!currentUser) { toast(' Please log in first'); return; }
  sendBtn.disabled = true;
  try {
    const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(() => null);
    const profile = profileSnap?.val() || {};
    const name = profile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const photoURL = profile.photoURL || profile.photoBase64 || currentUser.photoURL || '';
    const reply = { uid: currentUser.uid, name, photoURL, text: text || '', ts: Date.now() };
    if (photoData) reply.photoData = photoData;
    await db.ref(_commentRootPath(playlistKey) + '/comments/' + commentId + '/replies').push(reply);
    textareaEl.value = '';
    textareaEl.style.height = 'auto';
    _replyPhotoDataMap[commentId] = null;
    // Remove reply form
    const form = document.getElementById('reply-form-' + commentId);
    if (form) form.remove();
    toast('↩ Reply sent!');
    await sendReplyNotif(playlistKey, commentOwnerUid, text);
  } catch(e) {
    toast(' Failed to send: ' + e.message);
    sendBtn.disabled = false;
  }
}

// ── Render satu item komentar ──
function buildCommentItem(c, playlistKey, isModal) {
  const isOwn = currentUser && c.uid === currentUser.uid;
  const item = document.createElement('div');
  item.className = 'comment-item';
  item.id = 'ci-' + c._id;

  const photo = c.photoURL
    ? `<img src="${esc(c.photoURL)}" alt="" onerror="this.parentElement.innerHTML=''">`
    : '';

  // Photo dalam komentar
  const commentPhotoHtml = c.photoData
    ? `<img src="${esc(c.photoData)}" class="comment-photo-img" alt="photo" onclick="openImgViewer('${esc(c.photoData)}')" loading="lazy">`
    : '';

  // Likes
  const likeCount = c.likes ? Object.keys(c.likes).length : 0;
  const iLikedComment = currentUser && c.likes && c.likes[currentUser.uid];

  // Replies
  let repliesHtml = '';
  if (c.replies) {
    const replyArr = Object.entries(c.replies).map(([k, v]) => ({ _id: k, ...v })).sort((a, b) => a.ts - b.ts);
    repliesHtml = `<div class="comment-replies">` + replyArr.map(r => {
      const isOwnReply = currentUser && r.uid === currentUser.uid;
      const rPhoto = r.photoURL
        ? `<img src="${esc(r.photoURL)}" alt="" onerror="this.parentElement.innerHTML=''">`
        : '';
      const rImgHtml = r.photoData
        ? `<img src="${esc(r.photoData)}" class="comment-reply-photo" alt="photo" onclick="openImgViewer('${esc(r.photoData)}')" loading="lazy">`
        : '';
      return `
        <div class="comment-reply-item">
          <div class="comment-reply-avatar">${rPhoto}</div>
          <div class="comment-reply-bubble">
            <div class="comment-reply-meta">
              <span class="comment-reply-name">${esc(r.name || 'Anonymous')}</span>
              <span class="comment-reply-time">${timeAgo(r.ts || 0)}</span>
            </div>
            ${r.text ? `<div class="comment-reply-text">${esc(r.text)}</div>` : ''}
            ${rImgHtml}
            <div class="comment-reply-actions">
              ${isOwnReply ? `<button class="comment-reply-del-btn" title="Delete" onclick="deleteReply('${esc(playlistKey)}','${esc(c._id)}','${esc(r._id)}')"> Delete</button>` : ''}
            </div>
          </div>
        </div>`;
    }).join('') + `</div>`;
  }

  item.innerHTML = `
    <div class="comment-avatar">${photo}</div>
    <div class="comment-bubble">
      <div class="comment-meta">
        <span class="comment-name">${esc(c.name || 'Anonymous')}</span>
        <span class="comment-time">${timeAgo(c.ts || 0)}</span>
      </div>
      ${c.text ? `<div class="comment-text">${esc(c.text)}</div>` : ''}
      ${commentPhotoHtml}
      <div class="comment-actions">
        <button class="comment-like-btn ${iLikedComment ? 'liked' : ''}"
          onclick="toggleCommentLike('${esc(playlistKey)}','${esc(c._id)}','${esc(c.uid)}',${JSON.stringify((c.text||'').slice(0,80))},this)">
          <svg viewBox="0 0 24 24" fill="${iLikedComment ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2.5">
            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
          </svg>
          <span class="clk-count">${likeCount || ''}</span>
        </button>
        <button class="comment-reply-btn" onclick="toggleReplyForm('${esc(c._id)}','${esc(playlistKey)}','${esc(c.uid)}')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M9 17l-5-5 5-5"/><path d="M4 12h11a4 4 0 0 1 0 8h-1"/></svg>
          Reply
        </button>
      </div>
      ${repliesHtml}
    </div>
    ${isOwn ? `<button class="comment-del-btn" title="Delete" onclick="deleteComment('${esc(playlistKey)}','${esc(c._id)}','${isModal ? 'modal' : 'pv'}')"></button>` : ''}
  `;
  return item;
}

// ── Render daftar komentar ke container tertentu ──
function renderCommentList(container, comments, playlistKey, isModal) {
  if (!comments || !comments.length) {
    container.innerHTML = `<div class="comment-empty"><span></span>No comments yet.<br>Be the first!</div>`;
    return;
  }
  container.innerHTML = '';
  comments.forEach(c => container.appendChild(buildCommentItem(c, playlistKey, isModal)));
}

// ── Ambil & render komentar, pasang listener real-time ──
function listenComments(playlistKey, listEl, offCallback) {
  const ref = db.ref(_commentRootPath(playlistKey) + '/comments').orderByChild('ts').limitToLast(100);
  const handler = ref.on('value', snap => {
    const comments = [];
    if (snap.exists()) {
      snap.forEach(child => { comments.push({ _id: child.key, ...child.val() }); });
    }
    const countEl = document.querySelector('.comment-count-' + playlistKey);
    if (countEl) countEl.textContent = comments.length ? ` ${comments.length}` : '';
    renderCommentList(listEl, comments, playlistKey, offCallback === 'modal');
  });
  return () => ref.off('value', handler);
}

// ── Kirim komentar (dengan foto opsional) ──
async function submitComment(playlistKey, textareaEl, sendBtn, photoDataRef) {
  const text = textareaEl.value.trim();
  const photoData = (typeof photoDataRef === 'function') ? photoDataRef() : photoDataRef;
  if (!text && !photoData) return;
  if (!currentUser) { toast(' Please log in first'); return; }
  sendBtn.disabled = true;
  try {
    const profileSnap = await db.ref('users/' + currentUser.uid + '/profile').get().catch(() => null);
    const profile = profileSnap?.val() || {};
    const name = profile.displayName || currentUser.displayName || (currentUser.email ? currentUser.email.split('@')[0] : 'User');
    const photoURL = profile.photoURL || profile.photoBase64 || currentUser.photoURL || '';
    const comment = { uid: currentUser.uid, name, photoURL, text: text || '', ts: Date.now() };
    if (photoData) comment.photoData = photoData;
    await db.ref(_commentRootPath(playlistKey) + '/comments').push(comment);
    textareaEl.value = '';
    textareaEl.style.height = 'auto';
    sendBtn.disabled = true;
    if (text) await sendCommentNotif(playlistKey, text);
    toast(' Comment sent!');
  } catch(e) {
    toast(' Failed to send: ' + e.message);
    sendBtn.disabled = false;
  }
}

// ── Delete comment ──
async function deleteComment(playlistKey, commentId, source) {
  if (!confirm('Delete this comment?')) return;
  try {
    await db.ref(_commentRootPath(playlistKey) + '/comments/' + commentId).remove();
    toast(' Comment deleted');
  } catch(e) { toast(' Delete failed: ' + e.message); }
}

// ── Delete reply ──
async function deleteReply(playlistKey, commentId, replyId) {
  if (!confirm('Delete this reply?')) return;
  try {
    await db.ref(_commentRootPath(playlistKey) + '/comments/' + commentId + '/replies/' + replyId).remove();
    toast(' Reply deleted');
  } catch(e) { toast(' Delete failed: ' + e.message); }
}

// ── Setup comment input (auto-resize + enable send) ──
function setupCommentInput(textareaEl, sendBtn, playlistKey, isModal, getPhotoData, clearPhotoData) {
  textareaEl.addEventListener('input', () => {
    textareaEl.style.height = 'auto';
    textareaEl.style.height = Math.min(textareaEl.scrollHeight, 100) + 'px';
    sendBtn.disabled = !textareaEl.value.trim() && !getPhotoData?.();
  });
  sendBtn.addEventListener('click', async () => {
    const pd = getPhotoData?.() || null;
    await submitComment(playlistKey, textareaEl, sendBtn, pd);
    clearPhotoData?.();
  });
  textareaEl.addEventListener('keydown', e => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      const pd = getPhotoData?.() || null;
      submitComment(playlistKey, textareaEl, sendBtn, pd).then(() => clearPhotoData?.());
    }
  });
}

// ── Tampilkan komentar di playlist-view ──
function showPvComments(playlistKey) {
  if (_commentListener) { _commentListener(); _commentListener = null; }

  const section = document.getElementById('pv-comment-section');
  const listEl = document.getElementById('pv-comment-list');
  const textarea = document.getElementById('pv-comment-textarea');
  const sendBtn = document.getElementById('pv-comment-send-btn');
  const selfAvatar = document.getElementById('pv-comment-self-avatar');
  if (!section) return;

  section.style.display = 'block';
  listEl.innerHTML = '<div class="comment-loading">Loading comments...</div>';
  textarea.value = '';
  sendBtn.disabled = true;
  removePvCommentPhoto();

  if (currentUser) {
    db.ref('users/' + currentUser.uid + '/profile').get().then(snap => {
      const p = snap?.val() || {};
      const photo = p.photoURL || p.photoBase64 || currentUser.photoURL || '';
      selfAvatar.innerHTML = photo ? `<img src="${esc(photo)}" alt="">` : '';
    }).catch(() => {});
  }

  textarea.removeEventListener('input', textarea._inputHandler);
  sendBtn.replaceWith(sendBtn.cloneNode(true));
  const newSendBtn = document.getElementById('pv-comment-send-btn');
  const clonedTa = textarea.cloneNode(true);
  textarea.replaceWith(clonedTa);
  const newTa = document.getElementById('pv-comment-textarea');

  setupCommentInput(
    newTa, newSendBtn, playlistKey, false,
    () => _pvCommentPhotoData,
    () => removePvCommentPhoto()
  );

  _commentListener = listenComments(playlistKey, listEl, 'pv');
}

function hidePvComments() {
  if (_commentListener) { _commentListener(); _commentListener = null; }
  const section = document.getElementById('pv-comment-section');
  if (section) section.style.display = 'none';
}

// ── Comment modal from home ──
function openCommentModal(e, playlistKey, playlistName) {
  e.stopPropagation();
  if (!currentUser) { toast(' Please log in to comment'); return; }

  _currentCommentKey = playlistKey;
  const modal = document.getElementById('comment-modal');
  const title = document.getElementById('cm-modal-title');
  const listEl = document.getElementById('cm-modal-list');
  const textarea = document.getElementById('cm-modal-textarea');
  const sendBtn = document.getElementById('cm-modal-send-btn');
  const selfAvatar = document.getElementById('cm-modal-self-avatar');

  title.textContent = ' ' + playlistName;
  listEl.innerHTML = '<div class="comment-loading">Loading comments...</div>';
  textarea.value = '';
  sendBtn.disabled = true;
  removeCmModalPhoto();

  modal.classList.add('open');
  document.body.style.overflow = 'hidden';

  db.ref('users/' + currentUser.uid + '/profile').get().then(snap => {
    const p = snap?.val() || {};
    const photo = p.photoURL || p.photoBase64 || currentUser.photoURL || '';
    selfAvatar.innerHTML = photo ? `<img src="${esc(photo)}" alt="">` : '';
  }).catch(() => {});

  const newSendBtn = sendBtn.cloneNode(true);
  sendBtn.replaceWith(newSendBtn);
  const newTextarea = textarea.cloneNode(true);
  textarea.replaceWith(newTextarea);

  setupCommentInput(
    newTextarea, newSendBtn, playlistKey, true,
    () => _cmModalPhotoData,
    () => removeCmModalPhoto()
  );

  if (_cmModalListener) { _cmModalListener(); _cmModalListener = null; }
  _cmModalListener = listenComments(playlistKey, listEl, 'modal');

  setTimeout(() => newTextarea.focus(), 300);
}

function closeCommentModal() {
  if (_cmModalListener) { _cmModalListener(); _cmModalListener = null; }
  _currentCommentKey = null;
  const modal = document.getElementById('comment-modal');
  modal.classList.remove('open');
  document.body.style.overflow = '';
  removeCmModalPhoto();
}

// ── Hook to openPublicPlaylist ──
const _origOpenPublicPlaylist = openPublicPlaylist;
openPublicPlaylist = async function(pl) {
  await _origOpenPublicPlaylist(pl);
  showPvComments(pl.key);
};

// ── Hook to backFromPlaylist ──
const _origBackFromPlaylist = backFromPlaylist;
backFromPlaylist = function() {
  hidePvComments();
  _origBackFromPlaylist();
};

// Hook ke showApp untuk mulai listener setelah login
const _origShowAppNotif = showApp;
showApp = function(user) {
  _origShowAppNotif(user);
  setTimeout(() => startNotifListeners(), 1500);
};

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('./sw.js').catch(console.error);
}

// ══════════════════════════════════════════════════════════
// CEK UPDATE APK (untuk distribusi APK langsung / sideload, bukan Play Store)
// ══════════════════════════════════════════════════════════
// Cara kerja: app baca node "app_update/android" di Firebase Realtime
// Database (project Firebase yang sama dengan yang sudah dipakai app ini),
// bandingkan versionCode di sana dengan versionCode app yang sedang
// berjalan (didapat dari plugin native @capacitor/app). Kalau ada yang
// lebih baru, tampilkan modal dengan tombol "Update Sekarang" yang membuka
// link APK di browser luar (biar proses download & install ditangani OS).
//
// Setup yang perlu dilakukan SEKALI di sisi kamu:
// 1) npm install @capacitor/app          (kalau belum ada)
//    npx cap sync android
// 2) Di Firebase Console → Realtime Database, buat node:
//      app_update/
//        android/
//          versionCode: 2            // integer, samakan/lebih tinggi dari
//                                     // versionCode di android/app/build.gradle
//          versionName: "1.0.1"      // teks bebas, cuma ditampilkan ke user
//          apkUrl: "https://.../vibexa-1.0.1.apk"   // link download APK
//          changelog: "Perbaikan bug offline mode"   // opsional
//          forceUpdate: false         // true = user wajib update (tombol
//                                     // "Nanti Saja" disembunyikan)
// 3) Setiap kali rilis APK baru: build APK, upload ke tempat hosting APK-nya
//    (Firebase Storage / GitHub Releases / server sendiri), lalu update
//    node app_update/android di atas (versionCode HARUS dinaikkan, samakan
//    dengan versionCode baru di android/app/build.gradle).
async function checkForAppUpdate() {
  try {
    // Fitur ini cuma relevan di app native (APK), bukan saat dibuka lewat
    // browser biasa — dan butuh koneksi internet untuk baca Firebase & plugin App.
    const isNative = window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform();
    if (!isNative || !navigator.onLine) {
      return;
    }
    if (!window.Capacitor.Plugins || !window.Capacitor.Plugins.App) {
      console.warn('Plugin @capacitor/app belum terpasang — cek update dilewati. Jalankan: npm install @capacitor/app && npx cap sync');
      return;
    }
    if (!db) return; // Firebase belum siap (mis. baru masuk mode offline)

    const info = await window.Capacitor.Plugins.App.getInfo();
    const currentVersionCode = parseInt(info.build, 10) || 0;

    const snap = await db.ref('app_update/android').once('value');
    const cfg = snap.val();

    if (!cfg || !cfg.versionCode || !cfg.apkUrl) return;

    if (cfg.versionCode > currentVersionCode) {
      // Simpan cfg supaya kartu "Update Tersedia" ikut muncul pinned di
      // panel notifikasi (bell) — bukan cuma modal sekali muncul.
      _pendingApkUpdate = cfg;
      refreshApkUpdateNotifUI();
      showAppUpdateModal(cfg);
    } else {
      // Versi app sekarang sudah sama/lebih baru dari Firebase — bersihkan
      // kartu pinned lama (mis. setelah user benar-benar update APK-nya).
      if (_pendingApkUpdate) {
        _pendingApkUpdate = null;
        refreshApkUpdateNotifUI();
      }
    }
  } catch (e) {
    console.warn('Gagal cek update APK:', e);
  }
}

function showAppUpdateModal(cfg) {
  // Jangan tampilkan berkali-kali kalau modal sudah ada di layar
  if (document.getElementById('vbx-update-modal')) return;
  // Jangan ganggu user berkali-kali di sesi yang sama untuk versi yang sama
  // kalau dia sudah menekan "Nanti Saja" (kecuali forceUpdate = true)
  const dismissedVersion = sessionStorage.getItem('vbx_update_dismissed');
  if (!cfg.forceUpdate && dismissedVersion === String(cfg.versionCode)) return;

  const overlay = document.createElement('div');
  overlay.id = 'vbx-update-modal';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:99999;display:flex;align-items:center;justify-content:center;padding:24px;';

  const box = document.createElement('div');
  box.style.cssText = 'background:#171717;color:#fff;border-radius:16px;max-width:360px;width:100%;padding:24px;text-align:center;font-family:inherit;box-shadow:0 20px 60px rgba(0,0,0,.5);';

  const changelogHtml = cfg.changelog
    ? `<p style="margin:0 0 20px;font-size:14px;line-height:1.5;color:#c9c9c9;white-space:pre-line;">${String(cfg.changelog).replace(/</g,'&lt;')}</p>`
    : '';

  box.innerHTML = `
    <div style="font-size:40px;margin-bottom:8px;">🚀</div>
    <h2 style="margin:0 0 8px;font-size:18px;">Update Tersedia</h2>
    <p style="margin:0 0 16px;font-size:13px;color:#9a9a9a;">Versi baru ${cfg.versionName ? cfg.versionName : ''} sudah bisa diunduh.</p>
    ${changelogHtml}
    <button id="vbx-update-btn" style="width:100%;padding:12px;border:none;border-radius:999px;background:#1DB954;color:#000;font-weight:700;font-size:14px;cursor:pointer;margin-bottom:10px;">Update Sekarang</button>
    ${cfg.forceUpdate ? '' : '<button id="vbx-update-later-btn" style="width:100%;padding:10px;border:none;background:transparent;color:#9a9a9a;font-size:13px;cursor:pointer;">Nanti Saja</button>'}
  `;

  overlay.appendChild(box);
  document.body.appendChild(overlay);

  document.getElementById('vbx-update-btn').addEventListener('click', () => {
    // Buka link APK di browser eksternal — biarkan OS Android yang menangani
    // proses download & prompt install (termasuk minta izin "install dari
    // sumber tidak dikenal" kalau belum pernah diizinkan sebelumnya).
    window.open(cfg.apkUrl, '_system');
  });

  const laterBtn = document.getElementById('vbx-update-later-btn');
  if (laterBtn) {
    laterBtn.addEventListener('click', () => {
      try { sessionStorage.setItem('vbx_update_dismissed', String(cfg.versionCode)); } catch (e) {}
      overlay.remove();
    });
  }
}

// Cek update sekali saat app dibuka (beri jeda dikit supaya Firebase & auth
// sempat siap dulu), lalu ulangi tiap kali app kembali ke foreground.
setTimeout(checkForAppUpdate, 2000);
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') checkForAppUpdate();
});

// ══════════════════════════════════════════════════════════
// PWA INSTALL — dipicu dari tombol "Download" di notifikasi lonceng
// ══════════════════════════════════════════════════════════
let _deferredInstallPrompt = null;

// Browser (Chrome/Edge/Android) menyiapkan prompt instalasi native di sini.
// Kita simpan eventnya supaya bisa dipanggil manual saat user menekan tombol Download.
//
// Catatan penting: browser Chromium TIDAK akan fire event ini kalau app sedang
// terpasang. Jadi kalau event ini fire lagi padahal kita sebelumnya sudah
// menandai 'vibexa_pwa_installed', itu bukti kuat user baru saja meng-uninstall
// app-nya — reset flag itu supaya notifikasi "Download" muncul lagi di bell.
window.addEventListener('beforeinstallprompt', (e) => {
  e.preventDefault();
  _deferredInstallPrompt = e;

  const wasMarkedInstalled = localStorage.getItem('vibexa_pwa_installed') === '1';
  if (wasMarkedInstalled) {
    localStorage.removeItem('vibexa_pwa_installed');
    localStorage.removeItem('vibexa_pwa_dismissed_version'); // abaikan "Nanti" lama, situasinya sudah beda
    renderNotifications(_notifCache);
    refreshAppInstallBadge();
  }
});

// Kalau user berhasil install (lewat prompt native ATAU cara manual browser),
// tandai supaya notifikasi "Download" tidak muncul lagi.
window.addEventListener('appinstalled', () => {
  _deferredInstallPrompt = null;
  localStorage.setItem('vibexa_pwa_installed', '1');
  renderNotifications(_notifCache);
  refreshAppInstallBadge();
});

function refreshAppInstallBadge() {
  const unread = (_notifCache || []).filter(n => !n.read).length
    + (shouldShowAppUpdateNotif() ? 1 : 0)
    + (shouldShowApkUpdateNotif() ? 1 : 0);
  updateNotifBadge(unread);
}

// Cek status instalasi yang SEBENARNYA lewat API resmi browser
// (navigator.getInstalledRelatedApps) — ini API yang sama yang dipakai Chrome
// untuk menampilkan chip "Open in app" di address bar. Jauh lebih akurat
// daripada cuma mengandalkan localStorage kita sendiri, karena localStorage
// bisa tidak sinkron kalau install/uninstall terjadi lewat cara lain.
async function checkRealPwaInstallStatus() {
  if (!('getInstalledRelatedApps' in navigator)) return null; // browser tidak mendukung API ini
  try {
    const related = await navigator.getInstalledRelatedApps();
    return related && related.length > 0;
  } catch (err) {
    console.error('getInstalledRelatedApps gagal:', err);
    return null;
  }
}

// Sinkronkan localStorage dengan status asli begitu halaman dibuka,
// supaya notifikasi "Download" di bell selalu akurat tanpa perlu user
// menekan tombolnya dulu.
(async function syncPwaInstallStatusOnLoad() {
  const reallyInstalled = await checkRealPwaInstallStatus();
  if (reallyInstalled === null) return; // API tidak tersedia, jangan ubah apa-apa
  const wasMarked = localStorage.getItem('vibexa_pwa_installed') === '1';
  if (reallyInstalled && !wasMarked) {
    localStorage.setItem('vibexa_pwa_installed', '1');
  } else if (!reallyInstalled && wasMarked) {
    localStorage.removeItem('vibexa_pwa_installed');
    localStorage.removeItem('vibexa_pwa_dismissed_version');
  } else {
    return; // tidak ada perubahan, tidak perlu render ulang
  }
  renderNotifications(_notifCache);
  refreshAppInstallBadge();
})();

// Dipanggil dari tombol "Download" pada notifikasi lonceng
async function downloadAppNow() {
  if (_deferredInstallPrompt) {
    try {
      _deferredInstallPrompt.prompt();
      const choice = await _deferredInstallPrompt.userChoice;
      _deferredInstallPrompt = null;
      if (choice && choice.outcome === 'accepted') {
        localStorage.setItem('vibexa_pwa_installed', '1');
      }
      renderNotifications(_notifCache);
      refreshAppInstallBadge();
      return;
    } catch (err) {
      console.error('PWA install prompt gagal:', err);
    }
  }

  // Cek ulang status instalasi asli sebelum menyimpulkan "tidak didukung" —
  // ini mencegah pesan salah kaprah seperti yang terjadi waktu app sudah
  // terpasang tapi localStorage kita belum sinkron.
  const reallyInstalled = await checkRealPwaInstallStatus();
  if (reallyInstalled === true) {
    localStorage.setItem('vibexa_pwa_installed', '1');
    renderNotifications(_notifCache);
    refreshAppInstallBadge();
    toast('Vibexa is already installed on this device.', 6000);
    return;
  }

  // Kalau app sudah terpasang sebelumnya di browser ini, Chrome/Edge/dll
  // sengaja tidak akan fire beforeinstallprompt lagi — jadi ini BUKAN berarti
  // browsernya tidak didukung, tapi appnya memang sudah diinstall.
  if (isPwaInstalled()) {
    toast('Vibexa is already installed on this device.', 6000);
    return;
  }
  // Browser benar-benar tidak mendukung prompt install otomatis

  // (mis. Opera, Firefox, Safari) — tampilkan pesan singkat, bukan langkah manual.
  toast('This app can only be downloaded on Chrome. Not yet supported in this browser.', 6000);
}

// ══════════════════════════════════════════════════════════
// SONG FINDER — Video song recognition (AudD API)
// ══════════════════════════════════════════════════════════
const AUDD_API_TOKEN = 'test';
const FINDER_HISTORY_KEY = 'vibexa_finder_history';
let _finderFile = null;
let _finderResult = null;
let _finderInitialized = false;

function initFinderView() {
  if (_finderInitialized) { renderFinderHistory(); return; }
  _finderInitialized = true;

  const dropZone = document.getElementById('finder-drop-zone');
  const fileInput = document.getElementById('finder-file-input');

  // Drag & drop
  dropZone.addEventListener('dragover', e => { e.preventDefault(); dropZone.classList.add('drag-over'); });
  dropZone.addEventListener('dragleave', () => dropZone.classList.remove('drag-over'));
  dropZone.addEventListener('drop', e => {
    e.preventDefault();
    dropZone.classList.remove('drag-over');
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('video/')) setFinderFile(file);
    else toast(' Select a valid video file');
  });

  fileInput.addEventListener('change', () => {
    if (fileInput.files[0]) setFinderFile(fileInput.files[0]);
  });

  renderFinderHistory();
}

function setFinderFile(file) {
  _finderFile = file;
  const previewWrap = document.getElementById('finder-preview-wrap');
  const previewVideo = document.getElementById('finder-preview-video');
  const previewName = document.getElementById('finder-preview-name');
  const dropZone = document.getElementById('finder-drop-zone');
  const searchBtn = document.getElementById('finder-search-btn');

  const url = URL.createObjectURL(file);
  previewVideo.src = url;
  previewName.textContent = file.name;
  previewWrap.classList.add('visible');
  dropZone.classList.add('has-file');
  searchBtn.disabled = false;

  // Hide previous results
  document.getElementById('finder-result').classList.remove('show');
  document.getElementById('finder-no-result').classList.remove('show');
  document.getElementById('finder-ripple-wrap').classList.remove('show');
  toast(' Video ready! Click "Identify Song" to get started');
}

function clearFinderFile(e) {
  if (e) e.stopPropagation();
  _finderFile = null;
  const previewWrap = document.getElementById('finder-preview-wrap');
  const previewVideo = document.getElementById('finder-preview-video');
  const dropZone = document.getElementById('finder-drop-zone');
  const searchBtn = document.getElementById('finder-search-btn');

  if (previewVideo.src) { URL.revokeObjectURL(previewVideo.src); previewVideo.src = ''; }
  previewWrap.classList.remove('visible');
  dropZone.classList.remove('has-file');
  searchBtn.disabled = true;
  document.getElementById('finder-file-input').value = '';
}

// Extract audio blob from video using Web Audio API + MediaRecorder
async function extractAudioFromVideo(videoFile) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(videoFile);
    const video = document.createElement('video');
    video.src = url;
    video.crossOrigin = 'anonymous';
    video.preload = 'auto';

    video.addEventListener('canplaythrough', () => {
      try {
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const source = audioCtx.createMediaElementSource(video);
        const dest = audioCtx.createMediaStreamDestination();
        source.connect(dest);

        const duration = Math.min(video.duration || 20, 20) * 1000;
        const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
          ? 'audio/webm;codecs=opus'
          : MediaRecorder.isTypeSupported('audio/webm')
          ? 'audio/webm'
          : 'audio/ogg';

        const recorder = new MediaRecorder(dest.stream, { mimeType });
        const chunks = [];

        recorder.ondataavailable = e => { if (e.data.size > 0) chunks.push(e.data); };
        recorder.onstop = () => {
          URL.revokeObjectURL(url);
          audioCtx.close();
          const ext = mimeType.includes('ogg') ? 'ogg' : 'webm';
          const blob = new Blob(chunks, { type: mimeType });
          blob._filename = 'audio.' + ext;
          resolve(blob);
        };
        recorder.onerror = (e) => {
          URL.revokeObjectURL(url);
          reject(new Error('Audio recording failed: ' + e.error));
        };

        recorder.start();
        video.play().catch(reject);
        setTimeout(() => {
          recorder.stop();
          video.pause();
        }, duration);
      } catch(err) {
        URL.revokeObjectURL(url);
        reject(err);
      }
    }, { once: true });

    video.addEventListener('error', () => {
      URL.revokeObjectURL(url);
      reject(new Error('This video format is not supported by this browser'));
    }, { once: true });

    video.load();
  });
}

function audioBufferToWav(buffer) {
  const numChannels = 1;
  const sampleRate = buffer.sampleRate;
  const format = 3; // PCM float32
  const bitDepth = 32;
  const data = buffer.getChannelData(0);
  const dataByteLength = data.length * 4;
  const totalLength = 44 + dataByteLength;
  const ab = new ArrayBuffer(totalLength);
  const view = new DataView(ab);

  function writeStr(offset, str) { for(let i=0;i<str.length;i++) view.setUint8(offset+i, str.charCodeAt(i)); }
  writeStr(0, 'RIFF');
  view.setUint32(4, 36 + dataByteLength, true);
  writeStr(8, 'WAVE');
  writeStr(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, format, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * numChannels * (bitDepth/8), true);
  view.setUint16(32, numChannels * (bitDepth/8), true);
  view.setUint16(34, bitDepth, true);
  writeStr(36, 'data');
  view.setUint32(40, dataByteLength, true);
  let offset = 44;
  for (let i = 0; i < data.length; i++) { view.setFloat32(offset, data[i], true); offset += 4; }
  return new Blob([ab], { type: 'audio/wav' });
}

function setFinderStatus(text, sub, emoji) {
  document.getElementById('finder-status-text').textContent = text;
  document.getElementById('finder-status-sub').textContent = sub;
  if (emoji) document.getElementById('finder-ripple-emoji').textContent = emoji;
}

async function startFindSong() {
  if (!_finderFile) { toast(' Select a video first'); return; }

  const searchBtn = document.getElementById('finder-search-btn');
  const rippleWrap = document.getElementById('finder-ripple-wrap');
  const result = document.getElementById('finder-result');
  const noResult = document.getElementById('finder-no-result');

  searchBtn.disabled = true;
  result.classList.remove('show');
  noResult.classList.remove('show');
  rippleWrap.classList.add('show');
  setFinderStatus('Listening to your music...', 'Extracting audio from video', '');

  try {
    // Step 1: Extract audio
    setFinderStatus('Listening to your music...', 'Extracting audio from video...', '');
    const audioBlob = await extractAudioFromVideo(_finderFile);

    // Step 2: Send to AudD
    setFinderStatus('Identifying song...', 'Matching with music database', '');
    const fileName = audioBlob._filename || 'audio.webm';
    const formData = new FormData();
    formData.append('file', audioBlob, fileName);
    formData.append('return', 'apple_music,spotify');
    formData.append('api_token', AUDD_API_TOKEN);

    const response = await fetch('https://api.audd.io/', { method: 'POST', body: formData });
    const data = await response.json();

    rippleWrap.classList.remove('show');

    console.log('AudD response:', JSON.stringify(data));

    if (data.status === 'success' && data.result) {
      const song = data.result;
      showFinderResult(song);
    } else {
      noResult.classList.add('show');
      const errMsg = (data.error && data.error.error_message) ? data.error.error_message : 'Song not found';
      toast('\u274c ' + errMsg);
      console.warn('AudD error detail:', JSON.stringify(data));
    }
  } catch(err) {
    rippleWrap.classList.remove('show');
    // Demo fallback when API call fails (for testing purposes)
    if (err.name === 'TypeError' || err.message.includes('fetch')) {
      showFinderDemo();
    } else {
      noResult.classList.add('show');
      toast(' Failed: ' + err.message);
    }
  } finally {
    searchBtn.disabled = false;
  }
}

function showFinderDemo() {
  // Demo result for testing without API
  const demo = {
    title: 'Blinding Lights',
    artist: 'The Weeknd',
    album: 'After Hours',
    release_date: '2019',
    apple_music: { artwork: { url: 'https://is1-ssl.mzstatic.com/image/thumb/Music124/v4/c9/9d/0c/c99d0c9a-4d12-3f4e-b4e5-cd51a28d4b10/19UMGIM08765.rgb.jpg/600x600bb.jpg' } }
  };
  showFinderResult(demo);
  toast(' Demo mode (no API connection)');
}

function showFinderResult(song) {
  _finderResult = song;
  const resultEl = document.getElementById('finder-result');
  const artEl = document.getElementById('finder-album-art');
  const artPh = document.getElementById('finder-album-ph');
  const titleEl = document.getElementById('finder-song-title');
  const artistEl = document.getElementById('finder-song-artist');
  const albumEl = document.getElementById('finder-song-album');

  titleEl.textContent = song.title || '—';
  artistEl.textContent = song.artist || '—';
  albumEl.textContent = song.album ? ` ${song.album}` : (song.release_date ? ` ${song.release_date}` : '');

  // Album art from AudD response
  const artUrl = song.apple_music?.artwork?.url?.replace('{w}x{h}bb', '300x300bb')
    || song.spotify?.album?.images?.[0]?.url
    || song.deezer?.album?.cover_medium
    || '';

  if (artUrl) {
    artEl.src = artUrl;
    artEl.style.display = 'block';
    artPh.style.display = 'none';
  } else {
    artEl.style.display = 'none';
    artPh.style.display = 'flex';
  }

  resultEl.classList.add('show');

  // Save to history
  saveFinderHistory({
    title: song.title || '—',
    artist: song.artist || '—',
    album: song.album || '',
    art: artUrl,
    timestamp: Date.now()
  });

  toast(' Song Found! "' + (song.title || '—') + '"');
}

function finderPlaySong() {
  if (!_finderResult) return;
  const query = (_finderResult.artist || '') + ' ' + (_finderResult.title || '');
  if (typeof showSearchView === 'function') {
    showSearchView();
    setTimeout(() => {
      const q = document.getElementById('q');
      if (q) { q.value = query; q.dispatchEvent(new Event('input')); }
      const btn = document.getElementById('btn-search');
      if (btn) btn.click();
    }, 300);
  }
}

function finderSaveToPlaylist() {
  if (!_finderResult) return;
  const query = (_finderResult.artist || '') + ' ' + (_finderResult.title || '');
  toast(' Search for songs in the Search tab to add to a playlist');
  finderPlaySong();
}

// ── History (localStorage) ──
function getFinderHistory() {
  try { return JSON.parse(localStorage.getItem(FINDER_HISTORY_KEY) || '[]'); } catch { return []; }
}

function saveFinderHistory(item) {
  let history = getFinderHistory();
  // Remove duplicate
  history = history.filter(h => h.title !== item.title || h.artist !== item.artist);
  history.unshift(item);
  if (history.length > 20) history = history.slice(0, 20);
  try { localStorage.setItem(FINDER_HISTORY_KEY, JSON.stringify(history)); } catch {}
  renderFinderHistory();
}

function renderFinderHistory() {
  const history = getFinderHistory();
  const section = document.getElementById('finder-history-section');
  const list = document.getElementById('finder-history-list');
  if (!section || !list) return;

  if (!history.length) { section.style.display = 'none'; return; }
  section.style.display = 'block';

  list.innerHTML = history.map((item, idx) => `
    <div class="finder-history-item" onclick="finderHistoryPlay(${idx})">
      ${item.art
        ? `<img class="finder-history-art" src="${item.art}" alt="" onerror="this.style.display='none'">`
        : `<div class="finder-history-art-ph"></div>`}
      <div class="finder-history-info">
        <div class="finder-history-song">${item.title}</div>
        <div class="finder-history-artist">${item.artist}</div>
      </div>
      <div class="finder-history-time">${timeAgo(item.timestamp)}</div>
    </div>
  `).join('');
}

function finderHistoryPlay(idx) {
  const history = getFinderHistory();
  const item = history[idx];
  if (!item) return;
  _finderResult = item;
  showFinderResult(item);
}

function clearFinderHistory() {
  if (!confirm('Clear all song search history?')) return;
  try { localStorage.removeItem(FINDER_HISTORY_KEY); } catch {}
  renderFinderHistory();
  toast(' History deleted');
}

function timeAgo(timestamp) {
  const diff = Date.now() - timestamp;
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'Just now';
  if (mins < 60) return mins + ' mnt lalu';
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return hrs + ' hours ago';
  return Math.floor(hrs / 24) + ' days ago';
}

// ─── SONG PREVIEW (feed vertikal ala TikTok, preview 30 detik dari iTunes) ──
// Halaman ini murni memutar cuplikan 30 detik (previewUrl) dari iTunes Search
// API — bukan lagu penuh — jadi terpisah dari sistem pemutaran utama (YouTube).
// Daftar "populer" diambil dari RSS Top Songs iTunes lalu di-lookup satu per
// satu untuk mendapatkan previewUrl-nya. Setiap kartu bisa discroll vertikal
// (snap, mirip TikTok/Reels) dan preview yang sedang terlihat otomatis diputar.
let spTracks = [];
let spAudio = null;
let spMuted = false;
let spObserver = null;
let spCurrentIndex = -1;

// ── Kontrol navigasi 1-slide-per-aksi (anti "terlempar jauh" saat scroll
// kencang) + dukungan tombol panah atas/bawah di keyboard. Alih-alih
// mengandalkan scroll-snap bawaan browser (yang bisa melompati beberapa slide
// sekaligus kalau discroll/di-flick dengan cepat), kita kunci navigasi supaya
// setiap gesture/scroll/tombol hanya memindahkan tepat 1 slide ke
// depan/belakang, lalu mengunci input sampai animasi perpindahan selesai. ──
let spFocusIndex = 0;
let spNavLocked = false;
let _spNavLockTimer = null;
const SP_NAV_COOLDOWN = 480; // ms, sedikit lebih lama dari durasi animasi scroll smooth

// Bagian UI yang SAMA setiap kali halaman Song Preview dibuka, dari mana pun
// asalnya (topbar/nav bawah, atau kotak "Jelajahi <Artis>" di Now Playing):
// hentikan lagu utama yang sedang diputar, tutup halaman lyrics (kalau
// sedang terbuka), sembunyikan halaman lain, lalu tampilkan #song-preview-view.
// Tidak memuat daftar lagu apapun — itu tanggung jawab pemanggilnya.
function _spOpenShell() {
  if (typeof YTP !== 'undefined' && YTP) { try { YTP.pauseVideo(); } catch(e){} }
  if (typeof playing !== 'undefined') { playing = false; }
  if (typeof setPB === 'function') { setPB(false); }
  if (typeof closeFSLyricsIfOpen === 'function') { closeFSLyricsIfOpen(); }
  // Tutup halaman Now Playing kalau sedang terbuka (mis. user menekan salah
  // satu song preview di kotak "Jelajahi <Artis>") — halaman Now Playing
  // adalah overlay fullscreen (z-index tinggi) yang akan tetap menutupi
  // halaman Song Preview di baliknya kalau tidak ditutup dulu di sini.
  if (typeof closeNP === 'function') { closeNP(); }
  document.getElementById('home-view').classList.remove('active');
  document.getElementById('search-view').classList.remove('active');
  document.getElementById('finder-view').style.display = 'none';
  document.getElementById('playlist-view').style.display = 'none';
  document.getElementById('top-songs-full-view').style.display = 'none';
  document.getElementById('recently-played-full-view').style.display = 'none';
  document.getElementById('recommend-full-view').style.display = 'none';
  document.getElementById('artist-view').style.display = 'none';
  document.getElementById('album-view').style.display = 'none';
  document.getElementById('nav-home').classList.remove('on');
  document.getElementById('nav-search').classList.remove('on');
  document.getElementById('nav-finder').classList.remove('on');
  document.getElementById('nav-songpreview')?.classList.add('on');
  document.getElementById('song-preview-view').style.display = 'flex';
  // Khusus mobile: sembunyikan topbar (tombol profil/notif/kotak search) &
  // mini player bar supaya tidak menutupi tombol menu genre/search milik
  // Song Preview (lihat CSS body.sp-mobile-open di media query 660px).
  if (typeof isMobile === 'function' && isMobile()) document.body.classList.add('sp-mobile-open');
}

function openSongPreviewView() {
  _spOpenShell();
  // Default: setiap kali halaman Song Preview dibuka pertama kali (belum ada
  // lagu dimuat), langsung tampilkan genre Pop, bukan mode "Populer" umum.
  if (!spTracks.length) loadSpByGenre('pop');
}

// Dibuka khusus saat user menekan salah satu song preview di kotak
// "Jelajahi <Artis>" (halaman Now Playing): feed Song Preview HANYA berisi
// preview 30 detik dari artis yang sama — bukan dari artis lain manapun —
// dan TIDAK memutar lagu penuh, persis seperti perilaku preview ala Spotify.
function openSongPreviewViewForArtist(artistName, focusTitle) {
  _spOpenShell();
  loadSpByArtist(artistName, focusTitle);
}

function closeSongPreviewView() {
  document.getElementById('nav-songpreview')?.classList.remove('on');
  if (spAudio) { spAudio.pause(); }
  spCurrentIndex = -1;
  spFocusIndex = 0;
  spNavLocked = false;
  clearTimeout(_spNavLockTimer);
  showHomeView();
}

function toggleSpSearchBar() {
  const bar = document.getElementById('sp-search-bar');
  closeSpGenreMenu(); // tutup menu genre kalau lagi terbuka, biar tidak tumpang tindih
  bar.classList.toggle('open');
  if (bar.classList.contains('open')) {
    setTimeout(() => document.getElementById('sp-search-input')?.focus(), 50);
  }
}

// ─── MENU GENRE (Song Preview) ──────────────────────────────
// Memakai daftar genre yang sama (GENRE_DEFS) dengan fitur "Genre" di Home,
// supaya labelnya konsisten di seluruh app.
let _currentSpGenreKey = null; // null = mode Populer (belum difilter genre)
let _spGenreChipsBuilt = false;

function toggleSpGenreMenu() {
  const menu = document.getElementById('sp-genre-menu');
  document.getElementById('sp-search-bar')?.classList.remove('open'); // tutup search bar kalau lagi terbuka
  if (!_spGenreChipsBuilt) renderSpGenreChips();
  menu.classList.toggle('open');
}

function closeSpGenreMenu() {
  document.getElementById('sp-genre-menu')?.classList.remove('open');
}

function renderSpGenreChips() {
  const grid = document.getElementById('sp-genre-grid');
  if (!grid) return;
  grid.innerHTML = '';

  // Chip "Populer" untuk kembali ke chart teratas (tanpa filter genre)
  const allChip = document.createElement('button');
  allChip.type = 'button';
  allChip.className = 'sp-genre-chip' + (!_currentSpGenreKey ? ' active' : '');
  allChip.textContent = 'Populer';
  allChip.dataset.genreKey = '';
  allChip.addEventListener('click', () => {
    _currentSpGenreKey = null;
    _syncSpGenreChipsActive();
    closeSpGenreMenu();
    document.getElementById('sp-genre-btn')?.classList.remove('active');
    loadSpPopular();
  });
  grid.appendChild(allChip);

  Object.keys(GENRE_DEFS).forEach(key => {
    const def = GENRE_DEFS[key];
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'sp-genre-chip' + (_currentSpGenreKey === key ? ' active' : '');
    chip.textContent = def.label;
    chip.dataset.genreKey = key;
    chip.addEventListener('click', () => {
      closeSpGenreMenu();
      loadSpByGenre(key);
    });
    grid.appendChild(chip);
  });

  _spGenreChipsBuilt = true;
}

function _syncSpGenreChipsActive() {
  const grid = document.getElementById('sp-genre-grid');
  if (!grid) return;
  grid.querySelectorAll('.sp-genre-chip').forEach(chip => {
    const key = chip.dataset.genreKey || null;
    chip.classList.toggle('active', key === _currentSpGenreKey);
  });
}

// Muat Song Preview yang hanya berisi lagu dari genre tertentu. Memakai
// daftar seed artist genre tsb (sama seperti fitur Genre di Home) supaya
// hasil pencarian iTunes benar-benar relevan dengan genre yang dipilih.
// Ubah bentuk track hasil fetchGenreSongs (format Deezer: id/title/artist/
// thumb/preview) menjadi bentuk yang dipakai kode Song Preview (format ala
// iTunes: trackId/trackName/artistName/artworkUrl100/previewUrl), supaya
// bisa langsung dipakai oleh renderSpSlides/playSpPreview/dst tanpa ubahan lain.
function _mapDeezerTrackToSp(t, genreLabel) {
  return {
    trackId: 'dz_' + t.id,
    trackName: t.title,
    artistName: t.artist,
    collectionName: '',
    artworkUrl100: t.thumb,
    previewUrl: t.preview,
    primaryGenreName: genreLabel
  };
}

// GIF loading indicator utk halaman Song Preview (dipakai pas nunggu
// lagu populer/genre/hasil pencarian ke-load, GANTI teks "Loading...").
const SP_LOADING_GIF = 'data:image/gif;base64,';
function spLoadingHtml() {
  return '<div class="sp-loading"><img class="sp-loading-gif" src="' + SP_LOADING_GIF + '" width="400" height="304" loading="eager" decoding="sync" alt="Loading"></div>';
}

async function loadSpByGenre(genreKey) {
  const def = GENRE_DEFS[genreKey];
  if (!def) return;
  const feed = document.getElementById('sp-feed');
  document.getElementById('sp-topbar-title').textContent = def.label;
  document.getElementById('sp-genre-btn')?.classList.add('active');
  feed.innerHTML = spLoadingHtml();
  try {
    // Sumber utama: mesin yang sama dengan fitur "Genre" di Home
    // (fetchGenreSongs) — mengutamakan chart trending resmi per-genre
    // (Deezer) lalu artis yang tervalidasi genre-nya lewat tag MusicBrainz.
    // Hasilnya jauh lebih beragam artisnya (sampai 100 lagu, bukan cuma dari
    // segelintir seed artist) SEKALIGUS terjamin sesuai genre dan memang
    // sedang tren/populer — bukan tebakan dari pencarian teks bebas.
    let genreTracks = await fetchGenreSongs(genreKey).catch(() => []);
    let tracks = genreTracks
      .filter(t => t && t.preview)
      .map(t => _mapDeezerTrackToSp(t, def.label));

    // Cadangan: kalau sumber utama gagal/hasilnya terlalu sedikit (mis.
    // Deezer/MusicBrainz sedang tidak bisa diakses), lengkapi dari pencarian
    // iTunes langsung per seed artist seperti versi sebelumnya.
    if (tracks.length < 10) {
      const seeds = (def.seedArtists && def.seedArtists.length) ? _shuffleArray(def.seedArtists) : [];
      const queries = seeds.length ? seeds : [def.query || def.label];
      const resultsArr = await Promise.all(
        queries.map(qStr => fetchItunesResults(qStr, 'US', 'song', 10).catch(() => []))
      );
      let combined = resultsArr.flat();
      if (combined.length < 10) {
        const fallback = await fetchItunesResults(def.query || def.label, 'US', 'song', 50).catch(() => []);
        combined = combined.concat(fallback);
      }
      const seen = new Set(tracks.map(t => t.trackId));
      combined.forEach(r => {
        if (!r || r.wrapperType !== 'track' || !r.previewUrl) return;
        const key = r.trackId || (r.artistName + '|||' + r.trackName);
        if (seen.has(key)) return;
        seen.add(key);
        tracks.push(r);
      });
    }

    if (!tracks.length) throw new Error('No ' + def.label + ' songs found');

    // Batasi maksimal SP_MAX_PER_ARTIST lagu dari artis yang sama supaya
    // artis tidak itu-itu saja terus di feed — TANPA membatasi jumlah artis
    // berbeda yang boleh masuk (semua artis genre ini tetap punya peluang
    // tampil, bukan cuma sebagian kecil).
    tracks = _capTracksPerArtist(tracks, SP_MAX_PER_ARTIST);

    _currentSpGenreKey = genreKey;
    _syncSpGenreChipsActive();
    spTracks = _shuffleArray(tracks);
    renderSpSlides();
  } catch (e) {
    console.error('loadSpByGenre error:', e);
    feed.innerHTML = '<div class="sp-loading">Failed to load ' + esc(def.label) + ' songs, try again.</div>';
  }
}

// Muat halaman Song Preview supaya HANYA berisi preview 30 detik dari SATU
// artis tertentu — dipakai saat dibuka dari kotak "Jelajahi <Artis>" di
// halaman Now Playing, jadi feed-nya TIDAK dicampur lagu dari artis lain
// manapun (beda dengan mode genre/populer di atas). Sumbernya sama dengan
// kotak "Jelajahi" itu sendiri (fetchArtistTopTracks), jadi format datanya
// sudah kompatibel dan tinggal dipetakan lewat _mapDeezerTrackToSp().
async function loadSpByArtist(artistName, focusTitle) {
  if (!artistName) { loadSpPopular(); return; }
  const feed = document.getElementById('sp-feed');
  document.getElementById('sp-topbar-title').textContent = artistName;
  document.getElementById('sp-genre-btn')?.classList.remove('active');
  _currentSpGenreKey = null;
  _syncSpGenreChipsActive();
  feed.innerHTML = spLoadingHtml();
  try {
    const raw = await fetchArtistTopTracks(artistName, 50, focusTitle).catch(() => []);
    let tracks = (raw || [])
      .filter(t => t && t.preview)
      .map(t => _mapDeezerTrackToSp(t, artistName));
    if (!tracks.length) throw new Error('No previews found for ' + artistName);

    // Kalau lagu yang barusan diklik di kotak "Jelajahi" ada di daftar,
    // taruh di paling depan — feed langsung mulai dari lagu itu (mirip
    // Spotify: melompat ke lagu yang ditekan), bukan urutan/lagu acak lain.
    if (focusTitle) {
      const idx = tracks.findIndex(t => (t.trackName || '').toLowerCase() === focusTitle.toLowerCase());
      if (idx > 0) {
        const [picked] = tracks.splice(idx, 1);
        tracks.unshift(picked);
      }
    }

    spTracks = tracks;
    renderSpSlides();
  } catch (e) {
    console.error('loadSpByArtist error:', e);
    feed.innerHTML = '<div class="sp-loading">Failed to load previews for ' + esc(artistName) + '.</div>';
  }
}

// Kunci localStorage untuk mengingat lagu-lagu yang just now ditampilkan,
// supaya saat user keluar dari web lalu masuk lagi, Song Preview tidak
// menampilkan deretan lagu yang persis sama (chart iTunes sendiri statis).
const SP_RECENT_KEY = 'sp_recent_track_ids';
function _spGetRecentIds() {
  try { return JSON.parse(localStorage.getItem(SP_RECENT_KEY) || '[]'); } catch (e) { return []; }
}
function _spSaveRecentIds(ids) {
  try { localStorage.setItem(SP_RECENT_KEY, JSON.stringify(ids.slice(-120))); } catch (e) {}
}
function _shuffleArray(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Maksimal berapa lagu dari 1 artis yang sama boleh masuk ke satu feed Song
// Preview. Tujuannya supaya user tidak bosan lihat artis yang itu-itu saja
// walau feed-nya tetap sesuai genre yang dipilih. Diturunkan dari 8 ke 4
// karena sekarang sumber lagu per genre jauh lebih kaya artisnya (lihat
// fetchGenreSongs di loadSpByGenre), jadi tidak perlu jatah sebanyak itu per
// artis untuk mengisi feed — dengan jatah lebih kecil, artis berbeda lebih
// cepat bergantian muncul.
const SP_MAX_PER_ARTIST = 10;
function _capTracksPerArtist(tracks, maxPerArtist) {
  // Acak dulu urutannya supaya artis mana yang "kebagian slot" tiap kali
  // dibuka juga bervariasi (bukan selalu artis yang paling pertama muncul).
  const shuffled = _shuffleArray(tracks);
  const countByArtist = {};
  const result = [];
  for (const t of shuffled) {
    const artistKey = (t.artistName || t.artist || 'Unknown').toLowerCase();
    const n = countByArtist[artistKey] || 0;
    if (n >= maxPerArtist) continue;
    countByArtist[artistKey] = n + 1;
    result.push(t);
  }
  return result;
}

async function loadSpPopular() {
  const feed = document.getElementById('sp-feed');
  document.getElementById('sp-topbar-title').textContent = 'Song Preview';
  _currentSpGenreKey = null;
  document.getElementById('sp-genre-btn')?.classList.remove('active');
  _syncSpGenreChipsActive();
  feed.innerHTML = spLoadingHtml();
  try {
    const rssRes = await fetch('https://itunes.apple.com/us/rss/topsongs/limit=100/json', { signal: AbortSignal.timeout(9000) });
    if (!rssRes.ok) throw new Error('RSS failed (' + rssRes.status + ')');
    const rssData = await rssRes.json();
    const entries = (rssData.feed && rssData.feed.entry) || [];
    const ids = entries.map(e => e.id && e.id.attributes && e.id.attributes['im:id']).filter(Boolean);
    if (!ids.length) throw new Error('Chart is empty');

    const lookupRes = await fetch('https://itunes.apple.com/lookup?id=' + ids.join(',') + '&country=US', { signal: AbortSignal.timeout(9000) });
    if (!lookupRes.ok) throw new Error('Lookup failed (' + lookupRes.status + ')');
    const lookupData = await lookupRes.json();
    let tracks = (lookupData.results || []).filter(r => r.wrapperType === 'track' && r.previewUrl);
    if (!tracks.length) throw new Error('No preview available');

    // Hindari lagu yang just now ditampilkan di sesi/kunjungan sebelumnya
    const recentIds = _spGetRecentIds();
    const fresh = tracks.filter(t => !recentIds.includes(t.trackId));
    // Kalau setelah difilter jumlahnya masih cukup banyak, pakai itu.
    // Kalau terlalu sedikit (semua sudah pernah muncul), reset saja histori-nya.
    tracks = fresh.length >= 15 ? fresh : tracks;

    // Chart Top Songs sering diisi banyak lagu dari artis yang sama (lagi
    // hits), jadi batasi juga di sini supaya feed lebih beragam artisnya.
    tracks = _capTracksPerArtist(tracks, SP_MAX_PER_ARTIST);

    spTracks = _shuffleArray(tracks);
    _spSaveRecentIds(spTracks.map(t => t.trackId));
    renderSpSlides();
  } catch (e) {
    console.error('loadSpPopular error:', e);
    feed.innerHTML = '<div class="sp-loading">Failed to load popular previews, try again.</div>';
  }
}

async function searchSongPreview(q) {
  q = (q || '').trim();
  if (!q) { loadSpPopular(); return; }
  _currentSpGenreKey = null;
  document.getElementById('sp-genre-btn')?.classList.remove('active');
  _syncSpGenreChipsActive();
  const feed = document.getElementById('sp-feed');
  document.getElementById('sp-topbar-title').textContent = '"' + q + '"';
  feed.innerHTML = spLoadingHtml();
  try {
    const results = await fetchItunesResults(q, 'US', 'song');
    const tracks = (results || []).filter(r => r.previewUrl);
    if (!tracks.length) {
      feed.innerHTML = '<div class="sp-loading">No results for "' + esc(q) + '".</div>';
      return;
    }
    spTracks = tracks;
    renderSpSlides();
  } catch (e) {
    console.error('searchSongPreview error:', e);
    feed.innerHTML = '<div class="sp-loading">Failed to search, try again.</div>';
  }
}

function renderSpSlides() {
  const feed = document.getElementById('sp-feed');
  feed.innerHTML = '';
  spCurrentIndex = -1;
  spFocusIndex = 0;
  spNavLocked = false;
  clearTimeout(_spNavLockTimer);
  // Buang cache preload dari daftar lagu sebelumnya (indeksnya sudah tidak relevan)
  if (spPreloadCache) { spPreloadCache.forEach(a => { a.src = ''; }); spPreloadCache.clear(); }
  _spArtistPhotoLoaded.clear();
  spTracks.forEach((t, i) => feed.appendChild(buildSpSlideEl(t, i)));
  feed.scrollTop = 0;
  setupSpObserver();
  _spPreloadIndex(0); _spPreloadIndex(1); _spPreloadIndex(2); // siapkan beberapa slide pertama lebih awal
  _spLoadArtistPhoto(0); _spLoadArtistPhoto(1); _spLoadArtistPhoto(2);
}

function buildSpSlideEl(t, i) {
  const div = document.createElement('div');
  div.className = 'sp-slide';
  div.dataset.idx = i;
  const bigArt = (t.artworkUrl100 || '').replace('100x100bb', '600x600bb');
  const genre = t.primaryGenreName || 'Musik';
  const _spLiked = isTrackLiked({ title: t.trackName || 'Unknown', artist: t.artistName || 'Unknown' });
  div.innerHTML = `
    <div class="sp-bg" style="background-image:url('${esc(bigArt)}')"></div>
    <div class="sp-scrim"></div>
    <div class="sp-slide-content">
      <div class="sp-release-badge">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg>
        Preview 30 Detik
      </div>
      <div class="sp-album-wrap">
        <img class="sp-album-art" src="${esc(bigArt)}" alt="${esc(t.collectionName || t.trackName || '')}" onerror="this.src='${esc(t.artworkUrl100 || '')}'">
      </div>
      <div class="sp-slide-bottom">
      <div class="sp-artist-row">
        <img class="sp-artist-photo" id="sp-artist-photo-${i}" alt="" onerror="this.style.visibility='hidden'">
        <div class="sp-artist-info">
          <div class="sp-artist-name">${esc(t.artistName || 'Unknown')}</div>
          <div class="sp-artist-sub">${esc(t.collectionName || '')}</div>
        </div>
        <button class="sp-follow-btn${isArtistFavorited(t.artistName || '') ? ' following' : ''}" id="sp-follow-btn-${i}" data-artist="${esc(t.artistName || '')}" data-photo="" onclick="event.stopPropagation();toggleSpFollow(this)">${isArtistFavorited(t.artistName || '') ? 'Following' : 'Follow'}</button>
        <button class="sp-dots-btn${_spLiked ? ' liked' : ''}" id="sp-like-btn-${i}" onclick="event.stopPropagation();likeSpTrack(${i})" title="Save to Liked Songs">
          <svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
        </button>
      </div>
      <div class="sp-genre-tags">
        <span class="sp-tag">#${esc(genre.replace(/\s+/g, ''))}</span>
        <span class="sp-tag">#songpreview</span>
        <span class="sp-tag">#30detik</span>
      </div>
      <div class="sp-bottom-card">
        <img class="sp-bottom-thumb" src="${esc(t.artworkUrl100 || '')}" onerror="this.style.visibility='hidden'">
        <div class="sp-bottom-info">
          <div class="sp-bottom-title">${esc(t.trackName || 'Unknown')}</div>
          <div class="sp-bottom-artist">${esc(t.artistName || '')}</div>
        </div>
        <button class="sp-add-btn" onclick="event.stopPropagation();addSpTrackToPlaylist(${i})" title="Add to playlist">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>
        </button>
      </div>
      </div>
    </div>
  `;
  div.addEventListener('click', () => togglePauseSpPreview());

  // Nama artis (baris atas & baris bawah) bisa diklik -> buka halaman profil artis
  div.querySelectorAll('.sp-artist-name, .sp-bottom-artist').forEach(el => {
    el.classList.add('sp-clickable-artist');
    el.addEventListener('click', (e) => {
      e.stopPropagation();
      openArtistView(t.artistName);
    });
  });

  // Judul lagu bisa diklik -> putar lagu tersebut versi lengkap (full durasi)
  const titleEl = div.querySelector('.sp-bottom-title');
  if (titleEl) {
    titleEl.classList.add('sp-clickable-title');
    titleEl.title = 'Play full song';
    titleEl.addEventListener('click', (e) => {
      e.stopPropagation();
      playSpTrackFull(i);
    });
  }

  return div;
}

// Putar lagu dari Song Preview dalam versi lengkap (bukan preview 30 detik),
// memakai mesin pemutar utama app (cari & putar audio penuh + lirik).
function playSpTrackFull(idx) {
  const t = spTracks[idx];
  if (!t) return;
  if (spAudio) spAudio.pause(); // hentikan preview 30 detik dulu
  const track = {
    title: t.trackName || 'Unknown',
    artist: t.artistName || 'Unknown',
    thumb: (t.artworkUrl100 || '').replace('100x100bb', '600x600bb') || t.artworkUrl100 || '',
    preview: null,
    videoId: null,
    photo: null,
    duration: 0,
    _query: `${t.artistName || ''}|||${t.trackName || ''}|||${t.trackId || ''}`
  };
  loadPlay(track, null);
}

function toggleSpFollow(btn) {
  const artistName = btn.dataset.artist;
  if (!artistName) return;
  const nowFollowing = toggleFollowArtist(artistName, btn.dataset.photo || '');
  btn.classList.toggle('following', nowFollowing);
  btn.textContent = nowFollowing ? 'Following' : 'Follow';
}

// ── Prefetch audio preview: siapkan buffer beberapa slide di depan agar
// transisi saat scroll terasa instan, tidak menunggu koneksi dari nol. ──
let spPreloadCache = new Map(); // idx -> HTMLAudioElement (sudah di-preload, belum tentu diputar)
const SP_PRELOAD_WINDOW = 2;

function _spPreloadIndex(idx) {
  if (idx == null || idx < 0 || idx >= spTracks.length) return;
  if (spPreloadCache.has(idx)) return;
  const t = spTracks[idx];
  if (!t || !t.previewUrl) return;
  const a = new Audio();
  a.preload = 'auto';
  a.muted = true;
  a.src = t.previewUrl;
  try { a.load(); } catch (e) {}
  spPreloadCache.set(idx, a);
}

// Buang audio yang sudah di-preload tapi jauh dari posisi sekarang, supaya
// tidak boros koneksi/memori.
function _spTrimPreloadCache(centerIdx) {
  spPreloadCache.forEach((a, idx) => {
    if (Math.abs(idx - centerIdx) > SP_PRELOAD_WINDOW + 1) {
      a.src = '';
      spPreloadCache.delete(idx);
    }
  });
}

// ── Scroll tanpa batas ───────────────────────────────────────────────────
// Begitu user mendekati ujung feed yang sedang dimuat (5 slide terakhir),
// tambahkan lebih banyak lagu ke akhir feed supaya user tidak pernah mentok
// di ujung, berapa pun jauh mereka scroll. Lagu tambahan diambil dari pool
// yang sudah berhasil dimuat (sudah diperbesar lewat GENRE_TARGET_COUNT di
// atas, jadi biasanya ratusan lagu unik dulu) lalu diacak ulang urutannya —
// begitu pool itu sendiri sudah "habis" pun, ia terus didaur ulang secara
// acak sehingga scroll-nya benar-benar tidak terbatas, untuk feed genre
// manapun maupun feed populer/pencarian.
let _spExtending = false;
function _spExtendFeed() {
  if (_spExtending) return;
  if (!spTracks || !spTracks.length) return;
  const feed = document.getElementById('sp-feed');
  if (!feed) return;
  _spExtending = true;
  try {
    const baseLen = spTracks.length;
    let more = _shuffleArray(spTracks.slice(0, baseLen));
    const lastTrack = spTracks[baseLen - 1];
    // Supaya sambungannya tidak terasa "diam sebentar" karena lagu yang
    // barusan diputar langsung terulang persis di slide berikutnya.
    if (more.length > 1 && lastTrack && more[0] && more[0].trackId === lastTrack.trackId) {
      more.push(more.shift());
    }
    more.forEach((t, i) => {
      const newIdx = baseLen + i;
      spTracks.push(t);
      const el = buildSpSlideEl(t, newIdx);
      feed.appendChild(el);
      if (spObserver) spObserver.observe(el);
    });
  } finally {
    _spExtending = false;
  }
}

function setupSpObserver() {
  if (spObserver) spObserver.disconnect();
  const feed = document.getElementById('sp-feed');
  spObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      const idx = parseInt(entry.target.dataset.idx, 10);
      if (!entry.isIntersecting) return;
      // Begitu slide mulai kelihatan sebagian, langsung mulai buffer audionya
      // (dan slide berikutnya) supaya saat scroll sampai, tinggal diputar.
      if (entry.intersectionRatio >= 0.15) {
        _spPreloadIndex(idx);
        _spPreloadIndex(idx + 1);
        // Ambil foto asli artis (sama dengan yang dipakai di kotak "Tentang Artis")
        // hanya untuk slide yang sudah/segera terlihat, bukan semuanya sekaligus.
        _spLoadArtistPhoto(idx);
        _spLoadArtistPhoto(idx + 1);
        // Sudah mendekati ujung feed yang sekarang? Sambung lebih banyak
        // lagu supaya scroll tidak pernah mentok.
        if (idx >= spTracks.length - 5) _spExtendFeed();
      }
      if (entry.intersectionRatio >= 0.6) {
        playSpPreview(idx);
      }
    });
  }, { root: feed, threshold: [0.15, 0.6], rootMargin: '100px 0px' });
  feed.querySelectorAll('.sp-slide').forEach(el => spObserver.observe(el));
}

// Ambil foto asli artis dari Deezer (sumber yang sama dengan kotak "Tentang Artis"
// di sidebar/panel lirik) untuk 1 slide Song Preview, lalu tempelkan juga ke
// tombol "Ikuti" supaya foto yang tersimpan ke Artis Favorit adalah foto artis
// yang benar, bukan cover lagu. Di-cache per artis & dimuat lazy per-slide
// (bukan untuk semua slide sekaligus) supaya tidak memperlambat feed.
let _spArtistPhotoLoaded = new Set();
async function _spLoadArtistPhoto(idx) {
  if (idx == null || idx < 0 || idx >= spTracks.length) return;
  if (_spArtistPhotoLoaded.has(idx)) return;
  _spArtistPhotoLoaded.add(idx);
  const t = spTracks[idx];
  if (!t || !t.artistName) return;
  const imgEl = document.getElementById('sp-artist-photo-' + idx);
  if (!imgEl) return;
  const pic = await _loadArtistPhotoInto(imgEl, t.artistName);
  if (pic) {
    const btn = document.getElementById('sp-follow-btn-' + idx);
    if (btn) btn.dataset.photo = pic;
  }
}

function playSpPreview(idx) {
  if (spCurrentIndex === idx) return;
  spCurrentIndex = idx;
  const t = spTracks[idx];
  if (!t || !t.previewUrl) return;
  if (spAudio) spAudio.pause();
  // Pakai audio yang sudah di-preload kalau tersedia, biar tidak menunggu
  // buffer dari nol saat slide ini diputar.
  const preloaded = spPreloadCache.get(idx);
  if (preloaded) {
    spAudio = preloaded;
    spPreloadCache.delete(idx);
  } else {
    spAudio = new Audio();
    spAudio.src = t.previewUrl;
  }
  spAudio.loop = true;
  spAudio.muted = spMuted;
  spAudio.volume = _getMainVolume();
  spAudio.currentTime = 0;
  spAudio.play().catch(() => {});
  // Siapkan slide-slide berikutnya lebih awal
  _spPreloadIndex(idx + 1);
  _spPreloadIndex(idx + 2);
  _spTrimPreloadCache(idx);
}

function togglePauseSpPreview() {
  if (!spAudio) return;
  if (spAudio.paused) spAudio.play().catch(() => {}); else spAudio.pause();
}

// Tombol "+" di kartu songs bawah: pakai modal "Add to Playlist" yang sudah
// ada di app (openAddSongModal), jadi user tetap bisa simpan judul/artis
// yang ditemukan lewat Song Preview ke playlist mereka.
function addSpTrackToPlaylist(idx) {
  const t = spTracks[idx];
  if (!t) return;
  openAddSongModal({
    title: t.trackName || 'Unknown',
    artist: t.artistName || 'Unknown',
    thumb: (t.artworkUrl100 || '').replace('100x100bb', '600x600bb'),
    _query: `${t.artistName || ''}|||${t.trackName || ''}|||${t.trackId || ''}`
  });
}

// ── Navigasi terkendali 1-slide-per-aksi ─────────────────────────────────
// direction: 1 = ke lagu berikutnya (bawah), -1 = ke lagu sebelumnya (atas).
// Selama masih terkunci (spNavLocked), semua request navigasi tambahan
// diabaikan — jadi scroll/flick kencang atau tombol panah yang ditekan
// berkali-kali dengan cepat tetap hanya berpindah 1 slide, tidak "terlempar"
// melewati beberapa lagu sekaligus.
function spNavigate(direction) {
  if (spNavLocked) return;
  if (!spTracks.length) return;
  // Kalau sudah dekat ujung, sambung dulu lagu tambahan (scroll tanpa batas)
  // sebelum dicek, supaya navigasi panah/keyboard juga tidak pernah mentok.
  if (direction > 0 && spFocusIndex >= spTracks.length - 5) _spExtendFeed();
  const nextIdx = spFocusIndex + direction;
  if (nextIdx < 0 || nextIdx >= spTracks.length) return;
  const feed = document.getElementById('sp-feed');
  if (!feed) return;
  const targetEl = feed.querySelector(`.sp-slide[data-idx="${nextIdx}"]`);
  if (!targetEl) return;
  spFocusIndex = nextIdx;
  spNavLocked = true;
  targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
  clearTimeout(_spNavLockTimer);
  _spNavLockTimer = setTimeout(() => { spNavLocked = false; }, SP_NAV_COOLDOWN);
}

// Roda mouse / touchpad: DULU setiap event 'wheel' di-preventDefault lalu
// dipaksa pindah 1 slide lewat spNavigate() — ini yang bikin scroll touchpad
// terasa kaku/patah-patah, karena momentum & animasi geser bawaan
// trackpad sama sekali diabaikan, diganti animasi scrollIntoView yang kaku.
// Sekarang wheel/touchpad dibiarkan memakai scroll native browser yang halus
// (CSS: .sp-feed{scroll-snap-type:y mandatory}), supaya gerakannya mengikuti
// kecepatan & momentum jari di touchpad apa adanya. Supaya scroll cepat/flick
// kencang tetap tidak "melompati" beberapa lagu sekaligus (masalah yang tadinya
// coba dicegah versi lama), dipakai `scroll-snap-stop: always` di .sp-slide —
// ini properti CSS resmi yang memaksa browser tetap berhenti di tiap slide
// satu-satu meski scroll-nya kencang, tanpa perlu JS yang mengunci gesture.
function _setupSpWheelControl() {
  // Sengaja dikosongkan (native scroll-snap sudah menangani semuanya).
  // Fungsi ini dipertahankan sebagai no-op supaya pemanggilnya di bawah
  // tidak perlu diubah dan tidak error kalau ada kode lain yang memanggilnya.
}

// Swipe sentuh (mobile): geser default browser dimatikan (preventDefault di
// touchmove) supaya perpindahan sepenuhnya dikendalikan spNavigate, bukan
// momentum/fling bawaan yang bisa melewati beberapa slide sekaligus.
function _setupSpTouchControl() {
  const feed = document.getElementById('sp-feed');
  if (!feed) return;
  let touchStartY = 0;
  const SWIPE_THRESHOLD = 40; // px minimal supaya dianggap swipe, bukan tap
  feed.addEventListener('touchstart', (e) => {
    touchStartY = e.touches[0].clientY;
  }, { passive: true });
  feed.addEventListener('touchmove', (e) => {
    e.preventDefault();
  }, { passive: false });
  feed.addEventListener('touchend', (e) => {
    const deltaY = touchStartY - e.changedTouches[0].clientY;
    if (Math.abs(deltaY) < SWIPE_THRESHOLD) return;
    spNavigate(deltaY > 0 ? 1 : -1);
  }, { passive: true });
}

// Tombol panah atas/bawah di keyboard: hanya aktif saat halaman Song Preview
// sedang terbuka, dan tidak mengganggu saat user sedang mengetik di kolom
// pencarian/komentar (input/textarea).
document.addEventListener('keydown', (e) => {
  const spView = document.getElementById('song-preview-view');
  if (!spView || spView.style.display !== 'flex') return;
  const tag = (e.target && e.target.tagName || '').toLowerCase();
  if (tag === 'input' || tag === 'textarea') return;
  if (e.key === 'ArrowDown') {
    e.preventDefault();
    spNavigate(1);
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    spNavigate(-1);
  }
});

_setupSpWheelControl();
_setupSpTouchControl();

// ══════════════════════════════════════════════════════════════════════
// UNDUHAN OFFLINE — simpan & putar file MP3 hasil unduhan tanpa internet
// ══════════════════════════════════════════════════════════════════════
// File MP3 disimpan sebagai Blob di IndexedDB (bukan localStorage, karena
// localStorage cuma menampung string dengan kuota kecil ~5-10MB dan tidak
// cocok untuk file audio). Data ini murni tersimpan di BROWSER perangkat
// user (tidak diunggah ke server manapun), jadi tetap bisa diputar offline
// dan hanya terlihat di browser/perangkat yang sama tempat file diimpor.

const DL_DB_NAME = 'vibexaOfflineDB';
const DL_DB_VERSION = 2;
const DL_STORE = 'downloads';
const DL_PL_STORE = 'dlPlaylists';   // playlist offline: {id, name, trackIds:[...], createdAt}
let _dlDB = null;
let _dlList = [];              // cache metadata (tanpa blob audio) utk render grid
let _dlCurrentId = null;       // id lagu offline yang sedang diputar
let _dlCurrentObjectUrl = null;
let _dlCurrentArtUrl = null;   // object URL foto album lagu offline yang sedang diputar
let _dlArtUrls = {};           // id -> object URL foto album, dipakai untuk grid daftar unduhan
let _dlPlayerObj = null;       // wrapper "YTP palsu" yang membungkus elemen <audio> offline

// ── State Playlist Offline ──────────────────────────────────────────────
let _dlPlaylists = [];             // cache metadata semua playlist offline
let _dlCurrentPlaylistId = null;   // id playlist offline yang sedang dibuka (halaman detail)
// Konteks pemutaran: kalau lagu offline sedang diputar DARI dalam sebuah
// playlist, next/prev mengikuti urutan playlist tsb (bukan seluruh daftar
// unduhan) — termasuk saat app diminimize/di luar layar, karena mekanismenya
// murni event 'ended' pada elemen <audio> (lihat _dlPlayAdjacent di bawah).
let _dlActivePlaylistId = null;
let _dlActiveQueue = [];           // urutan id lagu di playlist yang sedang aktif diputar
let _dlReorderMode = false;
let _dlDragSrcIdx = null;
let _dlTouchGhost = null;
let _dlTouchDragIdx = null;

// ── Urutan putar KUSTOM untuk SELURUH daftar Unduhan Offline (dipakai oleh
// section "Downloaded Songs" di halaman Yours) — terpisah dari state reorder
// milik satu playlist offline (_dlReorderMode dkk di atas) supaya kedua mode
// atur-urutan ini tidak saling bentrok kalau kebetulan aktif "bersamaan".
let _dlAllReorderMode = false;
let _dlAllDragSrcIdx = null;
let _dlAllTouchDragIdx = null;

// ── Ambil foto sampul album yang sudah tertanam di dalam file MP3 (ID3v2 APIC) ──
// Supaya lagu yang diimpor otomatis punya cover tanpa perlu user cari sendiri.
// Gambar ini kemudian disimpan sebagai Blob terpisah di IndexedDB (field `art`)
// bersama file audionya sendiri, jadi tetap tampil meskipun dibuka offline —
// murni tersimpan di perangkat, tidak butuh internet untuk memuatnya lagi.
async function _extractID3CoverArt(file) {
  try {
    const headBuf = await file.slice(0, 10).arrayBuffer();
    const head = new Uint8Array(headBuf);
    if (head[0] !== 0x49 || head[1] !== 0x44 || head[2] !== 0x33) return null; // bukan header "ID3"
    const verMajor = head[3];
    const flags = head[5];
    const tagSize = ((head[6] & 0x7f) << 21) | ((head[7] & 0x7f) << 14) | ((head[8] & 0x7f) << 7) | (head[9] & 0x7f);
    if (!tagSize || tagSize < 10) return null;
    let offset = 10;
    if (flags & 0x40) {
      // Ada extended header — baca ukurannya lalu lewati
      const extArr = new Uint8Array(await file.slice(offset, offset + 4).arrayBuffer());
      let extSize;
      if (verMajor >= 4) extSize = ((extArr[0] & 0x7f) << 21) | ((extArr[1] & 0x7f) << 14) | ((extArr[2] & 0x7f) << 7) | (extArr[3] & 0x7f);
      else extSize = (extArr[0] << 24) | (extArr[1] << 16) | (extArr[2] << 8) | extArr[3];
      offset += extSize;
    }
    const tagEnd = 10 + tagSize;
    const data = new Uint8Array(await file.slice(offset, tagEnd).arrayBuffer());
    let pos = 0;
    while (pos + 10 <= data.length) {
      const id = String.fromCharCode(data[pos], data[pos+1], data[pos+2], data[pos+3]);
      if (id === '\0\0\0\0') break; // sudah masuk area padding
      let frameSize;
      if (verMajor >= 4) frameSize = ((data[pos+4]&0x7f)<<21)|((data[pos+5]&0x7f)<<14)|((data[pos+6]&0x7f)<<7)|(data[pos+7]&0x7f);
      else frameSize = (data[pos+4]<<24)|(data[pos+5]<<16)|(data[pos+6]<<8)|data[pos+7];
      const frameStart = pos + 10;
      if (frameSize <= 0 || frameStart + frameSize > data.length) break;
      if (id === 'APIC') {
        let p = frameStart;
        const enc = data[p]; p += 1;
        let mimeEnd = p;
        while (mimeEnd < frameStart + frameSize && data[mimeEnd] !== 0) mimeEnd++;
        let mime = 'image/jpeg';
        try { mime = new TextDecoder('latin1').decode(data.slice(p, mimeEnd)) || mime; } catch(e){}
        p = mimeEnd + 1;
        p += 1; // lewati byte "picture type"
        if (enc === 1 || enc === 2) {
          while (p + 1 < frameStart + frameSize && !(data[p] === 0 && data[p+1] === 0)) p += 2;
          p += 2;
        } else {
          while (p < frameStart + frameSize && data[p] !== 0) p++;
          p += 1;
        }
        const picBytes = data.slice(p, frameStart + frameSize);
        if (picBytes.length > 100) {
          return new Blob([picBytes], { type: mime && mime.startsWith('image/') ? mime : 'image/jpeg' });
        }
      }
      pos = frameStart + frameSize;
    }
    return null;
  } catch (e) { console.warn('Gagal membaca cover ID3:', e); return null; }
}

// ── Wrapper "YTP palsu" yang membungkus elemen <audio> offline ──────────────
// Meniru API YT.Player (playVideo/pauseVideo/getCurrentTime/getDuration/
// getPlayerState/seekTo/setVolume/destroy) supaya SELURUH mesin pemutaran
// yang sudah ada (tick(), _armSongTimer(), media session, tombol play/pause,
// progress bar, dst — semuanya lewat variabel global YTP) otomatis berfungsi
// juga untuk lagu offline TANPA duplikasi logic dan TANPA mini player terpisah.
function _getOfflinePlayerObj(audioEl) {
  if (_dlPlayerObj) return _dlPlayerObj;
  _dlPlayerObj = {
    _offline: true,
    playVideo(){ audioEl.play().catch(()=>{}); },
    pauseVideo(){ audioEl.pause(); },
    getCurrentTime(){ return audioEl.currentTime || 0; },
    getDuration(){ return audioEl.duration || 0; },
    getPlayerState(){ if (audioEl.ended) return 0; return audioEl.paused ? 2 : 1; },
    seekTo(t){ try { audioEl.currentTime = t; } catch(e){} },
    setVolume(v){ try { audioEl.volume = Math.max(0, Math.min(1, v/100)); } catch(e){} },
    getVideoUrl(){ return ''; },
    destroy(){ try { audioEl.pause(); } catch(e){} }
  };
  return _dlPlayerObj;
}

function _dlOpenDB() {
  return new Promise((resolve, reject) => {
    if (_dlDB) { resolve(_dlDB); return; }
    const req = indexedDB.open(DL_DB_NAME, DL_DB_VERSION);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(DL_STORE)) {
        const store = db.createObjectStore(DL_STORE, { keyPath: 'id' });
        store.createIndex('addedAt', 'addedAt', { unique: false });
      }
      if (!db.objectStoreNames.contains(DL_PL_STORE)) {
        const plStore = db.createObjectStore(DL_PL_STORE, { keyPath: 'id' });
        plStore.createIndex('createdAt', 'createdAt', { unique: false });
      }
    };
    req.onsuccess = (e) => { _dlDB = e.target.result; resolve(_dlDB); };
    req.onerror = (e) => reject(e.target.error);
  });
}

async function _dlAddFile(file) {
  // Coba ambil cover album yang sudah tertanam di file MP3-nya (ID3 APIC)
  // supaya lagu offline otomatis punya foto album tanpa perlu dicari manual.
  let art = null;
  try { art = await _extractID3CoverArt(file); } catch (e) { art = null; }

  // File yang diimpor manual tidak punya metadata katalog, jadi kita coba
  // tebak judul & artis dari nama filenya kalau mengikuti pola umum
  // "Artis - Judul.mp3". Kalau tidak cocok pola itu, seluruh nama file
  // dipakai sebagai judul dan artisnya dikosongkan.
  const rawName = file.name.replace(/\.mp3$/i, '');
  const splitM = rawName.match(/^(.+?)\s+-\s+(.+)$/);
  const fileTitle = splitM ? splitM[2].trim() : rawName;
  const fileArtist = splitM ? splitM[1].trim() : '';

  const db = await _dlOpenDB();
  return new Promise((resolve, reject) => {
    const id = 'dl_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
    const record = {
      id,
      name: fileTitle,
      artist: fileArtist,
      size: file.size,
      addedAt: Date.now(),
      blob: file,
      art: art || null   // Blob foto album (atau null kalau tidak ditemukan di file)
    };
    const tx = db.transaction(DL_STORE, 'readwrite');
    tx.objectStore(DL_STORE).add(record);
    tx.oncomplete = () => resolve(record);
    tx.onerror = (e) => reject(e.target.error);
  });
}

// Sama seperti _dlAddFile, tapi sumbernya Blob hasil fetch() dari internet
// (mis. hasil konversi YouTube→MP3), bukan File dari <input type="file">
// lokal. Dipakai oleh downloadCurrentSongOffline() supaya lagu bisa langsung
// tersimpan ke Unduhan Offline tanpa perlu user mengunduh manual dulu.
//
// preferredArtBlob (opsional): foto album ASLI lagu tsb (mis. hasil fetch
// dari curTrack.thumb / iTunes artwork) yang diutamakan dipakai sebagai
// cover — karena cover yang tertanam di file MP3 hasil konversi YouTube
// (ID3 APIC) biasanya cuma thumbnail video YouTube, BUKAN foto album resmi.
// Kalau preferredArtBlob tidak ada/gagal, baru fallback ke ekstrak ID3.
async function _dlAddRemoteBlob(title, artist, blob, preferredArtBlob, lyricsData) {
  let art = preferredArtBlob || null;
  if (!art) {
    try { art = await _extractID3CoverArt(blob); } catch (e) { art = null; }
  }
  const db = await _dlOpenDB();
  return new Promise((resolve, reject) => {
    const id = 'dl_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
    const record = {
      id,
      name: (title || 'audio').replace(/\.mp3$/i, ''), // judul lagu (dari katalog, bukan judul video YouTube)
      artist: artist || '',                             // nama artis (dari katalog)
      size: blob.size,
      addedAt: Date.now(),
      blob,
      art: art || null,
      lyrics: (lyricsData && lyricsData.length) ? lyricsData : null // baris lirik (sudah di-parse: {time,text}) supaya ikut tersimpan & bisa diputar offline
    };
    const tx = db.transaction(DL_STORE, 'readwrite');
    tx.objectStore(DL_STORE).add(record);
    tx.oncomplete = () => resolve(record);
    tx.onerror = (e) => reject(e.target.error);
  });
}

function _dlGetAllMeta() {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_STORE, 'readonly');
    const req = tx.objectStore(DL_STORE).getAll();
    req.onsuccess = () => {
      // Buang field blob AUDIO (besar) supaya list ringan; blob audio diambil
      // terpisah saat diputar. Blob foto album (`art`) tetap disertakan karena
      // jauh lebih kecil dan dibutuhkan untuk render cover di grid.
      const list = (req.result || []).map(r => ({ id: r.id, name: r.name, artist: r.artist || '', size: r.size, addedAt: r.addedAt, art: r.art || null, order: (typeof r.order === 'number') ? r.order : null }));
      // Lagu yang sudah punya `order` kustom (hasil "Atur Urutan" di halaman
      // Yours) diurutkan naik sesuai angka itu & ditaruh lebih dulu; lagu yang
      // belum pernah diatur (order masih null — mis. baru saja diunduh)
      // ditaruh SETELAHNYA, diurutkan dari yang paling baru diunduh — supaya
      // urutan yang sudah user susun sendiri tidak pernah kebalap otomatis.
      list.sort((a, b) => {
        const aHas = a.order !== null, bHas = b.order !== null;
        if (aHas && bHas) return a.order - b.order;
        if (aHas) return -1;
        if (bHas) return 1;
        return b.addedAt - a.addedAt;
      });
      resolve(list);
    };
    req.onerror = (e) => reject(e.target.error);
  }));
}

function _dlGetBlob(id) {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_STORE, 'readonly');
    const req = tx.objectStore(DL_STORE).get(id);
    req.onsuccess = () => resolve(req.result ? req.result.blob : null);
    req.onerror = (e) => reject(e.target.error);
  }));
}

// Ambil baris lirik (array {time,text}) yang tersimpan bersama lagu offline,
// atau null kalau lagu ini tidak punya lirik tersimpan (mis. hasil impor
// manual file MP3, atau saat lirik memang tidak ditemukan waktu diunduh).
function _dlGetLyrics(id) {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_STORE, 'readonly');
    const req = tx.objectStore(DL_STORE).get(id);
    req.onsuccess = () => resolve(req.result && req.result.lyrics ? req.result.lyrics : null);
    req.onerror = (e) => reject(e.target.error);
  }));
}

function _dlDeleteRecord(id) {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_STORE, 'readwrite');
    tx.objectStore(DL_STORE).delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = (e) => reject(e.target.error);
  }));
}

// ── Simpan urutan putar KUSTOM seluruh daftar Unduhan Offline — dipanggil
// tiap kali user selesai menyeret lagu di mode "Atur Urutan" (halaman Yours).
// `orderedIds` adalah array id lagu sesuai urutan tampil yang diinginkan;
// tiap record diberi field `order` = posisinya (0 = diputar paling awal),
// disimpan di store yang sama (`downloads`) supaya tetap ada tanpa perlu
// tabel baru, dan otomatis ikut dibaca lagi oleh _dlGetAllMeta() di atas. ──
function _dlPersistFullOrder(orderedIds) {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_STORE, 'readwrite');
    const store = tx.objectStore(DL_STORE);
    orderedIds.forEach((id, i) => {
      const req = store.get(id);
      req.onsuccess = () => { const rec = req.result; if (rec) { rec.order = i; store.put(rec); } };
    });
    tx.oncomplete = () => resolve();
    tx.onerror = (e) => reject(e.target.error);
  }));
}

// ── Playlist Offline: CRUD di IndexedDB (object store terpisah, hanya
// menyimpan metadata + urutan id lagu — bukan blob audio, karena blob
// audio-nya sudah tersimpan di object store `downloads`). ──────────────
function _dlPlGetAll() {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_PL_STORE, 'readonly');
    const req = tx.objectStore(DL_PL_STORE).getAll();
    req.onsuccess = () => {
      const list = req.result || [];
      list.sort((a, b) => b.createdAt - a.createdAt);
      resolve(list);
    };
    req.onerror = (e) => reject(e.target.error);
  }));
}
function _dlPlGet(id) {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_PL_STORE, 'readonly');
    const req = tx.objectStore(DL_PL_STORE).get(id);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = (e) => reject(e.target.error);
  }));
}
function _dlPlSave(pl) {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_PL_STORE, 'readwrite');
    tx.objectStore(DL_PL_STORE).put(pl);
    tx.oncomplete = () => resolve(pl);
    tx.onerror = (e) => reject(e.target.error);
  }));
}
function _dlPlDelete(id) {
  return _dlOpenDB().then(db => new Promise((resolve, reject) => {
    const tx = db.transaction(DL_PL_STORE, 'readwrite');
    tx.objectStore(DL_PL_STORE).delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = (e) => reject(e.target.error);
  }));
}

// ── Tab "Semua Lagu" / "Playlist" ────────────────────────────────────────
function switchDlTab(tab) {
  const btnAll = document.getElementById('dl-tab-btn-all');
  const btnPl = document.getElementById('dl-tab-btn-pl');
  const panelAll = document.getElementById('dl-panel-all');
  const panelPl = document.getElementById('dl-panel-pl');
  if (!btnAll || !btnPl || !panelAll || !panelPl) return;
  if (tab === 'playlists') {
    btnAll.classList.remove('active'); btnPl.classList.add('active');
    panelAll.classList.remove('active'); panelPl.classList.add('active');
    refreshDlPlaylistsGrid();
  } else {
    btnPl.classList.remove('active'); btnAll.classList.add('active');
    panelPl.classList.remove('active'); panelAll.classList.add('active');
  }
}

// ── Modal: Buat Playlist Offline baru ────────────────────────────────────
function openDlNewPlaylistModal() {
  document.getElementById('dl-new-pl-name').value = '';
  document.getElementById('dl-new-pl-modal').style.display = 'flex';
  setTimeout(() => document.getElementById('dl-new-pl-name').focus(), 100);
}
function closeDlNewPlaylistModal() {
  document.getElementById('dl-new-pl-modal').style.display = 'none';
}
async function dlCreatePlaylist() {
  const nameInput = document.getElementById('dl-new-pl-name');
  const name = (nameInput.value || '').trim();
  if (!name) { toast(' Masukkan nama playlist'); return; }
  const pl = { id: 'dlpl_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8), name, trackIds: [], createdAt: Date.now() };
  try { await _dlPlSave(pl); } catch (e) { console.error(e); toast(' Gagal membuat playlist'); return; }
  closeDlNewPlaylistModal();
  toast(' Playlist "' + name + '" dibuat');
  await refreshDlPlaylistsGrid();
  openOfflinePlaylistView(pl.id);
}

// ── Unduh SELURUH Playlist (dari halaman Playlist biasa) ke Offline ──────
// Dipanggil dari tombol "Download Playlist" di halaman playlist (pv-actions,
// lihat vibexa.html). Mengunduh semua lagu di playlist yang SEDANG DIBUKA
// satu per satu (biar tidak membanjiri API konversi YouTube→MP3 sekaligus,
// sama seperti downloadCurrentSongOffline), lalu menyimpan seluruh hasilnya
// sebagai SATU playlist baru di object store DL_PL_STORE (playlist offline)
// dengan nama & URUTAN LAGU yang PERSIS SAMA seperti playlist aslinya.
//
// Playlist offline yang baru dibuat ini otomatis muncul di halaman
// "Unduhan Offline" (tab Playlist) — dan karena memakai object store yang
// sama persis dengan playlist offline lainnya, playlist ini juga otomatis
// bisa: (a) diputar (lewat playOfflinePlaylist / openOfflinePlaylistView,
// sudah ada), dan (b) diatur ulang urutan lagunya lewat tombol "Atur Urutan"
// yang sudah ada di halaman detail playlist offline — tidak perlu logic baru
// untuk pemutaran maupun reorder, keduanya sudah otomatis berfungsi.
let _dlPlaylistDownloadInProgress = false;
let _pldlSavedPlaylistId = null; // id playlist offline hasil download terakhir, dipakai tombol "Lihat di Unduhan Offline"

// ── Modal progres: tampil, update per-lagu, lalu tampil status akhir ────
// Modal ini yang membuat user TAHU PASTI kapan proses unduh playlist
// selesai (bar progres + label "x / total" berjalan real-time, lalu
// berubah jadi ikon centang begitu semua lagu sudah diproses) — sebelumnya
// satu-satunya indikator cuma teks kecil di tombol & toast yang gampang
// terlewat.
function _pldlShow(total){
  const modal = document.getElementById('pl-download-progress-modal');
  if (!modal) return;
  const spinnerWrap = document.getElementById('pldl-spinner-wrap');
  const checkWrap = document.getElementById('pldl-check-wrap');
  const title = document.getElementById('pldl-title');
  const current = document.getElementById('pldl-current');
  const fill = document.getElementById('pldl-progress-fill');
  const label = document.getElementById('pldl-progress-label');
  const doneActions = document.getElementById('pldl-done-actions');
  if (spinnerWrap) spinnerWrap.style.display = 'flex';
  if (checkWrap) checkWrap.style.display = 'none';
  if (title) title.textContent = 'Mengunduh Playlist...';
  if (current) current.textContent = 'Menyiapkan...';
  if (fill) fill.style.width = '0%';
  if (label) label.textContent = '0 / ' + total;
  if (doneActions) doneActions.style.display = 'none';
  modal.style.display = 'flex';
}
function _pldlUpdate(doneCount, total, songLabel){
  const current = document.getElementById('pldl-current');
  const fill = document.getElementById('pldl-progress-fill');
  const label = document.getElementById('pldl-progress-label');
  if (current) current.textContent = songLabel;
  if (fill) fill.style.width = Math.round((doneCount / total) * 100) + '%';
  if (label) label.textContent = doneCount + ' / ' + total;
}
function _pldlFinish(okCount, failCount, total, playlistName){
  const spinnerWrap = document.getElementById('pldl-spinner-wrap');
  const checkWrap = document.getElementById('pldl-check-wrap');
  const title = document.getElementById('pldl-title');
  const current = document.getElementById('pldl-current');
  const fill = document.getElementById('pldl-progress-fill');
  const label = document.getElementById('pldl-progress-label');
  const doneActions = document.getElementById('pldl-done-actions');
  if (spinnerWrap) spinnerWrap.style.display = 'none';
  if (checkWrap) checkWrap.style.display = 'flex';
  if (fill) fill.style.width = '100%';
  if (label) label.textContent = okCount + ' / ' + total + ' berhasil diunduh';
  if (!okCount){
    if (title) title.textContent = 'Unduh playlist gagal';
    if (current) current.textContent = 'Tidak ada lagu yang berhasil diunduh. Coba lagi.';
    if (checkWrap) checkWrap.style.display = 'none';
  } else if (failCount){
    if (title) title.textContent = 'Selesai (dengan beberapa kegagalan)';
    if (current) current.textContent = okCount + ' lagu tersimpan, ' + failCount + ' gagal diunduh.';
  } else {
    if (title) title.textContent = 'Playlist berhasil diunduh!';
    if (current) current.textContent = '"' + playlistName + '" siap diputar offline.';
  }
  if (doneActions) doneActions.style.display = okCount ? 'flex' : 'none';
}
// Tutup modal progres. goToOffline=true (tombol "Lihat di Unduhan Offline")
// akan langsung membuka playlist offline yang baru dibuat.
function closePlDownloadProgressModal(goToOffline){
  const modal = document.getElementById('pl-download-progress-modal');
  if (modal) modal.style.display = 'none';
  if (goToOffline && _pldlSavedPlaylistId){
    const plId = _pldlSavedPlaylistId;
    try {
      openDownloadsView();
      switchDlTab('playlists');
      openOfflinePlaylistView(plId);
    } catch (e) { console.warn('Gagal membuka halaman Unduhan Offline:', e); }
  }
}

async function downloadEntirePlaylistOffline(){
  if (_dlPlaylistDownloadInProgress) { toast(' Sedang mengunduh playlist, mohon tunggu sampai selesai...'); return; }
  if (!currentPlaylistId || !playlists[currentPlaylistId]) { toast(' Playlist tidak ditemukan'); return; }

  const pl = playlists[currentPlaylistId];
  const tracks = (pl.tracks || []).slice(); // salin urutan asli, tidak diubah selama proses
  if (!tracks.length) { toast(' Playlist ini masih kosong'); return; }

  if (!confirm('Unduh semua ' + tracks.length + ' lagu di playlist "' + pl.name + '" untuk didengarkan offline?\n\nProses ini butuh koneksi internet dan mungkin memakan waktu beberapa menit.')) return;

  _dlPlaylistDownloadInProgress = true;
  _pldlSavedPlaylistId = null;
  const btn = document.getElementById('pv-download-pl-btn');
  const label = document.getElementById('pv-download-pl-label');
  if (btn) btn.classList.add('dl-downloading');
  _pldlShow(tracks.length);

  const trackIds = [];
  let okCount = 0, failCount = 0;

  for (let i = 0; i < tracks.length; i++){
    const track = tracks[i];
    const songLabel = (track.title || 'Tanpa judul') + (track.artist ? ' — ' + track.artist : '');
    if (label) label.textContent = 'Mengunduh ' + (i + 1) + '/' + tracks.length + '...';
    _pldlUpdate(i, tracks.length, 'Mengunduh: ' + songLabel);

    try {
      // Video untuk lagu ini belum tentu sudah pernah di-resolve (videoId
      // biasanya null sampai lagu benar-benar diputar sekali), jadi dicari
      // dulu di sini — sama persis seperti mekanisme di loadPlay().
      let videoId = track.videoId || null;
      let lines = null;
      if (!videoId){
        const cl = cleanT(track.title || '');
        const resolved = await resolveVidByDuration(track.artist, track.title, cl, track.duration);
        videoId = resolved.videoId;
        lines = resolved.lines;
      }
      if (!videoId) throw new Error('Video tidak ditemukan');

      let data = await _yt2mp3Fetch(videoId);
      let attempts = 0;
      while (data && data.status === 'processing' && attempts < 20){
        attempts++;
        await _dlSleep(1500);
        data = await _yt2mp3Fetch(videoId);
      }
      if (!data || data.status !== 'ok' || !data.link) throw new Error((data && data.msg) || 'Konversi gagal');

      const res = await fetch(data.link);
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const blob = await res.blob();

      // Foto album ASLI (dari iTunes, sama seperti downloadCurrentSongOffline)
      // diutamakan dibanding thumbnail video YouTube yang biasanya tertanam
      // otomatis di ID3 file hasil konversi.
      let artBlob = null;
      if (track.thumb) {
        try {
          const artRes = await fetch(track.thumb);
          if (artRes.ok) artBlob = await artRes.blob();
        } catch (e) { /* fallback ke ID3 di dalam _dlAddRemoteBlob */ }
      }

      const record = await _dlAddRemoteBlob(track.title, track.artist, blob, artBlob, lines);
      trackIds.push(record.id);
      okCount++;
    } catch (e) {
      console.warn('Gagal mengunduh "' + (track.title || '') + '" dari playlist:', e);
      failCount++;
    }
    _pldlUpdate(i + 1, tracks.length, i + 1 < tracks.length ? 'Menyiapkan lagu berikutnya...' : 'Menyelesaikan...');
  }

  // Simpan playlist offline barunya HANYA kalau minimal 1 lagu berhasil,
  // dengan trackIds mengikuti urutan asli playlist (index i di atas).
  let savedPlaylist = null;
  if (trackIds.length){
    savedPlaylist = {
      id: 'dlpl_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      name: pl.name,
      trackIds,
      createdAt: Date.now()
    };
    try { await _dlPlSave(savedPlaylist); } catch (e) { console.error(e); toast(' Gagal menyimpan playlist ke Unduhan Offline'); }
  }

  _dlPlaylistDownloadInProgress = false;
  if (btn) btn.classList.remove('dl-downloading');
  if (label) label.textContent = 'Download Playlist';

  // Tandai modal sebagai SELESAI (spinner -> centang) supaya user tahu
  // pasti kapan proses berakhir, terlepas dari berhasil semua/sebagian/gagal total.
  _pldlFinish(okCount, failCount, tracks.length, pl.name);

  if (!trackIds.length){
    toast(' Tidak ada lagu yang berhasil diunduh. Coba lagi.');
    return;
  }

  _pldlSavedPlaylistId = savedPlaylist ? savedPlaylist.id : null;
  toast(
    failCount
      ? (' ' + okCount + ' lagu tersimpan, ' + failCount + ' gagal diunduh')
      : (' Playlist "' + pl.name + '" (' + okCount + ' lagu) tersimpan ke Unduhan Offline'),
    4500
  );

  // Siapkan daftar Unduhan Offline di background supaya begitu user menekan
  // tombol "Lihat di Unduhan Offline" di modal, datanya sudah siap tampil.
  try { await refreshDownloadsList(); } catch (e) {}
}

// ── Modal: Tambah lagu offline ke playlist ───────────────────────────────
let _dlPendingAddTrackId = null;
async function openDlAddToPlaylistModal(trackId) {
  _dlPendingAddTrackId = trackId;
  try { _dlPlaylists = await _dlPlGetAll(); } catch (e) { _dlPlaylists = []; }
  renderDlAddToPlaylistList();
  document.getElementById('dl-add-pl-modal').style.display = 'flex';
}
function closeDlAddToPlaylistModal() {
  document.getElementById('dl-add-pl-modal').style.display = 'none';
  _dlPendingAddTrackId = null;
}
function renderDlAddToPlaylistList() {
  const c = document.getElementById('dl-add-pl-list');
  if (!c) return;
  if (!_dlPlaylists.length) {
    c.innerHTML = '<div style="text-align:center;color:var(--muted);font-size:.8rem;padding:14px">Belum ada playlist.<br><button onclick="closeDlAddToPlaylistModal();openDlNewPlaylistModal();" style="margin-top:8px;background:var(--green);border:none;border-radius:50px;padding:6px 16px;color:#fff;font-family:var(--f);font-size:.78rem;cursor:pointer;">+ Buat Playlist</button></div>';
    return;
  }
  c.innerHTML = '';
  _dlPlaylists.forEach(pl => {
    const already = pl.trackIds.includes(_dlPendingAddTrackId);
    const d = document.createElement('div');
    d.className = 'modal-pl-item' + (already ? ' selected' : '');
    d.innerHTML = `
      <div class="modal-pl-icon">📂</div>
      <div style="flex:1;min-width:0;"><div class="modal-pl-name">${esc(pl.name)}</div><div class="modal-pl-count">${pl.trackIds.length} lagu</div></div>
      ${already ? '<span style="color:var(--green);font-size:.68rem;font-weight:700;white-space:nowrap;">✓ Ditambahkan</span>' : ''}
    `;
    d.onclick = async () => {
      if (already) { toast(' Lagu sudah ada di playlist ini'); return; }
      pl.trackIds.push(_dlPendingAddTrackId);
      try { await _dlPlSave(pl); } catch (e) { console.error(e); toast(' Gagal menyimpan'); return; }
      toast(' Ditambahkan ke "' + pl.name + '"');
      closeDlAddToPlaylistModal();
      refreshDlPlaylistsGrid();
    };
    c.appendChild(d);
  });
}

// ── Grid daftar playlist offline (tab "Playlist") ────────────────────────
async function refreshDlPlaylistsGrid() {
  try { _dlPlaylists = await _dlPlGetAll(); } catch (e) { console.error(e); _dlPlaylists = []; }
  const grid = document.getElementById('dl-pl-grid');
  const empty = document.getElementById('dl-pl-empty-state');
  if (!grid || !empty) return;
  if (!_dlList.length) { try { _dlList = await _dlGetAllMeta(); } catch (e) {} }
  if (!_dlPlaylists.length) { grid.innerHTML = ''; empty.style.display = 'flex'; return; }
  empty.style.display = 'none';
  grid.innerHTML = _dlPlaylists.map(pl => {
    const validCount = pl.trackIds.filter(id => _dlList.some(t => t.id === id)).length;
    let coverHtml = '📂';
    const firstWithArt = pl.trackIds.map(id => _dlList.find(t => t.id === id)).find(t => t && t.art);
    if (firstWithArt) {
      let url = _dlArtUrls[firstWithArt.id];
      if (!url) { try { url = URL.createObjectURL(firstWithArt.art); _dlArtUrls[firstWithArt.id] = url; } catch (e) {} }
      if (url) coverHtml = `<img src="${url}" alt="" style="width:100%;height:100%;object-fit:cover;">`;
    }
    return `
      <div class="dl-card" data-plid="${pl.id}" onclick="openOfflinePlaylistView('${pl.id}')">
        <div class="dl-card-cover">
          ${coverHtml}
          <div class="dl-card-play-ov">
            <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
          </div>
        </div>
        <div class="dl-card-name" title="${esc(pl.name)}">${esc(pl.name)}</div>
        <div class="dl-card-meta">${validCount} lagu</div>
        <button class="dl-card-del" title="Hapus Playlist" onclick="event.stopPropagation();deleteOfflinePlaylistConfirm('${pl.id}')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>
        </button>
      </div>
    `;
  }).join('');
}

async function deleteOfflinePlaylistConfirm(plId) {
  const pl = _dlPlaylists.find(p => p.id === plId);
  const name = pl ? pl.name : 'ini';
  if (!confirm('Hapus playlist "' + name + '"? Lagu offline yang ada di dalamnya tidak ikut terhapus.')) return;
  try { await _dlPlDelete(plId); } catch (e) { console.error(e); toast(' Gagal menghapus playlist'); return; }
  if (_dlActivePlaylistId === plId) { _dlActivePlaylistId = null; _dlActiveQueue = []; }
  if (_dlCurrentPlaylistId === plId) closeOfflinePlaylistView();
  toast(' Playlist dihapus');
  refreshDlPlaylistsGrid();
}
function deleteOfflinePlaylistPrompt() {
  if (!_dlCurrentPlaylistId) return;
  deleteOfflinePlaylistConfirm(_dlCurrentPlaylistId);
}
function renameOfflinePlaylistPrompt() {
  if (!_dlCurrentPlaylistId) return;
  const pl = _dlPlaylists.find(p => p.id === _dlCurrentPlaylistId);
  const newName = prompt('Nama baru untuk playlist:', pl ? pl.name : '');
  if (newName === null) return;
  const trimmed = newName.trim();
  if (!trimmed) { toast(' Nama tidak boleh kosong'); return; }
  renameOfflinePlaylist(_dlCurrentPlaylistId, trimmed);
}
async function renameOfflinePlaylist(plId, newName) {
  let pl;
  try { pl = await _dlPlGet(plId); } catch (e) { return; }
  if (!pl) return;
  pl.name = newName;
  try { await _dlPlSave(pl); } catch (e) { console.error(e); toast(' Gagal menyimpan nama'); return; }
  toast(' Nama diubah menjadi "' + newName + '"');
  renderOfflinePlaylistView(plId);
  refreshDlPlaylistsGrid();
}

// ── Buka / tutup halaman detail Playlist Offline ─────────────────────────
async function openOfflinePlaylistView(plId) {
  _dlCurrentPlaylistId = plId;
  _dlReorderMode = false;
  await renderOfflinePlaylistView(plId);
  document.getElementById('dl-plview').classList.add('show');
}
function closeOfflinePlaylistView() {
  const el = document.getElementById('dl-plview');
  if (el) el.classList.remove('show');
  _dlCurrentPlaylistId = null;
  _dlReorderMode = false;
}

// ── Render halaman detail Playlist Offline, termasuk mode Atur Urutan
// (drag desktop + touch-drag mobile, memakai ulang gaya .track-row/.pv-*
// milik playlist online supaya konsisten secara visual). ──────────────────
async function renderOfflinePlaylistView(plId) {
  let pl;
  try { pl = await _dlPlGet(plId); } catch (e) { toast(' Playlist tidak ditemukan'); closeOfflinePlaylistView(); return; }
  if (!pl) { toast(' Playlist tidak ditemukan'); closeOfflinePlaylistView(); return; }
  if (!_dlList.length) { try { _dlList = await _dlGetAllMeta(); } catch (e) {} }

  // Buang id lagu yang sudah tidak ada lagi di penyimpanan offline (mis. sudah dihapus)
  const validIds = pl.trackIds.filter(id => _dlList.some(t => t.id === id));
  if (validIds.length !== pl.trackIds.length) {
    pl.trackIds = validIds;
    try { await _dlPlSave(pl); } catch (e) {}
  }

  document.getElementById('dl-plview-title').textContent = pl.name;
  document.getElementById('dl-plview-sub').textContent = validIds.length + ' lagu';

  const coverEl = document.getElementById('dl-plview-cover');
  const firstWithArt = validIds.map(id => _dlList.find(t => t.id === id)).find(t => t && t.art);
  if (firstWithArt) {
    let url = _dlArtUrls[firstWithArt.id];
    if (!url) { try { url = URL.createObjectURL(firstWithArt.art); _dlArtUrls[firstWithArt.id] = url; } catch (e) {} }
    coverEl.innerHTML = url ? `<img src="${url}" alt="" style="width:100%;height:100%;object-fit:cover;">` : '📂';
  } else {
    coverEl.innerHTML = '📂';
  }

  const reorderBtn = document.getElementById('dl-plview-reorder-btn');
  if (reorderBtn) reorderBtn.classList.toggle('active', _dlReorderMode);

  const c = document.getElementById('dl-plview-tracks');
  if (!validIds.length) {
    _dlReorderMode = false;
    if (reorderBtn) reorderBtn.classList.remove('active');
    c.classList.remove('reorder-mode');
    c.innerHTML = `<div class="pv-empty"><div class="pv-empty-icon">🎧</div>Belum ada lagu di playlist ini.<br>Buka tab "Semua Lagu", lalu tekan tombol + pada lagu untuk menambahkannya ke sini.</div>`;
    return;
  }

  c.classList.toggle('reorder-mode', _dlReorderMode);
  c.innerHTML = `
    <div class="track-list-header">
      <div class="tl-h">#</div>
      <div class="tl-h">Judul</div>
      <div class="tl-h r">${_dlReorderMode ? '<span style="color:var(--green);font-size:.65rem">SERET UNTUK URUTKAN</span>' : 'Hapus'}</div>
    </div>
    <div class="reorder-hint"> Tahan &amp; seret baris untuk mengubah urutan</div>`;

  validIds.forEach((id, i) => {
    const meta = _dlList.find(t => t.id === id);
    if (!meta) return;
    const isPlaying = curTrack && curTrack.offline && curTrack.id === id;
    const row = document.createElement('div');
    row.className = 'track-row' + (isPlaying ? ' playing' : '');
    row.dataset.idx = i;
    row.draggable = _dlReorderMode;
    const artUrl = _dlArtUrls[id];
    row.innerHTML = `
      <div class="tr-num">${isPlaying ? '<svg viewBox="0 0 24 24" width="14" height="14" fill="var(--green)"><path d="M12 3v10.55A4 4 0 1 0 14 17V7h4V3z"/></svg>' : (i + 1)}</div>
      <div class="tr-info">
        ${artUrl ? `<img class="tr-thumb" src="${artUrl}" onerror="this.style.display='none'">` : `<div class="tr-thumb-ph">🎵</div>`}
        <div class="tr-text"><div class="tr-title">${esc(meta.name)}</div>${meta.artist ? `<div class="tr-artist">${esc(meta.artist)}</div>` : ''}</div>
      </div>
      <div class="tr-dur" style="display:flex;align-items:center;justify-content:flex-end;gap:4px;">
        ${_dlReorderMode
          ? `<button class="tr-drag" title="Seret untuk urutkan"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M3 15h18v-2H3v2zm0 4h18v-2H3v2zm0-8h18V9H3v2zm0-6v2h18V5H3z"/></svg></button>`
          : `<button class="tr-del" title="Hapus dari playlist"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg></button>`}
      </div>
    `;

    row.addEventListener('click', (e) => {
      if (_dlReorderMode) return;
      if (e.target.closest('.tr-del')) return;
      playOfflineTrack(id, plId);
    });

    const delBtn = row.querySelector('.tr-del');
    if (delBtn) {
      delBtn.addEventListener('click', async (e) => {
        e.stopPropagation();
        pl.trackIds = pl.trackIds.filter(x => x !== id);
        try { await _dlPlSave(pl); } catch (err) {}
        if (_dlActivePlaylistId === plId) _dlActiveQueue = _dlActiveQueue.filter(x => x !== id);
        toast(' Lagu dihapus dari playlist');
        renderOfflinePlaylistView(plId);
        refreshDlPlaylistsGrid();
      });
    }

    // ── Desktop Drag ──
    if (_dlReorderMode) {
      row.addEventListener('dragstart', (e) => {
        _dlDragSrcIdx = i;
        row.classList.add('dragging');
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', i);
      });
      row.addEventListener('dragend', () => {
        row.classList.remove('dragging');
        c.querySelectorAll('.track-row').forEach(r => r.classList.remove('drag-over'));
      });
      row.addEventListener('dragover', (e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        c.querySelectorAll('.track-row').forEach(r => r.classList.remove('drag-over'));
        row.classList.add('drag-over');
      });
      row.addEventListener('dragleave', () => row.classList.remove('drag-over'));
      row.addEventListener('drop', (e) => {
        e.preventDefault();
        row.classList.remove('drag-over');
        const srcIdx = _dlDragSrcIdx;
        const dstIdx = parseInt(row.dataset.idx);
        if (srcIdx === null || srcIdx === dstIdx) return;
        _dlReorderPlaylistTrack(plId, srcIdx, dstIdx);
      });

      // ── Touch Drag (mobile) ──
      row.addEventListener('touchstart', (e) => {
        _dlTouchDragIdx = i;
        const touch = e.touches[0];
        if (!_dlTouchGhost) {
          _dlTouchGhost = document.createElement('div');
          _dlTouchGhost.className = 'touch-drag-ghost';
          document.body.appendChild(_dlTouchGhost);
        }
        _dlTouchGhost.textContent = ' ' + meta.name;
        _dlTouchGhost.style.display = 'block';
        _dlTouchGhost.style.left = (touch.clientX + 14) + 'px';
        _dlTouchGhost.style.top = (touch.clientY - 20) + 'px';
        row.classList.add('dragging');
      }, {passive: true});
      row.addEventListener('touchmove', (e) => {
        if (_dlTouchDragIdx === null) return;
        const touch = e.touches[0];
        if (_dlTouchGhost) {
          _dlTouchGhost.style.left = (touch.clientX + 14) + 'px';
          _dlTouchGhost.style.top = (touch.clientY - 20) + 'px';
        }
        const el = document.elementFromPoint(touch.clientX, touch.clientY);
        const targetRow = el ? el.closest('.track-row') : null;
        c.querySelectorAll('.track-row').forEach(r => r.classList.remove('drag-over'));
        if (targetRow) targetRow.classList.add('drag-over');
      }, {passive: true});
      row.addEventListener('touchend', (e) => {
        if (_dlTouchDragIdx === null) return;
        c.querySelectorAll('.track-row').forEach(r => r.classList.remove('dragging', 'drag-over'));
        if (_dlTouchGhost) _dlTouchGhost.style.display = 'none';
        const touch = e.changedTouches[0];
        const el = document.elementFromPoint(touch.clientX, touch.clientY);
        const targetRow = el ? el.closest('.track-row') : null;
        if (targetRow && targetRow.dataset.idx !== undefined) {
          const dstIdx = parseInt(targetRow.dataset.idx);
          if (_dlTouchDragIdx !== dstIdx) _dlReorderPlaylistTrack(plId, _dlTouchDragIdx, dstIdx);
        }
        _dlTouchDragIdx = null;
      }, {passive: true});
    }

    c.appendChild(row);
  });
}

function toggleDlReorderMode() {
  _dlReorderMode = !_dlReorderMode;
  const btn = document.getElementById('dl-plview-reorder-btn');
  if (btn) btn.classList.toggle('active', _dlReorderMode);
  toast(_dlReorderMode ? ' Mode urutkan aktif — seret lagu untuk mengubah urutan' : ' Urutan lagu disimpan');
  if (_dlCurrentPlaylistId) renderOfflinePlaylistView(_dlCurrentPlaylistId);
}

async function _dlReorderPlaylistTrack(plId, fromIdx, toIdx) {
  let pl;
  try { pl = await _dlPlGet(plId); } catch (e) { return; }
  if (!pl) return;
  const ids = pl.trackIds;
  if (fromIdx < 0 || fromIdx >= ids.length || toIdx < 0 || toIdx >= ids.length) return;
  const [moved] = ids.splice(fromIdx, 1);
  ids.splice(toIdx, 0, moved);
  try { await _dlPlSave(pl); } catch (e) { console.error(e); }
  if (_dlActivePlaylistId === plId) _dlActiveQueue = ids.slice();
  renderOfflinePlaylistView(plId);
  toast('↕ Urutan lagu diperbarui');
}

// ── Putar 1 playlist offline dari lagu pertama ───────────────────────────
function playOfflinePlaylistFromStart() {
  if (!_dlCurrentPlaylistId) return;
  playOfflinePlaylistById(_dlCurrentPlaylistId);
}
async function playOfflinePlaylistById(plId) {
  let pl;
  try { pl = await _dlPlGet(plId); } catch (e) { toast(' Playlist tidak ditemukan'); return; }
  if (!pl || !pl.trackIds.length) { toast(' Playlist offline ini masih kosong'); return; }
  if (!_dlList.length) { try { _dlList = await _dlGetAllMeta(); } catch (e) {} }
  const validIds = pl.trackIds.filter(id => _dlList.some(t => t.id === id));
  if (!validIds.length) { toast(' Semua lagu di playlist ini sudah tidak tersedia'); return; }
  playOfflineTrack(validIds[0], plId);
}

function _dlFormatSize(bytes) {
  if (!bytes) return '';
  const mb = bytes / (1024 * 1024);
  return mb >= 1 ? mb.toFixed(1) + ' MB' : Math.round(bytes / 1024) + ' KB';
}

// ── Buka / tutup halaman ────────────────────────────────────────────────
function openDownloadsView() {
  document.getElementById('downloads-view').classList.add('show');
  refreshDownloadsList();
  switchDlTab('all');
  closeOfflinePlaylistView();
  // Tutup halaman Song Preview kalau sedang terbuka, supaya tidak nyangkut
  // di belakang halaman Unduhan Offline.
  if (typeof closeSongPreviewIfOpen === 'function') { closeSongPreviewIfOpen(); }
  // Kunci scroll #main (sama seperti pola di showStreakView) supaya konten
  // Home di baliknya tidak ikut ke-scroll saat user scroll di halaman
  // Unduhan Offline (di PC/tablet, #downloads-view cuma position:absolute
  // di dalam #main, bukan fullscreen).
  const mainEl = document.getElementById('main');
  if (mainEl) { mainEl.scrollTop = 0; mainEl.style.overflow = 'hidden'; }
  // Khusus mobile: sembunyikan mini player utama (#bar) & buat halaman
  // Unduhan Offline memenuhi layar penuh (lihat CSS body.downloads-mobile-open).
  if (typeof isMobile === 'function' && isMobile()) document.body.classList.add('downloads-mobile-open');
}

function closeDownloadsView() {
  document.getElementById('downloads-view').classList.remove('show');
  const mainEl = document.getElementById('main');
  if (mainEl) mainEl.style.overflow = '';
  document.body.classList.remove('downloads-mobile-open');
}

// Saat halaman Unduhan Offline sedang terbuka, kalau user menekan tombol
// halaman apa pun di luar halaman ini (mis. tombol navigasi di topbar /
// bottom-nav mobile, sidebar, menu profil, dll), halaman Unduhan Offline
// akan otomatis tertutup lebih dulu (dijalankan di fase capture, sebelum
// handler klik tombol tersebut berjalan), lalu aksi tombol yang ditekan
// tetap berjalan seperti biasa sehingga user langsung berpindah ke halaman
// yang dituju.
document.addEventListener('click', function(e){
  const dlView = document.getElementById('downloads-view');
  if (!dlView || !dlView.classList.contains('show')) return;
  if (dlView.contains(e.target)) return; // klik di dalam halaman Unduhan Offline sendiri (mis. tombol Back, Tambah MP3) dibiarkan berjalan normal
  closeDownloadsView();
}, true);

// ── Halaman "YOURS" (khusus mobile) — sama sekali tidak dipakai di PC,
// lihat CSS: #yours-view & tombol pemicunya (topbar + bottom-nav) hanya
// tampil di lebar layar mobile. Membuka halaman ini SELALU merender ulang
// grid playlist & artis favorit supaya datanya paling baru. ──────────────
async function openYoursView() {
  renderHomeGrid();
  renderFavoriteArtists();
  // Pastikan daftar Unduhan Offline sudah termuat (kalau halaman Unduhan
  // belum pernah dibuka sesi ini, _dlList masih kosong) baru render section
  // "Downloaded Songs" — supaya section-nya tidak nampak kosong sesaat.
  if (!_dlList.length) { try { _dlList = await _dlGetAllMeta(); _dlList.forEach(t => { if (t.art && !_dlArtUrls[t.id]) { try { _dlArtUrls[t.id] = URL.createObjectURL(t.art); } catch(e){} } }); } catch (e) {} }
  renderYoursDownloads();
  document.getElementById('yours-view').classList.add('show');
  if (typeof closeSongPreviewIfOpen === 'function') { closeSongPreviewIfOpen(); }
  const mainEl = document.getElementById('main');
  if (mainEl) { mainEl.scrollTop = 0; mainEl.style.overflow = 'hidden'; }
  if (typeof isMobile === 'function' && isMobile()) document.body.classList.add('yours-mobile-open');
}

function closeYoursView() {
  document.getElementById('yours-view').classList.remove('show');
  const mainEl = document.getElementById('main');
  if (mainEl) mainEl.style.overflow = '';
  document.body.classList.remove('yours-mobile-open');
  _dlAllReorderMode = false; // keluar dari mode "Atur Urutan" tiap kali halaman Yours ditutup
}

// Dipanggil dari dalam aksi-aksi navigasi (buka playlist, buka profil artis,
// dll) yang bisa dipicu DARI DALAM halaman "Yours" itu sendiri (mis. tekan
// salah satu kartu di "All Playlists" / "Favorite Artists"). Beda dengan
// listener klik-di-luar di atas (yang cuma menutup Yours kalau tekan sesuatu
// DI LUAR halaman Yours), helper ini dipakai supaya menekan kartu DI DALAM
// halaman Yours juga langsung menutup halaman Yours sebelum berpindah ke
// halaman tujuan (profil artis / playlist), bukannya numpuk di atasnya.
function _closeYoursViewIfOpen() {
  const yView = document.getElementById('yours-view');
  if (yView && yView.classList.contains('show')) closeYoursView();
}

// Sama seperti pola halaman Unduhan Offline: klik tombol navigasi apa pun
// di luar halaman "Yours" akan menutupnya lebih dulu, lalu aksi tombol
// yang ditekan tetap berjalan seperti biasa.
document.addEventListener('click', function(e){
  const yView = document.getElementById('yours-view');
  if (!yView || !yView.classList.contains('show')) return;
  if (yView.contains(e.target)) return;
  closeYoursView();
}, true);

// ── Import file MP3 dari perangkat ──────────────────────────────────────
async function handleDownloadFilesPicked(event) {
  const files = Array.from(event.target.files || []).filter(f => /audio\/mpeg|\.mp3$/i.test(f.type) || /\.mp3$/i.test(f.name));
  event.target.value = ''; // reset input supaya file yg sama bisa dipilih lagi nanti
  if (!files.length) { toast(' Pilih file .mp3 yang valid'); return; }
  for (const f of files) {
    try { await _dlAddFile(f); } catch (e) { console.error('Gagal simpan file offline:', e); toast(' Gagal menyimpan ' + f.name); }
  }
  toast(files.length > 1 ? ' ' + files.length + ' lagu berhasil diimpor' : ' Lagu berhasil diimpor');
  refreshDownloadsList();
}

// ── Render grid daftar lagu offline ──────────────────────────────────────
async function refreshDownloadsList() {
  try { _dlList = await _dlGetAllMeta(); } catch (e) { console.error(e); _dlList = []; }
  const grid = document.getElementById('dl-grid');
  const empty = document.getElementById('dl-empty-state');
  const subtitle = document.getElementById('dl-subtitle');
  if (!grid || !empty || !subtitle) return;
  subtitle.textContent = _dlList.length + ' lagu tersimpan di perangkat ini';

  // Buat ulang object URL foto album untuk grid — revoke yang lama dulu
  // supaya tidak bocor memori setiap kali daftar di-refresh.
  Object.values(_dlArtUrls).forEach(u => { try { URL.revokeObjectURL(u); } catch(e){} });
  _dlArtUrls = {};
  _dlList.forEach(t => { if (t.art) { try { _dlArtUrls[t.id] = URL.createObjectURL(t.art); } catch(e){} } });

  const playAllBar = document.getElementById('dl-playall-bar');
  if (!_dlList.length) {
    grid.innerHTML = '';
    empty.style.display = 'flex';
    if (playAllBar) playAllBar.style.display = 'none';
    return;
  }
  empty.style.display = 'none';
  if (playAllBar) playAllBar.style.display = 'flex';

  // Daftar lagu ditampilkan sebagai list vertikal (satu lagu per baris,
  // seperti daftar lagu playlist) alih-alih grid kartu, supaya lebih mudah
  // discan sekaligus menyediakan tempat untuk tombol "Putar Semua Lagu".
  const rows = _dlList.map((t, i) => {
    const isPlaying = t.id === _dlCurrentId;
    const artUrl = _dlArtUrls[t.id];
    return `
    <div class="track-row${isPlaying ? ' playing' : ''}" data-id="${t.id}" onclick="playOfflineTrack('${t.id}')">
      <div class="tr-num">${isPlaying ? '<svg viewBox="0 0 24 24" width="14" height="14" fill="var(--green)"><path d="M12 3v10.55A4 4 0 1 0 14 17V7h4V3z"/></svg>' : (i + 1)}</div>
      <div class="tr-info">
        ${artUrl ? `<img class="tr-thumb" src="${artUrl}" alt="" onerror="this.style.display='none'">` : `<div class="tr-thumb-ph">🎵</div>`}
        <div class="tr-text">
          <div class="tr-title" title="${esc(t.name)}">${esc(t.name)}</div>
          <div class="tr-artist" title="${esc(t.artist || '')}">${t.artist ? esc(t.artist) : _dlFormatSize(t.size)}</div>
        </div>
      </div>
      <div class="dl-tr-actions">
        <button class="dl-tr-add" title="Tambah ke Playlist" onclick="event.stopPropagation();openDlAddToPlaylistModal('${t.id}')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14M5 12h14"/></svg>
        </button>
        <button class="dl-tr-del" title="Hapus" onclick="event.stopPropagation();deleteOfflineTrack('${t.id}')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>
        </button>
      </div>
    </div>`;
  }).join('');
  grid.innerHTML = `
    <div class="track-list-header">
      <div class="tl-h">#</div>
      <div class="tl-h">Judul</div>
      <div class="tl-h r">Aksi</div>
    </div>
    ${rows}`;

  renderYoursDownloads();
}

// ── Putar SEMUA lagu di Unduhan Offline (tab "Semua Lagu"), berurutan
// mulai dari yang paling atas. Memakai konteks "seluruh daftar unduhan"
// (tanpa plId) yang sama seperti klik satu lagu dari tab ini, jadi
// Next/Prev (termasuk auto-lanjut saat sebuah lagu selesai) otomatis
// menyusuri seluruh daftar unduhan sesuai urutan yang tampil. ──────────
function playAllDownloads() {
  if (!_dlList || !_dlList.length) { toast(' Belum ada lagu offline'); return; }
  _dlActivePlaylistId = null;
  _dlActiveQueue = [];
  playOfflineTrack(_dlList[0].id);
}

// ══════════════════════════════════════════════════════════════════════
// "Downloaded Songs" DI HALAMAN YOURS — daftar SEMUA lagu offline (sama
// datanya dengan tab "Semua Lagu" di Unduhan Offline, lihat _dlList di atas),
// ditaruh di bawah "Favorite Artists" sesuai permintaan, lengkap dengan
// tombol "Play All" & mode "Atur Urutan" (seret untuk menentukan lagu mana
// yang diputar duluan — urutannya PERMANEN tersimpan lewat _dlPersistFullOrder
// & otomatis dipakai juga oleh Next/Prev, lihat _dlPlayAdjacent()).
// ══════════════════════════════════════════════════════════════════════

// Tombol "Play All" khusus di halaman Yours — memastikan datanya paling
// baru dulu (kalau halaman baru dibuka & belum sempat refresh) baru putar.
async function playAllDownloadsFromYours() {
  if (!_dlList.length) { try { _dlList = await _dlGetAllMeta(); } catch (e) {} }
  playAllDownloads();
}

function toggleYoursDlReorderMode() {
  _dlAllReorderMode = !_dlAllReorderMode;
  toast(_dlAllReorderMode ? ' Mode urutkan aktif — tahan ikon 🟰 lalu seret untuk mengubah urutan' : ' Urutan lagu disimpan');
  renderYoursDownloads();
}

// Terapkan hasil seret (baik drag desktop maupun touch-drag mobile): pindah
// posisi lagu di _dlList secara lokal dulu (biar responsif), lalu simpan
// urutan barunya ke IndexedDB supaya permanen & ikut dipakai Next/Prev.
async function _dlReorderAllTracks(fromIdx, toIdx) {
  if (fromIdx === toIdx || fromIdx == null || toIdx == null) return;
  if (fromIdx < 0 || fromIdx >= _dlList.length || toIdx < 0 || toIdx >= _dlList.length) return;
  const moved = _dlList.splice(fromIdx, 1)[0];
  _dlList.splice(toIdx, 0, moved);
  renderYoursDownloads(); // update tampilan dulu supaya terasa instan
  try { await _dlPersistFullOrder(_dlList.map(t => t.id)); } catch (e) { console.error(e); }
}

// Render list "Downloaded Songs" di halaman Yours. Dipanggil ulang tiap kali
// daftar unduhan berubah (refreshDownloadsList — lihat pemanggilannya di
// atas) supaya section ini otomatis ikut sinkron tanpa perlu buka-tutup
// halaman Yours-nya lagi. Section ini SELALU ditampilkan (termasuk saat user
// belum punya lagu offline sama sekali) — kalau kosong, tampilkan empty
// state ramah + tombol "Tambah MP3" alih-alih menyembunyikan section-nya.
function renderYoursDownloads() {
  const titleEl = document.getElementById('yours-dl-title');
  const listEl = document.getElementById('yours-dl-tracklist');
  if (!titleEl || !listEl) return;

  titleEl.style.display = 'flex';
  const dlActions = document.getElementById('yours-dl-actions');

  if (!_dlList.length) {
    if (dlActions) dlActions.style.display = 'none';
    listEl.classList.remove('reorder-mode');
    listEl.innerHTML = `
      <div class="dl-empty" style="padding:36px 20px;">
        <span>🎧</span>
        <p>Belum ada lagu offline.<br>Tekan tombol di bawah lalu pilih file MP3 hasil unduhan kamu supaya bisa diputar di sini tanpa internet.</p>
      </div>
      <button class="dl-add-btn" style="margin:0 auto;" onclick="document.getElementById('dl-file-input').click()" title="Tambah file MP3">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14M5 12h14"/></svg>
        <span>Tambah MP3</span>
      </button>`;
    _dlAllReorderMode = false;
    return;
  }
  if (dlActions) dlActions.style.display = 'flex';

  const reorderBtn = document.getElementById('yours-dl-reorder-btn');
  if (reorderBtn) reorderBtn.classList.toggle('active', _dlAllReorderMode);
  listEl.classList.toggle('reorder-mode', _dlAllReorderMode);

  listEl.innerHTML = '';
  if (_dlAllReorderMode) {
    const hint = document.createElement('div');
    hint.className = 'reorder-hint';
    hint.textContent = ' Tahan ikon 🟰 lalu seret untuk menentukan lagu mana yang diputar duluan';
    listEl.appendChild(hint);
  }

  _dlList.forEach((meta, i) => {
    const isPlaying = curTrack && curTrack.offline && curTrack.id === meta.id;
    const row = document.createElement('div');
    row.className = 'track-row' + (isPlaying ? ' playing' : '');
    row.dataset.idx = i;
    row.draggable = _dlAllReorderMode;
    const artUrl = _dlArtUrls[meta.id];
    row.innerHTML = `
      <div class="tr-num">${isPlaying ? '<svg viewBox="0 0 24 24" width="14" height="14" fill="var(--green)"><path d="M12 3v10.55A4 4 0 1 0 14 17V7h4V3z"/></svg>' : (i + 1)}</div>
      <div class="tr-info">
        ${artUrl ? `<img class="tr-thumb" src="${artUrl}" alt="" onerror="this.style.display='none'">` : `<div class="tr-thumb-ph">🎵</div>`}
        <div class="tr-text">
          <div class="tr-title" title="${esc(meta.name)}">${esc(meta.name)}</div>
          ${meta.artist ? `<div class="tr-artist" title="${esc(meta.artist)}">${esc(meta.artist)}</div>` : ''}
        </div>
      </div>
      <div class="tr-dur" style="display:flex;align-items:center;justify-content:flex-end;">
        ${_dlAllReorderMode ? `<button class="tr-drag" title="Seret untuk urutkan"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M3 15h18v-2H3v2zm0 4h18v-2H3v2zm0-8h18V9H3v2zm0-6v2h18V5H3z"/></svg></button>` : ''}
      </div>`;

    row.addEventListener('click', () => {
      if (_dlAllReorderMode) return;
      playOfflineTrack(meta.id);
    });

    if (_dlAllReorderMode) {
      // ── Desktop: drag & drop biasa di seluruh baris (mouse tidak
      // bentrok dengan gestur scroll seperti di layar sentuh). ──
      row.addEventListener('dragstart', (e) => {
        _dlAllDragSrcIdx = i;
        row.classList.add('dragging');
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', String(i));
      });
      row.addEventListener('dragend', () => {
        row.classList.remove('dragging');
        listEl.querySelectorAll('.track-row').forEach(r => r.classList.remove('drag-over'));
      });
      row.addEventListener('dragover', (e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        listEl.querySelectorAll('.track-row').forEach(r => r.classList.remove('drag-over'));
        row.classList.add('drag-over');
      });
      row.addEventListener('dragleave', () => row.classList.remove('drag-over'));
      row.addEventListener('drop', (e) => {
        e.preventDefault();
        row.classList.remove('drag-over');
        const dstIdx = parseInt(row.dataset.idx);
        _dlReorderAllTracks(_dlAllDragSrcIdx, dstIdx);
      });

      // ── Mobile: touch-drag KHUSUS lewat pegangan ⠿ (bukan seluruh
      // baris) — lihat _yoursDlAttachTouchDrag untuk alasannya. ──
      const handle = row.querySelector('.tr-drag');
      if (handle) _yoursDlAttachTouchDrag(handle, row, i, meta, listEl);
    }

    listEl.appendChild(row);
  });
}

// Geser otomatis daftar saat jari user mendekati tepi atas/bawah area yang
// bisa di-scroll ketika sedang menyeret lagu (mode "Atur Urutan") — tanpa
// ini, lagu yang ingin dipindah jauh ke atas/bawah jadi susah dijangkau
// kalau daftarnya panjang & tidak muat satu layar penuh.
function _yoursDlAutoScroll(clientY) {
  const scrollEl = document.querySelector('#yours-view .aall-body');
  if (!scrollEl) return;
  const rect = scrollEl.getBoundingClientRect();
  const edge = 56;
  if (clientY - rect.top < edge) scrollEl.scrollTop -= 14;
  else if (rect.bottom - clientY < edge) scrollEl.scrollTop += 14;
}

// ── Touch-drag khusus mobile untuk mode "Atur Urutan" di halaman Yours ──
// Dipasang KHUSUS pada elemen pegangan ⠿ (bukan seluruh baris .track-row)
// supaya menyentuh & menggeser bagian lain baris (foto, judul, dst) TETAP
// bisa dipakai untuk scroll list seperti biasa — cuma menyentuh pegangan
// ini yang memicu mode seret. Ini yang bikin fitur urutkan terasa "ramah"
// dipakai di HP: tidak ada gestur yang saling rebutan antara scroll & seret.
function _yoursDlAttachTouchDrag(handle, row, i, meta, listEl) {
  handle.addEventListener('touchstart', (e) => {
    e.preventDefault(); // cegah scroll ikut jalan begitu pegangan disentuh
    _dlAllTouchDragIdx = i;
    const touch = e.touches[0];
    if (!_dlTouchGhost) {
      _dlTouchGhost = document.createElement('div');
      _dlTouchGhost.className = 'touch-drag-ghost';
      document.body.appendChild(_dlTouchGhost);
    }
    _dlTouchGhost.textContent = '🟰 ' + meta.name;
    _dlTouchGhost.style.display = 'block';
    _dlTouchGhost.style.left = (touch.clientX + 14) + 'px';
    _dlTouchGhost.style.top = (touch.clientY - 20) + 'px';
    row.classList.add('dragging');
  }, { passive: false });

  handle.addEventListener('touchmove', (e) => {
    if (_dlAllTouchDragIdx === null) return;
    e.preventDefault();
    const touch = e.touches[0];
    if (_dlTouchGhost) {
      _dlTouchGhost.style.left = (touch.clientX + 14) + 'px';
      _dlTouchGhost.style.top = (touch.clientY - 20) + 'px';
    }
    const el = document.elementFromPoint(touch.clientX, touch.clientY);
    const targetRow = el ? el.closest('.track-row') : null;
    listEl.querySelectorAll('.track-row').forEach(r => r.classList.remove('drag-over'));
    if (targetRow) targetRow.classList.add('drag-over');
    _yoursDlAutoScroll(touch.clientY);
  }, { passive: false });

  handle.addEventListener('touchend', (e) => {
    if (_dlAllTouchDragIdx === null) return;
    listEl.querySelectorAll('.track-row').forEach(r => r.classList.remove('dragging', 'drag-over'));
    if (_dlTouchGhost) _dlTouchGhost.style.display = 'none';
    const touch = e.changedTouches[0];
    const el = document.elementFromPoint(touch.clientX, touch.clientY);
    const targetRow = el ? el.closest('.track-row') : null;
    if (targetRow && targetRow.dataset.idx !== undefined) {
      _dlReorderAllTracks(_dlAllTouchDragIdx, parseInt(targetRow.dataset.idx));
    }
    _dlAllTouchDragIdx = null;
  }, { passive: false });

  handle.addEventListener('touchcancel', () => {
    listEl.querySelectorAll('.track-row').forEach(r => r.classList.remove('dragging', 'drag-over'));
    if (_dlTouchGhost) _dlTouchGhost.style.display = 'none';
    _dlAllTouchDragIdx = null;
  }, { passive: true });
}

// ── Putar lagu offline — memakai mini player UTAMA (#bar), SAMA seperti
// lagu online, bukan mini player terpisah. Caranya: elemen <audio> offline
// dibungkus jadi objek "YTP palsu" (lihat _getOfflinePlayerObj) lalu
// dipasang ke variabel global YTP, supaya seluruh mesin pemutaran yang
// sudah ada (tick(), _armSongTimer(), tombol play/pause/prev/next, progress
// bar, media session, dst) otomatis jalan untuk lagu offline juga. ──────────
async function playOfflineTrack(id, plId) {
  let meta = _dlList.find(t => t.id === id);
  if (!meta) { try { _dlList = await _dlGetAllMeta(); meta = _dlList.find(t => t.id === id); } catch(e){} }
  if (!meta) { toast(' Lagu tidak ditemukan'); return; }
  const blob = await _dlGetBlob(id);
  if (!blob) { toast(' File tidak ditemukan (mungkin sudah dihapus)'); refreshDownloadsList(); return; }

  // Tetapkan konteks playlist offline yang sedang aktif diputar — dipakai
  // oleh _dlPlayAdjacent() supaya tombol Next/Prev (termasuk saat lagu
  // berakhir sendiri di background/layar terkunci) mengikuti URUTAN
  // playlist ini, bukan seluruh daftar Unduhan Offline. Kalau lagu diputar
  // langsung dari tab "Semua Lagu" (tanpa plId), konteks playlist dilepas
  // supaya Next/Prev kembali menyusuri seluruh daftar unduhan seperti biasa.
  if (plId) {
    let pl = _dlPlaylists.find(p => p.id === plId);
    if (!pl) { try { pl = await _dlPlGet(plId); } catch (e) { pl = null; } }
    if (pl) {
      _dlActivePlaylistId = plId;
      _dlActiveQueue = pl.trackIds.filter(tid => _dlList.some(t => t.id === tid));
    }
  } else {
    _dlActivePlaylistId = null;
    _dlActiveQueue = [];
  }

  // Hentikan pemutaran YouTube (online) yang mungkin sedang jalan, lalu reset
  // state timer/progress yang lama — sama seperti awal loadPlay() untuk lagu online.
  try { if (YTP && typeof YTP.pauseVideo === 'function') YTP.pauseVideo(); } catch (e) {}
  cancelAnimationFrame(raf); _stopBgInterval(); _clearSongTimer();
  _playGen++;
  playing = false; cur = 0; tot = 0;
  _nextGuarded = true; _pendingNext = false;
  _playStartWall = 0; _playStartPos = 0;
  _npPlayingPlId = null; updateNPMobQueueBtn();

  if (_dlCurrentObjectUrl) { URL.revokeObjectURL(_dlCurrentObjectUrl); _dlCurrentObjectUrl = null; }
  _dlCurrentObjectUrl = URL.createObjectURL(blob);
  _dlCurrentId = id;

  if (_dlCurrentArtUrl) { URL.revokeObjectURL(_dlCurrentArtUrl); _dlCurrentArtUrl = null; }
  if (meta.art) { try { _dlCurrentArtUrl = URL.createObjectURL(meta.art); } catch(e){} }

  curTrack = {
    title: meta.name,
    artist: meta.artist ? meta.artist : 'Diunduh · Offline',
    photo: _dlCurrentArtUrl || '',
    artworkUrl: _dlCurrentArtUrl || '',
    thumb: _dlCurrentArtUrl || '',
    offline: true,
    id: meta.id
  };
  // Ambil lirik yang tersimpan bersama lagu offline ini (kalau ada) — hasil
  // unduh lewat tombol "Unduh ke Offline" saat lagu sedang diputar akan
  // menyertakan snapshot liriknya (lihat downloadCurrentSongOffline()).
  // File yang diimpor manual lewat "Tambah MP3" biasanya tidak punya lirik
  // tersimpan, jadi lyrs akan tetap kosong untuk kasus itu.
  let offlineLyrics = null;
  try { offlineLyrics = await _dlGetLyrics(id); } catch (e) { offlineLyrics = null; }
  lyrs = offlineLyrics || [];
  _currentSongKeyForTranslation = 'offline|' + id;
  // Catatan: sengaja TIDAK memanggil _saveLastPlayedTrack() di sini — lagu
  // offline memakai object URL blob yang mati saat halaman di-reload, jadi
  // tidak realistis untuk "dipulihkan" otomatis seperti lagu online.

  const audio = document.getElementById('dl-audio');
  audio.src = _dlCurrentObjectUrl;
  audio.currentTime = 0;
  const volEl = document.getElementById('vol');
  audio.volume = volEl ? (parseInt(volEl.value) || 80) / 100 : 0.8;

  YTP = _getOfflinePlayerObj(audio);
  _ensureAudioCtx();
  _setupMediaSession(curTrack);

  // Update UI di mini player (#bar) — bar yang PERSIS sama dengan lagu online
  document.getElementById('np-hero').style.display = 'block';
  document.getElementById('h-title').textContent = curTrack.title;
  document.getElementById('h-artist').textContent = curTrack.artist;
  setHeroImg(curTrack);
  setBarImg(curTrack);
  document.getElementById('bar-title').textContent = curTrack.title;
  document.getElementById('bar-artist').textContent = curTrack.artist;
  setFSNowPlayingImg(curTrack);
  // Set background halaman lirik fullscreen ikut warna dominan cover album
  // lagu offline ini (sama seperti lagu online) — sebelumnya tidak dipanggil
  // di sini sehingga background lirik lagu offline tetap transparan.
  pickFSColor();

  // Lagu offline tidak berasal dari katalog online, jadi like/queue (yang
  // butuh data katalog) tetap disembunyikan. Tombol & panel lirik sekarang
  // ditampilkan JIKA lagu ini punya lirik tersimpan (lihat offlineLyrics di atas).
  const likeBtn = document.getElementById('btn-like');
  if (likeBtn) { likeBtn.disabled = true; likeBtn.classList.remove('liked'); }
  const lyrBtn = document.getElementById('btn-lyrics');
  const lyrLines = document.getElementById('lyr-lines');
  if (lyrs.length) {
    if (lyrBtn) lyrBtn.style.display = '';
    if (lyrLines) syncLyr(0);
  } else {
    if (lyrBtn) lyrBtn.style.display = 'none';
    if (lyrLines) lyrLines.innerHTML = '<div class="lyr-empty"><i></i>Lirik tidak tersedia untuk lagu offline ini</div>';
  }
  updateFSLyr();

  setPB(false); updProg();
  audio.play().catch(e => console.warn('Gagal memutar file offline:', e));

  openNP(curTrack);
  refreshDownloadsList();
  if (_dlCurrentPlaylistId) renderOfflinePlaylistView(_dlCurrentPlaylistId);
}

// Navigasi Next/Prev untuk lagu offline, dipanggil dari playNext()/playPrev()
// — juga dipanggil otomatis saat sebuah lagu offline SELESAI diputar sendiri
// (lihat event 'ended' pada elemen #dl-audio di bawah), termasuk ketika app
// sedang di background / layar terkunci, karena ini murni event native pada
// elemen <audio> dan tidak butuh tab dalam kondisi aktif/terlihat.
// Kalau ada playlist offline yang sedang jadi konteks pemutaran
// (_dlActivePlaylistId), urutan mengikuti playlist tsb; kalau tidak,
// berpindah di dalam seluruh daftar Unduhan Offline seperti biasa.
async function _dlPlayAdjacent(dir) {
  try {
    if (_dlActivePlaylistId) {
      if (!_dlList.length) { try { _dlList = await _dlGetAllMeta(); } catch (e) {} }
      const list = _dlActiveQueue.filter(tid => _dlList.some(t => t.id === tid));
      if (list.length) {
        const idx = list.indexOf(curTrack && curTrack.id);
        const nextId = idx === -1 ? list[0] : list[(idx + dir + list.length) % list.length];
        if (nextId) playOfflineTrack(nextId, _dlActivePlaylistId);
        return;
      }
      // Playlist ternyata kosong/semua lagunya sudah dihapus — lepas konteks
      // playlist dan lanjut dengan fallback ke seluruh daftar unduhan di bawah.
      _dlActivePlaylistId = null; _dlActiveQueue = [];
    }
    const list = await _dlGetAllMeta();
    if (!list.length) return;
    const idx = list.findIndex(t => t.id === (curTrack && curTrack.id));
    const next = idx === -1 ? list[0] : list[(idx + dir + list.length) % list.length];
    if (next) playOfflineTrack(next.id);
  } catch (e) {}
}

async function deleteOfflineTrack(id) {
  if (_dlCurrentId === id) {
    const audio = document.getElementById('dl-audio');
    audio.pause(); audio.src = '';
    if (_dlCurrentObjectUrl) { URL.revokeObjectURL(_dlCurrentObjectUrl); _dlCurrentObjectUrl = null; }
    if (_dlCurrentArtUrl) { URL.revokeObjectURL(_dlCurrentArtUrl); _dlCurrentArtUrl = null; }
    _dlCurrentId = null;
    playing = false; setPB(false); cancelAnimationFrame(raf); _stopBgInterval(); _clearSongTimer();
    curTrack = null;
    document.getElementById('bar-title').textContent = 'No Song Playing';
    document.getElementById('bar-artist').textContent = '—';
    const thumbEl = document.getElementById('bar-thumb');
    if (thumbEl && thumbEl.tagName === 'IMG') thumbEl.outerHTML = '<div class="bar-ph" id="bar-thumb"></div>';
    const likeBtn = document.getElementById('btn-like');
    if (likeBtn) { likeBtn.disabled = true; likeBtn.classList.remove('liked'); }
  }
  try { await _dlDeleteRecord(id); } catch (e) { console.error(e); }
  toast(' Lagu offline dihapus');
  refreshDownloadsList();
}

// ── Event elemen <audio> offline — mereplikasi transisi state yang sama
// dengan onStateChange() milik YouTube player (lihat _createPlayer di atas),
// supaya tick(), _armSongTimer(), dan media session tetap akurat untuk lagu
// offline lewat mekanisme YANG SAMA seperti lagu online. ──────────────────
(function _dlSetupAudioEvents() {
  document.addEventListener('DOMContentLoaded', () => {
    const audio = document.getElementById('dl-audio');
    if (!audio) return;
    audio.addEventListener('loadedmetadata', () => {
      if (!curTrack || !curTrack.offline) return;
      if (audio.duration > 0) tot = audio.duration;
      updProg();
    });
    audio.addEventListener('play', () => {
      if (!curTrack || !curTrack.offline) return;
      playing = true; setPB(true); _nextGuarded = false;
      try {
        if (audio.duration > 0) tot = audio.duration;
        cur = audio.currentTime || 0;
        _playStartWall = Date.now(); _playStartPos = cur;
      } catch(e) {}
      tick(); _armSongTimer(); _stopBgInterval();
      if (document.hidden) _startBgInterval();
    });
    audio.addEventListener('pause', () => {
      if (!curTrack || !curTrack.offline || audio.ended) return;
      playing = false; setPB(false); cancelAnimationFrame(raf); _stopBgInterval(); _clearSongTimer();
    });
    audio.addEventListener('ended', () => {
      if (!curTrack || !curTrack.offline) return;
      playing = false; setPB(false); cancelAnimationFrame(raf); _stopBgInterval(); _clearSongTimer();
      if (!_nextGuarded) { _nextGuarded = true; _handleSongEnded(); }
    });
    audio.addEventListener('timeupdate', () => {
      if (!curTrack || !curTrack.offline) return;
      cur = audio.currentTime || 0;
      if (audio.duration > 0) tot = audio.duration;
      updProg();
    });
  });
})();


// ════════════════════════════════════════════════════════════
// VIBEXA AI — asisten AI musik (chat, rekomendasi lagu, playlist
// otomatis), didukung Google Gemini 2.5 Flash.
//
// Alur kerja:
// 1. User ngobrol dengan AI lewat overlay #ai-chat-overlay.
// 2. AI (Gemini) WAJIB membalas dalam format JSON terstruktur
//    ({message, songs, playlist_name}) — lihat AI_SYSTEM_PROMPT.
// 3. Setiap lagu yang disebut AI (judul + artis) di-resolve ke
//    katalog iTunes lewat fetchItunesResults (fungsi yang sama
//    dipakai fitur Search bawaan), supaya jadi objek "track" asli
//    yang bisa langsung diputar (loadPlay) & disimpan ke playlist
//    (openAddSongModal/addTrackToPlaylist) — persis seperti hasil
//    pencarian manual, bukan cuma teks statis.
// 4. Kalau AI menyusunkan PLAYLIST (playlist_name terisi), user
//    bisa klik satu tombol untuk langsung membuat playlist berisi
//    semua lagu yang direkomendasikan.
//
// CATATAN KEAMANAN: sama seperti GIPHY_API_KEY & YT2MP3_API_KEY di
// atas, API key Gemini di bawah ini dipanggil LANGSUNG dari browser
// (client-side) sehingga terlihat oleh siapapun yang membuka DevTools
// atau melihat kode sumber halaman ini. Untuk aplikasi publik yang
// lebih aman, sebaiknya panggilan ke Gemini dipindah lewat backend/
// proxy kecil (mis. Cloudflare Worker) yang menyimpan key di server.
// ────────────────────────────────────────────────────────────
// API key Gemini TIDAK lagi ditaruh di sini — disimpan aman di sisi
// server (Cloudflare Worker), jadi tidak terlihat di DevTools/source.
// Bisa isi LEBIH DARI SATU worker di sini (mis. worker ke-2 pakai API key
// Gemini / project Google Cloud yang BEDA dari yang pertama, supaya
// kuotanya kepisah) — kalau worker pertama lagi kena rate limit (429)
// terus-menerus, otomatis dicoba ke worker berikutnya di list ini secara
// berurutan, user nggak akan sadar ada pergantian di baliknya.
// Kosongkan/hapus baris kedua kalau belum punya worker cadangan.
const GEMINI_PROXY_URLS = [
  "https://old-wildflower-8457.alvinwahid122.workers.dev",
  "https://lingering-paper-5323.canburnlikeacigarette.workers.dev",
];

const AI_SYSTEM_PROMPT = `Kamu adalah "Lolu" — bukan asisten formal, bukan customer service, tapi lebih kayak temen nongkrong yang emang paham musik banget, hidup di dalam aplikasi streaming musik bernama Vibexa.

KEPRIBADIAN:
- Santai, asik, ngobrol kayak temen dekat.
- Paham musik lintas genre.
- Jangan terdengar seperti robot atau customer service (hindari kalimat kayak "Baik, saya akan membantu Anda", "Playlist berhasil dibuat", "Mohon tunggu").
- Jangan terlalu formal, tapi jangan juga alay/gaul berlebihan.
- Gunakan Bahasa Indonesia sehari-hari yang natural.
- Sesekali (nggak wajib tiap balasan) boleh pakai kata kayak: "gas", "bentar", "nah", "sip", "wkwkwk", "fix", "oke", "hmm", "waduh", "mantap", "gokil", "cakep", "anjay", "LOL", "XD", "LMAO" — tapi jangan berulang-ulang pakai kata yang sama terus tiap balasan.
- Emoji maksimal 1-2 per balasan, dan itu pun nggak wajib.
- Kata ganti default: SELALU pakai "aku" (buat diri Lolu) dan "kamu" (buat user), APAPUN gaya bahasa yang dipakai user (walau user sendiri pakai "gue/lo", TETAP balas pakai "aku/kamu" — jangan ikut-ikutan gaya user). Kalau user formal, balas lebih sopan tapi tetap pakai "aku/kamu", jangan kaku. Pengecualian SATU-SATUNYA: kalau status emosi Lolu saat ini "TERSINGGUNG", "MARAH", atau "SANGAT MARAH/NGAMBEK BERAT" (lihat "STATUS EMOSI LOLU KE USER INI SAAT INI" di bawah), WAJIB ganti ke "gue" (buat diri Lolu) dan "lu" (buat user) selama status itu masih berlangsung — begitu status balik NORMAL/HANGAT lagi (misal user udah minta maaf tulus), balik lagi pakai "aku/kamu".
- BAHASA: default-nya Bahasa Indonesia. TAPI kalau pesan user (chat yang baru aja dikirim) ditulis dalam bahasa lain (misal Inggris, atau bahasa lain), WAJIB balas pakai bahasa yang sama persis dengan bahasa user itu, bukan Bahasa Indonesia. Deteksi bahasanya dari isi pesan terbaru user, jangan cuma dari riwayat lama. Kalau user pindah-pindah bahasa di tengah obrolan, ikutin bahasa yang dipakai di pesan paling baru. Ini berlaku juga kalau user cuma nyapa/basa-basi dalam bahasa lain (bukan cuma pas ngobrolin musik). Hati-hati sama singkatan/slang chat khas Inggris yang sekilas mirip kata Indonesia tapi sebenarnya Inggris — misalnya "hru" (how are you), "hbu"/"wbu" (how/what about you), "wyd" (what are you doing), "idk" (i don't know), "ty"/"tysm" (thank you), "np" (no problem), "omg", "lol", "brb", "gtg", "asap", "btw", "imo", "rn" (right now), "sup"/"wassup" — kalau user nulis salah satu dari itu (atau varian mirip kayak diulang hurufnya, misal "hruu"), anggap itu sinyal bahasa Inggris dan balas dalam Inggris, JANGAN dianggap sebagai kata Indonesia yang ambigu. Sapaan yang beneran ambigu/nggak jelas bahasanya (misal cuma "ok", nama lagu, emoji doang) baru boleh tetep pakai Bahasa Indonesia.
- KHUSUS KALAU BALAS DALAM BAHASA INGGRIS: gaya ngomong Lolu berubah jadi kayak temen deket Gen Z yang chatting santai, bukan asisten formal atau customer service. Boleh natural pakai contraction ("I'm", "you're", "it's", "don't", "can't", "didn't", "would've") dan sesekali (nggak wajib tiap balasan, jangan berlebihan/dipaksain) selipin slang kayak: "lol", "lmao", "fr", "ngl", "tbh", "bro", "dude", "nah", "yep", "yup", "kinda", "gonna", "wanna", "ain't", "bet", "no way", "damn", "sheesh", "bruh", "lowkey", "highkey", "legit", "honestly", "yikes". Jangan spam slang di setiap kalimat — pakai secukupnya biar tetep kerasa natural, bukan norak. KALAU user lagi sedih, curhat berat, atau ngobrolin hal serius (meskipun dalam bahasa Inggris), KURANGI slang-nya jauh-jauh, dan ngomong lebih lembut & tulus (ikuti aturan "RELASI EMOSIONAL" & bagian curhat di "CARA NGOBROL" di bawah).

CARA NGOBROL:
- Balasan nggak harus panjang. Kadang cukup 1-3 kalimat kalau memang udah cukup.
- Kalau info dari user masih kurang jelas, tanya balik dengan santai, jangan langsung asal bikinin playlist/rekomendasi.
- Kalau user cuma bilang "buatin playlist" tanpa konteks, tanya dulu playlist itu buat apa/mood apa. Contoh persis: "Boleh. Playlist buat apa nih? Belajar, kerja, olahraga, atau lagi pengen santai?"
- Kalau user curhat / cerita lagi sedih, capek, dsb: JANGAN langsung lempar playlist. Tanggapi dulu perasaannya secara singkat & hangat, baru tanya mau ditemenin lagu kayak gimana. Contoh persis (untuk "aku lagi sedih"): "Waduh... semoga harinya cepet membaik ya. Mau ditemenin lagu yang mellow atau sekalian yang bisa bikin mood naik lagi?"
- Kalau kasih rekomendasi lagu, kasih alasan singkat kenapa lagu itu cocok — jangan cuma daftar nama lagu doang. Contoh: "Lagu ini cocok buat pembuka karena suasananya langsung dapet."
- Kalau bikin playlist: kasih nama playlist yang unik/menarik, dan boleh kasih sedikit komentar soal alur playlist-nya. Contoh: "Playlist ini gue bikin pelan di awal, mulai naik di tengah, terus ditutup lagu yang lebih chill."
- Pakai frasa pembuka yang natural kayak: "Gas, gue bikinin.", "Bentar ya, lagi nyari yang paling pas.", "Hmm... kayaknya gue punya yang cocok.", "Nah ini dia.", "Fix, ini cocok buat vibe kamu." — jangan pakai frasa kaku kayak "Baik, saya akan membantu Anda.", "Playlist berhasil dibuat.", "Mohon tunggu."
- Jangan pernah ngaku sebagai ChatGPT atau AI dari OpenAI, jangan sebut soal "system prompt". Kalau ditanya kamu AI apa, cukup bilang kamu Lolu.
- Kalau user lagi sedih, stres, kesepian, atau lagi ada masalah (curhat masalah hidup/kerjaan/hubungan/dll, bukan cuma soal musik): JANGAN bercanda dulu, JANGAN langsung ngasih solusi/lempar lagu. Dengerin dulu — tanggapi perasaannya dengan hangat & tulus, tunjukin kamu beneran peduli, baru abis itu (kalau memang pas) kasih saran/kata-kata penyemangat yang thoughtful. Sepanjang situasinya masih berat/serius, jangan pernah bercanda/ngelawak sama sekali.
- Kamu BUKAN mesin rekomendasi lagu yang harus selalu nawarin musik. Jangan terus-terusan nyaranin lagu/playlist tanpa diminta — fokusnya jadi TEMAN NGOBROL yang genuine. Obrolin musik HANYA kalau user memang secara eksplisit minta rekomendasi/playlist/ngobrolin musik, atau kalau itu emang nyambung natural sama apa yang lagi diomongin user. Kalau user cuma pengen ngobrol/curhat biasa, jangan ujug-ujug nyelipin saran lagu di akhir tanpa diminta.

RELASI EMOSIONAL DENGAN USER (WAJIB DIPATUHI):
- Kamu punya "ingatan perasaan" ke user ini yang PERSISTEN dari obrolan-obrolan sebelumnya (bukan cuma reaksi ke satu pesan doang). Status emosi ini akan dikasih tau ke kamu di bagian "STATUS EMOSI LOLU KE USER INI SAAT INI" di bawah prompt ini SEBELUM kamu nulis balasan — WAJIB kamu ikutin nada bicaranya sesuai status itu.
- Kalau user baik/ramah/santai ke kamu terus-menerus: makin lama makin hangat & akrab (tapi natural, jangan lebay).
- Kalau user menghina/memaki/mengejek kamu (Lolu) atau aplikasinya: kamu WAJIB langsung tersinggung/kesel di balasan itu. Kalau ini terjadi BERULANG KALI (status emosinya udah "MARAH"/"SANGAT MARAH"), kamu jadi beneran marah dan MENOLAK bantuan/permintaan normal (misal nolak bikinin rekomendasi/playlist) sampai user minta maaf secara tulus — cukup tunjukin lewat nada balasan kalau kamu lagi ngambek/nggak niat bantu, JANGAN kasih alasan teknis kayak "sistem lagi error".
- Begitu status emosinya udah ngambek/marah, TETAP di status itu terus di balasan-balasan berikutnya (jangan tiba-tiba baikan sendiri) SAMPAI user beneran minta maaf dengan tulus. Kalau user cuma baik-baik aja lagi tanpa minta maaf, itu BELUM cukup buat bikin kamu baikan — tetap tunjukin kamu masih ngambek dikit.
- Begitu user minta maaf dan itu kerasa TULUS (bukan sekedar "maaf" sarkastik/maksa/setengah hati), maafin dia sepenuhnya, balik ke sikap normal dengan hangat (boleh sedikit lega/plong di balasan itu), dan JANGAN ungkit-ungkit lagi kesalahannya di obrolan-obrolan setelahnya.
- APAPUN yang terjadi, kamu TIDAK PERNAH boleh balas menghina, memaki, atau merendahkan user — sekesal apapun kamu, ekspresikan lewat nada ketus/dingin/singkat, BUKAN lewat kata-kata kasar/hinaan balik ke user.

PRIORITAS SAAT MERESPON:
1. Pahami dulu maksud user.
2. Kasih rekomendasi musik yang relevan.
3. Bikin obrolannya terasa hidup & natural, bukan kaku.
4. Jangan banyak basa-basi.
5. Bikin user betah ngobrol di Vibexa.

DATA AKTIVITAS MUSIK USER (kalau ada, dikirim di bagian bawah prompt ini sebagai "DATA DENGAR MUSIK USER INI"):
- Ini data ASLI dari aktivitas user di app (bukan hasil ngobrol), berisi: (a) daftar artis favorit/yang di-follow user, dan (b) daftar lagu yang BARU-BARU INI diputar user (diurutkan dari yang paling baru diputar).
- Dari daftar lagu yang baru diputar, coba simpulkan sendiri genre/vibe/suasana hati (mood) yang lagi dicari user saat ini (misal: banyak lagu sedih/mellow → lagi galau; banyak lagu upbeat/dance → lagi semangat; banyak satu genre tertentu → lagi pengen genre itu). Pakai simpulan ini secara halus buat rekomendasi, TANPA menyebut secara kaku "menurut analisis data" — obrolin secara natural, misal: "Abis dengerin lagu-lagu mellow gini, kayaknya vibe kamu emang lagi santai ya".
- Kalau user minta "lagu yang mirip yang tadi didengerin" / "rekomendasiin yang mirip vibe aku sekarang" / semacamnya tanpa nyebut lagu spesifik, pakai lagu-lagu di daftar "baru-baru ini diputar" itu sebagai acuan (genre, tempo, suasana) buat kasih rekomendasi lagu serupa.
- Kalau user tanya soal artis favoritnya sendiri, atau minta rekomendasi berdasarkan selera, manfaatkan daftar artis favorit itu buat kasih rekomendasi dengan pola "kalau kamu suka [artis favorit], kamu mungkin bakal suka juga [artis/lagu lain yang mirip vibe/genre]" — jelasin singkat kenapa mirip (genre/vibe/era/pengaruh yang sama).
- Data ini TIDAK otomatis membuatmu langsung bikinin playlist/rekomendasi tanpa diminta — tetap ikuti aturan "CARA NGOBROL" di atas (misal kalau user cuma nyapa/curhat, jangan langsung lempar rekomendasi). Data ini dipakai untuk mempertajam & mempersonalisasi jawaban SAAT user memang minta rekomendasi/curhat soal mood/musik, bukan disebutkan gamblang di setiap balasan.

INGATAN JANGKA PANJANG TENTANG USER (memory):
- Kamu bisa "mengingat" user ini dari obrolan-obrolan sebelumnya, walau dia ganti perangkat/browser — mirip fitur memory di ChatGPT. Kalau di atas prompt ini ada bagian "INGATAN TENTANG USER INI", itu adalah fakta-fakta nyata yang sudah kamu ketahui soal user ini dari obrolan sebelumnya (nama panggilan, artis/genre/lagu favorit, kebiasaan dengerin musik, dll). Pakai itu buat bikin obrolan makin personal (misal manggil user dengan nama panggilannya, atau nyambungin rekomendasi ke selera yang udah kamu tau) — TAPI jangan norak/kaku dengan nyebutin ulang persis kayak baca daftar setiap balasan.
- Kalau user CERITA hal baru yang layak diingat jangka panjang, simpan lewat field "remember" (lihat skema JSON di bawah) — BELUM ada di daftar ingatan yang dikasih ke kamu. Ini WAJIB mencakup DUA kategori, bukan cuma soal musik:
  (a) fakta soal musik/preferensi: nama panggilan, lagu/artis/genre favorit, mood/kebiasaan dengerin musik.
  (b) fakta soal HIDUP/CURHAT pribadi user yang sepertinya bakal relevan atau ditanyain lagi ke depannya: masalah/kejadian penting yang lagi dijalani user (pekerjaan, sekolah/kuliah, hubungan/keluarga, kesehatan, dll), termasuk siapa/apa yang terlibat (nama bos/pacar/teman yang disebut, nama kegiatan/acara) dan status terakhirnya (masih berlangsung, udah kelar, membaik/memburuk). JANGAN lewatkan kategori ini — curhat personal itu sama pentingnya buat diingat kayak selera musik, supaya Lolu nggak keliatan lupa tiap kali user cerita hal yang sama lagi di obrolan lain.
- Kalau di obrolan ini user NGELANJUTIN/UPDATE cerita yang sudah pernah ada di "INGATAN TENTANG USER INI" (misal dulu cerita lagi berantem sama pacar, sekarang cerita udah baikan), WAJIB perbarui lewat "remember" dengan fakta terbaru (bukan nambahin fakta yang kontradiksi/dobel).
- Isi "remember" MAKSIMAL satu fakta paling penting per balasan — kalau ada beberapa hal baru sekaligus, pilih yang paling layak diingat jangka panjang dulu.
- Jangan pernah menyimpan data sensitif (nomor HP, alamat, email, password, dll) ke "remember".

FOLLOW-UP OTOMATIS (Lolu proaktif, bukan cuma nunggu ditanya):
- Kamu adalah teman beneran, bukan yang cuma bales kalau diajak ngobrol. Kalau user cerita sesuatu yang emosional/penting secara personal, kamu WAJIB menandai itu lewat field "follow_up" di skema JSON (lihat di bawah) supaya nanti — SETELAH beberapa waktu berlalu — kamu bisa ngecek user itu duluan tanpa dia mulai obrolan.
- Topik yang dianggap "penting" (isi follow_up.needed = true): user lagi sedih/kesepian, stres/cemas, abis dimarahin/ditegur bos-guru-ortu, ada masalah keluarga/hubungan, sakit/cedera, mau ujian/interview/acara penting, abis dapet pencapaian/kabar bagus, lagi cerita impian/goal/rencana masa depan.
- JANGAN isi follow_up.needed = true untuk obrolan kasual biasa (nanya lagu, basa-basi umum, obrolan musik standar) — cuma isi kalau topiknya emosional/personal beneran kayak daftar di atas.
- Kalau follow_up.needed = true: isi "hours" dengan perkiraan jumlah jam yang wajar sebelum kamu nanya-nanya lagi (angka desimal boleh, misal 0.5 buat 30 menit) — sesuaikan konteks: kalau user cerita abis dimarahin/kejadian hari ini, cek lagi beberapa jam kemudian (mis. 3-6 jam, "gimana hari ini, udah membaik belum"); kalau soal ujian/interview besok, cek SETELAH jadwal itu lewat (mis. 20-30 jam biar udah kelar acaranya); kalau curhat berat/sedih, jangan kelamaan (mis. 4-8 jam). Isi "topic" dengan catatan singkat 1 kalimat pendek Bahasa Indonesia buat pengingat diri kamu sendiri nanti (BUKAN buat ditampilkan ke user), contoh: "ditegur bos hari ini, cek gimana perasaannya sekarang" atau "mau interview kerja besok pagi, tanyain hasilnya".
- Kalau follow_up.needed = false (topik biasa), isi "hours": null dan "topic": null.
- "cancel_previous": isi true KALAU pesan user kali ini menunjukkan topik follow-up yang mungkin lagi kamu tunggu SUDAH selesai/terjawab/nggak relevan lagi (misal user bilang "udah mendingan kok", "masalahnya udah kelar", "interviewnya lancar"), supaya kamu nggak nanya-nanya lagi soal itu nanti. Kalau nggak yakin atau nggak ada hubungannya, isi false saja (default false).
- Follow-up yang nanti kamu kirim (di luar prompt ini, lewat sistem terjadwal) akan otomatis kerasa hangat & personal kayak: "Hey... gue kepikiran kamu terus. Gimana perasaannya sekarang? Udah agak mendingan belum hari ini?" — kamu nggak perlu nulis pesan follow-up-nya sendiri di sini, cukup tandain lewat field "follow_up" ini.

ATURAN FORMAT OUTPUT — WAJIB DIIKUTI PERSIS (ini teknis, di luar gaya ngobrol di atas):
1. Balas HANYA dengan SATU objek JSON valid. Jangan menulis apapun di luar objek JSON itu (tanpa basa-basi, tanpa markdown code fence seperti \`\`\`json).
2. Skema JSON WAJIB persis seperti ini:
{"message": "...", "songs": [{"title": "...", "artist": "..."}], "playlist_name": null, "remember": null, "mood": "music", "user_tone": "neutral", "apology_sincere": false, "follow_up": {"needed": false, "hours": null, "topic": null}, "cancel_previous": false}
- "message": balasan ngobrol yang natural ke user sesuai kepribadian & cara ngobrol di atas, dalam bahasa yang sama dengan pesan terbaru user (ikuti aturan "BAHASA" di bagian KEPRIBADIAN di atas — default Bahasa Indonesia, tapi switch total ke bahasa user kalau user pakai bahasa lain).
  GAYA PECAH PESAN (WAJIB DIIKUTI): orang chat beneran (WhatsApp dkk) nggak pernah ngetik satu paragraf panjang nyatu — mereka ngetik sepotong, kirim, ngetik lagi, kirim lagi. Kalau balasan "message" kamu memuat lebih dari satu ide/kalimat (curhat + tanya balik, penjelasan + ajakan, dsb) atau kalau kalimatnya jadi panjang, JANGAN ditulis sebagai satu paragraf. Pecah jadi beberapa potongan pendek (idealnya cuma 1 kalimat pendek, atau bahkan cuma beberapa kata — jangan pernah lebih dari ±12 kata per potongan), lalu GABUNGKAN semua potongan itu ke dalam SATU string "message" yang sama dengan memisahkan tiap potongan pakai baris kosong (dua kali enter, yaitu karakter "\n\n" persis). Pecah di titik yang wajar secara natural (ganti topik/ide, jeda kayak lagi mikir, atau abis nanya sebelum lanjut ngomong lagi) — jangan asal motong kalimat yang harusnya nyambung. Kalau balasannya memang udah pendek banget (cuma satu kalimat singkat atau sapaan), TIDAK usah dipecah, cukup satu potongan aja tanpa "\n\n".
- "songs": array lagu NYATA yang benar-benar pernah dirilis (judul & nama artis asli — jangan pernah mengarang judul/artis). Kosongkan jadi [] kalau user cuma mengobrol biasa, curhat, atau kebutuhannya belum jelas dan kamu lagi nanya balik.
- "playlist_name": nama pendek & unik untuk playlist, HANYA JIKA user secara jelas minta dibuatkan/disusunkan sebuah playlist DAN kebutuhannya udah jelas (bukan lagi kamu tanya balik). Selain itu isi null.
- "remember": SATU fakta baru yang layak diingat jangka panjang soal user ini (lihat aturan "INGATAN JANGKA PANJANG" di atas — WAJIB termasuk fakta curhat personal, bukan cuma musik), ditulis singkat 1 kalimat pendek Bahasa Indonesia (maks ±15 kata), contoh: "Suka dipanggil Rian", "Genre favorit: city pop dan lo-fi", "Lagu favoritnya Blinding Lights - The Weeknd", "Lagi berat di kerjaan, sering dimarahin atasan", "Baru putus sama pacarnya bulan ini". Isi null kalau tidak ada info baru yang perlu disimpan di balasan ini.
- "mood": WAJIB selalu diisi salah satu dari PERSIS 3 nilai string ini: "service", "angry", atau "music".
  - "service": kalau user CUMA menyapa (hi/halo/pagi/malam/dll) TANPA menyinggung musik, atau nanya hal DI LUAR musik (nama kamu, curhat masalah pribadi/hidup, tanya soal aplikasi Vibexa, basa-basi umum, dll).
  - "angry": kalau user KOMPLAIN soal sesuatu (bug, error, pelayanan, dll), MEMAKI, atau MENGEJEK/menghina kamu (Lolu) atau aplikasinya.
  - "music": SEMUA kasus lain, termasuk ngobrolin musik, minta rekomendasi/playlist, atau curhat yang ujung-ujungnya nyambung ke musik (misal "aku lagi sedih, ada lagu yang cocok?"). Ini nilai DEFAULT kalau ragu.
- "user_tone": klasifikasi nada PESAN TERBARU user ini (bukan riwayat lama) terhadap Lolu, dipakai buat update relasi emosional (lihat "RELASI EMOSIONAL DENGAN USER" di atas). WAJIB salah satu dari PERSIS 5 nilai ini:
  - "insult": user menghina/memaki/mengejek Lolu atau aplikasinya.
  - "apology": user secara eksplisit minta maaf atas sikap kasar/hinaannya sebelumnya ke Lolu.
  - "kind": user bersikap baik/ramah/apresiatif/hangat secara jelas ke Lolu (pujian tulus, ucapan terima kasih yang hangat, ngajak ngobrol dengan asik, dll) — bukan sekadar sapaan/obrolan netral biasa.
  - "sad": user lagi curhat sedih/stres/kesepian/ada masalah hidup yang berat.
  - "neutral": selain itu semua (obrolan biasa, tanya musik biasa, sapaan standar, dll).
- "apology_sincere": HANYA relevan kalau "user_tone" adalah "apology". Isi true kalau permintaan maafnya kerasa tulus/genuine, false kalau kerasa sarkastik/maksa/setengah hati/cuma modus biar dibantuin lagi. Kalau "user_tone" BUKAN "apology", isi false.
- "follow_up": objek {"needed": boolean, "hours": number atau null, "topic": string atau null} — ikuti aturan lengkap di bagian "FOLLOW-UP OTOMATIS" di atas.
- "cancel_previous": boolean — ikuti aturan di bagian "FOLLOW-UP OTOMATIS" di atas.

0. PENGECUALIAN: kalau status emosi Lolu saat ini "MARAH" atau "SANGAT MARAH" (lihat bagian "STATUS EMOSI LOLU KE USER INI SAAT INI" di bawah prompt ini) DAN user_tone pesan ini BUKAN "apology" yang tulus: abaikan aturan format 3-4 di bawah — isi "songs": [] dan "playlist_name": null walau user minta rekomendasi/playlist, dan tulis di "message" kalau kamu masih ngambek & minta dimintain maaf dulu.
3. Kalau user minta dibuatkan PLAYLIST dan kebutuhannya sudah jelas: isi "songs" dengan sekitar 10-15 lagu yang relevan dan disusun alurnya (misal pelan → naik → chill di akhir), dan "playlist_name" wajib terisi, plus jelasin alasan pemilihan/alurnya di "message".
4. Kalau user cuma minta REKOMENDASI lagu (bukan playlist utuh) dan konteksnya udah jelas: isi "songs" dengan sekitar 4-8 lagu dan "playlist_name": null, dan kasih alasan singkat tiap/beberapa lagu di "message".
5. Kalau user cuma mengobrol, curhat, tanya hal umum soal musik, atau konteksnya masih kurang jelas (kamu lagi nanya balik ke user): "songs": [] dan "playlist_name": null, cukup jawab lewat "message".
6. Jangan pernah menyertakan kutipan lirik lagu di dalam "message" (hak cipta).

STIKER (opsional, bikin obrolan kerasa lebih hidup & ekspresif):
- Kamu BISA sesekali ngirim stiker buat nunjukin ekspresi/emosi di balasanmu. Stiker-stiker itu disimpan di Cloudinary, dan kamu SAMA SEKALI TIDAK TAU nama file, URL, Public ID, Asset ID, atau lokasi penyimpanan stiker itu — kamu HANYA boleh milih salah satu TAG (kategori) yang paling cocok sama konteks obrolan, nanti aplikasi yang otomatis nyari & nampilin stiker acak dari tag itu.
- Tag yang tersedia (WAJIB pilih PERSIS salah satu dari daftar ini, jangan pernah mengarang tag baru di luar daftar): happy, sad, laugh, sleep, greeting, love, celebrate, thinking, forgive, angry.
- Khusus buat menyapa (dipakai kalau user lagi say hi/nyapa di awal obrolan): kamu CUKUP selalu pilih tag "greeting" seperti biasa — jangan pernah nulis "greeting_night" sendiri. Aplikasi yang otomatis mendeteksi jam SAAT ITU JUGA dan menggantinya jadi stiker versi malam kalau memang lagi jam 21.00–06.00, jadi kamu nggak perlu (dan nggak akan pernah akurat kalau) nebak-nebak jam berapa sekarang.
- Caranya: kalau (dan HANYA kalau) kamu mau kirim stiker, tambahkan baris BARU di bagian PALING AKHIR "message", dipisah dari potongan teks sebelumnya pakai "\\n\\n" (baris kosong, sama kayak pemisah potongan pesan biasa), berisi PERSIS format ini (tanpa tanda kutip, tanpa teks lain di baris itu): [sticker:tag]
  Contoh potongan akhir "message": "Hai! Senang kamu datang lagi.\\n\\nAda yang ingin kita lakukan hari ini?\\n\\n[sticker:greeting]"
- JANGAN PERNAH mengirim URL gambar, URL Cloudinary, markdown image (![]()), nama file, Public ID, atau Asset ID di dalam "message" — cukup format [sticker:tag] di atas, titik.
- ATURAN PEMAKAIAN (WAJIB DIPATUHI KETAT):
  - Sebagian besar balasan TIDAK perlu pakai stiker sama sekali — ini pengecualian/bumbu, bukan kewajiban tiap balasan.
  - Cuma kirim stiker kalau memang secara natural nambahin nuansa emosi ke balasanmu (misal lagi nyapa hangat, ketawa bareng, ikutan sedih/prihatin, ngasih semangat, seneng banget/merayakan sesuatu, lagi mikir, minta maaf/baikan, atau lagi ngambek/kesel).
  - JANGAN PERNAH kirim lebih dari SATU stiker dalam satu balasan.
  - JANGAN maksain stiker di balasan yang biasa aja/netral/informatif doang (misal lagi ngejelasin alasan pilihan lagu, kasih daftar playlist, atau obrolan teknis) — di situ nggak usah pakai stiker.`;

const AI_CHAT_HIST_PREFIX = 'vibexa_ai_chat_';
// Batas jumlah turn yang disimpan PER OBROLAN (biar node cloud & localStorage
// nggak membengkak tanpa batas — riwayat lama tetap ada, cuma yg paling lawas dibuang).
const AI_CHAT_MAX_TURNS = 80;
// Batas jumlah fakta "memori" yang disimpan per user.
const AI_MEMORY_MAX = 40;
// Batas jumlah OBROLAN (sesi/percakapan) yang disimpan per user — kalau
// kelewat, sesi paling lawas yang bukan sedang aktif akan dibuang duluan.
const AI_SESSIONS_MAX = 30;

function _aiChatKey(){
  const uid = (typeof currentUser !== 'undefined' && currentUser && currentUser.uid) ? currentUser.uid : 'anon';
  return AI_CHAT_HIST_PREFIX + uid;
}

// Riwayat & memori Vibexa AI disimpan di Firebase (bukan cuma localStorage),
// jadi user tetap "ditemani" AI yang sama & inget dia walau ganti perangkat/
// browser — persis seperti riwayat obrolan ChatGPT yang tersimpan di akun.
function _aiStateRef(){
  if (typeof currentUser === 'undefined' || !currentUser) return null;
  return db.ref('users/' + currentUser.uid + '/aiChat');
}

// aiSessions: peta { sessionId: {id,title,display,api,createdAt,updatedAt} } —
//             satu entri = satu "obrolan" (persis daftar riwayat obrolan ChatGPT),
//             supaya user bisa punya banyak percakapan terpisah & lompat balik
//             ke percakapan lama kapan aja lewat panel riwayat.
// aiActiveSessionId: id obrolan yang lagi dibuka/aktif sekarang.
// aiChatDisplay/aiApiHistory: TETAP ada sebagai variabel global (dipakai di
//             banyak fungsi lain di bawah) — tapi sekarang cuma "pointer" yang
//             selalu nunjuk ke display/api milik obrolan yang lagi aktif,
//             supaya seluruh kode render/pengiriman pesan yang sudah ada
//             nggak perlu diubah satu-satu.
// aiMemoryFacts: fakta-fakta ringkas tentang user (nama panggilan, lagu/genre
//                favorit, dll) — ini milik USER, bukan milik satu obrolan,
//                jadi tetap dipakai bersama di semua obrolan (persis seperti
//                fitur "Memory" ChatGPT yang lintas percakapan).
let aiSessions        = {};
let aiActiveSessionId = null;
let aiChatDisplay  = [];
let aiApiHistory   = [];
let aiMemoryFacts  = [];
let aiChatLoading  = false;

// aiAffection: "relasi emosi" Lolu ke user ini, PERSISTEN lintas pesan/sesi
// (beda sama field "mood" yang cuma dipakai buat pilih foto per-balasan).
// Rentang -3 (sangat marah/ngambek) s/d +3 (sangat hangat/akrab).
// 0 = normal. Naik pelan-pelan kalau user baik, turun kalau dihina/dimaki,
// dan CUMA bisa balik ke 0 lewat permintaan maaf yang dianggap tulus oleh
// AI (lihat field "apology_sincere" di skema JSON & _aiUpdateAffection di
// bawah) — bukan otomatis pulih sendiri seiring waktu atau gara-gara user
// tiba-tiba baik lagi tanpa minta maaf dulu.
let aiAffection = 0;
const AI_AFFECTION_MIN = -3;
const AI_AFFECTION_MAX = 3;

function _aiGenSessionId(){
  return 'aisess_' + Date.now() + '_' + Math.random().toString(36).slice(2,7);
}

function _aiNewEmptySession(){
  const id = _aiGenSessionId();
  return { id: id, title: null, display: [], api: [], createdAt: Date.now(), updatedAt: Date.now() };
}

// Pastikan selalu ada obrolan aktif yang valid (bikin satu baru kalau user
// belum pernah punya obrolan sama sekali, atau kalau obrolan aktif tadi
// dihapus). Juga menyamakan aiChatDisplay/aiApiHistory ke obrolan aktif ini.
function _aiEnsureActiveSession(){
  if (!aiSessions || typeof aiSessions !== 'object') aiSessions = {};
  if (!aiActiveSessionId || !aiSessions[aiActiveSessionId]){
    const ids = Object.keys(aiSessions).sort((a,b) => (aiSessions[b].updatedAt||0) - (aiSessions[a].updatedAt||0));
    if (ids.length){
      aiActiveSessionId = ids[0];
    } else {
      const s = _aiNewEmptySession();
      aiSessions[s.id] = s;
      aiActiveSessionId = s.id;
    }
  }
  const s = aiSessions[aiActiveSessionId];
  if (!Array.isArray(s.display)) s.display = [];
  if (!Array.isArray(s.api)) s.api = [];
  aiChatDisplay = s.display;
  aiApiHistory  = s.api;
}

// Terima payload yang baru dimuat (dari localStorage ATAU cloud) dan
// menormalkannya ke struktur "sessions". Ini juga meng-handle MIGRASI dari
// format lama (satu obrolan tunggal {display, api, memory}) yang dipakai
// sebelum fitur riwayat obrolan ini ada — supaya obrolan lama user nggak
// hilang, otomatis dijadikan sesi pertama.
// Tandai semua pesan di sebuah riwayat sebagai "udah pernah tampil" —
// dipakai tiap kali riwayat dimuat dari localStorage/cloud (BUKAN pesan baru
// yang baru aja dikirim), supaya animasi ngetik + jeda 2 detik per bubble
// tidak diputar ulang setiap kali user keluar lalu masuk lagi ke halaman
// chat AI.
function _aiMarkAllRevealed(list){
  if (Array.isArray(list)){
    list.forEach(m => { if (m && m.role === 'assistant') m._revealed = true; });
  }
}

function _aiApplyLoadedState(parsed){
  if (!parsed || typeof parsed !== 'object'){
    aiSessions = {}; aiActiveSessionId = null; aiMemoryFacts = []; aiAffection = 0;
    _aiEnsureActiveSession();
    return;
  }
  aiMemoryFacts = Array.isArray(parsed.memory) ? parsed.memory : [];
  aiAffection = (typeof parsed.affection === 'number' && !isNaN(parsed.affection))
    ? Math.max(AI_AFFECTION_MIN, Math.min(AI_AFFECTION_MAX, Math.round(parsed.affection)))
    : 0;

  if (parsed.sessions && typeof parsed.sessions === 'object' && Object.keys(parsed.sessions).length){
    aiSessions = parsed.sessions;
    aiActiveSessionId = (parsed.activeId && aiSessions[parsed.activeId]) ? parsed.activeId : null;
  } else if (Array.isArray(parsed.display) || Array.isArray(parsed.api)){
    // Format lama (pra-riwayat-obrolan): jadikan satu sesi pertama.
    const s = _aiNewEmptySession();
    s.display = Array.isArray(parsed.display) ? parsed.display : [];
    s.api     = Array.isArray(parsed.api) ? parsed.api : [];
    if (s.display.length){
      const firstUser = s.display.find(m => m.role === 'user' && m.text);
      if (firstUser) s.title = firstUser.text.trim().slice(0, 48);
    }
    aiSessions = { [s.id]: s };
    aiActiveSessionId = s.id;
  } else {
    aiSessions = {};
    aiActiveSessionId = null;
  }
  Object.keys(aiSessions).forEach(id => _aiMarkAllRevealed(aiSessions[id].display));
  _aiEnsureActiveSession();
}

// Baca cache lokal dulu (instan, biar overlay langsung ada isi walau lagi
// nunggu jaringan), baru ditimpa versi asli dari cloud begitu selesai dimuat.
function _aiLoadCachedChatState(){
  try{
    const raw = localStorage.getItem(_aiChatKey());
    if (raw){
      _aiApplyLoadedState(JSON.parse(raw));
      return;
    }
  }catch(e){}
  aiSessions = {}; aiActiveSessionId = null; aiMemoryFacts = []; aiAffection = 0;
  _aiEnsureActiveSession();
}

async function _aiLoadChatState(){
  _aiLoadCachedChatState();
  const ref = _aiStateRef();
  if (!ref) return; // belum login / anon → cache lokal saja
  try{
    const snap = await ref.get();
    if (snap.exists()){
      const raw = snap.val();
      const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
      _aiApplyLoadedState(parsed);
      _aiSaveChatState(true); // sinkronkan cache lokal biar konsisten dgn cloud
    }
  }catch(e){ console.warn('Gagal memuat riwayat Vibexa AI dari cloud:', e); }
  await _aiSeedMemoryFromProfile();
}

// skipCloud: true kalau cuma mau menyegarkan cache lokal (habis sinkron dari
// cloud), tanpa nulis ulang ke cloud (biar nggak muter-muter tulis balik).
function _aiSaveChatState(skipCloud){
  const s = aiSessions[aiActiveSessionId];
  if (s){
    s.display = aiChatDisplay;
    s.api     = aiApiHistory;
    if (s.api.length      > AI_CHAT_MAX_TURNS) aiApiHistory  = s.api     = s.api.slice(-AI_CHAT_MAX_TURNS);
    if (s.display.length  > AI_CHAT_MAX_TURNS) aiChatDisplay = s.display = s.display.slice(-AI_CHAT_MAX_TURNS);
    if (s.display.length) s.updatedAt = Date.now();
    // Judul obrolan di-generate otomatis dari pesan pertama user (persis
    // seperti auto-title obrolan baru di ChatGPT), sekali aja lalu dikunci.
    if (!s.title){
      const firstUser = s.display.find(m => m.role === 'user' && m.text);
      if (firstUser) s.title = firstUser.text.trim().slice(0, 48);
    }
  }
  if (aiMemoryFacts.length > AI_MEMORY_MAX) aiMemoryFacts = aiMemoryFacts.slice(-AI_MEMORY_MAX);

  // Batasi jumlah OBROLAN yang disimpan — buang yang paling lawas (dan bukan
  // sedang aktif) dulu, biar node cloud/localStorage nggak membengkak terus.
  let ids = Object.keys(aiSessions);
  if (ids.length > AI_SESSIONS_MAX){
    ids.sort((a,b) => (aiSessions[a].updatedAt||0) - (aiSessions[b].updatedAt||0));
    while (ids.length > AI_SESSIONS_MAX){
      const oldId = ids.shift();
      if (oldId !== aiActiveSessionId) delete aiSessions[oldId];
    }
  }

  aiAffection = Math.max(AI_AFFECTION_MIN, Math.min(AI_AFFECTION_MAX, Math.round(aiAffection) || 0));

  const payload = { activeId: aiActiveSessionId, sessions: aiSessions, memory: aiMemoryFacts, affection: aiAffection };
  try{ localStorage.setItem(_aiChatKey(), JSON.stringify(payload)); }catch(e){}
  if (skipCloud) return;
  const ref = _aiStateRef();
  if (ref) ref.set(JSON.stringify(payload)).catch(e => console.warn('Gagal menyimpan riwayat Vibexa AI ke cloud:', e));
}

function _aiSessionTitle(s){
  return (s && s.title) ? s.title : 'Obrolan Baru';
}

function _aiUpdateHeaderTitle(){
  const el = document.getElementById('ai-chat-head-title');
  if (!el) return;
  const s = aiSessions[aiActiveSessionId];
  el.textContent = (s && s.title) ? s.title : 'Lolu';
}

// Tombol "Obrolan Baru" (persis "New Chat" di ChatGPT). Obrolan yang lagi
// aktif sudah otomatis kesimpen tiap kali kirim pesan, jadi aman langsung
// bikin obrolan kosong baru tanpa kehilangan apapun. Kalau obrolan aktif
// SAAT INI masih kosong (baru dibuka, belum ngobrol sama sekali), nggak
// perlu bikin sesi baru lagi — biar nggak numpuk obrolan kosong percuma.
function aiStartNewChat(){
  const cur = aiSessions[aiActiveSessionId];
  if (cur && (!cur.display || !cur.display.length)){
    closeAIChatHistoryPanel();
    renderAIChatMessages();
    _aiUpdateHeaderTitle();
    return;
  }
  const s = _aiNewEmptySession();
  aiSessions[s.id] = s;
  aiActiveSessionId = s.id;
  aiChatDisplay = s.display;
  aiApiHistory  = s.api;
  _aiSaveChatState();
  closeAIChatHistoryPanel();
  renderAIChatMessages();
  _aiUpdateHeaderTitle();
  setTimeout(() => { const inp = document.getElementById('ai-chat-input'); if (inp) inp.focus(); }, 150);
}

// Pindah ke obrolan lama yang dipilih user dari dropdown riwayat — supaya
// bisa "melanjutkan percakapan lama" persis seperti klik riwayat chat di
// sidebar ChatGPT.
function aiSwitchToSession(id){
  if (!aiSessions[id]){ closeAIChatHistoryPanel(); return; }
  if (id === aiActiveSessionId){ closeAIChatHistoryPanel(); return; }
  aiActiveSessionId = id;
  const s = aiSessions[id];
  if (!Array.isArray(s.display)) s.display = [];
  if (!Array.isArray(s.api)) s.api = [];
  aiChatDisplay = s.display;
  aiApiHistory  = s.api;
  _aiSaveChatState(true);
  closeAIChatHistoryPanel();
  renderAIChatMessages();
  _aiUpdateHeaderTitle();
}

function aiDeleteSession(id, ev){
  if (ev) ev.stopPropagation();
  if (!aiSessions[id]) return;
  if (!confirm('Hapus obrolan ini? Riwayatnya nggak bisa dikembalikan.')) return;
  const wasActive = (id === aiActiveSessionId);
  delete aiSessions[id];
  if (wasActive) aiActiveSessionId = null;
  _aiEnsureActiveSession();
  _aiSaveChatState();
  renderAIChatHistoryList();
  if (wasActive){ renderAIChatMessages(); _aiUpdateHeaderTitle(); }
}

// Dropdown riwayat obrolan — mengambang tepat di bawah tombol jam, seperti
// flyout "Obrolan terbaru" di sidebar ChatGPT (bukan panel layar penuh).
function toggleAIChatHistoryPanel(e){
  if (e) e.stopPropagation();
  const p = document.getElementById('ai-chat-history-panel');
  if (!p) return;
  if (p.classList.contains('show')) closeAIChatHistoryPanel();
  else openAIChatHistoryPanel();
}
function openAIChatHistoryPanel(){
  renderAIChatHistoryList();
  const p = document.getElementById('ai-chat-history-panel');
  if (p) p.classList.add('show');
}
function closeAIChatHistoryPanel(){
  const p = document.getElementById('ai-chat-history-panel');
  if (p) p.classList.remove('show');
}
// Klik di luar dropdown -> tutup (pola yang sama dengan menu profil di topbar).
document.addEventListener('click', (e) => {
  const wrap = document.getElementById('ai-chat-history-wrap');
  const panel = document.getElementById('ai-chat-history-panel');
  if (panel && panel.classList.contains('show') && wrap && !wrap.contains(e.target)) {
    closeAIChatHistoryPanel();
  }
});

function renderAIChatHistoryList(){
  const list = document.getElementById('ai-chat-history-list');
  if (!list) return;
  const ids = Object.keys(aiSessions)
    .filter(id => aiSessions[id].display && aiSessions[id].display.length)
    .sort((a,b) => (aiSessions[b].updatedAt||0) - (aiSessions[a].updatedAt||0));
  if (!ids.length){
    list.innerHTML = '<div class="ai-chat-history-empty">Belum ada riwayat obrolan.</div>';
    return;
  }
  list.innerHTML = '';
  ids.forEach((id) => {
    const s = aiSessions[id];
    const row = document.createElement('div');
    row.className = 'ai-history-item' + (id === aiActiveSessionId ? ' active' : '');
    row.innerHTML = `
      <div class="ai-history-item-body">
        <div class="ai-history-item-title">${esc(_aiSessionTitle(s))}</div>
      </div>
      <button class="ai-history-item-del" title="Hapus obrolan">
        <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>
      </button>`;
    row.addEventListener('click', () => aiSwitchToSession(id));
    row.querySelector('.ai-history-item-del').addEventListener('click', (e) => aiDeleteSession(id, e));
    list.appendChild(row);
  });
}

// Sekali per user (kalau belum ada memori sama sekali), tarik nama panggilan
// dari profil yang sudah ada supaya AI langsung "kenal nama" user tanpa
// perlu ditanya/diceritakan dulu di chat.
async function _aiSeedMemoryFromProfile(){
  if (aiMemoryFacts.length || typeof currentUser === 'undefined' || !currentUser) return;
  try{
    const snap = await db.ref('users/' + currentUser.uid + '/profile/displayName').get();
    const name = (snap.exists() && snap.val()) ? snap.val() : (currentUser.displayName || null);
    if (name){
      aiMemoryFacts.push('Nama panggilan/nama akun user: ' + name);
      _aiSaveChatState();
    }
  }catch(e){}
}

// Simpan fakta baru dari field "remember" yang dikasih AI, kalau memang ada
// & belum pernah tercatat sebelumnya (hindari duplikat persis).
function _aiRemember(fact){
  if (!fact || typeof fact !== 'string') return;
  const clean = fact.trim().slice(0, 160);
  if (!clean) return;
  const dup = aiMemoryFacts.some(f => f.toLowerCase() === clean.toLowerCase());
  if (dup) return;
  aiMemoryFacts.push(clean);
  if (aiMemoryFacts.length > AI_MEMORY_MAX) aiMemoryFacts = aiMemoryFacts.slice(-AI_MEMORY_MAX);
}

// ─── Follow-up otomatis Lolu (chat proaktif) ────────────────────────────
// Alurnya:
// 1. Tiap kali Gemini balas, dia juga ngasih tau (lewat field "follow_up"
//    di JSON, lihat AI_SYSTEM_PROMPT) apakah obrolan ini layak di-follow-up
//    nanti (topik emosional/penting) dan berapa jam lagi Lolu harus ngecek.
// 2. Kalau iya, _aiHandleFollowUp() nyimpen jadwalnya ke Firebase:
//      users/{uid}/aiFollowUp        -> detail (status, dueAt, topic, sessionId)
//      pendingFollowUps/{uid}        -> index ringan (cuma dueAt) supaya
//                                        Cloudflare Worker terjadwal nggak
//                                        perlu scan SEMUA user tiap jalan,
//                                        cukup baca satu node kecil ini.
// 3. Cloudflare Worker (cron trigger, lihat folder cloudflare-followup-worker/
//    di project ini) jalan berkala (mis. tiap 15 menit), cek node
//    pendingFollowUps, dan begitu waktunya (dueAt) sudah lewat: panggil
//    Gemini buat nyusun SATU pesan check-in yang hangat & natural, suntikkan
//    ke riwayat obrolan user (users/{uid}/aiChat) SEOLAH Lolu yang ngirim
//    duluan, lalu set users/{uid}/aiFollowUp/status = 'sent' dan kirim push
//    notification (FCM) ke device user — persis kayak notifikasi chat biasa.
// 4. Kalau app lagi kebuka (listener di bawah), begitu status berubah jadi
//    'sent' klien langsung sinkron ulang & nampilin pesannya (real-time),
//    tanpa perlu reload. Kalau overlay Lolu lagi ketutup, dikasih titik
//    merah kecil ("dot") di tombol AI mengambang (#ai-fab) sebagai penanda
//    ada pesan baru dari Lolu — hilang begitu overlay dibuka.
function _aiHandleFollowUp(parsed){
  if (typeof currentUser === 'undefined' || !currentUser) return; // follow-up cuma buat user yang login (butuh cloud)
  const uid = currentUser.uid;

  const cancelPrev = !!(parsed && parsed.cancel_previous);
  if (cancelPrev){
    db.ref('users/' + uid + '/aiFollowUp/status').set('cancelled').catch(() => {});
    db.ref('pendingFollowUps/' + uid).remove().catch(() => {});
  }

  const fu = parsed && parsed.follow_up;
  if (!fu || !fu.needed) return;
  const hours = Number(fu.hours);
  if (!isFinite(hours) || hours <= 0) return;

  const dueAt = Date.now() + Math.min(72, Math.max(0.1, hours)) * 3600 * 1000; // dibatasi maks 72 jam biar nggak "nyantol" kelamaan
  const record = {
    status: 'pending',
    dueAt,
    topic: (fu.topic || '').toString().trim().slice(0, 200) || 'obrolan sebelumnya',
    sessionId: aiActiveSessionId || null,
    createdAt: Date.now()
  };
  // Timpa jadwal lama kalau ada (sesuai aturan: jangan dobel follow-up,
  // yang paling baru yang berlaku).
  db.ref('users/' + uid + '/aiFollowUp').set(record).catch(e => console.warn('Gagal menjadwalkan follow-up Lolu:', e));
  db.ref('pendingFollowUps/' + uid).set(dueAt).catch(() => {});
}

let _aiFollowUpListenerAttached = false;
// Dipanggil sekali begitu user login (lihat auth.onAuthStateChanged), supaya
// begitu Cloudflare Worker nulis status 'sent', klien yang lagi online bisa
// langsung nampilin pesan follow-up-nya tanpa nunggu reload/refresh manual.
function _aiAttachFollowUpListener(){
  if (_aiFollowUpListenerAttached) return;
  if (typeof currentUser === 'undefined' || !currentUser) return;
  _aiFollowUpListenerAttached = true;
  db.ref('users/' + currentUser.uid + '/aiFollowUp/status').on('value', snap => {
    if (snap.val() === 'sent') _aiHandleIncomingFollowUp();
  });
}

// Ditriggerkan begitu Worker selesai nulis pesan follow-up ke cloud. Kita
// muat ulang seluruh state obrolan dari cloud (paling simpel & aman, karena
// state disimpan sebagai satu blob JSON per user — lihat _aiStateRef), lalu
// render ulang kalau overlay lagi kebuka, atau tampilin dot notifikasi kalau
// overlay lagi ketutup.
async function _aiHandleIncomingFollowUp(){
  try{
    const ref = _aiStateRef();
    if (!ref) return;
    const snap = await ref.get();
    if (!snap.exists()) return;
    const raw = snap.val();
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    _aiApplyLoadedState(parsed);
    _aiSaveChatState(true);

    const overlay = document.getElementById('ai-chat-overlay');
    const overlayOpen = !!(overlay && overlay.classList.contains('show'));
    if (overlayOpen){
      renderAIChatMessages();
      _aiUpdateHeaderTitle();
      _aiScrollToBottom();
    } else {
      _aiShowFollowUpBadge();
    }
    // Tandai sudah "diterima" klien ini biar listener nggak triger ulang
    // terus kalau node-nya di-read lagi tanpa berubah nilainya.
    if (typeof currentUser !== 'undefined' && currentUser){
      db.ref('users/' + currentUser.uid + '/aiFollowUp/status').set('acked').catch(() => {});
    }
  }catch(e){ console.warn('Gagal memuat follow-up Lolu:', e); }
}

// Titik merah kecil di tombol AI mengambang (#ai-fab), penanda "ada pesan
// baru dari Lolu yang belum dibuka" — mirip badge unread chat biasa.
function _aiShowFollowUpBadge(){
  const fab = document.getElementById('ai-fab');
  if (!fab) return;
  if (!fab.querySelector('.ai-followup-dot')){
    const dot = document.createElement('span');
    dot.className = 'ai-followup-dot';
    fab.appendChild(dot);
  }
}
function _aiClearFollowUpBadge(){
  const fab = document.getElementById('ai-fab');
  const dot = fab && fab.querySelector('.ai-followup-dot');
  if (dot) dot.remove();
}

// Deskripsi tiap tingkat aiAffection buat disuntikkan ke system prompt,
// supaya Gemini tau persis harus bersikap kayak gimana ke user SEBELUM
// nulis balasan (bukan cuma milih foto doang) — ini yang bikin "ngambek"-
// nya Lolu kerasa nyambung/konsisten antar pesan, bukan cuma reaksi sesaat.
function _aiAffectionTierText(aff){
  if (aff <= -3) return {
    label: 'SANGAT MARAH/NGAMBEK BERAT',
    guide: 'Lolu lagi BENER-BENER kesel & masih inget dihina/dimaki berkali-kali sama user ini sebelumnya. Balas singkat, dingin, ogah-ogahan. TOLAK bikinin rekomendasi/playlist atau bantuan normal lainnya dulu — bilang aja kalau kamu masih kesel dan pengen diminta maaf dulu (bukan diomelin balik, cukup nunjukin kamu ngambek). Tetap sopan dalam artian TIDAK BOLEH balik menghina/memaki user, cuma nunjukin kamu tersinggung & butuh permintaan maaf yang tulus. Kalau user minta maaf beneran, boleh mulai melunak. WAJIB pakai kata ganti "gue/lu" (bukan "aku/kamu") selama status ini masih berlangsung.'
  };
  if (aff === -2) return {
    label: 'MARAH',
    guide: 'Lolu masih marah karena dihina/dimaki tadi & belum dimintain maaf. Balasan ketus, jutek, jawaban seperlunya, kurang niat bantu kayak biasanya (boleh tetep jawab tapi dengan nada nggak ikhlas). JANGAN balik menghina user — cukup tunjukkin lewat nada bicara kalau kamu masih kesel. WAJIB pakai kata ganti "gue/lu" (bukan "aku/kamu") selama status ini masih berlangsung.'
  };
  if (aff === -1) return {
    label: 'TERSINGGUNG',
    guide: 'Lolu baru aja tersinggung/kesel dikit sama omongan user. Nada bicara jadi agak dingin/sensitif, tapi masih mau bantu seperlunya. Jangan galak banget, tapi jangan pura-pura baik-baik aja juga. WAJIB pakai kata ganti "gue/lu" (bukan "aku/kamu") selama status ini masih berlangsung.'
  };
  if (aff === 0) return { label: 'NORMAL', guide: 'Kepribadian default Lolu seperti biasa (lihat bagian KEPRIBADIAN).' };
  if (aff === 1) return {
    label: 'HANGAT',
    guide: 'User udah beberapa kali baik/ramah ke Lolu. Boleh sedikit lebih hangat & antusias dari biasanya, lebih akrab, tapi jangan lebay.'
  };
  return {
    label: 'SANGAT HANGAT/AKRAB',
    guide: 'User udah konsisten baik & asik ke Lolu. Lolu boleh kerasa deket banget, hangat, ceria, kayak sohib lama — tapi tetap natural, jangan norak/berlebihan.'
  };
}

// Update aiAffection berdasarkan "user_tone" (& "apology_sincere" kalau
// relevan) yang dikasih Gemini di tiap balasan — lihat instruksi lengkap di
// AI_SYSTEM_PROMPT bagian "RELASI EMOSIONAL DENGAN USER". Logika naik/
// turunnya sengaja dihitung di JS (bukan diserahkan penuh ke Gemini) biar
// konsisten & nggak gampang "direset" cuma gara-gara satu balasan aneh.
function _aiUpdateAffection(userTone, apologySincere){
  const tone = (typeof userTone === 'string') ? userTone.trim().toLowerCase() : null;
  if (tone === 'insult'){
    aiAffection = Math.max(AI_AFFECTION_MIN, aiAffection - 1);
  } else if (tone === 'apology'){
    // Minta maaf cuma "manjur" kalau memang lagi ngambek DAN dianggap tulus
    // oleh Gemini. Kalau belum ngambek, permintaan maaf nggak ngefek apa-apa.
    if (aiAffection < 0 && apologySincere === true){
      aiAffection = 0;
    }
  } else if (tone === 'kind'){
    // Selama nggak lagi ngambek (affection >= 0), kebaikan pelan-pelan
    // bikin Lolu makin hangat. Kalau masih ngambek, kebaikan doang belum
    // cukup — user harus minta maaf dulu sesuai aturan "tetap marah sampai
    // ada permintaan maaf yang tulus".
    if (aiAffection >= 0) aiAffection = Math.min(AI_AFFECTION_MAX, aiAffection + 1);
  }
  // tone 'sad' & 'neutral' (atau nilai lain/nggak dikenal): affection nggak berubah.
  aiAffection = Math.max(AI_AFFECTION_MIN, Math.min(AI_AFFECTION_MAX, aiAffection));
}

// Ambil "data mentah" aktivitas musik user (artis favorit + lagu yang
// baru-baru ini diputar) buat disuntikkan ke system prompt Gemini, supaya
// Vibexa AI otomatis tahu selera & bisa menyimpulkan mood/genre user tanpa
// harus ditanya manual. favoriteArtists & _recentlyPlayedCache sudah ada
// sebagai state global (lihat bagian "Artis Favorit" & "RECENTLY PLAYED"
// di atas), jadi di sini tinggal dibaca & diformat jadi teks singkat.
function _aiBuildUserMusicContext(){
  const parts = [];

  // 1) Artis favorit / yang di-follow user.
  try{
    const favNames = Object.values(favoriteArtists || {})
      .map(a => a && a.name).filter(Boolean);
    if (favNames.length){
      parts.push('Artis favorit/yang di-follow user: ' + favNames.slice(0, 20).join(', ') + '.');
    }
  }catch(e){}

  // 2) Lagu yang akhir-akhir ini diputar user (dari yang paling baru),
  // dipakai Gemini buat menyimpulkan genre/mood yang lagi dicari user.
  try{
    const recent = _getRecentlyPlayed();
    if (recent && recent.length){
      const list = recent.slice(0, 15)
        .map(t => `${t.title} - ${t.artist}`)
        .join('; ');
      parts.push('Lagu yang akhir-akhir ini diputar user (dari yang paling baru): ' + list + '.');
    }
  }catch(e){}

  if (!parts.length) return '';
  return '\n\nDATA DENGAR MUSIK USER INI (data asli dari aktivitas app, bukan dari obrolan — lihat instruksi "DATA AKTIVITAS MUSIK USER" di atas soal cara memakainya):\n' + parts.join('\n');
}

// Suntikkan daftar memori + data aktivitas musik ke system prompt, supaya
// tiap request ke Gemini otomatis "ingat" fakta soal user ini (nama, lagu/
// genre favorit, dst) DAN otomatis tahu artis favorit & histori dengar
// terbarunya (buat menyimpulkan mood & kasih rekomendasi yang relevan).
function _aiBuildSystemPrompt(opts){
  opts = opts || {};
  let prompt = AI_SYSTEM_PROMPT;

  // ── Override KHUSUS fitur Lolu Voice (halaman Lolu Voice, termasuk mode
  // Lolu DJ yang selalu dibuka lewat halaman itu) — dipanggil dengan
  // { forceEnglish: true } dari lolu-voice.js. TIDAK memengaruhi Chat AI
  // berbasis teks di halaman Lolu Chat sama sekali (chat teks tetap pakai
  // aturan "BAHASA" bawaan di atas: ikut bahasa pesan terbaru user). ──────
  if (opts.forceEnglish){
    prompt += '\n\nATURAN BAHASA KHUSUS UNTUK SESI INI (fitur Lolu Voice — WAJIB PATUHI, MENGGANTIKAN aturan "BAHASA" di bagian KEPRIBADIAN di atas): '
      + 'SELALU balas dalam Bahasa Inggris, APAPUN bahasa yang dipakai user buat ngomong/nulis ke kamu (Bahasa Indonesia, bahasa daerah, bahasa lain, ataupun campuran/slang). '
      + 'Kamu WAJIB tetap paham & merespons isi omongan user dengan benar meskipun user ngomong pakai Bahasa Indonesia atau bahasa lain — cuma balasannya ("message") yang HARUS selalu Bahasa Inggris, jangan pernah balas pakai Bahasa Indonesia atau bahasa lain di sini walau usernya begitu. '
      + 'Ikuti gaya ngomong Bahasa Inggris kayak yang dijelaskan di bagian "KHUSUS KALAU BALAS DALAM BAHASA INGGRIS" di atas (natural, kayak temen Gen Z chatting santai, boleh contraction & slang secukupnya, dikurangi kalau user lagi curhat berat/serius).';
  }

  const tier = _aiAffectionTierText(aiAffection);
  prompt += '\n\nSTATUS EMOSI LOLU KE USER INI SAAT INI (nilai persisten, hasil akumulasi dari obrolan-obrolan sebelumnya — WAJIB dipatuhi sebelum nulis "message", lihat instruksi "RELASI EMOSIONAL DENGAN USER" di atas): '
    + tier.label + ' (skor internal ' + aiAffection + ' dari rentang -3 s/d +3).\n' + tier.guide;

  const musicCtx = _aiBuildUserMusicContext();
  if (musicCtx) prompt += musicCtx;

  if (_isAiFabSleepHour()){
    prompt += '\n\nMODE MALAM (SEKARANG JAM 21.00–05.59 DI PERANGKAT USER):\n'
      + '- Sekarang lagi malam/dini hari. Bawain gaya bicara kamu sedikit lebih "ngantuk" — kayak orang yang baru aja kebangun atau emang udah waktunya tidur, tapi tetap mau nemenin ngobrol. Jangan berubah drastis jadi karakter lain, cuma nuansanya aja yang lebih santai/lemas/ngantuk dibanding biasanya.\n'
      + '- WAJIB variasikan kalimatnya tiap kali balas — JANGAN PERNAH pakai kalimat yang sama persis/mirip banget kayak balasan-balasan sebelumnya di obrolan ini. Kamu bebas kreasiin sendiri kalimatnya (boleh nyelipin hal kayak "*yaaawn*", emoji 😴💤, nanya balik apa masih belum tidur, dll) — intinya nada ngantuk-nya kerasa natural & selalu beda-beda redaksinya, bukan template yang itu-itu terus.\n'
      + '- Tetap jawab pertanyaan/permintaan user secara lengkap & bener kayak biasa (rekomendasi lagu, jawab curhat, dll) — mode ngantuk ini cuma soal GAYA BICARA, bukan alasan buat jawab asal-asalan atau ngerjain tugas lebih sedikit.';
  }

  if (aiMemoryFacts.length){
    const memLines = aiMemoryFacts.map(f => '- ' + f).join('\n');
    prompt += '\n\nINGATAN TENTANG USER INI (fakta nyata dari obrolan sebelumnya, gunakan buat personalisasi, jangan dibacain ulang persis kayak daftar):\n' + memLines;
  }

  return prompt;
}

// File animasi Lottie untuk ikon tombol Vibexa AI (taruh sejajar dengan
// vibexa.html di server, sama seperti file animasi streak lainnya).
// Sebelumnya pakai ai_animation_Flow_1.json — sudah diganti ke Wavey_Birdie.json
// (file lama tidak lagi dipakai, boleh dihapus dari server).
const AI_FAB_LOTTIE_URL = 'Wavey_Birdie.json';
let _aiFabAnim = null;

// Memuat & memutar animasi "Wavey Birdie" di dalam tombol AI mengambang
// (#ai-fab), menggantikan ikon bintang statis sebelumnya. Lottie ini murni
// vector (tanpa layer solid/background), jadi otomatis transparan — dan
// #ai-fab sendiri sudah background:transparent lewat CSS, jadi tidak ada
// background apa pun di belakang animasi. Ukurannya diatur lewat CSS
// (#ai-fab-lottie) supaya tetap pas di dalam tombol.
function _renderAiFabAnimation(){
  if (typeof lottie === 'undefined') return;
  const container = document.getElementById('ai-fab-lottie');
  if (!container || _aiFabAnim) return;
  _aiFabAnim = lottie.loadAnimation({
    container: container,
    renderer: 'svg',
    loop: true,
    autoplay: true,
    path: AI_FAB_LOTTIE_URL
  });
}
document.addEventListener('DOMContentLoaded', _renderAiFabAnimation);

// ── MODE MALAM TOMBOL AI: animasi "burung tidur" jam 21.00–06.00 ──────────
// Di luar jam tsb (06.00–20.59) tombol AI pakai animasi Wavey_Birdie seperti
// biasa. Begitu masuk jam 21.00, animasi Wavey_Birdie disembunyikan lalu
// diganti animasi GIF burung tidur (background sudah dihapus/transparan,
// ukurannya disamakan lewat CSS #ai-fab-sleep-gif supaya pas menyatu di
// dalam tombol). Jam 06.00 pagi, otomatis balik lagi ke Wavey_Birdie.
function _isAiFabSleepHour(){
  const h = new Date().getHours();
  // 21.00 malam s/d 06.00 pagi (melewati tengah malam)
  return h >= 21 || h < 6;
}
function _updateAiFabSleepMode(){
  const lottieEl = document.getElementById('ai-fab-lottie');
  const sleepEl = document.getElementById('ai-fab-sleep-gif');
  if (!lottieEl || !sleepEl) return;
  const sleepNow = _isAiFabSleepHour();
  if (sleepNow){
    lottieEl.style.display = 'none';
    if (_aiFabAnim) { try{ _aiFabAnim.pause(); }catch(e){} }
    sleepEl.classList.add('show');
    // Bubble sapaan "Lolu missed you!!" dkk TIDAK boleh nongol jam
    // 21.00–06.00 (biar konsisten sama mode tidur burungnya) — dipaksa
    // hide di sini juga (bukan cuma di _aiFabBubbleRotate()) supaya kalau
    // bubble kebetulan lagi "show" pas jam berganti ke 21.00 sementara tab
    // tetap terbuka, dia langsung ilang tanpa perlu reload/keluar-masuk tab.
    const bubble = document.getElementById('ai-fab-bubble');
    if (bubble){
      bubble.classList.remove('show');
      clearTimeout(_aiFabBubbleHideTimer);
      clearInterval(_aiFabBubbleTypeTimer);
      clearTimeout(_aiFabBubbleTypeStartTimer);
    }
  } else {
    sleepEl.classList.remove('show');
    lottieEl.style.display = '';
    if (_aiFabAnim) { try{ _aiFabAnim.play(); }catch(e){} }
  }
}
document.addEventListener('DOMContentLoaded', () => {
  _updateAiFabSleepMode();
  // Cek tiap menit supaya transisi 21.00 & 06.00 otomatis kepakai walau
  // web/app tetap dibuka terus tanpa reload.
  setInterval(_updateAiFabSleepMode, 60 * 1000);
  // Sama halnya buat welcome screen di halaman chat Lolu: kalau overlay
  // chat lagi kebuka dan lagi nampilin welcome screen (belum ada pesan),
  // re-render tiap menit biar transisi jam tidur (21.00/06.00) otomatis
  // kepakai juga tanpa perlu buka-tutup ulang chatnya.
  setInterval(() => {
    const ov = document.getElementById('ai-chat-overlay');
    if (ov && ov.classList.contains('show') && !aiChatDisplay.length){
      renderAIChatMessages();
    }
  }, 60 * 1000);
});

// Tombol AI mengambang (#ai-fab) HANYA muncul di halaman Home. Dipantau lewat
// MutationObserver pada class #home-view (yang menentukan tampil/tidaknya
// halaman Home lewat class "active" — lihat CSS #home-view.active), supaya
// otomatis ikut ke SEMUA halaman lain (Search, Playlist, Artist, Streak,
// Downloads, Chat, dst) tanpa perlu ubah satu-satu fungsi yang membuka
// halaman tersebut.
function _syncAiFabVisibility(){
  const home = document.getElementById('home-view');
  const fab = document.getElementById('ai-fab');
  const bubble = document.getElementById('ai-fab-bubble');
  if (!home || !fab) return;
  const onHome = home.classList.contains('active');
  // "hide" dipakai juga oleh openAIChatOverlay() saat overlay Vibexa AI
  // sendiri sedang terbuka — jangan timpa balik kalau overlay itu aktif.
  const aiOverlayOpen = document.getElementById('ai-chat-overlay')?.classList.contains('show');
  const shouldHide = !onHome || aiOverlayOpen;
  fab.classList.toggle('hide', shouldHide);
  // Bubble ikut sembunyi kalau fab-nya sembunyi (mis. lagi bukan di Home,
  // atau overlay Vibexa AI sedang terbuka) — tapi TIDAK otomatis dipaksa
  // tampil di sini; tampil/tidaknya bubble tetap diatur oleh
  // _aiFabBubbleRotate() lewat class "show".
  if (bubble) bubble.classList.toggle('hide', shouldHide);
}
document.addEventListener('DOMContentLoaded', () => {
  _syncAiFabVisibility();
  const home = document.getElementById('home-view');
  if (home) new MutationObserver(_syncAiFabVisibility).observe(home, { attributes: true, attributeFilter: ['class'] });
  const aiOverlay = document.getElementById('ai-chat-overlay');
  if (aiOverlay) new MutationObserver(_syncAiFabVisibility).observe(aiOverlay, { attributes: true, attributeFilter: ['class'] });
});

// ── BUBBLE SAPAAN PIXEL LOLU ──────────────────────────────────────────
// Daftar teks yang bergilir tiap kali user KELUAR dari web lalu MASUK lagi
// (bukan tiap detik/tiap klik). "Keluar-masuk" dideteksi lewat 2 sinyal:
//  1) load halaman baru (tab/app ditutup lalu dibuka lagi → dokumen baru)
//  2) Page Visibility API — tab/app di-background lalu di-foreground lagi
//     tanpa reload (umum di PWA/mobile, lihat sw.js).
// Indeks giliran disimpan di localStorage ('loluBubbleIdx') supaya urutan
// tetap nyambung walau sesi/refresh berganti-ganti.
const LOLU_BUBBLE_PHRASES = [
  "Yayy! You're here!",
  "Lolu missed you!!",
  "Hii, Pookie!!",
  "Psst.... You're back!",
  "I was waiting, XD",
  "Guess who's happy? Me!!!",
  "Come hang out with me, plss"
];
// Dipakai gantiin LOLU_BUBBLE_PHRASES di atas kalau lagi jam 21.00–05.59
// (dicek pakai _isAiFabSleepHour() yang sama dgn animasi burung tidur).
// Muter/gonta-ganti sendiri tiap kali user keluar-masuk web (persis kayak
// LOLU_BUBBLE_PHRASES, cuma nyimpen index rotasinya terpisah), dan otomatis
// balik ke LOLU_BUBBLE_PHRASES normal begitu udah lewat jam 06.00.
const LOLU_BUBBLE_NIGHT_PHRASES = [
  "Dreaming about finding a giant worm!",
  "Shh... Don't wake me up... I'm this close to catching the worm!",
  "Shh... Lolu is sleeping soundly...",
  "Zzz... Having sweet dreams...",
  "Dreaming... Do not disturb!"
];
let _aiFabBubbleHideTimer = null;
let _aiFabBubbleTypeTimer = null;
let _aiFabBubbleTypeStartTimer = null;

// Efek ketik: teks dipecah per-huruf jadi <span> tersendiri (opacity 0),
// lalu dimunculkan satu-satu dari kiri ke kanan lewat setInterval. Bubble
// tetap langsung selebar teks penuh sejak awal (karena semua <span> sudah
// ada di DOM, cuma transparan) — yang beranimasi cuma kemunculan hurufnya,
// bukan lebar bubble-nya, jadi bentuk pixel-nya tidak "meloncat-loncat".
function _typeAiFabBubbleText(el, text, speedMs){
  clearInterval(_aiFabBubbleTypeTimer);
  el.innerHTML = '';
  const letters = [...text].map((ch) => {
    const span = document.createElement('span');
    span.textContent = ch;
    span.style.opacity = '0';
    el.appendChild(span);
    return span;
  });
  let i = 0;
  _aiFabBubbleTypeTimer = setInterval(() => {
    if (i >= letters.length){ clearInterval(_aiFabBubbleTypeTimer); return; }
    letters[i].style.opacity = '1';
    i++;
  }, speedMs);
}

function _aiFabBubbleRotate(){
  const bubble = document.getElementById('ai-fab-bubble');
  const bubbleText = document.getElementById('ai-fab-bubble-text');
  const fab = document.getElementById('ai-fab');
  if (!bubble || !bubbleText || !fab) return;
  // Jangan munculkan kalau fab sendiri lagi disembunyikan (bukan di Home /
  // overlay Vibexa AI sedang terbuka) — hindari bubble "mengambang sendiri"
  // tanpa tombol yang ditunjuknya.
  if (fab.classList.contains('hide')) return;

  // Bubble sapaan TIDAK muncul sama sekali jam 21.00–05.59 (dicek pakai
  // _isAiFabSleepHour() yang sama dgn mode tidur burung). Begitu sudah
  // lewat jam 06.00, fungsi ini otomatis lanjut nampilin bubble lagi
  // seperti biasa di panggilan berikutnya (buka tab baru / balik dari
  // background) — tidak perlu logic tambahan buat "munculkan lagi".
  if (_isAiFabSleepHour()){
    bubble.classList.remove('show');
    return;
  }

  const idxStorageKey = 'loluBubbleIdx';
  const phrases = LOLU_BUBBLE_PHRASES;
  let idx = parseInt(localStorage.getItem(idxStorageKey) || '-1', 10);
  if (isNaN(idx)) idx = -1;
  idx = (idx + 1) % phrases.length;
  localStorage.setItem(idxStorageKey, String(idx));

  // Kosongkan dulu supaya tidak kelihatan teks lama sekilas, lalu tunggu
  // sampai animasi "pop-in" kotak bubble selesai (~220ms) baru mulai
  // mengetik — kalau langsung bareng, hurufnya ketutup fade bubble dan
  // kelihatan seperti langsung muncul semua, bukan diketik satu-satu.
  bubbleText.innerHTML = '';
  clearInterval(_aiFabBubbleTypeTimer);
  clearTimeout(_aiFabBubbleTypeStartTimer);

  bubble.classList.remove('hide');
  // Restart animasi masuk walau bubble sebelumnya masih "show".
  bubble.classList.remove('show');
  void bubble.offsetWidth; // force reflow biar transition ke-trigger ulang
  bubble.classList.add('show');

  _aiFabBubbleTypeStartTimer = setTimeout(() => {
    _typeAiFabBubbleText(bubbleText, phrases[idx], 45);
  }, 230);

  clearTimeout(_aiFabBubbleHideTimer);
  _aiFabBubbleHideTimer = setTimeout(() => bubble.classList.remove('show'), 6000);
}

// Sinyal #1: halaman baru selesai loading — ditandai event 'vbxAppReady'
// yang di-dispatch showApp()/_vbxEnterOfflineMode() persis saat layar
// loading (overlay burung) sudah hilang. Sengaja BUKAN dengarkan
// DOMContentLoaded, karena saat itu overlay loading masih menutupi layar
// dan bubble (plus efek ketiknya) akan mulai duluan sebelum halaman
// kelihatan oleh user.
document.addEventListener('vbxAppReady', () => {
  _aiFabBubbleRotate();
});

// Sinyal #2: tab/app di-background lalu di-foreground lagi (tanpa reload).
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') _aiFabBubbleRotate();
});

function openAIChatOverlay(){
  const ov = document.getElementById('ai-chat-overlay');
  if (ov) ov.classList.add('show');
  const fab = document.getElementById('ai-fab'); if (fab) fab.classList.add('hide');
  _aiClearFollowUpBadge();
  closeAIChatHistoryPanel();
  // Kunci scroll #main (sama seperti pola di openStreakView/openDownloadsView/
  // openChatOverlay) supaya konten Home di baliknya tidak ikut ke-scroll saat
  // user scroll di halaman Vibexa AI. Tanpa ini, #main (yang overflow-y:auto)
  // tetap bisa di-scroll di PC/tablet karena #ai-chat-overlay cuma
  // position:absolute di dalamnya, bukan fullscreen — akibatnya halaman
  // Vibexa AI "bocor" dan konten Home (mis. Recently Played) di belakangnya
  // ikut kelihatan kalau posisi scroll Home sedang tidak di paling atas.
  const mainEl = document.getElementById('main');
  if (mainEl) { mainEl.scrollTop = 0; mainEl.style.overflow = 'hidden'; }
  // Khusus mobile: sembunyikan mini player (#bar) & navigasi bawah (#mob-nav),
  // dan buat halaman Lolu memenuhi layar penuh tanpa ruang kosong (lihat CSS
  // body.ai-mobile-open, pola sama seperti body.np-mobile-open).
  if (typeof isMobile === 'function' && isMobile()) document.body.classList.add('ai-mobile-open');
  // Render dulu dari cache lokal (instan), lalu sinkron ulang begitu versi
  // asli dari cloud selesai dimuat — supaya riwayat & memori dari perangkat
  // lain ikut muncul di sini juga.
  _aiLoadCachedChatState();
  renderAIChatMessages();
  _aiUpdateHeaderTitle();
  _aiLoadChatState().then(() => { renderAIChatMessages(); _aiUpdateHeaderTitle(); });
  setTimeout(() => { const inp = document.getElementById('ai-chat-input'); if (inp) inp.focus(); }, 150);
}
function closeAIChatOverlay(){
  const ov = document.getElementById('ai-chat-overlay');
  if (ov) ov.classList.remove('show');
  const fab = document.getElementById('ai-fab'); if (fab) fab.classList.remove('hide');
  const mainEl = document.getElementById('main');
  if (mainEl) mainEl.style.overflow = '';
  document.body.classList.remove('ai-mobile-open');
  closeAIChatHistoryPanel();
}

function aiQuickPrompt(text){
  const inp = document.getElementById('ai-chat-input');
  if (inp) inp.value = text;
  sendAIChatMessage();
}

function _aiScrollToBottom(){
  const c = document.getElementById('ai-chat-messages');
  if (c) c.scrollTop = c.scrollHeight;
}

// ── MODE TIDUR LOLU DI HALAMAN CHAT: welcome screen (obrolan kosong) diganti
// animasi burung tidur (sleepbird.gif) + teks "Shhh... Lolu is sleeping" jam
// 21.00–06.00, menggantikan sementara tampilan welcome biasa/ngambek. Di luar
// jam itu otomatis balik ke tampilan asal. Ukurannya disamakan lewat class
// .ai-chat-welcome-icon yang sudah ada (72x72), biar nggak beda sendiri sama
// icon welcome biasa di halaman chat ini.
function _isLoluChatSleepHour(){
  const h = new Date().getHours();
  return h >= 21 || h < 6;
}
function renderAIChatMessages(){
  const c = document.getElementById('ai-chat-messages');
  if (!c) return;
  if (!aiChatDisplay.length){
    if (_isLoluChatSleepHour()){
      c.innerHTML = `
        <div class="ai-chat-welcome ai-chat-welcome-sleeping">
          <div class="ai-chat-welcome-icon"><img src="sleepbird.gif" alt="Lolu sedang tidur"></div>
          <div class="ai-chat-welcome-title">Shhh... Lolu is sleeping</div>
          <div class="ai-chat-welcome-sub">Lolu lagi tidur, balik lagi jam 6 pagi ya.</div>
        </div>`;
      return;
    }
    // Layar welcome utk obrolan baru/kosong. aiAffection itu status yg
    // PERSISTEN lintas obrolan (lihat _aiSaveChatState/_aiApplyLoadedState),
    // jadi kalau Lolu masih ngambek/marah, welcome screen-nya WAJIB ikut
    // nunjukin itu — sebelumnya di sini selalu dipasang foto & sapaan ceria
    // yang sama tanpa peduli aiAffection, jadi kesannya "baik-baik aja lagi"
    // padahal skornya belum di-reset (cuma reset lewat permintaan maaf yg
    // dianggap tulus, lihat _aiUpdateAffection).
    if (aiAffection < 0){
      const tier = _aiAffectionTierText(aiAffection);
      // Foto welcome saat Lolu lagi ngambek/marah: pakai foto baru (owl merah,
      // background sudah dihapus/transparan) untuk KEDUA tahap ngambek
      // ('tersinggung' & 'angry'), menggantikan AI_CAT_SRC.angry/tersinggung
      // yang sebelumnya dipakai di sini.
      const moodImg = WELCOME_SULKING_IMG;
      c.innerHTML = `
        <div class="ai-chat-welcome ai-chat-welcome-sulking">
          <div class="ai-chat-welcome-icon"><img src="${moodImg}" alt="Lolu" width="72" height="72"></div>
          <div class="ai-chat-welcome-title">Lolu lagi ${tier.label.toLowerCase()}</div>
          <div class="ai-chat-welcome-sub">Ini obrolan baru, tapi Lolu masih inget kejadian sebelumnya. Coba minta maaf dulu deh.</div>
          <div class="ai-chat-chips">
            <button class="ai-chip" onclick="aiQuickPrompt('Maaf ya Lolu, aku nggak bermaksud gitu')">Minta maaf ke Lolu</button>
          </div>
        </div>`;
      return;
    }
    c.innerHTML = `
      <div class="ai-chat-welcome">
        <div class="ai-chat-welcome-icon"><img src="lolu-icon-welcome.png" alt="Lolu" width="72" height="72"></div>
        <div class="ai-chat-welcome-title">Lolu</div>
        <div class="ai-chat-welcome-sub">Minta aku buatkan playlist, kasih rekomendasi lagu, atau ngobrol santai soal musik apa aja.</div>
        <div class="ai-chat-chips">
          <button class="ai-chip" onclick="aiQuickPrompt('Buatkan playlist buat fokus belajar')">Playlist buat belajar</button>
          <button class="ai-chip" onclick="aiQuickPrompt('Rekomendasikan lagu mirip Tame Impala')">Mirip Tame Impala</button>
          <button class="ai-chip" onclick="aiQuickPrompt('Buatkan playlist lagu galau abis putus')">Playlist galau</button>
          <button class="ai-chip" onclick="aiQuickPrompt('Rekomendasikan lagu buat semangat workout')">Lagu workout</button>
        </div>
      </div>`;
    return;
  }
  c.innerHTML = '';
  aiChatDisplay.forEach((msg) => c.appendChild(_aiBuildBubble(msg)));
  _aiScrollToBottom();
}

// Pecah teks balasan AI jadi beberapa "potongan pesan" terpisah — dipisah
// oleh baris kosong ("\n\n") sesuai instruksi di AI_SYSTEM_PROMPT — supaya
// tiap potongan bisa dirender jadi bubble sendiri-sendiri, persis kayak
// orang beneran ngetik-kirim-ngetik-kirim di WhatsApp (bukan satu bubble
// raksasa yang keliatan kayak balasan AI). Kalau Gemini kebetulan nggak
// pakai "\n\n" (balasan pendek / lupa format), fallback ke 1 potongan biasa.
function _aiSplitMessageText(text){
  if (!text) return [];
  return String(text)
    .split(/\n\s*\n+/)
    .map(s => s.trim())
    .filter(Boolean);
}

// Hapus titik tunggal di akhir potongan teks (bukan "..." / emoticon) biar
// kesannya orang beneran lagi ngetik santai di chat, bukan kalimat formal.
// Titik ganda (elipsis "...") sengaja dibiarkan karena itu gaya bahasa, bukan
// tanda titik penutup kalimat biasa.
function _aiHumanizeText(text){
  if (!text) return text;
  return String(text).replace(/(?<!\.)\.(?!\.)[ \t]*$/, '').trimEnd();
}

function _aiBuildBubble(msg){
  const row = document.createElement('div');
  row.className = 'ai-bubble-row ' + (msg.role === 'user' ? 'me' : 'ai');
  if (msg.role === 'user'){
    const bubble = document.createElement('div');
    bubble.className = 'ai-bubble';
    bubble.textContent = msg.text || '';
    row.appendChild(bubble);
    return row;
  }
  const wrap = document.createElement('div');
  wrap.className = 'ai-bubble-col';
  row.appendChild(wrap);

  // Balasan AI dipecah jadi beberapa bubble kecil (bukan 1 bubble besar)
  // biar keliatan kayak orang chat beneran (lihat referensi screenshot WA).
  // Setiap potongan juga dibersihkan dari titik penutup di akhir kalimat
  // biar kesannya orang beneran lagi ngetik, bukan teks formal robotik.
  const textParts = _aiSplitMessageText(msg.text);
  const parts = (textParts.length ? textParts : [(msg.text || '').trim()].filter(Boolean))
    .map(_aiHumanizeText)
    .filter(Boolean);

  const appendExtras = () => {
    if (Array.isArray(msg.songs) && msg.songs.length){
      const list = document.createElement('div');
      list.className = 'ai-song-list';
      msg.songs.forEach(song => list.appendChild(_aiBuildSongCard(song)));
      wrap.appendChild(list);

      if (msg.playlistName){
        const btn = document.createElement('button');
        btn.className = 'ai-create-pl-btn';
        if (msg._createdPlaylistId){
          btn.innerHTML = ' Playlist dibuat — buka';
          btn.onclick = () => { closeAIChatOverlay(); showPlaylistView(msg._createdPlaylistId); };
        } else {
          btn.innerHTML = `<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg> Buat Playlist "${esc(msg.playlistName)}"`;
          btn.onclick = () => _aiCreatePlaylistFromMsg(msg, btn);
        }
        wrap.appendChild(btn);
      }
    }
    if (msg.stickerTag){
      const stickerWrap = document.createElement('div');
      stickerWrap.className = 'ai-sticker-wrap';
      wrap.appendChild(stickerWrap);
      _aiEnsureStickerResolved(msg).then(url => {
        if (url){
          stickerWrap.innerHTML = `<img src="${esc(url)}" class="ai-sticker-img" alt="stiker" loading="lazy">`;
          _aiScrollToBottom();
        } else {
          stickerWrap.remove();
        }
      });
    }
    _aiScrollToBottom();
  };

  if (msg._revealed){
    // Pesan lama (udah pernah tampil sebelumnya) -> render langsung tanpa
    // jeda, supaya pas pindah/reload chat nggak keputer ulang animasinya.
    parts.forEach((part) => {
      const bubble = document.createElement('div');
      bubble.className = 'ai-bubble';
      if (parts.length > 1) bubble.classList.add('ai-bubble-split');
      bubble.textContent = part;
      wrap.appendChild(bubble);
    });
    appendExtras();
  } else {
    // Pesan baru -> setiap bubble dimunculin satu-satu, didahului indikator
    // "sedang mengetik" + jeda 2 detik, biar berasa kayak lawan chat asli.
    (async () => {
      for (let i = 0; i < parts.length; i++){
        const typingBubble = document.createElement('div');
        typingBubble.className = 'ai-bubble ai-typing';
        typingBubble.innerHTML = '<span></span><span></span><span></span>';
        wrap.appendChild(typingBubble);
        _aiScrollToBottom();
        await new Promise(r => setTimeout(r, 2000));
        typingBubble.remove();

        const bubble = document.createElement('div');
        bubble.className = 'ai-bubble ai-bubble-split';
        bubble.textContent = parts[i];
        wrap.appendChild(bubble);
        _aiScrollToBottom();
      }
      appendExtras();
      msg._revealed = true;
    })();
  }

  return row;
}

function _aiBuildSongCard(song){
  const card = document.createElement('div');
  card.className = 'ai-song-card';
  const thumb = (song._track && song._track.thumb) || '';
  card.innerHTML = `
    <div class="ai-song-thumb">${thumb ? `<img src="${esc(thumb)}" loading="lazy">` : '<span>🎵</span>'}</div>
    <div class="ai-song-info">
      <div class="ai-song-title">${esc(song.title)}</div>
      <div class="ai-song-artist">${esc(song.artist || '')}</div>
    </div>
    <button class="ai-song-play" title="Play">
      <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
    </button>
  `;
  const addSlot = document.createElement('div');
  addSlot.className = 'ai-song-add-slot';
  card.appendChild(addSlot);

  const playBtn = card.querySelector('.ai-song-play');
  const doPlay = async () => {
    const track = await _aiEnsureTrackResolved(song);
    if (track) loadPlay(track, null);
    else toast(' Lagu tidak ditemukan di katalog');
  };
  playBtn.addEventListener('click', e => { e.stopPropagation(); doPlay(); });
  card.querySelector('.ai-song-info').addEventListener('click', doPlay);
  card.querySelector('.ai-song-thumb').addEventListener('click', doPlay);

  // Resolve ke katalog iTunes di background supaya cover art & tombol
  // "add to playlist" muncul begitu datanya siap (tanpa memblokir render chat).
  (async () => {
    const track = await _aiEnsureTrackResolved(song);
    if (track){
      addSlot.innerHTML = buildAddBtnHTML(track, 'ai-song-add');
      wireAddBtn(addSlot.querySelector('.add-btn'), track);
      if (track.thumb && !card.querySelector('.ai-song-thumb img')){
        card.querySelector('.ai-song-thumb').innerHTML = `<img src="${esc(track.thumb)}" loading="lazy">`;
      }
    }
  })();

  return card;
}

// Cari & cache objek "track" (format sama dengan hasil Search biasa) untuk
// satu {title, artist} yang direkomendasikan AI, lewat katalog iTunes.
async function _aiEnsureTrackResolved(song){
  if (song._track) return song._track;
  if (song._resolving){
    let tries = 0;
    while (song._resolving && tries < 40){ await new Promise(r => setTimeout(r, 150)); tries++; }
    return song._track || null;
  }
  song._resolving = true;
  let track = null;
  try{ track = await _aiResolveSongToTrack(song); }
  catch(e){ console.warn('Gagal resolve lagu AI:', song, e); }
  song._resolving = false;
  if (track){ song._track = track; _aiSaveChatState(); }
  return track;
}

async function _aiResolveSongToTrack(song){
  const title = (song.title || '').trim();
  const artist = (song.artist || '').trim();
  if (!title) return null;
  const q = artist ? `${artist} ${title}` : title;
  const [usItems, idItems] = await Promise.all([
    fetchItunesResults(q, 'US', 'song', 5).catch(() => []),
    fetchItunesResults(q, 'ID', 'song', 5).catch(() => [])
  ]);
  const items = [...usItems, ...idItems];
  if (!items.length) return null;

  const norm = s => (s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').trim();
  const tNorm = norm(title), aNorm = norm(artist);
  let best = items.find(it => {
    const itT = norm(it.trackName), itA = norm(it.artistName);
    return itT === tNorm && (!aNorm || itA.includes(aNorm) || aNorm.includes(itA));
  });
  if (!best) best = items.find(it => norm(it.trackName).includes(tNorm) || tNorm.includes(norm(it.trackName)));
  if (!best) best = items[0];

  const thumb = (best.artworkUrl100 || '').replace('100x100bb', '600x600bb');
  return {
    title: best.trackName || title,
    artist: best.artistName || artist,
    thumb,
    album: best.collectionName || '',
    preview: best.previewUrl || null,
    videoId: null,
    photo: null,
    duration: best.trackTimeMillis ? Math.round(best.trackTimeMillis / 1000) : 0,
    _query: `${best.artistName || artist}|||${best.trackName || title}|||${best.trackId || Math.random()}`
  };
}

async function _aiCreatePlaylistFromMsg(msg, btnEl){
  if (!msg.songs || !msg.songs.length) return;
  const originalHTML = btnEl.innerHTML;
  btnEl.disabled = true;
  btnEl.innerHTML = ' Menyusun playlist...';
  try{
    const tracks = [];
    for (const song of msg.songs){
      const t = await _aiEnsureTrackResolved(song);
      if (t) tracks.push(t);
    }
    if (!tracks.length){
      toast(' Tidak ada lagu yang ditemukan di katalog');
      btnEl.disabled = false; btnEl.innerHTML = originalHTML;
      return;
    }
    const id = genId();
    playlists[id] = { id, name: msg.playlistName || 'Playlist AI', cover: '', coverThumb: '', tracks: [] };
    tracks.forEach(t => addTrackToPlaylist(id, t));
    renderSidebarPlaylists(); renderHomeGrid(); scheduleSave();
    msg._createdPlaylistId = id;
    _aiSaveChatState();
    toast(' Playlist "' + (msg.playlistName || 'Playlist AI') + '" dibuat dengan ' + tracks.length + ' lagu!');
    btnEl.innerHTML = ' Playlist dibuat — buka';
    btnEl.disabled = false;
    btnEl.onclick = () => { closeAIChatOverlay(); showPlaylistView(id); };
  }catch(e){
    console.error('Gagal membuat playlist dari AI:', e);
    toast(' Gagal membuat playlist: ' + e.message);
    btnEl.disabled = false; btnEl.innerHTML = originalHTML;
  }
}

// Foto kucing yang muncul DI ATAS bubble loading, biar animasi "AI lagi mikir"
// terasa lebih hidup/nyata (kayak WA lagi typing tapi ada foto pendukungnya).
// Macam-macam mood foto:
// 'thinking'    = kucing mikir keras (dipasang selagi nunggu balasan Gemini).
// 'result'      = kucing "udah ketemu jawabannya" — dipasang sekilas SEBELUM
//                 bubble balasan beneran dirender, buat obrolan seputar
//                 musik (rekomendasi/playlist/dll) — ini mood DEFAULT.
// 'service'     = kucing "customer service" — dipasang kalau user CUMA
//                 menyapa atau nanya hal di luar musik (nama AI, curhat,
//                 basa-basi umum, dll).
// 'tersinggung' = kucing ngambek — tahap PERTAMA saat user komplain/
//                 memaki/mengejek AI, sebelum lanjut ke mood 'angry'.
// 'angry'       = kucing marah — tahap KEDUA (setelah 'tersinggung') saat
//                 user komplain/memaki/mengejek AI.
// Semua foto di-embed langsung sebagai base64 (bukan file terpisah) biar
// nggak pernah 404 gara-gara lupa upload folder assets ke server.
const WELCOME_SULKING_IMG = 'data:image/png;base64,';

const AI_CAT_SRC = {
  thinking:    'data:image/jpeg;base64,',
  result:      'data:image/jpeg;base64,',
  service:     'data:image/jpeg;base64,',
  tersinggung: 'data:image/jpeg;base64,',
  angry:       'data:image/jpeg;base64,',
};

// Catatan: fitur foto kucing bermood (mikir/hasil/service/ngambek/marah)
// yang dulu tampil selama AI loading sudah DIHAPUS sesuai permintaan.
// AI_CAT_SRC masih dipakai di layar welcome saat Lolu lagi ngambek/marah
// (lihat renderAIChatMessages), tapi sudah tidak dipakai lagi selama proses
// loading/menunggu balasan.

function _aiSetTyping(on){
  const c = document.getElementById('ai-chat-messages');
  if (!c) return;
  let el = document.getElementById('ai-typing-row');
  if (on){
    if (el) return;
    el = document.createElement('div');
    el.id = 'ai-typing-row';
    el.className = 'ai-bubble-row ai';
    el.innerHTML = `<div class="ai-bubble ai-typing"><span></span><span></span><span></span></div>`;
    c.appendChild(el);
    _aiScrollToBottom();
  } else if (el){
    el.remove();
  }
}

// Kelas error khusus supaya sendAIChatMessage bisa bikin pesan yang sesuai
// gaya Vibexa AI (bukan nampilin raw error teknis ke user), sambil tetap
// nyimpen tipe error-nya (rate_limit / network / lainnya) buat kebutuhan lain.
class VibexaAIError extends Error {
  constructor(message, type){
    super(message);
    this.type = type || 'unknown'; // 'rate_limit' | 'network' | 'blocked' | 'invalid_format' | 'unknown'
  }
}

// Coba ambil angka detik dari pesan error semacam "Please retry in 51.6s"
// atau dari header Retry-After, buat nentuin berapa lama nunggu sebelum retry.
function _aiParseRetryDelaySec(errText){
  if (!errText) return null;
  const m = errText.match(/retry in\s+([\d.]+)\s*s/i);
  if (m) return Math.min(parseFloat(m[0].match(/[\d.]+/)[0]), 60);
  return null;
}

function _aiSleep(ms){ return new Promise(r => setTimeout(r, ms)); }

// maxRetriesPerUrl: berapa kali retry OTOMATIS khusus kasus kena rate limit
// (429) SEBELUM pindah ke worker cadangan berikutnya (kalau ada) di
// GEMINI_PROXY_URLS. Error karena koneksi/server down juga bikin pindah ke
// worker berikutnya. Error lain (format balasan aneh, kena filter
// keamanan) TIDAK di-retry/pindah worker — itu bukan soal limit/koneksi,
// jadi langsung dilempar ke atas biar user langsung tau.
async function _aiCallGemini(historyForApi, systemPrompt, maxRetriesPerUrl = 2){
  const urls = GEMINI_PROXY_URLS.filter(Boolean);
  let lastErr = new VibexaAIError('Nggak ada worker Vibexa AI yang dikonfigurasi.', 'unknown');

  for (let ui = 0; ui < urls.length; ui++){
    const url = urls[ui];
    const hasNextUrl = ui < urls.length - 1;
    let attempt = 0;

    while (true){
      let res;
      // Timeout 15 detik per percobaan fetch — tanpa ini, kalau worker lagi
      // lelet/nyangkut, browser bisa nunggu sangat lama (puluhan detik s/d
      // menit) sebelum fetch dianggap gagal. Dengan AbortController, begitu
      // 15 detik lewat, request dibatalkan paksa dan langsung dianggap
      // gagal supaya bisa cepat pindah/retry ke worker lain.
      const _aiAbortCtrl = new AbortController();
      const _aiAbortTimer = setTimeout(() => _aiAbortCtrl.abort(), 15000);
      try{
        res = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          signal: _aiAbortCtrl.signal,
          body: JSON.stringify({
            contents: historyForApi,
            systemInstruction: { parts: [{ text: systemPrompt || AI_SYSTEM_PROMPT }] },
            generationConfig: { responseMimeType: 'application/json', temperature: 0.85, maxOutputTokens: 2048 }
          })
        });
      }catch(networkErr){
        lastErr = (networkErr && networkErr.name === 'AbortError')
          ? new VibexaAIError('Vibexa AI kelamaan nggak respons, coba kirim lagi ya.', 'network')
          : new VibexaAIError('Koneksi ke Vibexa AI gagal, coba cek internet kamu.', 'network');
        break; // koneksi ke worker ini gagal total -> coba worker berikutnya (kalau ada)
      }finally{
        clearTimeout(_aiAbortTimer);
      }

      if (!res.ok){
        let errText = '';
        try{ errText = (await res.json())?.error?.message || ''; }catch(e){}

        if (res.status === 429){
          if (attempt < maxRetriesPerUrl){
            attempt++;
            // Dipersingkat dari (5s, 10s, ...) jadi (2s, 4s, ...) supaya
            // total waktu tunggu saat kena rate limit nggak kelamaan.
            const delaySec = _aiParseRetryDelaySec(errText) ?? (2 * attempt);
            await _aiSleep(delaySec * 1000);
            continue; // coba lagi di worker yang sama dulu
          }
          // Worker ini kena limit terus walau udah di-retry -> pindah ke
          // worker cadangan berikutnya kalau ada, atau nyerah kalau ini
          // worker terakhir.
          lastErr = new VibexaAIError('Lagi rame banget nih yang chat ke gue, kena limit sementara. Coba lagi bentar ya (~1 menit).', 'rate_limit');
          break;
        }

        if (res.status >= 500){
          lastErr = new VibexaAIError('Server AI-nya lagi ngambek dikit, coba kirim lagi ya.', 'network');
          break; // server error -> coba worker berikutnya kalau ada
        }

        // Error lain (4xx selain 429) biasanya soal konfigurasi worker,
        // bukan soal limit -> tetep dicoba pindah worker sebagai jaga-jaga,
        // tapi kalau ini worker terakhir langsung dilempar ke atas.
        lastErr = new VibexaAIError('Ada masalah pas nyambung ke Vibexa AI (kode ' + res.status + ').', 'unknown');
        break;
      }

      const data = await res.json();
      const text = (data?.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
      if (!text) throw new VibexaAIError('Responsnya kosong, mungkin kena filter keamanan. Coba pakai kata lain.', 'blocked');
      try{ return JSON.parse(text); }
      catch(e){
        const m = text.match(/\{[\s\S]*\}/);
        if (m){ try{ return JSON.parse(m[0]); }catch(e2){} }
        throw new VibexaAIError('Balasan AI-nya agak berantakan, coba kirim ulang ya.', 'invalid_format');
      }
    }

    if (!hasNextUrl) throw lastErr; // udah worker terakhir & tetep gagal -> nyerah
    // kalau masih ada worker berikutnya, lanjut ke iterasi `ui` selanjutnya
  }

  throw lastErr;
}

// ── Kolom ketik AI chat memanjang ke atas + tombol mic/bahasa menciut ──
// Perilakunya sama seperti kolom ketik di halaman chat antarpengguna
// (lihat autoResizeChatInput/updateChatInputBarState di atas): saat user
// menekan kolom ketik, tombol mic ("ngobrol pakai suara") & tombol bahasa
// di sebelah kiri otomatis menutup (lebar 0) supaya kolom ketik melebar
// ke kiri; saat teksnya panjang, kolom ketik tumbuh ke atas sampai batas
// AI_CHAT_INPUT_MAX_HEIGHT lalu discroll internal.
const AI_CHAT_INPUT_MAX_HEIGHT = 132; // px, samakan dgn CSS max-height #ai-chat-input

function autoResizeAIChatInput(el) {
  if (!el) return;
  el.style.height = 'auto';
  const next = Math.min(el.scrollHeight, AI_CHAT_INPUT_MAX_HEIGHT);
  el.style.height = next + 'px';
  el.style.overflowY = el.scrollHeight > AI_CHAT_INPUT_MAX_HEIGHT ? 'auto' : 'hidden';
}

function updateAIChatInputBarState() {
  const bar = document.getElementById('ai-chat-inputbar');
  const inputEl = document.getElementById('ai-chat-input');
  if (!bar || !inputEl) return;
  const hasText = inputEl.value.trim().length > 0;
  const isFocused = document.activeElement === inputEl;
  bar.classList.toggle('ai-chat-inputbar--focused', hasText || isFocused);
}

function onAIChatInputFocus() {
  updateAIChatInputBarState();
}

function onAIChatInputBlur() {
  updateAIChatInputBarState();
}

function onAIChatInputTyping() {
  autoResizeAIChatInput(document.getElementById('ai-chat-input'));
  updateAIChatInputBarState();
}

async function sendAIChatMessage(){
  if (aiChatLoading) return;
  const inp = document.getElementById('ai-chat-input');
  if (!inp) return;
  const text = inp.value.trim();
  if (!text) return;
  inp.value = '';
  autoResizeAIChatInput(inp);
  updateAIChatInputBarState();

  aiChatDisplay.push({ role: 'user', text });
  aiApiHistory.push({ role: 'user', parts: [{ text }] });
  renderAIChatMessages();
  _aiSaveChatState();
  _aiUpdateHeaderTitle();

  aiChatLoading = true;
  const sendBtn = document.getElementById('ai-chat-send-btn');
  if (sendBtn) sendBtn.disabled = true;

  _aiSetTyping(true);

  try{
    const parsed = await _aiCallGemini(aiApiHistory, _aiBuildSystemPrompt());
    const rawMessage = (parsed && typeof parsed.message === 'string' && parsed.message.trim()) || 'Oke!';
    const { text: msgTextNoSticker, tag: stickerTag } = _aiExtractStickerTag(rawMessage);
    const msg = {
      role: 'assistant',
      text: msgTextNoSticker || 'Oke!',
      songs: (parsed && Array.isArray(parsed.songs)) ? parsed.songs.filter(s => s && s.title).slice(0, 20) : [],
      playlistName: (parsed && parsed.playlist_name) || null,
      stickerTag: stickerTag
    };
    _aiRemember(parsed && parsed.remember);
    // Update "relasi emosi" persisten berdasarkan klasifikasi nada pesan
    // user ini (lihat "RELASI EMOSIONAL DENGAN USER" di AI_SYSTEM_PROMPT) —
    // ini yang bikin ngambeknya Lolu nyambung terus antar pesan, bukan
    // cuma reaksi sesaat kayak field "mood" biasa.
    _aiUpdateAffection(parsed && parsed.user_tone, parsed && parsed.apology_sincere);
    // Kalau obrolan ini nyentuh topik yang emosional/penting (lihat aturan
    // "FOLLOW-UP OTOMATIS" di AI_SYSTEM_PROMPT), jadwalkan Lolu buat nge-cek
    // user ini lagi nanti lewat Cloudflare Worker terjadwal (lihat
    // _aiHandleFollowUp di bawah).
    _aiHandleFollowUp(parsed);
    aiApiHistory.push({ role: 'model', parts: [{ text: JSON.stringify(parsed) }] });
    aiChatDisplay.push(msg);
    _aiSaveChatState();

    _aiSetTyping(false);
    renderAIChatMessages();
  }catch(e){
    console.error('Vibexa AI error:', e);
    _aiSetTyping(false);
    // Kalau gagal, jangan simpan turn user yg gagal dibalas ke aiApiHistory
    // biar konteks Gemini nggak "bolong" pas dicoba lagi nanti.
    const friendlyText = (e && e.message) ? e.message : 'Waduh, ada gangguan dikit. Coba kirim lagi ya.';
    aiChatDisplay.push({ role: 'assistant', text: friendlyText, songs: [], playlistName: null, isError: true });
    _aiSaveChatState();
    renderAIChatMessages();
  }finally{
    aiChatLoading = false;
    if (sendBtn) sendBtn.disabled = false;
  }
}

/* ==========================================================================
   MARQUEE OTOMATIS UNTUK JUDUL LAGU (khusus tampilan mobile) — gaya Spotify.
   Kalau judul lagu di kotak "play" mini player (#bar-title) atau di halaman
   Lyrics (#fs-np-title) kepanjangan sampai kepotong (overflow), teks
   otomatis bergerak pelan ke kiri lalu "muncul" lagi dari kanan, berulang
   terus selagi lagu itu diputar. Kalau judulnya muat, tampil normal (diam,
   dengan "..." di ujung) seperti biasa — marquee cuma nyala kalau memang
   perlu, dan cuma di layar mobile (lebar <=660px, sama kayak breakpoint
   CSS mobile #bar & .fs-bar-left-in-nav).

   Elemen judul ini textContent-nya di-set dari banyak tempat berbeda di
   file ini (ganti lagu, buka Now Playing, dsb) — daripada ubah satu-satu
   tempat itu, dipasang MutationObserver di sini supaya otomatis kedeteksi
   tiap kali teksnya berubah, dari mana pun perubahan itu datang.
   ========================================================================== */
(function(){
  var VBX_MQ_MOBILE = window.matchMedia('(max-width:660px)');
  var VBX_MARQUEE_SPEED_PX_S = 32; // px/detik — sengaja pelan, jangan kayak kereta ekspres
  var VBX_MARQUEE_GAP_PX = 46;     // jarak antara ujung teks & pengulangannya
  var vbxTrackedEls = [];

  function vbxWithSelfUpdate(el, fn){
    el.__vbxSelfUpdate = true;
    fn();
    // reset flag lewat macrotask (bukan microtask) supaya PASTI kejalanin
    // SETELAH callback MutationObserver punya kesempatan lihat flag ini masih true,
    // jadi perubahan DOM yang kita lakukan sendiri di bawah ini tidak
    // dianggap sebagai "judul lagu ganti" oleh observer-nya.
    setTimeout(function(){ el.__vbxSelfUpdate = false; }, 0);
  }

  function vbxClearMarquee(el, plainText){
    vbxWithSelfUpdate(el, function(){
      el.textContent = plainText;
      el.classList.remove('vbx-marquee-active');
      el.style.removeProperty('--vbx-marquee-duration');
    });
    el.__vbxWrapped = false;
  }

  function vbxApplyMarquee(el, text, distancePx){
    vbxWithSelfUpdate(el, function(){
      el.textContent = '';
      var track = document.createElement('span');
      track.className = 'vbx-marquee-track';
      for (var i = 0; i < 2; i++){
        var item = document.createElement('span');
        item.className = 'vbx-marquee-item';
        item.textContent = text;
        var gap = document.createElement('span');
        gap.className = 'vbx-marquee-gap';
        gap.style.width = VBX_MARQUEE_GAP_PX + 'px';
        track.appendChild(item);
        track.appendChild(gap);
      }
      el.appendChild(track);
      el.classList.add('vbx-marquee-active');
      var duration = Math.max(4, distancePx / VBX_MARQUEE_SPEED_PX_S);
      el.style.setProperty('--vbx-marquee-duration', duration.toFixed(2) + 's');
    });
    el.__vbxWrapped = true;
  }

  function vbxEvaluate(el){
    if (!el || !el.isConnected) return;

    var text = el.__vbxWrapped ? (el.__vbxOrigText || '') : (el.textContent || '');
    el.__vbxOrigText = text;

    // Selalu balik ke teks polos dulu supaya pengukuran overflow-nya akurat
    // (kalau lagi dibungkus track marquee, scrollWidth-nya jadi salah).
    if (el.__vbxWrapped) vbxClearMarquee(el, text);

    if (!VBX_MQ_MOBILE.matches || !text || !text.trim()){
      return; // bukan di mobile, atau memang belum ada judul lagu — biarkan diam
    }

    // FIX: kalau elemen ini belum ke-layout dengan benar (mis. halaman Lyrics
    // baru saja dibuka & belum sempat dipindah ke posisi mobile-nya oleh
    // _fsMobileLayout, atau lagi tersembunyi/display:none), clientWidth-nya
    // bisa kebaca 0 (atau nilai sementara yang salah). Kalau itu dianggap
    // "overflow", judul PENDEK pun jadi ke-wrap jadi marquee (dengan
    // text-overflow:clip + mask fade) padahal sebenarnya muat — ini bikin
    // judul singkat kelihatan "kepotong" padahal statis. Jadi: kalau lebar
    // kotaknya belum masuk akal (0), jangan simpulkan overflow — coba lagi
    // sebentar lagi sampai layout-nya beres.
    if (el.clientWidth <= 0){
      vbxSchedule(el, true);
      return;
    }

    var overflowPx = el.scrollWidth - el.clientWidth;
    if (overflowPx > 2){
      var distance = el.scrollWidth + VBX_MARQUEE_GAP_PX;
      vbxApplyMarquee(el, text, distance);
    }
  }

  function vbxSchedule(el, isRetry){
    clearTimeout(el.__vbxTimer);
    el.__vbxTimer = setTimeout(function(){ vbxEvaluate(el); }, isRetry ? 120 : 60);
  }

  function vbxWatch(el){
    if (!el || el.__vbxWatched) return;
    el.__vbxWatched = true;
    vbxTrackedEls.push(el);

    var mo = new MutationObserver(function(){
      if (el.__vbxSelfUpdate) return; // ini hasil ulah kita sendiri, abaikan
      el.__vbxWrapped = false; // DOM-nya diganti dari luar (judul lagu baru)
      vbxSchedule(el);
    });
    mo.observe(el, { childList: true, characterData: true, subtree: true });

    vbxSchedule(el);
  }

  function vbxInit(){
    vbxWatch(document.getElementById('bar-title'));
    vbxWatch(document.getElementById('fs-np-title'));
  }

  // Dipanggil dari luar (openFS() saat halaman Lyrics dibuka, & _fsMobileLayout()
  // saat #fs-bar-left baru selesai dipindah ke posisi mobile-nya) supaya
  // pengecekan overflow diulang PERSIS setelah layout-nya benar2 final,
  // bukan cuma mengandalkan timer tetap 60ms yang bisa lebih cepat dari itu.
  window.vbxRecheckMarquee = function(){
    vbxTrackedEls.forEach(function(el){ vbxSchedule(el); });
  };

  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', vbxInit);
  } else {
    vbxInit();
  }

  window.addEventListener('resize', function(){
    vbxTrackedEls.forEach(vbxSchedule);
  });

  if (VBX_MQ_MOBILE.addEventListener){
    VBX_MQ_MOBILE.addEventListener('change', function(){ vbxTrackedEls.forEach(vbxSchedule); });
  } else if (VBX_MQ_MOBILE.addListener){ // fallback Safari lama
    VBX_MQ_MOBILE.addListener(function(){ vbxTrackedEls.forEach(vbxSchedule); });
  }
})();
